)),'{guidance,goingWell}','"Decisions say what else was considered and why not"'::jsonb),'v5:80ed104e0492403fad219d1ed709e8b0beadbbbdeaa534320aff3a9396cd188d','practice:v3:8ab2869b40c52821ec690ea68e72f5ba333ced458d228fec9da89a97f95afd4d');
INSERT INTO _cutover_bundle VALUES('GROUP','delivery-and-version-control-discipline',NULL,'{"name":"Disciplined delivery and version control","description":"Keep your delivery clean. Make each commit one self-contained change, leave generated and build files out of the diff, and branch from the shared integration branch so your work stands on its own.","icon":"GitBranch","color":"fuchsia"}'::jsonb,'{"name":"Disciplined delivery and version control","description":"Keep your delivery clean. Make each commit one self-contained change, leave generated and build files out of the diff, and branch from the shared integration branch so your work stands on its own.","icon":"GitBranch","color":"fuchsia"}'::jsonb,'51b7e7033ee6a65bcfce5b5cb25ca48f5cb5eb6bf7b902807afc3e0dd661a6f5','group:v1:51b7e7033ee6a65bcfce5b5cb25ca48f5cb5eb6bf7b902807afc3e0dd661a6f5');
INSERT INTO _cutover_bundle VALUES('PRACTICE','commits-are-atomic-and-cohesive','scm.pull_request','{"name":"Keep each commit to one logical change","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.core","stance":"EXHAUSTIVE"},{"sourceKind":"scm.pull-request.diff","stance":"REQUIRED"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured pull or merge request at its pinned revision: the change itself, the description as written, the commits, the review discussion and the linked context the practice names. Distinguish what the author wrote from what a reviewer, a template or the provider''s current state says.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: how the pull request''s commits are partitioned — each commit one cohesive logical change, as its authored subject and body describe it and its own files show.\n\n## The standard\nJudge one thing: whether the commits are SPLIT so each one captures a single logical change, rather than one commit tangling separable work into a bundle a reviewer cannot follow, revert, or cherry-pick on its own. One logical change is one piece of work with everything it needs: a feature with its model, view, view model, test, asset, the manifest entry for the package it uses and the navigation that reaches it; a fix with its test; a diagram with the README line that embeds it; one document''s sections revised for one reason. That is one concern however many clauses or files name it (\"parse the header and validate it\"). Two concerns are two pieces of work that each make sense alone: two features or user stories, two unrelated fixes, behavioural work beside a chore (a reformat or lint sweep, a rename or move sweep, a dependency bump, tooling or editor settings), or code beside an unrelated document or course deliverable. Several cohesive commits in one pull request is fine here, and a chore or a revert in its own commit is the partition working, not a tangle. Decide what is separable as an experienced reviewer would; there is no fixed word list. This is a workflow practice about how the history is partitioned, never a code-defect claim.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name which case, and stop when there was no split to judge: no authored non-merge commit remains: every entry is an automatic merge commit (two or more `parents`, or a \"Merge ...\" subject).\n\n## Sources\n1. The commits (`context/commits.json`): each subject, full body, `parents` and the `files` it touched against its first parent, with status and line counts. They establish the author''s partition — what each commit says it holds and what it actually touched. A commit whose files carry a second piece of work its subject does not name — a whole source-tree rename or a new view under a README subject, a user-story rewrite under a diagram subject — is a tangle the subject hides; the supporting files of the work it does name never are. `git show <sha>` in the checkout gives its patch when the file list is not enough.\n2. The per-file changed-line spread of the whole change (`work/change/files.json`, `work/change/diff.patch`): the overall breadth the commits together cover.\nRead subjects, bodies and each commit''s files together and judge conservatively. The precomputed leads below these criteria list every authored commit as one row — its subject''s shape (bare, a repeat, joined clauses, cut off), how many files it only moved, and the files it edited with their line counts — as places to look, never verdicts: joined clauses are punctuation, not a count of concerns. If `context/commits.json` is unavailable, report a collection gap and record no observation; uncollected subjects are never authored silence and never UNDETERMINED.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: every commit holds one logical change, as its subject, body and files show. Looks like a lapse but is not: \"Add order history, and adjust the order fetch\" where the adjustment returns what the new history reads; \"Rewrite the README goal for the new scope, update its user stories\" revising one README for one reason; \"Update class diagram: add Invoice, drop method signatures\" revising one diagram; a feature commit that also edits `project.yml` for its package; README commits later reverted, each on its own. Each is one concern.\n- NOT_MET: at least one commit holds two concerns — its subject or body names both (\"Extract the card views, replace deprecated colour calls everywhere\": a refactor and an API sweep; \"add formatter settings + start the settings screen\"), or its files carry one its subject does not name. Quote the deciding subject with its short SHA, name the two pieces of work, and name the path that shows an unnamed one.\n- UNDETERMINED when a bare or vague subject (\"fixes\", \"ccc\", \"Improve MR\") leaves a commit''s content open and neither its files nor its patch settle whether it holds one piece of work or two; name the commit and the missing distinction. A broad commit under a vague subject is not a tangle by breadth alone; a narrow one whose files show a single piece of work is cohesive.\nOne observation per review, over the whole series, including a single authored commit that can be cohesive or bundled.\n\n## Severity\nNOT_MET only; never above MAJOR on commit atomicity alone — a formative practice, not a merge gate. MINOR, the usual band: a single commit bundles separable work, and splitting it would isolate each concern. MAJOR: the history broadly tangles, so a reviewer cannot reason about or revert one concern at a time.\n\n## Grounding\nEvery claim cites the commit record that supports it: quote the deciding subject(s) verbatim, each with its short SHA, for NOT_MET, and name any path from that commit''s `files` that shows the unnamed concern; cite the subjects whose partition you accepted for MET. Never claim a per-commit file mapping you cannot observe. Cite the corresponding subject, SHA and file entries in the captured `context/commits.json` artifact. Never cite a diff line for this observation, and never record UNDETERMINED because the subjects have no line of their own to cite. Describe the observable split; never impute intent or character, and never frame a tangle as a defect in the code.\n\n## Defer\nOverall pull request size, and a pull request carrying several features in separate commits, belong to `scope-one-reviewable-change`; a large but cohesive partition can be a strength here. Subject wording belongs to `commit-subjects-explain-each-change`; a vague subject alone establishes neither cohesion nor a tangle. A generated or editor file swept into a commit (`.idea/`, `.DS_Store`, a regenerated `Info.plist`) belongs to `excludes-generated-and-build-artifacts`. Here only: does each commit hold one logical change?","precomputeScript":"// Precompute FACTS for commits-are-atomic-and-cohesive: one row per authored commit — its subject,\n// whether it joins clauses, and the files it touched with their line counts and moves — read from the\n// commit record. The criteria say what one logical change is and the model judges the partition; a\n// flag is a place to look, never a verdict.\nimport { readCapturedCommits } from \"../lib/change.ts\";\nimport { commitRows, describeCommitCount, subjectFacts } from \"../lib/commit-subjects.ts\";\nimport type { DiffFile, PullRequestMetadata } from \"../lib/types.ts\";\n\nexport default async function commitsAreAtomicAndCohesive(\n\t_repoPath: string,\n\t_diffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n\tcontextDir: string | undefined,\n\t_changeDir: string | undefined,\n\tcontextReference: string,\n) {\n\tconst captured = await readCapturedCommits(contextDir);\n\tconst facts = subjectFacts(captured ?? []);\n\tconst authored = facts.filter((f) => !f.merge);\n\tlet directions = [\n\t\tdescribeCommitCount(facts),\n\t\t\"`joinedClauses` marks a subject that joins clauses with ''and'', ''&'', ''+'', a comma, a semicolon or a sentence break, or a body with two or more bullets; `moved` counts files renamed with no line changed. Both describe the record, not how many changes a commit holds.\",\n\t];\n\tif (captured === null) {\n\t\tdirections = [\n\t\t\t\"commits.json is missing or malformed: a collection gap, not a history without authored commits.\",\n\t\t];\n\t} else if (authored.length === 0) {\n\t\tdirections = [\"No authored commit in the reviewed range: only merge commits, or none.\"];\n\t}\n\treturn {\n\t\thints: commitRows(facts, contextReference),\n\t\tmetrics:\n\t\t\tcaptured === null\n\t\t\t\t? {}\n\t\t\t\t: {\n\t\t\t\t\t\tauthoredCommits: authored.length,\n\t\t\t\t\t\tmergeCommits: facts.length - authored.length,\n\t\t\t\t\t\tjoinedSubjects: authored.filter((f) => f.joinedClauses).length,\n\t\t\t\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"Mixing unrelated changes in a commit makes selective review, reverts and backports harder. Keeping changes separable makes the history more useful; clear commit subjects help a reader understand that intended separation.","whatGoodLooksLike":"Separate commits for separate ideas, such as ''Fix off-by-one in pagination'' in one and ''Rename helper for clarity'' in another, so each can be reviewed, reverted, or backported on its own.","groupSlug":"delivery-and-version-control-discipline","deliveryBehavior":{"summaryOnly":true,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 156\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Mixed commit</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(16 48)\"><path class=\"pv-stroke-ink\" d=\"M0 8h4.5M11.5 8H16\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"3.5\" fill=\"none\" stroke-width=\"1.5\"/></g>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"61\" font-size=\"15\">Commit</text>\n  <text class=\"pv-fill-muted\" x=\"16\" y=\"85\" font-size=\"15\">Fix paging, reformat</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"16\" y=\"109\" font-size=\"15\">paging.ts</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"136\" y=\"109\" font-size=\"15\">format.ts</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"152\" font-size=\"15\">Revert takes both</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Separate commits</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"142.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(352 48)\"><path class=\"pv-stroke-ink\" d=\"M0 8h4.5M11.5 8H16\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"3.5\" fill=\"none\" stroke-width=\"1.5\"/></g>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"61\" font-size=\"15\">Commit</text>\n  <text class=\"pv-fill-accent\" x=\"352\" y=\"85\" font-size=\"15\">Fix paging</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"352\" y=\"109\" font-size=\"15\">paging.ts</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"496.75\" y=\"32.75\" width=\"142.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(512 48)\"><path class=\"pv-stroke-ink\" d=\"M0 8h4.5M11.5 8H16\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"3.5\" fill=\"none\" stroke-width=\"1.5\"/></g>\n  <text class=\"pv-fill-ink\" x=\"540\" y=\"61\" font-size=\"15\">Commit</text>\n  <text class=\"pv-fill-accent\" x=\"512\" y=\"85\" font-size=\"15\">Reformat</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"512\" y=\"109\" font-size=\"15\">format.ts</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"152\" font-size=\"15\">Each reverts alone</text>\n</svg>\n","alt":"One mixed commit, “Fix paging, reformat”, touches paging.ts and format.ts, so a revert takes both. Separate commits, “Fix paging” and “Reformat”, each touch one file, so each reverts alone."},"guide":{"markdown":"## How to do it\n\n- Commit each piece of work when it’s done, before you start the next one. It’s easier to join small commits later than to split a big one.\n- Keep everything one change needs in its commit. A fix goes with its test. A feature goes with its view, its model and its package entry.\n- Give unrelated chores their own commits. For example, instead of one commit that fixes a paging bug and reformats the file, commit the fix first. Then commit the reformat.\n- Before you ask for a review, read the subject, the body and the files of each commit. If a commit holds two pieces of work that each make sense alone, split it with `git rebase --interactive`.\n- If one commit needs another, keep them in order. Each commit should still build and pass the tests.\n\n## When it does not apply\n\n- Every commit in the pull request or merge request is an automatic merge commit, such as “Merge branch …”. There is no split of your own to check.\n\nIt still applies when the pull request or merge request has only one commit that you wrote.\n\n## Common mistakes\n\n- Counting files or the word “and” in a subject. One change can touch many files and need two verbs, such as “Parse the header and validate it”. Instead, ask whether each part makes sense alone.\n- Cutting one change into pieces that cannot stand alone, such as a fix and its test in two commits. Instead, keep the parts of one change together.\n- Mixing an unrelated rename, lint fix or dependency update into a feature commit. Instead, put the unrelated work in its own commit. Keep the changes that the feature needs with the feature.\n- Squashing separate ideas into one commit to keep the history short. Instead, keep each idea in its own commit. Several commits are fine, and so is a revert in its own commit.\n\n## Sources\n\n- [Separate your changes](https://docs.kernel.org/process/submitting-patches.html#separate-your-changes), Linux kernel documentation. Each logical change gets its own patch, even across many files, and each patch must keep the build working.\n- [Separate changes](https://git-scm.com/docs/gitworkflows#_separate_changes), Git documentation. Split work into small logical steps, and edit the commits before you publish them.\n- [Partitioning composite code changes](https://hunkim.cse.ust.hk/papers/tao-msr2015.pdf), Tao and Kim, 2015. In a study with 18 students, partitioned changes led to better review answers in a similar time.\n- [The impact of tangled code changes](https://www.microsoft.com/en-us/research/publication/the-impact-of-tangled-code-changes/), Herzig and Zeller, 2013. Unrelated changes within bug fixes made associations between files and bug reports less accurate. One author worked at Microsoft, which sells version control tools.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Keep each commit to one logical change","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.core","stance":"EXHAUSTIVE"},{"sourceKind":"scm.pull-request.diff","stance":"REQUIRED"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured pull or merge request at its pinned revision: the change itself, the description as written, the commits, the review discussion and the linked context the practice names. Distinguish what the author wrote from what a reviewer, a template or the provider''s current state says.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: how the pull request''s commits are partitioned — each commit one cohesive logical change, as its authored subject and body describe it and its own files show.\n\n## The standard\nJudge one thing: whether the commits are SPLIT so each one captures a single logical change, rather than one commit tangling separable work into a bundle a reviewer cannot follow, revert, or cherry-pick on its own. One logical change is one piece of work with everything it needs: a feature with its model, view, view model, test, asset, the manifest entry for the package it uses and the navigation that reaches it; a fix with its test; a diagram with the README line that embeds it; one document''s sections revised for one reason. That is one concern however many clauses or files name it (\"parse the header and validate it\"). Two concerns are two pieces of work that each make sense alone: two features or user stories, two unrelated fixes, behavioural work beside a chore (a reformat or lint sweep, a rename or move sweep, a dependency bump, tooling or editor settings), or code beside an unrelated document or course deliverable. Several cohesive commits in one pull request is fine here, and a chore or a revert in its own commit is the partition working, not a tangle. Decide what is separable as an experienced reviewer would; there is no fixed word list. This is a workflow practice about how the history is partitioned, never a code-defect claim.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name which case, and stop when there was no split to judge: no authored non-merge commit remains: every entry is an automatic merge commit (two or more `parents`, or a \"Merge ...\" subject).\n\n## Sources\n1. The commits (`context/commits.json`): each subject, full body, `parents` and the `files` it touched against its first parent, with status and line counts. They establish the author''s partition — what each commit says it holds and what it actually touched. A commit whose files carry a second piece of work its subject does not name — a whole source-tree rename or a new view under a README subject, a user-story rewrite under a diagram subject — is a tangle the subject hides; the supporting files of the work it does name never are. `git show <sha>` in the checkout gives its patch when the file list is not enough.\n2. The per-file changed-line spread of the whole change (`work/change/files.json`, `work/change/diff.patch`): the overall breadth the commits together cover.\nRead subjects, bodies and each commit''s files together and judge conservatively. The precomputed leads below these criteria list every authored commit as one row — its subject''s shape (bare, a repeat, joined clauses, cut off), how many files it only moved, and the files it edited with their line counts — as places to look, never verdicts: joined clauses are punctuation, not a count of concerns. If `context/commits.json` is unavailable, report a collection gap and record no observation; uncollected subjects are never authored silence and never UNDETERMINED.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: every commit holds one logical change, as its subject, body and files show. Looks like a lapse but is not: \"Add order history, and adjust the order fetch\" where the adjustment returns what the new history reads; \"Rewrite the README goal for the new scope, update its user stories\" revising one README for one reason; \"Update class diagram: add Invoice, drop method signatures\" revising one diagram; a feature commit that also edits `project.yml` for its package; README commits later reverted, each on its own. Each is one concern.\n- NOT_MET: at least one commit holds two concerns — its subject or body names both (\"Extract the card views, replace deprecated colour calls everywhere\": a refactor and an API sweep; \"add formatter settings + start the settings screen\"), or its files carry one its subject does not name. Quote the deciding subject with its short SHA, name the two pieces of work, and name the path that shows an unnamed one.\n- UNDETERMINED when a bare or vague subject (\"fixes\", \"ccc\", \"Improve MR\") leaves a commit''s content open and neither its files nor its patch settle whether it holds one piece of work or two; name the commit and the missing distinction. A broad commit under a vague subject is not a tangle by breadth alone; a narrow one whose files show a single piece of work is cohesive.\nOne observation per review, over the whole series, including a single authored commit that can be cohesive or bundled.\n\n## Severity\nNOT_MET only; never above MAJOR on commit atomicity alone — a formative practice, not a merge gate. MINOR, the usual band: a single commit bundles separable work, and splitting it would isolate each concern. MAJOR: the history broadly tangles, so a reviewer cannot reason about or revert one concern at a time.\n\n## Grounding\nEvery claim cites the commit record that supports it: quote the deciding subject(s) verbatim, each with its short SHA, for NOT_MET, and name any path from that commit''s `files` that shows the unnamed concern; cite the subjects whose partition you accepted for MET. Never claim a per-commit file mapping you cannot observe. Cite the corresponding subject, SHA and file entries in the captured `context/commits.json` artifact. Never cite a diff line for this observation, and never record UNDETERMINED because the subjects have no line of their own to cite. Describe the observable split; never impute intent or character, and never frame a tangle as a defect in the code.\n\n## Defer\nOverall pull request size, and a pull request carrying several features in separate commits, belong to `scope-one-reviewable-change`; a large but cohesive partition can be a strength here. Subject wording belongs to `commit-subjects-explain-each-change`; a vague subject alone establishes neither cohesion nor a tangle. A generated or editor file swept into a commit (`.idea/`, `.DS_Store`, a regenerated `Info.plist`) belongs to `excludes-generated-and-build-artifacts`. Here only: does each commit hold one logical change?","precomputeScript":"// Precompute FACTS for commits-are-atomic-and-cohesive: one row per authored commit — its subject,\n// whether it joins clauses, and the files it touched with their line counts and moves — read from the\n// commit record. The criteria say what one logical change is and the model judges the partition; a\n// flag is a place to look, never a verdict.\nimport { readCapturedCommits } from \"../lib/change.ts\";\nimport { commitRows, describeCommitCount, subjectFacts } from \"../lib/commit-subjects.ts\";\nimport type { DiffFile, PullRequestMetadata } from \"../lib/types.ts\";\n\nexport default async function commitsAreAtomicAndCohesive(\n\t_repoPath: string,\n\t_diffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n\tcontextDir: string | undefined,\n\t_changeDir: string | undefined,\n\tcontextReference: string,\n) {\n\tconst captured = await readCapturedCommits(contextDir);\n\tconst facts = subjectFacts(captured ?? []);\n\tconst authored = facts.filter((f) => !f.merge);\n\tlet directions = [\n\t\tdescribeCommitCount(facts),\n\t\t\"`joinedClauses` marks a subject that joins clauses with ''and'', ''&'', ''+'', a comma, a semicolon or a sentence break, or a body with two or more bullets; `moved` counts files renamed with no line changed. Both describe the record, not how many changes a commit holds.\",\n\t];\n\tif (captured === null) {\n\t\tdirections = [\n\t\t\t\"commits.json is missing or malformed: a collection gap, not a history without authored commits.\",\n\t\t];\n\t} else if (authored.length === 0) {\n\t\tdirections = [\"No authored commit in the reviewed range: only merge commits, or none.\"];\n\t}\n\treturn {\n\t\thints: commitRows(facts, contextReference),\n\t\tmetrics:\n\t\t\tcaptured === null\n\t\t\t\t? {}\n\t\t\t\t: {\n\t\t\t\t\t\tauthoredCommits: authored.length,\n\t\t\t\t\t\tmergeCommits: facts.length - authored.length,\n\t\t\t\t\t\tjoinedSubjects: authored.filter((f) => f.joinedClauses).length,\n\t\t\t\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"Mixing unrelated changes in a commit makes selective review, reverts and backports harder. Keeping changes separable makes the history more useful; clear commit subjects help a reader understand that intended separation.","whatGoodLooksLike":"Separate commits for separate ideas, such as ''Fix off-by-one in pagination'' in one and ''Rename helper for clarity'' in another, so each can be reviewed, reverted, or backported on its own.","groupSlug":"delivery-and-version-control-discipline","deliveryBehavior":{"summaryOnly":true,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 156\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Mixed commit</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(16 48)\"><path class=\"pv-stroke-ink\" d=\"M0 8h4.5M11.5 8H16\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"3.5\" fill=\"none\" stroke-width=\"1.5\"/></g>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"61\" font-size=\"15\">Commit</text>\n  <text class=\"pv-fill-muted\" x=\"16\" y=\"85\" font-size=\"15\">Fix paging, reformat</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"16\" y=\"109\" font-size=\"15\">paging.ts</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"136\" y=\"109\" font-size=\"15\">format.ts</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"152\" font-size=\"15\">Revert takes both</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Separate commits</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"142.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(352 48)\"><path class=\"pv-stroke-ink\" d=\"M0 8h4.5M11.5 8H16\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"3.5\" fill=\"none\" stroke-width=\"1.5\"/></g>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"61\" font-size=\"15\">Commit</text>\n  <text class=\"pv-fill-accent\" x=\"352\" y=\"85\" font-size=\"15\">Fix paging</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"352\" y=\"109\" font-size=\"15\">paging.ts</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"496.75\" y=\"32.75\" width=\"142.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(512 48)\"><path class=\"pv-stroke-ink\" d=\"M0 8h4.5M11.5 8H16\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"3.5\" fill=\"none\" stroke-width=\"1.5\"/></g>\n  <text class=\"pv-fill-ink\" x=\"540\" y=\"61\" font-size=\"15\">Commit</text>\n  <text class=\"pv-fill-accent\" x=\"512\" y=\"85\" font-size=\"15\">Reformat</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"512\" y=\"109\" font-size=\"15\">format.ts</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"152\" font-size=\"15\">Each reverts alone</text>\n</svg>\n","alt":"One mixed commit, “Fix paging, reformat”, touches paging.ts and format.ts, so a revert takes both. Separate commits, “Fix paging” and “Reformat”, each touch one file, so each reverts alone."},"guide":{"markdown":"## How to do it\n\n- Commit each piece of work when it’s done, before you start the next one. It’s easier to join small commits later than to split a big one.\n- Keep everything one change needs in its commit. A fix goes with its test. A feature goes with its view, its model and its package entry.\n- Give unrelated chores their own commits. For example, instead of one commit that fixes a paging bug and reformats the file, commit the fix first. Then commit the reformat.\n- Before you ask for a review, read the subject, the body and the files of each commit. If a commit holds two pieces of work that each make sense alone, split it with `git rebase --interactive`.\n- If one commit needs another, keep them in order. Each commit should still build and pass the tests.\n\n## When it does not apply\n\n- Every commit in the pull request or merge request is an automatic merge commit, such as “Merge branch …”. There is no split of your own to check.\n\nIt still applies when the pull request or merge request has only one commit that you wrote.\n\n## Common mistakes\n\n- Counting files or the word “and” in a subject. One change can touch many files and need two verbs, such as “Parse the header and validate it”. Instead, ask whether each part makes sense alone.\n- Cutting one change into pieces that cannot stand alone, such as a fix and its test in two commits. Instead, keep the parts of one change together.\n- Mixing an unrelated rename, lint fix or dependency update into a feature commit. Instead, put the unrelated work in its own commit. Keep the changes that the feature needs with the feature.\n- Squashing separate ideas into one commit to keep the history short. Instead, keep each idea in its own commit. Several commits are fine, and so is a revert in its own commit.\n\n## Sources\n\n- [Separate your changes](https://docs.kernel.org/process/submitting-patches.html#separate-your-changes), Linux kernel documentation. Each logical change gets its own patch, even across many files, and each patch must keep the build working.\n- [Separate changes](https://git-scm.com/docs/gitworkflows#_separate_changes), Git documentation. Split work into small logical steps, and edit the commits before you publish them.\n- [Partitioning composite code changes](https://hunkim.cse.ust.hk/papers/tao-msr2015.pdf), Tao and Kim, 2015. In a study with 18 students, partitioned changes led to better review answers in a similar time.\n- [The impact of tangled code changes](https://www.microsoft.com/en-us/research/publication/the-impact-of-tangled-code-changes/), Herzig and Zeller, 2013. Unrelated changes within bug fixes made associations between files and bug reports less accurate. One author worked at Microsoft, which sells version control tools.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Each commit holds one logical change and no more"'::jsonb),'v5:86430ebdc1c44555d1a2fd1add300d7094985d131f67521f7d79cdcbf87bc3cd','practice:v3:80c40d6feb514d13c1ad871ba21cabc6ad13f9f5b32327338c3e07e4bad51ab2');
INSERT INTO _cutover_bundle VALUES('PRACTICE','excludes-generated-and-build-artifacts','scm.pull_request','{"name":"Track generated artifacts only when justified","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.core","stance":"REQUIRED"},{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: tracked generated or build artifacts are justified by captured repository policy or the source-to-artifact workflow.\n\n## The standard\nJudge one thing: does the change include generated or build artifacts only where the repository''s captured policy or its source-to-artifact workflow justifies tracking them? This is a repository-hygiene practice about what gets committed — never a code-defect claim about a file''s contents, and generated output is not itself the defect. Judge from the file paths in the diff. Machine noise being reviewed as if it were source has a recognisable shape across any stack or language — a location or a banner that says \"a tool wrote this\": a build-output directory, an editor or OS cruft file, a coverage dump, a vendored or cached blob, a minified single-line bundle, or a tracked generated file someone hand-edited instead of regenerating. These are open examples, not a closed list. A repository may deliberately version-control some generated sources — a committed OpenAPI spec, a generated client, an ERD, a route tree. When such a tracked artifact moves in step with the hand-written change that drives its regeneration, that is intended, regeneration-consistent movement: do not flag it. An intentional regeneration may be appropriate without a simultaneous hand-written edit. Flag only output that is not meant to be tracked, or a tracked generated file left hand-edited or stale relative to its source.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop only for an empty change. A change whose files are all generated still has content whose inclusion can be reviewed; it is judged, not ruled out.\n\n## Sources\n1. The file spread (`work/change/files.json`) and the per-file headers of the diff (`work/change/diff.patch`): the paths. They establish which paths changed and where they sit — the primary evidence. A path never establishes compile, build or runtime behaviour.\n2. The patch body (`work/change/diff.patch`): open it only to confirm a flagged path is machine-emitted when the path alone is ambiguous — a \"DO NOT EDIT\", \"@generated\" or \"auto-generated\" banner, a minified single line. The evidence is the path plus that confirming line, never a line-by-line review of the file''s contents.\n3. The checkout (`<repositoryRoot>`): the ignore rules, the documented generation workflow, and whether an artifact is tracked and which source drives it. It establishes whether tracking a generated file is intended. It never establishes manual editing or stale generation from an unchanged source file alone.\nIf the policy or source evidence a flag needs was not acquired, report a collection gap and record no observation.\n\n## Judge\nAssess conformance to the standard in this context.\n- NOT_MET: a quoted repository policy or an observable workflow establishes that an added artifact should not be tracked, or a tracked generated file was hand-edited or left stale relative to the source that drives it. Quote each offending path.\n- MET: a complete bounded search over every changed path establishes that the changed artifacts are appropriately tracked — every path is something a person authored or intended: source, tests, docs, hand-written config, a lockfile moving in step with its manifest, or a tracked generated artifact whose regeneration is justified by the captured workflow, with or without a simultaneous source edit.\n- UNDETERMINED when the one path this practice turns on is genuinely ambiguous — the path, any banner and the patch together cannot tell you whether it is machine-emitted, or whether tracking and regenerating that artifact is justified by the captured policy or workflow. Say so rather than let the doubt pass as a clean bill; name what would settle it. Having walked every path and found each justified is MET, not UNDETERMINED.\nOne observation per review, covering every flagged path.\n\n## Severity\nNOT_MET only; never above MAJOR on this practice alone — a practice to grow, not a merge gate. MINOR, the usual band: a lone stray artifact. MAJOR: a committed build-output directory, several leaked artifacts, or a hand-edited generated file that should have been regenerated. Identical situations land identically.\n\n## Grounding\nEvery NOT_MET names each offending path verbatim and, for a generated-file flag, quotes the confirming banner or names the tracked artifact and its driving source. If you cannot name an offending path there is nothing to flag; do not invent one. Cite a line of the flagged file from `work/change/diff.patch` (`scm.pull-request.diff`, the pinned `context/change.json`): `work/change/files.json` is derived here and is not citable; a flagged file the diff shows without numbered lines (binary, or renamed without edits) is cited through the `path` line of its entry in `context/commits.json`. For MET evidence.search records the boundary and the citations quote it: `changed_files` in `context/metadata.json` (`scm.pull-request.core`) and the paths you walked, listed in the rationale. Describe the observable fact (\"this path is machine-emitted\") and the next step (ignore it and drop it, or regenerate from source). Never assert compile, build or runtime behaviour from a path; never impute intent or character.\n\n## Defer\nWhether a dependency change was deliberate or justified belongs to `changes-dependencies-deliberately`; a lockfile moving in step with its manifest is its concern. Do not infer that a lockfile was hand-edited merely because its manifest did not change — an intentional resolution refresh may update a lockfile alone. Here only: does the diff carry machine output that should not be tracked?","precomputeScript":null,"automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A reviewer catches the most problems in the hand-written lines they can read closely, and a committed build output or editor config buries that source under machine noise nobody reviews. Leaving generated files out keeps the diff to the change a person can actually check, and spares everyone the odd conflict in a file no human wrote.","whatGoodLooksLike":"Build outputs, logs and editor files stay out of the repository. Deliberately tracked generated artifacts follow the documented generation workflow; intentional regeneration can be appropriate even without a simultaneous source edit.","groupSlug":"delivery-and-version-control-discipline","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 164\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Unwanted output committed</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(16 48)\"><path class=\"pv-stroke-ink\" d=\"M0 8h4.5M11.5 8H16\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"3.5\" fill=\"none\" stroke-width=\"1.5\"/></g>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"61\" font-size=\"15\">Committed files</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"16\" y=\"92\" font-size=\"15\">src/cart.ts</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"16\" y=\"116\" font-size=\"15\">dist/cart.min.js</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"160\" font-size=\"15\">Machine noise</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Unwanted output ignored</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(352 48)\"><path class=\"pv-stroke-ink\" d=\"M0 8h4.5M11.5 8H16\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"3.5\" fill=\"none\" stroke-width=\"1.5\"/></g>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"61\" font-size=\"15\">Committed files</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"352\" y=\"92\" font-size=\"15\">src/cart.ts</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"352\" y=\"116\" font-size=\"15\">.gitignore</text>\n  <text class=\"pv-fill-accent\" x=\"472\" y=\"116\" font-size=\"15\">ignores <tspan class=\"pv-mono\">dist/</tspan></text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"160\" font-size=\"15\">Source only</text>\n</svg>\n","alt":"Committed files that include src/cart.ts and dist/cart.min.js are machine noise. When the committed files are src/cart.ts and .gitignore, which ignores dist/, they are source only."},"guide":{"markdown":"## How to do it\n\n- Before you ask for a review, compare each changed path with the project’s ignore rules and documented generation steps. Tool output includes build folders, coverage reports, logs, minified bundles and editor files.\n- For output that the project does not track, add its path to the project’s ignore file.\n- Remove that output from Git tracking. For example, instead of leaving `dist/app.min.js` in the change, run `git rm --cached -- dist/app.min.js`.\n- Put the files that your own editor and operating system make in your personal ignore file. Then they never reach any repository.\n- For a generated file that the project tracks, follow its documented generation steps. Regeneration can be valid even when its source does not change.\n\n## When it does not apply\n\n- The change is empty.\n\nIt still applies when every file in the change is generated.\n\n## Common mistakes\n\n- Removing every generated file. Generated output is not wrong in itself. Some projects track it on purpose, such as a route tree or a diagram. Instead, check the project’s ignore rules and docs before you remove one.\n- Fixing a generated file by hand. The next run of the generator undoes your fix. Instead, change the source and regenerate. A banner such as `DO NOT EDIT` or `@generated` at the top tells you that a tool wrote the file.\n- Changing the source of a tracked generated file without regenerating it. The file then no longer matches its source. Instead, regenerate it in the same change.\n- Adding a path to the ignore file and expecting the tracked copy to go away. An ignore rule does not affect a file that is already tracked. Instead, also remove the file from tracking with `git rm --cached`.\n\n## Sources\n\n- [gitignore](https://git-scm.com/docs/gitignore), Git documentation. Ignore rules name intentionally untracked files, such as temporary editor files, and do not affect files that Git already tracks.\n- [What to look for in a code review](https://google.github.io/eng-practices/review/reviewer/looking-for.html), Google Engineering Practices. Reviewers can scan over generated code, but they read every line that a person wrote.\n- [Generate Go files by processing source](https://pkg.go.dev/cmd/go#hdr-Generate_Go_files_by_processing_source), Go documentation. A generated file carries a `DO NOT EDIT` line, and the build never runs the generator for you.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Track generated artifacts only when justified","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.core","stance":"REQUIRED"},{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: tracked generated or build artifacts are justified by captured repository policy or the source-to-artifact workflow.\n\n## The standard\nJudge one thing: does the change include generated or build artifacts only where the repository''s captured policy or its source-to-artifact workflow justifies tracking them? This is a repository-hygiene practice about what gets committed — never a code-defect claim about a file''s contents, and generated output is not itself the defect. Judge from the file paths in the diff. Machine noise being reviewed as if it were source has a recognisable shape across any stack or language — a location or a banner that says \"a tool wrote this\": a build-output directory, an editor or OS cruft file, a coverage dump, a vendored or cached blob, a minified single-line bundle, or a tracked generated file someone hand-edited instead of regenerating. These are open examples, not a closed list. A repository may deliberately version-control some generated sources — a committed OpenAPI spec, a generated client, an ERD, a route tree. When such a tracked artifact moves in step with the hand-written change that drives its regeneration, that is intended, regeneration-consistent movement: do not flag it. An intentional regeneration may be appropriate without a simultaneous hand-written edit. Flag only output that is not meant to be tracked, or a tracked generated file left hand-edited or stale relative to its source.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop only for an empty change. A change whose files are all generated still has content whose inclusion can be reviewed; it is judged, not ruled out.\n\n## Sources\n1. The file spread (`work/change/files.json`) and the per-file headers of the diff (`work/change/diff.patch`): the paths. They establish which paths changed and where they sit — the primary evidence. A path never establishes compile, build or runtime behaviour.\n2. The patch body (`work/change/diff.patch`): open it only to confirm a flagged path is machine-emitted when the path alone is ambiguous — a \"DO NOT EDIT\", \"@generated\" or \"auto-generated\" banner, a minified single line. The evidence is the path plus that confirming line, never a line-by-line review of the file''s contents.\n3. The checkout (`<repositoryRoot>`): the ignore rules, the documented generation workflow, and whether an artifact is tracked and which source drives it. It establishes whether tracking a generated file is intended. It never establishes manual editing or stale generation from an unchanged source file alone.\nIf the policy or source evidence a flag needs was not acquired, report a collection gap and record no observation.\n\n## Judge\nAssess conformance to the standard in this context.\n- NOT_MET: a quoted repository policy or an observable workflow establishes that an added artifact should not be tracked, or a tracked generated file was hand-edited or left stale relative to the source that drives it. Quote each offending path.\n- MET: a complete bounded search over every changed path establishes that the changed artifacts are appropriately tracked — every path is something a person authored or intended: source, tests, docs, hand-written config, a lockfile moving in step with its manifest, or a tracked generated artifact whose regeneration is justified by the captured workflow, with or without a simultaneous source edit.\n- UNDETERMINED when the one path this practice turns on is genuinely ambiguous — the path, any banner and the patch together cannot tell you whether it is machine-emitted, or whether tracking and regenerating that artifact is justified by the captured policy or workflow. Say so rather than let the doubt pass as a clean bill; name what would settle it. Having walked every path and found each justified is MET, not UNDETERMINED.\nOne observation per review, covering every flagged path.\n\n## Severity\nNOT_MET only; never above MAJOR on this practice alone — a practice to grow, not a merge gate. MINOR, the usual band: a lone stray artifact. MAJOR: a committed build-output directory, several leaked artifacts, or a hand-edited generated file that should have been regenerated. Identical situations land identically.\n\n## Grounding\nEvery NOT_MET names each offending path verbatim and, for a generated-file flag, quotes the confirming banner or names the tracked artifact and its driving source. If you cannot name an offending path there is nothing to flag; do not invent one. Cite a line of the flagged file from `work/change/diff.patch` (`scm.pull-request.diff`, the pinned `context/change.json`): `work/change/files.json` is derived here and is not citable; a flagged file the diff shows without numbered lines (binary, or renamed without edits) is cited through the `path` line of its entry in `context/commits.json`. For MET evidence.search records the boundary and the citations quote it: `changed_files` in `context/metadata.json` (`scm.pull-request.core`) and the paths you walked, listed in the rationale. Describe the observable fact (\"this path is machine-emitted\") and the next step (ignore it and drop it, or regenerate from source). Never assert compile, build or runtime behaviour from a path; never impute intent or character.\n\n## Defer\nWhether a dependency change was deliberate or justified belongs to `changes-dependencies-deliberately`; a lockfile moving in step with its manifest is its concern. Do not infer that a lockfile was hand-edited merely because its manifest did not change — an intentional resolution refresh may update a lockfile alone. Here only: does the diff carry machine output that should not be tracked?","precomputeScript":null,"automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A reviewer catches the most problems in the hand-written lines they can read closely, and a committed build output or editor config buries that source under machine noise nobody reviews. Leaving generated files out keeps the diff to the change a person can actually check, and spares everyone the odd conflict in a file no human wrote.","whatGoodLooksLike":"Build outputs, logs and editor files stay out of the repository. Deliberately tracked generated artifacts follow the documented generation workflow; intentional regeneration can be appropriate even without a simultaneous source edit.","groupSlug":"delivery-and-version-control-discipline","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 164\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Unwanted output committed</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(16 48)\"><path class=\"pv-stroke-ink\" d=\"M0 8h4.5M11.5 8H16\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"3.5\" fill=\"none\" stroke-width=\"1.5\"/></g>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"61\" font-size=\"15\">Committed files</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"16\" y=\"92\" font-size=\"15\">src/cart.ts</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"16\" y=\"116\" font-size=\"15\">dist/cart.min.js</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"160\" font-size=\"15\">Machine noise</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Unwanted output ignored</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(352 48)\"><path class=\"pv-stroke-ink\" d=\"M0 8h4.5M11.5 8H16\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"3.5\" fill=\"none\" stroke-width=\"1.5\"/></g>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"61\" font-size=\"15\">Committed files</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"352\" y=\"92\" font-size=\"15\">src/cart.ts</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"352\" y=\"116\" font-size=\"15\">.gitignore</text>\n  <text class=\"pv-fill-accent\" x=\"472\" y=\"116\" font-size=\"15\">ignores <tspan class=\"pv-mono\">dist/</tspan></text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"160\" font-size=\"15\">Source only</text>\n</svg>\n","alt":"Committed files that include src/cart.ts and dist/cart.min.js are machine noise. When the committed files are src/cart.ts and .gitignore, which ignores dist/, they are source only."},"guide":{"markdown":"## How to do it\n\n- Before you ask for a review, compare each changed path with the project’s ignore rules and documented generation steps. Tool output includes build folders, coverage reports, logs, minified bundles and editor files.\n- For output that the project does not track, add its path to the project’s ignore file.\n- Remove that output from Git tracking. For example, instead of leaving `dist/app.min.js` in the change, run `git rm --cached -- dist/app.min.js`.\n- Put the files that your own editor and operating system make in your personal ignore file. Then they never reach any repository.\n- For a generated file that the project tracks, follow its documented generation steps. Regeneration can be valid even when its source does not change.\n\n## When it does not apply\n\n- The change is empty.\n\nIt still applies when every file in the change is generated.\n\n## Common mistakes\n\n- Removing every generated file. Generated output is not wrong in itself. Some projects track it on purpose, such as a route tree or a diagram. Instead, check the project’s ignore rules and docs before you remove one.\n- Fixing a generated file by hand. The next run of the generator undoes your fix. Instead, change the source and regenerate. A banner such as `DO NOT EDIT` or `@generated` at the top tells you that a tool wrote the file.\n- Changing the source of a tracked generated file without regenerating it. The file then no longer matches its source. Instead, regenerate it in the same change.\n- Adding a path to the ignore file and expecting the tracked copy to go away. An ignore rule does not affect a file that is already tracked. Instead, also remove the file from tracking with `git rm --cached`.\n\n## Sources\n\n- [gitignore](https://git-scm.com/docs/gitignore), Git documentation. Ignore rules name intentionally untracked files, such as temporary editor files, and do not affect files that Git already tracks.\n- [What to look for in a code review](https://google.github.io/eng-practices/review/reviewer/looking-for.html), Google Engineering Practices. Reviewers can scan over generated code, but they read every line that a person wrote.\n- [Generate Go files by processing source](https://pkg.go.dev/cmd/go#hdr-Generate_Go_files_by_processing_source), Go documentation. A generated file carries a `DO NOT EDIT` line, and the build never runs the generator for you.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Tracked artifacts follow the repository generation policy"'::jsonb),'v5:8466011dfa551d1d78d55c7e5beb76bad9ac1747ef5dadbb411f001550a4512a','practice:v3:52e92ff32ee332e3d9f0b7a7d5a737bb46fd2463dd04aaec787bee16e762ba0b');
INSERT INTO _cutover_bundle VALUES('GROUP','issue-traceability-and-lifecycle',NULL,'{"name":"Tracking work from issue to merge","description":"Plan and track the work so a maintainer can route it and watch it progress, and keep the issue and the change that answers it linked: split genuinely large issues into trackable sub-tasks, triage each one, name the issue the change implements, and confirm the issue''s outcome when the change lands.","icon":"ListChecks","color":"indigo"}'::jsonb,'{"name":"Tracking work from issue to merge","description":"Plan and track the work so a maintainer can route it and watch it progress, and keep the issue and the change that answers it linked: split genuinely large issues into trackable sub-tasks, triage each one, name the issue the change implements, and confirm the issue''s outcome when the change lands.","icon":"ListChecks","color":"indigo"}'::jsonb,'fe655adf64b5b29a37a0c76c24d480f27c5dfc5d7dbbbc4536286ec8da96fc16','group:v1:fe655adf64b5b29a37a0c76c24d480f27c5dfc5d7dbbbc4536286ec8da96fc16');
INSERT INTO _cutover_bundle VALUES('PRACTICE','breaks-large-work-into-trackable-subtasks','scm.issue','{"name":"Break large work into trackable subtasks","signals":["scm.issue.closed","scm.issue.opened","scm.issue.updated"],"evidenceRequirements":[{"sourceKind":"scm.issue.comments","stance":"EXHAUSTIVE"},{"sourceKind":"scm.issue.core","stance":"EXHAUSTIVE"}],"reviewWhen":{},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured issue: its title, description, labels and the discussion the practice names. Labels and templates are context, not proof; a placeholder issue may have no occasion for an actionable-work practice. Do not infer that a bug reproduces or that an outcome was implemented.\n\nFor a practice about requested work, establish the current request from the complete issue body and the discussion the practice names. Brief, vague or title-only requests still pass this premise.\n\nWhen genuinely conflicting current statements leave that request unresolved, record UNDETERMINED for the request-dependent judgment, cite the conflict, and judge neither statement under the standard. Position or date alone does not resolve it. If an explicit authored withdrawal leaves no work requested, record NOT_APPLICABLE for that judgment and treat earlier requirements as history. Judge a remaining request under the practice''s standard. Historical and closure practices retain their own subjects, including accounting for dropped or deferred work.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: a trackable breakdown of work that is large enough to need one — checkable sub-units a maintainer can watch reach done, rather than one monolithic ask.\n\n## The standard\nJudge ONE thing: when the issue describes genuinely LARGE or multi-part work, is that work broken into explicit, trackable sub-units, rather than left as a single undivided block? Trackable means the parts are individually checkable or addressable: a task list of checkboxes that name work to do, a tracked sub-issue tree, or enumerated child or tracking issues the body frames as parts. Reason like a senior reviewer scanning a backlog: a big ask written as one block is either 0% or 100% done with no visible progress; a decomposed one lets pieces be picked up in parallel and tracked to done. What counts as LARGE is a judgment, not a word count: the signal is two or more SEPARABLE deliverables that could ship or be assigned independently, or an explicit epic, initiative, meta or tracking framing the issue itself chose. Largeness comes from what the parts are, never from how many items, clauses or characters there are: independent deliverables listed in one short sentence — a rename, a new tab, a theme, a changed default — are large work, while the sections, topics or checks of one page, screen or feature are parts of one deliverable, not separate work. Sequential steps of ONE cohesive flow described as a journey are a single deliverable, not several parts. A checklist of verification items is not a work breakdown unless it also names concrete implementation sub-steps.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the case, and stop when: the issue is a pure question, a support request or an open discussion with no concrete deliverable; the body is empty, title-only or an unmodified template, so nothing is quotable; or the work is a focused single-concern deliverable (one feature, one bug), which neither needs a breakdown nor is penalised for lacking one. Never manufacture a strength from the mere absence of largeness, and never make the single-concern scope judgment here — that belongs to `issue-scoped-to-single-concern`.\n\n## Sources\nYour context is the issue only; there is no diff or code.\n1. The title and the WHOLE body (`context/description.md`): every section, checklist and enumerated list. It establishes whether the work is large (separable deliverables, epic framing) and whether a checklist or a set of framed child issues breaks it down. It never establishes largeness from title length or tone alone.\n2. The labels and the sub-issue rollup (`context/metadata.json`): a label such as epic or tracking, and the `sub_issues_total` / `sub_issues_completed` figures. A non-zero rollup is a tracked sub-issue tree; a null or missing figure is unknown, never zero. The labels establish the framing the issue chose; they never by themselves establish that a breakdown exists.\n3. The comments (`context/comments.json`): a later comment can supply the breakdown or the child issues. They establish a breakdown on that surface; they never establish one the text does not show.\nAn image in the body: read its caption and the sentence around it. An external link: nothing. Before concluding that no breakdown exists, scan ALL three surfaces. If the body or the comments were not captured, report a collection gap and record no observation.\n\n## Judge\nThese conformance cases apply after the shared issue premise establishes a current request.\n- MET: the work is genuinely large AND a trackable breakdown is quotable — named sub-steps as a checklist (\"design the schema\", \"add the endpoint\", \"wire up the UI\"), a non-zero sub-issue rollup, or child issues the body frames as parts. Sibling issues in the project inventory that this body never names are not its breakdown, however well they match its sentences.\n- NOT_MET: the work is clearly large AND the captured body and comments contain no trackable breakdown, with a reported zero sub-issue rollup. This establishes absence across the three surfaces; an unreported or null rollup does not.\n- UNDETERMINED when no trackable breakdown is quotable and either the text cannot settle whether its spans are one journey or several separable deliverables, or the work is large and its sub-issue rollup is unknown. Cite the ambiguity or unknown source fact and say what would settle it.\nOne observation per review, over the whole issue. Identical evidence yields the same call.\n\n## Severity\nNOT_MET only; never above MAJOR on decomposition alone — a non-blocking workflow practice, not a merge gate. MINOR, the usual band: only a couple of parts go untracked, and a short checklist would fix it. MAJOR: an issue the text itself frames as an epic, initiative, meta or tracking issue has nothing tracked under it at all.\n\n## Grounding\nEvery \"large\" claim and every \"no breakdown\" claim quotes the exact span: a label name, a body sentence naming each separable deliverable, the rollup figure, or a comment. For MET, quote the checklist lines, the rollup figure or the framed child references. For NOT_MET, cite the spans that establish largeness and name the boundary searched: the body, the rollup, and the comments. Never invent largeness, never fabricate a breakdown you did not see. Never assert technical feasibility, hour estimates or design correctness, and never grade the reporter as a person; describe the observable artifact state only.\n\n## Defer\nWhether the work SHOULD have been one concern belongs to `issue-scoped-to-single-concern`; treat a multi-part ask as legitimately large work needing a breakdown, and do not re-judge its scope. Whether acceptance criteria or a Definition of Done are present belongs to `issue-has-checkable-outcome`; do not re-flag a verification checklist here. Here only: is large work DECOMPOSED into trackable parts?","precomputeScript":"// Precompute FACTS for breaks-large-work-into-trackable-subtasks: the task-list items and issue-number\n// mentions the body carries, its labels, and the captured sub-issue rollup with its source. Whether the\n// work is large and whether it is broken down are the criteria''s to decide from the text.\nimport {\n\tbodyFact,\n\tclassifyIssue,\n\tsubIssueRollup,\n\ttype IssueMetadata,\n} from \"../lib/issue-classification.ts\";\nimport { checkableItems } from \"../lib/review.ts\";\nimport type { Hint } from \"../lib/types.ts\";\n\nexport default function breaksLargeWorkIntoTrackableSubtasks(\n\t_repo: string,\n\t_diff: Map<string, unknown>,\n\tm: IssueMetadata,\n) {\n\tconst shape = classifyIssue(m);\n\tconst { body, labels } = shape;\n\tconst items = checkableItems(body);\n\tconst checked = items.filter((item) => item.checked).length;\n\tconst issueMentions = new Set((body.match(/(?:^|\\s)#\\d+\\b/gu) ?? []).map((s) => s.trim())).size;\n\tconst rollup = subIssueRollup(m);\n\n\tconst directions = [\n\t\t...bodyFact(shape),\n\t\t`Captured: ${String(items.length)} task-list item(s) (${String(checked)} ticked), ${String(issueMentions)} issue-number mention(s), ${rollup.text}; labels ${labels.join(\", \") || \"none\"}. Judge the standard once: whether the work is large and whether these items or mentions break it down is read from what they say, never from how many there are.`,\n\t];\n\n\tconst hints: Hint[] = [];\n\treturn {\n\t\thints,\n\t\tmetrics: {\n\t\t\tbodyLength: body.length,\n\t\t\ttaskCheckboxes: items.length,\n\t\t\tchildIssueRefs: issueMentions,\n\t\t\t...rollup.metrics,\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"IMPLEMENTATION_NOT_OBSERVED","description":"Issue evidence does not establish whether the described work was implemented correctly."}],"insufficiencyReason":null},"whyItMatters":"A big ask written as one wall of text is either 0% or 100% done, with no way to see progress or split the load. Breaking it into checkable steps turns a daunting job into pieces people can pick up and finish one at a time.","whatGoodLooksLike":"A genuinely large issue split into a task list or linked sub-issues, such as ''design the schema'', ''add the endpoint'', and ''wire up the UI'', so progress is visible and pieces can be worked in parallel.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 188\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">One big ask</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"126.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(16 48)\"><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"6.75\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-fill-ink\" cx=\"8\" cy=\"8\" r=\"1.75\"/></g>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"61\" font-size=\"15\">Issue #42</text>\n  <text class=\"pv-fill-muted\" x=\"16\" y=\"93\" font-size=\"15\">Schema, endpoint and UI</text>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"110\" width=\"256\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"122\" width=\"224\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"134\" width=\"168\" height=\"6\" rx=\"3\"/>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"184\" font-size=\"15\">All or nothing</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Checkable steps</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"302.5\" height=\"126.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(352 48)\"><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"6.75\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-fill-ink\" cx=\"8\" cy=\"8\" r=\"1.75\"/></g>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"61\" font-size=\"15\">Issue #42</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"352.75\" y=\"80.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <path class=\"pv-stroke-ink\" d=\"M356 88.5l3 3 5.5-6\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <text class=\"pv-fill-accent\" x=\"380\" y=\"93\" font-size=\"15\">Schema</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"352.75\" y=\"104.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"380\" y=\"117\" font-size=\"15\">Endpoint</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"352.75\" y=\"128.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"380\" y=\"141\" font-size=\"15\">UI</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"184\" font-size=\"15\">Progress shows</text>\n</svg>\n","alt":"One big ask puts “Schema, endpoint and UI” in Issue #42 as one block of text, so it is all or nothing. Checkable steps list Schema, Endpoint and UI in Issue #42, one of them ticked, so progress shows."},"guide":{"markdown":"## How to do it\n\n- Before you file a big issue, list the parts that someone could ship or pick up on their own.\n- Give each part its own check box, or open it as a child issue. For example, instead of one line that asks for “export, settings and alerts”, write three check boxes. Name them “Add the export”, “Add the settings page” and “Send the alerts”.\n- Name the work to do in each item, so that anyone can tell when it’s done.\n- If the issue is an epic or a tracking issue, give its work a task list or child issues.\n- If you find the parts later, add a task list or child-issue links to the issue body or a comment.\n\n## When it does not apply\n\n- The issue asks a question, asks for support or opens a discussion, and asks for no concrete work.\n- The issue body is empty, has only a title or is an unchanged template.\n- The issue asks for one focused piece of work, such as one feature or one bug fix.\n\nIt still applies when one short sentence asks for several separate things, such as a rename, a new tab and a new default.\n\n## Common mistakes\n\n- Judging size by the length of the issue. Instead, look at the parts. Two or more parts that could ship or go to different people are large work, even in one line.\n- Writing the parts as one paragraph. Instead, give each part its own check box or child issue, so each one can reach done on its own.\n- Labeling an issue as an epic with nothing under it. Instead, add the task list or link the child issues when you open it.\n- Treating a list of checks as the plan. A list of things to verify does not say what to build. Instead, add the steps of the work, such as “add the endpoint”.\n\n## Sources\n\n- [Adding sub-issues](https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/adding-sub-issues), GitHub Docs. Sub-issues break larger work into tasks, and the parent issue shows their progress.\n- [Tasks](https://docs.gitlab.com/user/tasks/), GitLab Docs. Tasks break an issue into smaller items that you can track and assign, and the issue shows their progress.\n- [INVEST in good stories, and SMART tasks](https://xp123.com/invest-in-good-stories-and-smart-tasks/), Bill Wake, 2003. A good task makes clear what work it involves and what the team means by done.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Break large work into trackable subtasks","signals":["scm.issue.closed","scm.issue.opened","scm.issue.updated"],"evidenceRequirements":[{"sourceKind":"scm.issue.comments","stance":"EXHAUSTIVE"},{"sourceKind":"scm.issue.core","stance":"EXHAUSTIVE"}],"reviewWhen":{},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured issue: its title, description, labels and the discussion the practice names. Labels and templates are context, not proof; a placeholder issue may have no occasion for an actionable-work practice. Do not infer that a bug reproduces or that an outcome was implemented.\n\nFor a practice about requested work, establish the current request from the complete issue body and the discussion the practice names. Brief, vague or title-only requests still pass this premise.\n\nWhen genuinely conflicting current statements leave that request unresolved, record UNDETERMINED for the request-dependent judgment, cite the conflict, and judge neither statement under the standard. Position or date alone does not resolve it. If an explicit authored withdrawal leaves no work requested, record NOT_APPLICABLE for that judgment and treat earlier requirements as history. Judge a remaining request under the practice''s standard. Historical and closure practices retain their own subjects, including accounting for dropped or deferred work.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: a trackable breakdown of work that is large enough to need one — checkable sub-units a maintainer can watch reach done, rather than one monolithic ask.\n\n## The standard\nJudge ONE thing: when the issue describes genuinely LARGE or multi-part work, is that work broken into explicit, trackable sub-units, rather than left as a single undivided block? Trackable means the parts are individually checkable or addressable: a task list of checkboxes that name work to do, a tracked sub-issue tree, or enumerated child or tracking issues the body frames as parts. Reason like a senior reviewer scanning a backlog: a big ask written as one block is either 0% or 100% done with no visible progress; a decomposed one lets pieces be picked up in parallel and tracked to done. What counts as LARGE is a judgment, not a word count: the signal is two or more SEPARABLE deliverables that could ship or be assigned independently, or an explicit epic, initiative, meta or tracking framing the issue itself chose. Largeness comes from what the parts are, never from how many items, clauses or characters there are: independent deliverables listed in one short sentence — a rename, a new tab, a theme, a changed default — are large work, while the sections, topics or checks of one page, screen or feature are parts of one deliverable, not separate work. Sequential steps of ONE cohesive flow described as a journey are a single deliverable, not several parts. A checklist of verification items is not a work breakdown unless it also names concrete implementation sub-steps.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the case, and stop when: the issue is a pure question, a support request or an open discussion with no concrete deliverable; the body is empty, title-only or an unmodified template, so nothing is quotable; or the work is a focused single-concern deliverable (one feature, one bug), which neither needs a breakdown nor is penalised for lacking one. Never manufacture a strength from the mere absence of largeness, and never make the single-concern scope judgment here — that belongs to `issue-scoped-to-single-concern`.\n\n## Sources\nYour context is the issue only; there is no diff or code.\n1. The title and the WHOLE body (`context/description.md`): every section, checklist and enumerated list. It establishes whether the work is large (separable deliverables, epic framing) and whether a checklist or a set of framed child issues breaks it down. It never establishes largeness from title length or tone alone.\n2. The labels and the sub-issue rollup (`context/metadata.json`): a label such as epic or tracking, and the `sub_issues_total` / `sub_issues_completed` figures. A non-zero rollup is a tracked sub-issue tree; a null or missing figure is unknown, never zero. The labels establish the framing the issue chose; they never by themselves establish that a breakdown exists.\n3. The comments (`context/comments.json`): a later comment can supply the breakdown or the child issues. They establish a breakdown on that surface; they never establish one the text does not show.\nAn image in the body: read its caption and the sentence around it. An external link: nothing. Before concluding that no breakdown exists, scan ALL three surfaces. If the body or the comments were not captured, report a collection gap and record no observation.\n\n## Judge\nThese conformance cases apply after the shared issue premise establishes a current request.\n- MET: the work is genuinely large AND a trackable breakdown is quotable — named sub-steps as a checklist (\"design the schema\", \"add the endpoint\", \"wire up the UI\"), a non-zero sub-issue rollup, or child issues the body frames as parts. Sibling issues in the project inventory that this body never names are not its breakdown, however well they match its sentences.\n- NOT_MET: the work is clearly large AND the captured body and comments contain no trackable breakdown, with a reported zero sub-issue rollup. This establishes absence across the three surfaces; an unreported or null rollup does not.\n- UNDETERMINED when no trackable breakdown is quotable and either the text cannot settle whether its spans are one journey or several separable deliverables, or the work is large and its sub-issue rollup is unknown. Cite the ambiguity or unknown source fact and say what would settle it.\nOne observation per review, over the whole issue. Identical evidence yields the same call.\n\n## Severity\nNOT_MET only; never above MAJOR on decomposition alone — a non-blocking workflow practice, not a merge gate. MINOR, the usual band: only a couple of parts go untracked, and a short checklist would fix it. MAJOR: an issue the text itself frames as an epic, initiative, meta or tracking issue has nothing tracked under it at all.\n\n## Grounding\nEvery \"large\" claim and every \"no breakdown\" claim quotes the exact span: a label name, a body sentence naming each separable deliverable, the rollup figure, or a comment. For MET, quote the checklist lines, the rollup figure or the framed child references. For NOT_MET, cite the spans that establish largeness and name the boundary searched: the body, the rollup, and the comments. Never invent largeness, never fabricate a breakdown you did not see. Never assert technical feasibility, hour estimates or design correctness, and never grade the reporter as a person; describe the observable artifact state only.\n\n## Defer\nWhether the work SHOULD have been one concern belongs to `issue-scoped-to-single-concern`; treat a multi-part ask as legitimately large work needing a breakdown, and do not re-judge its scope. Whether acceptance criteria or a Definition of Done are present belongs to `issue-has-checkable-outcome`; do not re-flag a verification checklist here. Here only: is large work DECOMPOSED into trackable parts?","precomputeScript":"// Precompute FACTS for breaks-large-work-into-trackable-subtasks: the task-list items and issue-number\n// mentions the body carries, its labels, and the captured sub-issue rollup with its source. Whether the\n// work is large and whether it is broken down are the criteria''s to decide from the text.\nimport {\n\tbodyFact,\n\tclassifyIssue,\n\tsubIssueRollup,\n\ttype IssueMetadata,\n} from \"../lib/issue-classification.ts\";\nimport { checkableItems } from \"../lib/review.ts\";\nimport type { Hint } from \"../lib/types.ts\";\n\nexport default function breaksLargeWorkIntoTrackableSubtasks(\n\t_repo: string,\n\t_diff: Map<string, unknown>,\n\tm: IssueMetadata,\n) {\n\tconst shape = classifyIssue(m);\n\tconst { body, labels } = shape;\n\tconst items = checkableItems(body);\n\tconst checked = items.filter((item) => item.checked).length;\n\tconst issueMentions = new Set((body.match(/(?:^|\\s)#\\d+\\b/gu) ?? []).map((s) => s.trim())).size;\n\tconst rollup = subIssueRollup(m);\n\n\tconst directions = [\n\t\t...bodyFact(shape),\n\t\t`Captured: ${String(items.length)} task-list item(s) (${String(checked)} ticked), ${String(issueMentions)} issue-number mention(s), ${rollup.text}; labels ${labels.join(\", \") || \"none\"}. Judge the standard once: whether the work is large and whether these items or mentions break it down is read from what they say, never from how many there are.`,\n\t];\n\n\tconst hints: Hint[] = [];\n\treturn {\n\t\thints,\n\t\tmetrics: {\n\t\t\tbodyLength: body.length,\n\t\t\ttaskCheckboxes: items.length,\n\t\t\tchildIssueRefs: issueMentions,\n\t\t\t...rollup.metrics,\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"IMPLEMENTATION_NOT_OBSERVED","description":"Issue evidence does not establish whether the described work was implemented correctly."}],"insufficiencyReason":null},"whyItMatters":"A big ask written as one wall of text is either 0% or 100% done, with no way to see progress or split the load. Breaking it into checkable steps turns a daunting job into pieces people can pick up and finish one at a time.","whatGoodLooksLike":"A genuinely large issue split into a task list or linked sub-issues, such as ''design the schema'', ''add the endpoint'', and ''wire up the UI'', so progress is visible and pieces can be worked in parallel.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 188\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">One big ask</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"126.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(16 48)\"><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"6.75\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-fill-ink\" cx=\"8\" cy=\"8\" r=\"1.75\"/></g>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"61\" font-size=\"15\">Issue #42</text>\n  <text class=\"pv-fill-muted\" x=\"16\" y=\"93\" font-size=\"15\">Schema, endpoint and UI</text>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"110\" width=\"256\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"122\" width=\"224\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"134\" width=\"168\" height=\"6\" rx=\"3\"/>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"184\" font-size=\"15\">All or nothing</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Checkable steps</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"302.5\" height=\"126.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(352 48)\"><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"6.75\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-fill-ink\" cx=\"8\" cy=\"8\" r=\"1.75\"/></g>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"61\" font-size=\"15\">Issue #42</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"352.75\" y=\"80.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <path class=\"pv-stroke-ink\" d=\"M356 88.5l3 3 5.5-6\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <text class=\"pv-fill-accent\" x=\"380\" y=\"93\" font-size=\"15\">Schema</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"352.75\" y=\"104.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"380\" y=\"117\" font-size=\"15\">Endpoint</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"352.75\" y=\"128.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"380\" y=\"141\" font-size=\"15\">UI</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"184\" font-size=\"15\">Progress shows</text>\n</svg>\n","alt":"One big ask puts “Schema, endpoint and UI” in Issue #42 as one block of text, so it is all or nothing. Checkable steps list Schema, Endpoint and UI in Issue #42, one of them ticked, so progress shows."},"guide":{"markdown":"## How to do it\n\n- Before you file a big issue, list the parts that someone could ship or pick up on their own.\n- Give each part its own check box, or open it as a child issue. For example, instead of one line that asks for “export, settings and alerts”, write three check boxes. Name them “Add the export”, “Add the settings page” and “Send the alerts”.\n- Name the work to do in each item, so that anyone can tell when it’s done.\n- If the issue is an epic or a tracking issue, give its work a task list or child issues.\n- If you find the parts later, add a task list or child-issue links to the issue body or a comment.\n\n## When it does not apply\n\n- The issue asks a question, asks for support or opens a discussion, and asks for no concrete work.\n- The issue body is empty, has only a title or is an unchanged template.\n- The issue asks for one focused piece of work, such as one feature or one bug fix.\n\nIt still applies when one short sentence asks for several separate things, such as a rename, a new tab and a new default.\n\n## Common mistakes\n\n- Judging size by the length of the issue. Instead, look at the parts. Two or more parts that could ship or go to different people are large work, even in one line.\n- Writing the parts as one paragraph. Instead, give each part its own check box or child issue, so each one can reach done on its own.\n- Labeling an issue as an epic with nothing under it. Instead, add the task list or link the child issues when you open it.\n- Treating a list of checks as the plan. A list of things to verify does not say what to build. Instead, add the steps of the work, such as “add the endpoint”.\n\n## Sources\n\n- [Adding sub-issues](https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/adding-sub-issues), GitHub Docs. Sub-issues break larger work into tasks, and the parent issue shows their progress.\n- [Tasks](https://docs.gitlab.com/user/tasks/), GitLab Docs. Tasks break an issue into smaller items that you can track and assign, and the issue shows their progress.\n- [INVEST in good stories, and SMART tasks](https://xp123.com/invest-in-good-stories-and-smart-tasks/), Bill Wake, 2003. A good task makes clear what work it involves and what the team means by done.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Large work arrives split into trackable pieces"'::jsonb),'v5:e643bb892f0d779eff2981f5817a220ada7799ca5eabcbd8bd86adbc27b902ff','practice:v3:46780c1c972ee3c7a9ee41091b3d15e22cf833ab8c4a1549c98e8a7a4566390c');
INSERT INTO _cutover_bundle VALUES('PRACTICE','triages-the-issue-with-labels-and-ownership','scm.issue','{"name":"Classify the issue the way the project classifies issues","signals":["scm.issue.opened","scm.issue.updated"],"evidenceRequirements":[{"sourceKind":"scm.issue.core","stance":"REQUIRED"}],"reviewWhen":{},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured issue: its title, description, labels and the discussion the practice names. Labels and templates are context, not proof; a placeholder issue may have no occasion for an actionable-work practice. Do not infer that a bug reproduces or that an outcome was implemented.\n\nFor a practice about requested work, establish the current request from the complete issue body and the discussion the practice names. Brief, vague or title-only requests still pass this premise.\n\nWhen genuinely conflicting current statements leave that request unresolved, record UNDETERMINED for the request-dependent judgment, cite the conflict, and judge neither statement under the standard. Position or date alone does not resolve it. If an explicit authored withdrawal leaves no work requested, record NOT_APPLICABLE for that judgment and treat earlier requirements as history. Judge a remaining request under the practice''s standard. Historical and closure practices retain their own subjects, including accounting for dropped or deferred work.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the issue satisfies the classification requirements of the documented project policy applicable to it.\n\n## The standard\nJudge whether this issue follows the labelling convention the project actually keeps, not whether every metadata field is filled. A convention must be established by an explicit documented project policy applicable to this kind of issue. Label frequency, a list of labels in use or another issue''s assignment does not establish a requirement. Compare the captured issue with that policy: require only the label kinds, native type, ownership or milestone it actually mandates. A native issue type can satisfy a corresponding label kind. Never demand a classification the project does not use.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE when a captured project policy establishes that no classification requirement applies to this kind of issue. Missing policy is not evidence of no convention. Current automated capture does not supply project classification requirements, so this practice is unavailable for automated review. In a manual review, use the documented policy; failed acquisition of required policy or metadata is a collection gap.\n\n## Sources\n1. The documented project classification policy supplied to the manual review: applicable label kinds, native issue types, ownership and milestone requirements. It establishes what this issue is required to carry, not how often metadata happens to occur elsewhere.\n2. The issue metadata (`context/metadata.json`): native type, labels, assignees and milestone. It establishes what this issue carries.\n3. The title and body (`context/description.md`): the issue kind and any explicit routing request. A request alone does not establish a project-wide rule.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: every classification requirement applicable under the captured policy is satisfied. Quote the policy and corresponding metadata.\n- NOT_MET: an applicable policy requirement is not satisfied. Quote the requirement and the complete metadata that lacks it.\n- UNDETERMINED: complete supplied policy or metadata leaves the applicability of a deciding requirement genuinely ambiguous; name what would settle it. Missing required acquisition produces no observation.\nOne observation per review, over the whole issue.\n\n## Severity\nNOT_MET only; never above MINOR — non-blocking feedback about routing, not a merge gate. MINOR: no label at all in a labelled project, or the body asks to be routed and no label answers it. INFO: one kind of several missing.\n\n## Grounding\nQuote the applicable documented requirement and this issue''s metadata. Never infer a normative convention from label frequency, labels in use, ownership on other issues or the number of people in a project. Never assess whether the work is worth doing.\n\n## Defer\nProblem framing belongs to `issue-states-an-actionable-problem`, scope to `issue-scoped-to-single-concern`, and the definition of done to `issue-has-checkable-outcome`. Here only: is the issue classified the way this project classifies its issues?","precomputeScript":null,"automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"DECLARED_EVIDENCE_INSUFFICIENT"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"IMPLEMENTATION_NOT_OBSERVED","description":"Issue evidence does not establish whether the described work was implemented correctly."}],"insufficiencyReason":{"code":"PROJECT_CLASSIFICATION_SCHEME_NOT_CAPTURED","description":"Hephaestus captures the issue metadata, but not the project classification requirements that establish which labels, owners or milestones this issue should carry. Labels used elsewhere do not establish a required convention. A person with the project policy can assess this practice."}},"whyItMatters":"A label kind the project filters and groups by — type, priority, size — routes the issue to the board column, the person and the sprint it belongs to. An issue outside that scheme is the one nobody''s filter shows, so it waits.","whatGoodLooksLike":"The issue carries the labels, native type, owner or milestone required by the documented project policy for its kind; fields that the policy does not require may remain unset.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 164\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Unclassified</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(16 48)\"><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"6.75\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-fill-ink\" cx=\"8\" cy=\"8\" r=\"1.75\"/></g>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"61\" font-size=\"15\">Issue</text>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"80\" width=\"232\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"16.75\" y=\"96.75\" width=\"94.5\" height=\"22.5\" rx=\"8\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/>\n  <text class=\"pv-fill-muted\" x=\"28\" y=\"113\" font-size=\"15\">No labels</text>\n  <text class=\"pv-fill-muted\" x=\"168\" y=\"113\" font-size=\"15\">No owner</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"160\" font-size=\"15\">Waits unseen</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Classified</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(352 48)\"><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"6.75\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-fill-ink\" cx=\"8\" cy=\"8\" r=\"1.75\"/></g>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"61\" font-size=\"15\">Issue</text>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"80\" width=\"232\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-surface pv-stroke-accent\" x=\"352.75\" y=\"96.75\" width=\"46.5\" height=\"22.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"364\" y=\"113\" font-size=\"15\">Bug</text>\n  <rect class=\"pv-fill-surface pv-stroke-accent\" x=\"408.75\" y=\"96.75\" width=\"70.5\" height=\"22.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"420\" y=\"113\" font-size=\"15\">Urgent</text>\n  <text class=\"pv-fill-accent\" x=\"504\" y=\"113\" font-size=\"15\">Owner @ada</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"160\" font-size=\"15\">Gets routed</text>\n</svg>\n","alt":"An unclassified issue has no labels and no owner, so it waits unseen. A classified issue carries Bug, Urgent and Owner @ada, so it gets routed."},"guide":{"markdown":"## How to do it\n\n- Find the project’s written policy for classifying issues. It often lives in a contributing guide or a triage page.\n- For your kind of issue, set each label kind that the policy requires, such as type, priority or size.\n- If the policy requires an issue type, set the built-in type or the type label that the policy accepts.\n- If the policy requires an owner or a milestone for your kind of issue, set it.\n- If the policy requires a team label for the issue, add it. For example, instead of only asking “Can the network team look at this?”, add the required network label.\n\n## When it does not apply\n\n- The project’s written policy says that this kind of issue needs no labels, type, owner or milestone.\n\nA missing policy does not tell you whether classification requirements apply.\n\n## Common mistakes\n\n- Filling in every field you can see. The practice does not ask for that. Instead, set only what the policy asks for on this kind of issue. Fields that it does not ask for can stay empty.\n- Copying the labels that other issues carry. A label that many issues use is not a rule. Instead, check what the written policy asks for.\n- Picking a kind that does not match the issue, such as labelling a support question as a bug. Instead, pick the kind that the policy defines for this work. If you are not sure, ask a maintainer.\n\n## Sources\n\n- [Issue triage](https://handbook.gitlab.com/handbook/product-development/how-we-work/issue-triage/), GitLab Handbook. GitLab’s written policy asks for type and group labels, plus a severity label for bugs.\n- [Issue triage guidelines](https://www.kubernetes.dev/docs/guide/issue-triage/), Kubernetes contributor guide. Kubernetes uses kind, priority and owning-group labels, and an issue with no priority label has not been prioritized.\n- [Best practices for Projects](https://docs.github.com/en/issues/planning-and-tracking-with-projects/learning-about-projects/best-practices-for-projects), GitHub Docs. GitHub suggests issue types to classify work and assignees to show who is responsible.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Classify the issue the way the project classifies issues","signals":["scm.issue.opened","scm.issue.updated"],"evidenceRequirements":[{"sourceKind":"scm.issue.core","stance":"REQUIRED"}],"reviewWhen":{},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured issue: its title, description, labels and the discussion the practice names. Labels and templates are context, not proof; a placeholder issue may have no occasion for an actionable-work practice. Do not infer that a bug reproduces or that an outcome was implemented.\n\nFor a practice about requested work, establish the current request from the complete issue body and the discussion the practice names. Brief, vague or title-only requests still pass this premise.\n\nWhen genuinely conflicting current statements leave that request unresolved, record UNDETERMINED for the request-dependent judgment, cite the conflict, and judge neither statement under the standard. Position or date alone does not resolve it. If an explicit authored withdrawal leaves no work requested, record NOT_APPLICABLE for that judgment and treat earlier requirements as history. Judge a remaining request under the practice''s standard. Historical and closure practices retain their own subjects, including accounting for dropped or deferred work.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the issue satisfies the classification requirements of the documented project policy applicable to it.\n\n## The standard\nJudge whether this issue follows the labelling convention the project actually keeps, not whether every metadata field is filled. A convention must be established by an explicit documented project policy applicable to this kind of issue. Label frequency, a list of labels in use or another issue''s assignment does not establish a requirement. Compare the captured issue with that policy: require only the label kinds, native type, ownership or milestone it actually mandates. A native issue type can satisfy a corresponding label kind. Never demand a classification the project does not use.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE when a captured project policy establishes that no classification requirement applies to this kind of issue. Missing policy is not evidence of no convention. Current automated capture does not supply project classification requirements, so this practice is unavailable for automated review. In a manual review, use the documented policy; failed acquisition of required policy or metadata is a collection gap.\n\n## Sources\n1. The documented project classification policy supplied to the manual review: applicable label kinds, native issue types, ownership and milestone requirements. It establishes what this issue is required to carry, not how often metadata happens to occur elsewhere.\n2. The issue metadata (`context/metadata.json`): native type, labels, assignees and milestone. It establishes what this issue carries.\n3. The title and body (`context/description.md`): the issue kind and any explicit routing request. A request alone does not establish a project-wide rule.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: every classification requirement applicable under the captured policy is satisfied. Quote the policy and corresponding metadata.\n- NOT_MET: an applicable policy requirement is not satisfied. Quote the requirement and the complete metadata that lacks it.\n- UNDETERMINED: complete supplied policy or metadata leaves the applicability of a deciding requirement genuinely ambiguous; name what would settle it. Missing required acquisition produces no observation.\nOne observation per review, over the whole issue.\n\n## Severity\nNOT_MET only; never above MINOR — non-blocking feedback about routing, not a merge gate. MINOR: no label at all in a labelled project, or the body asks to be routed and no label answers it. INFO: one kind of several missing.\n\n## Grounding\nQuote the applicable documented requirement and this issue''s metadata. Never infer a normative convention from label frequency, labels in use, ownership on other issues or the number of people in a project. Never assess whether the work is worth doing.\n\n## Defer\nProblem framing belongs to `issue-states-an-actionable-problem`, scope to `issue-scoped-to-single-concern`, and the definition of done to `issue-has-checkable-outcome`. Here only: is the issue classified the way this project classifies its issues?","precomputeScript":null,"automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"DECLARED_EVIDENCE_INSUFFICIENT"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"IMPLEMENTATION_NOT_OBSERVED","description":"Issue evidence does not establish whether the described work was implemented correctly."}],"insufficiencyReason":{"code":"PROJECT_CLASSIFICATION_SCHEME_NOT_CAPTURED","description":"Hephaestus captures the issue metadata, but not the project classification requirements that establish which labels, owners or milestones this issue should carry. Labels used elsewhere do not establish a required convention. A person with the project policy can assess this practice."}},"whyItMatters":"A label kind the project filters and groups by — type, priority, size — routes the issue to the board column, the person and the sprint it belongs to. An issue outside that scheme is the one nobody''s filter shows, so it waits.","whatGoodLooksLike":"The issue carries the labels, native type, owner or milestone required by the documented project policy for its kind; fields that the policy does not require may remain unset.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 164\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Unclassified</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(16 48)\"><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"6.75\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-fill-ink\" cx=\"8\" cy=\"8\" r=\"1.75\"/></g>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"61\" font-size=\"15\">Issue</text>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"80\" width=\"232\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"16.75\" y=\"96.75\" width=\"94.5\" height=\"22.5\" rx=\"8\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/>\n  <text class=\"pv-fill-muted\" x=\"28\" y=\"113\" font-size=\"15\">No labels</text>\n  <text class=\"pv-fill-muted\" x=\"168\" y=\"113\" font-size=\"15\">No owner</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"160\" font-size=\"15\">Waits unseen</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Classified</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(352 48)\"><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"6.75\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-fill-ink\" cx=\"8\" cy=\"8\" r=\"1.75\"/></g>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"61\" font-size=\"15\">Issue</text>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"80\" width=\"232\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-surface pv-stroke-accent\" x=\"352.75\" y=\"96.75\" width=\"46.5\" height=\"22.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"364\" y=\"113\" font-size=\"15\">Bug</text>\n  <rect class=\"pv-fill-surface pv-stroke-accent\" x=\"408.75\" y=\"96.75\" width=\"70.5\" height=\"22.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"420\" y=\"113\" font-size=\"15\">Urgent</text>\n  <text class=\"pv-fill-accent\" x=\"504\" y=\"113\" font-size=\"15\">Owner @ada</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"160\" font-size=\"15\">Gets routed</text>\n</svg>\n","alt":"An unclassified issue has no labels and no owner, so it waits unseen. A classified issue carries Bug, Urgent and Owner @ada, so it gets routed."},"guide":{"markdown":"## How to do it\n\n- Find the project’s written policy for classifying issues. It often lives in a contributing guide or a triage page.\n- For your kind of issue, set each label kind that the policy requires, such as type, priority or size.\n- If the policy requires an issue type, set the built-in type or the type label that the policy accepts.\n- If the policy requires an owner or a milestone for your kind of issue, set it.\n- If the policy requires a team label for the issue, add it. For example, instead of only asking “Can the network team look at this?”, add the required network label.\n\n## When it does not apply\n\n- The project’s written policy says that this kind of issue needs no labels, type, owner or milestone.\n\nA missing policy does not tell you whether classification requirements apply.\n\n## Common mistakes\n\n- Filling in every field you can see. The practice does not ask for that. Instead, set only what the policy asks for on this kind of issue. Fields that it does not ask for can stay empty.\n- Copying the labels that other issues carry. A label that many issues use is not a rule. Instead, check what the written policy asks for.\n- Picking a kind that does not match the issue, such as labelling a support question as a bug. Instead, pick the kind that the policy defines for this work. If you are not sure, ask a maintainer.\n\n## Sources\n\n- [Issue triage](https://handbook.gitlab.com/handbook/product-development/how-we-work/issue-triage/), GitLab Handbook. GitLab’s written policy asks for type and group labels, plus a severity label for bugs.\n- [Issue triage guidelines](https://www.kubernetes.dev/docs/guide/issue-triage/), Kubernetes contributor guide. Kubernetes uses kind, priority and owning-group labels, and an issue with no priority label has not been prioritized.\n- [Best practices for Projects](https://docs.github.com/en/issues/planning-and-tracking-with-projects/learning-about-projects/best-practices-for-projects), GitHub Docs. GitHub suggests issue types to classify work and assignees to show who is responsible.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','null'::jsonb),'v5:71cb1f14cacf2b5088486ea80af69e8d3b3302b4d3ad0d59c767731b5ec94e88','practice:v3:565844a9861ccf22d3668a4825de26b212fb93e0867bb6d42c42d37c2d2bfc0a');
INSERT INTO _cutover_bundle VALUES('PRACTICE','issue-closed-with-unmet-outcome','scm.issue','{"name":"Confirm the outcome before closing the issue","signals":["scm.issue.closed"],"evidenceRequirements":[{"sourceKind":"scm.issue.comments","stance":"REQUIRED"},{"sourceKind":"scm.issue.core","stance":"REQUIRED"}],"reviewWhen":{},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured issue: its title, description, labels and the discussion the practice names. Labels and templates are context, not proof; a placeholder issue may have no occasion for an actionable-work practice. Do not infer that a bug reproduces or that an outcome was implemented.\n\nFor a practice about requested work, establish the current request from the complete issue body and the discussion the practice names. Brief, vague or title-only requests still pass this premise.\n\nWhen genuinely conflicting current statements leave that request unresolved, record UNDETERMINED for the request-dependent judgment, cite the conflict, and judge neither statement under the standard. Position or date alone does not resolve it. If an explicit authored withdrawal leaves no work requested, record NOT_APPLICABLE for that judgment and treat earlier requirements as history. Judge a remaining request under the practice''s standard. Historical and closure practices retain their own subjects, including accounting for dropped or deferred work.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: evidence dated to the close accounts for the issue''s stated outcome, through confirmed completion or an explained remainder.\n\n## The standard\nWhen an issue is CLOSED as done, judge whether its own stated definition of done was confirmed at that close — every checkable acceptance item ticked and every tracked sub-issue finished — or whether a remainder was named at the close. Assess this single closure decision only, never the work: an empty checkbox may simply never have been ticked while the work was genuinely done. A closing comment that says plainly what is being dropped or deferred and why accounts for the remainder. The question is about the record as it stood at the close, and only evidence dated to that close can answer it. Never assert compile, runtime or correctness behaviour; there is no diff or code here.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when evidence dated to this close shows the issue was not closed as done: closed as not-planned, wontfix, duplicate, superseded or deferred. The current `state_reason`, body and rollup describe the latest state, not this close, so they cannot settle whether this close was done or stated a checkable outcome; when nothing dated to the close does, the gate is unresolved and the Judge records UNDETERMINED. NOT_APPLICABLE belongs to scope facts dated to the close, never to evidence you could not read or could not date.\n\n## Sources\n1. The issue record (`context/metadata.json`): state, `state_reason`, `closed_at`, labels and the sub-issue rollup. `closed_at` dates the close and nothing else. The body, labels and rollup are their values when the review read them, which is after the close; they never show their values at the close.\n2. The title and body (`context/description.md`): the current text. A checkbox can be ticked, unticked or added after the close, and the issue can be reopened and closed again, so a current checkbox is not a checkbox at the close.\n3. Comments (`context/comments.json`): `created_at` dates when a comment was written, not its present text, which may since have been edited; a comment written after the close is never a disposition at the close.\n4. The workspace inventory (`context/project_inventory.json`): state the overlapping or closing artifact you found, quoted as `#number \"title\" (state)`, or that you scanned it and found none.\nWhen the comments or the issue record were not captured, report a collection gap and record no observation.\n\n## Judge\nThe undesirable behaviour is closing as done with a stated outcome unmet and unaccounted for. Assess conformance to the standard in this context.\n- NOT_MET: evidence dated to this close shows a done-item still open at it — an unchecked acceptance or Definition-of-Done line, or a rollup short of complete — and nothing at the close names where that remainder went.\n- MET: evidence dated to this close shows every checkable item ticked and every tracked sub-issue completed, or a remainder named at the close.\n- UNDETERMINED: the issue was closed as done or with an unrecorded disposition, and the only record of its checklist, rollup or closing comments is the one read after the close. Name the undated fact. Never decide either cell from the current body, the current rollup or current comment text, whichever way they point.\nOne observation per review, on the single at-close question. Do not infer a longitudinal or developer-wide pattern from this one issue.\n\n## Severity\nNOT_MET only; never above MAJOR on outcome confirmation alone — non-blocking. MINOR: an open sub-issue rollup alone. MAJOR: an unconfirmed acceptance or Definition-of-Done condition with nothing at the close accounting for it. A remainder named at the close is not a negative. Identical inputs yield identical severity.\n\n## Grounding\nEvery claim cites an exact quoted span and says what dates it: the state or `state_reason` value, the `closed_at` timestamp, and for either assessed cell the at-close evidence of each item it relies on. An UNDETERMINED observation quotes what was read and states that it is dated after the close. State the inventory result in every observation. Describe only observable state — \"closed as done with ''<quoted line>'' still unchecked at the close\" — never a charge against the closer. Never fabricate a checklist, a clean bill or a disposition.\n\n## Defer\nWhether a NEW or OPEN issue defines a checkable outcome belongs to `issue-has-checkable-outcome`. Here only: was the stated outcome confirmed at the close?","precomputeScript":null,"automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"DECLARED_EVIDENCE_INSUFFICIENT"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"IMPLEMENTATION_NOT_OBSERVED","description":"Issue evidence does not establish whether the described work was implemented correctly."}],"insufficiencyReason":{"code":"AT_CLOSE_STATE_NOT_CAPTURED","description":"Hephaestus reads an issue as it stands when the review runs, after the close. Its checklist, sub-issue progress and comments can all change after the close, and the issue can be reopened and closed again, so what Hephaestus reads cannot show what was still open when it was closed. Whether the outcome was confirmed at that close needs a person who saw it."}},"whyItMatters":"Closing an issue tells the whole team it is handled. Closing it with a checklist item still unticked or sub-issues still open drops that work quietly, and someone hits the gap later expecting it to be done.","whatGoodLooksLike":"Before closing, every acceptance item is checked and every tracked sub-issue is finished, or a comment says plainly what is being dropped and why, so ''closed'' honestly means done.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 220\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Closed, unexplained</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"16\" y=\"61\" font-size=\"15\">Issue #57</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"16.75\" y=\"80.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <path class=\"pv-stroke-ink\" d=\"M20 88.5l3 3 5.5-6\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"93\" font-size=\"15\">Search</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"16.75\" y=\"104.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"117\" font-size=\"15\">Export</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M36.75 144.75H291.25A12 12 0 0 1 303.25 156.75V179.25A12 12 0 0 1 291.25 191.25H24.75V156.75A12 12 0 0 1 36.75 144.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"40\" y=\"173\" font-size=\"15\">Done, closing</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"216\" font-size=\"15\">Gap found later</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Closed, explained</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"352\" y=\"61\" font-size=\"15\">Issue #57</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"352.75\" y=\"80.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <path class=\"pv-stroke-ink\" d=\"M356 88.5l3 3 5.5-6\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"93\" font-size=\"15\">Search</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"352.75\" y=\"104.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"117\" font-size=\"15\">Export</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M372.75 144.75H627.25A12 12 0 0 1 639.25 156.75V179.25A12 12 0 0 1 627.25 191.25H360.75V156.75A12 12 0 0 1 372.75 144.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"376\" y=\"173\" font-size=\"15\">Closing: export not needed</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"216\" font-size=\"15\">No surprises</text>\n</svg>\n","alt":"Issue #57 is closed with Search ticked, Export open and a comment that says only “Done, closing”, so the gap is found later. Closed and explained, the comment says “Closing: export not needed”, so there are no surprises."},"guide":{"markdown":"## How to do it\n\n- Before you close an issue as done, read its checklist and its sub-issues.\n- Tick each checklist item that the work finished.\n- Close each sub-issue that is finished.\n- If an item is still open, name it in a closing comment that you post when you close. Say why it is dropped or deferred. For example, instead of closing with “Done”, write “Done except PDF export. We deferred it until the export library is ready.”\n- If you drop the whole issue, close it as not planned instead of as done.\n\n## When it does not apply\n\n- You close the issue as not planned.\n- You close it as wontfix, because you will not fix it.\n- You close it as a duplicate of another issue.\n- You close it as superseded, because other work replaced it.\n- You close it as deferred, to come back to it later.\n\n## Common mistakes\n\n- Closing finished work with its boxes still empty. The work may be done, but the issue still says that it is open. Instead, tick each finished item before you close.\n- Closing with “Done” or with no comment while an item is still open. The open item then looks finished. Instead, name the item and say why it is dropped or deferred.\n- Adding the note or ticking the boxes days after the close. Until then, the team reads the issue as done. Instead, do it before you close, or in the same step.\n- Leaving sub-issues open under a parent that you close as done. Instead, finish them first. Or name them in the closing comment.\n\n## Sources\n\n- [Closing an issue](https://docs.github.com/en/issues/tracking-your-work-with-issues/administering-issues/closing-an-issue), GitHub Docs. You can choose a close reason to show that work is finished or not planned.\n- [Manage issues](https://docs.gitlab.com/user/project/issues/managing_issues/), GitLab Docs. The `/close` quick action can close an issue from a comment.\n- [The Scrum Guide](https://scrumguides.org/scrum-guide.html), Ken Schwaber and Jeff Sutherland, 2020. In Scrum, work that fails the team’s agreed quality checks returns to their list of future work.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Confirm the outcome before closing the issue","signals":["scm.issue.closed"],"evidenceRequirements":[{"sourceKind":"scm.issue.comments","stance":"REQUIRED"},{"sourceKind":"scm.issue.core","stance":"REQUIRED"}],"reviewWhen":{},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured issue: its title, description, labels and the discussion the practice names. Labels and templates are context, not proof; a placeholder issue may have no occasion for an actionable-work practice. Do not infer that a bug reproduces or that an outcome was implemented.\n\nFor a practice about requested work, establish the current request from the complete issue body and the discussion the practice names. Brief, vague or title-only requests still pass this premise.\n\nWhen genuinely conflicting current statements leave that request unresolved, record UNDETERMINED for the request-dependent judgment, cite the conflict, and judge neither statement under the standard. Position or date alone does not resolve it. If an explicit authored withdrawal leaves no work requested, record NOT_APPLICABLE for that judgment and treat earlier requirements as history. Judge a remaining request under the practice''s standard. Historical and closure practices retain their own subjects, including accounting for dropped or deferred work.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: evidence dated to the close accounts for the issue''s stated outcome, through confirmed completion or an explained remainder.\n\n## The standard\nWhen an issue is CLOSED as done, judge whether its own stated definition of done was confirmed at that close — every checkable acceptance item ticked and every tracked sub-issue finished — or whether a remainder was named at the close. Assess this single closure decision only, never the work: an empty checkbox may simply never have been ticked while the work was genuinely done. A closing comment that says plainly what is being dropped or deferred and why accounts for the remainder. The question is about the record as it stood at the close, and only evidence dated to that close can answer it. Never assert compile, runtime or correctness behaviour; there is no diff or code here.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when evidence dated to this close shows the issue was not closed as done: closed as not-planned, wontfix, duplicate, superseded or deferred. The current `state_reason`, body and rollup describe the latest state, not this close, so they cannot settle whether this close was done or stated a checkable outcome; when nothing dated to the close does, the gate is unresolved and the Judge records UNDETERMINED. NOT_APPLICABLE belongs to scope facts dated to the close, never to evidence you could not read or could not date.\n\n## Sources\n1. The issue record (`context/metadata.json`): state, `state_reason`, `closed_at`, labels and the sub-issue rollup. `closed_at` dates the close and nothing else. The body, labels and rollup are their values when the review read them, which is after the close; they never show their values at the close.\n2. The title and body (`context/description.md`): the current text. A checkbox can be ticked, unticked or added after the close, and the issue can be reopened and closed again, so a current checkbox is not a checkbox at the close.\n3. Comments (`context/comments.json`): `created_at` dates when a comment was written, not its present text, which may since have been edited; a comment written after the close is never a disposition at the close.\n4. The workspace inventory (`context/project_inventory.json`): state the overlapping or closing artifact you found, quoted as `#number \"title\" (state)`, or that you scanned it and found none.\nWhen the comments or the issue record were not captured, report a collection gap and record no observation.\n\n## Judge\nThe undesirable behaviour is closing as done with a stated outcome unmet and unaccounted for. Assess conformance to the standard in this context.\n- NOT_MET: evidence dated to this close shows a done-item still open at it — an unchecked acceptance or Definition-of-Done line, or a rollup short of complete — and nothing at the close names where that remainder went.\n- MET: evidence dated to this close shows every checkable item ticked and every tracked sub-issue completed, or a remainder named at the close.\n- UNDETERMINED: the issue was closed as done or with an unrecorded disposition, and the only record of its checklist, rollup or closing comments is the one read after the close. Name the undated fact. Never decide either cell from the current body, the current rollup or current comment text, whichever way they point.\nOne observation per review, on the single at-close question. Do not infer a longitudinal or developer-wide pattern from this one issue.\n\n## Severity\nNOT_MET only; never above MAJOR on outcome confirmation alone — non-blocking. MINOR: an open sub-issue rollup alone. MAJOR: an unconfirmed acceptance or Definition-of-Done condition with nothing at the close accounting for it. A remainder named at the close is not a negative. Identical inputs yield identical severity.\n\n## Grounding\nEvery claim cites an exact quoted span and says what dates it: the state or `state_reason` value, the `closed_at` timestamp, and for either assessed cell the at-close evidence of each item it relies on. An UNDETERMINED observation quotes what was read and states that it is dated after the close. State the inventory result in every observation. Describe only observable state — \"closed as done with ''<quoted line>'' still unchecked at the close\" — never a charge against the closer. Never fabricate a checklist, a clean bill or a disposition.\n\n## Defer\nWhether a NEW or OPEN issue defines a checkable outcome belongs to `issue-has-checkable-outcome`. Here only: was the stated outcome confirmed at the close?","precomputeScript":null,"automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"DECLARED_EVIDENCE_INSUFFICIENT"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"IMPLEMENTATION_NOT_OBSERVED","description":"Issue evidence does not establish whether the described work was implemented correctly."}],"insufficiencyReason":{"code":"AT_CLOSE_STATE_NOT_CAPTURED","description":"Hephaestus reads an issue as it stands when the review runs, after the close. Its checklist, sub-issue progress and comments can all change after the close, and the issue can be reopened and closed again, so what Hephaestus reads cannot show what was still open when it was closed. Whether the outcome was confirmed at that close needs a person who saw it."}},"whyItMatters":"Closing an issue tells the whole team it is handled. Closing it with a checklist item still unticked or sub-issues still open drops that work quietly, and someone hits the gap later expecting it to be done.","whatGoodLooksLike":"Before closing, every acceptance item is checked and every tracked sub-issue is finished, or a comment says plainly what is being dropped and why, so ''closed'' honestly means done.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 220\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Closed, unexplained</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"16\" y=\"61\" font-size=\"15\">Issue #57</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"16.75\" y=\"80.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <path class=\"pv-stroke-ink\" d=\"M20 88.5l3 3 5.5-6\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"93\" font-size=\"15\">Search</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"16.75\" y=\"104.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"117\" font-size=\"15\">Export</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M36.75 144.75H291.25A12 12 0 0 1 303.25 156.75V179.25A12 12 0 0 1 291.25 191.25H24.75V156.75A12 12 0 0 1 36.75 144.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"40\" y=\"173\" font-size=\"15\">Done, closing</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"216\" font-size=\"15\">Gap found later</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Closed, explained</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"352\" y=\"61\" font-size=\"15\">Issue #57</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"352.75\" y=\"80.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <path class=\"pv-stroke-ink\" d=\"M356 88.5l3 3 5.5-6\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"93\" font-size=\"15\">Search</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"352.75\" y=\"104.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"117\" font-size=\"15\">Export</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M372.75 144.75H627.25A12 12 0 0 1 639.25 156.75V179.25A12 12 0 0 1 627.25 191.25H360.75V156.75A12 12 0 0 1 372.75 144.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"376\" y=\"173\" font-size=\"15\">Closing: export not needed</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"216\" font-size=\"15\">No surprises</text>\n</svg>\n","alt":"Issue #57 is closed with Search ticked, Export open and a comment that says only “Done, closing”, so the gap is found later. Closed and explained, the comment says “Closing: export not needed”, so there are no surprises."},"guide":{"markdown":"## How to do it\n\n- Before you close an issue as done, read its checklist and its sub-issues.\n- Tick each checklist item that the work finished.\n- Close each sub-issue that is finished.\n- If an item is still open, name it in a closing comment that you post when you close. Say why it is dropped or deferred. For example, instead of closing with “Done”, write “Done except PDF export. We deferred it until the export library is ready.”\n- If you drop the whole issue, close it as not planned instead of as done.\n\n## When it does not apply\n\n- You close the issue as not planned.\n- You close it as wontfix, because you will not fix it.\n- You close it as a duplicate of another issue.\n- You close it as superseded, because other work replaced it.\n- You close it as deferred, to come back to it later.\n\n## Common mistakes\n\n- Closing finished work with its boxes still empty. The work may be done, but the issue still says that it is open. Instead, tick each finished item before you close.\n- Closing with “Done” or with no comment while an item is still open. The open item then looks finished. Instead, name the item and say why it is dropped or deferred.\n- Adding the note or ticking the boxes days after the close. Until then, the team reads the issue as done. Instead, do it before you close, or in the same step.\n- Leaving sub-issues open under a parent that you close as done. Instead, finish them first. Or name them in the closing comment.\n\n## Sources\n\n- [Closing an issue](https://docs.github.com/en/issues/tracking-your-work-with-issues/administering-issues/closing-an-issue), GitHub Docs. You can choose a close reason to show that work is finished or not planned.\n- [Manage issues](https://docs.gitlab.com/user/project/issues/managing_issues/), GitLab Docs. The `/close` quick action can close an issue from a comment.\n- [The Scrum Guide](https://scrumguides.org/scrum-guide.html), Ken Schwaber and Jeff Sutherland, 2020. In Scrum, work that fails the team’s agreed quality checks returns to their list of future work.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','null'::jsonb),'v5:3770e257c4469b49ed31c0d303f30cfb1463ffc86a0b5c3180f70398cfafde5e','practice:v3:5a5bfdadb878c51095ca319706316fe59321373fab179885a5c84bfbc4083ab1');
INSERT INTO _cutover_bundle VALUES('PRACTICE','closed-issue-outcome-recorded','scm.issue','{"name":"Record the outcome of a closed issue","signals":["scm.issue.closed","scm.issue.updated"],"evidenceRequirements":[{"sourceKind":"scm.issue.comments","stance":"EXHAUSTIVE"},{"sourceKind":"scm.issue.core","stance":"EXHAUSTIVE"}],"reviewWhen":{"state":["CLOSED"]},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured issue: its title, description, labels and the discussion the practice names. Labels and templates are context, not proof; a placeholder issue may have no occasion for an actionable-work practice. Do not infer that a bug reproduces or that an outcome was implemented.\n\nFor a practice about requested work, establish the current request from the complete issue body and the discussion the practice names. Brief, vague or title-only requests still pass this premise.\n\nWhen genuinely conflicting current statements leave that request unresolved, record UNDETERMINED for the request-dependent judgment, cite the conflict, and judge neither statement under the standard. Position or date alone does not resolve it. If an explicit authored withdrawal leaves no work requested, record NOT_APPLICABLE for that judgment and treat earlier requirements as history. Judge a remaining request under the practice''s standard. Historical and closure practices retain their own subjects, including accounting for dropped or deferred work.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the authored record of a closed issue — its body and discussion as captured now — accounts for the outcome the issue states.\n\n## The standard\nJudge one bookkeeping act on an issue that is CLOSED as this review reads it: do its body and discussion, as they stand now, account for the outcome the issue itself states? An outcome is stated when the issue gives an observable completion condition you can quote: an acceptance item, a Definition of Done, a Given-When-Then scenario, or an explicit outcome statement in its title or prose. A concrete title alone can state that condition; no checklist or separate body is required. A topic or activity name without a discernible completion condition does not state a checkable outcome, so there is no closure accounting to assess here. A stated item is accounted for when it is ticked, or when the body or a comment clearly confirms it done — a short confirmation is enough when it unambiguously covers the item — or, if it was not done, explicitly says which work was dropped or deferred. A remainder needs accounting only when there is one. Judge what the record says, never whether the work was done or done correctly: a tick or a confirmation records a claim, and an unticked item may describe finished work. The closed state or a closing pull or merge request accounts for nothing by itself, and a statement that names the feature counts only for the items it plainly covers. The person who closed the issue may not be its author; describe the record, never who failed to write it.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when: the captured issue is not closed; its current disposition is not planned, duplicate or superseded; or it states no checkable outcome you can quote. The current disposition is the current `state_reason`, or a comment that clearly speaks to the present close; a comment from before an earlier reopen does not decide it, and `completed` alone does not disprove an explicit current disposition statement: some providers synthesize it for every non-duplicate closure. If current statements genuinely conflict, use UNDETERMINED.\n\n## Sources\n1. The issue record (`context/metadata.json`): `state`, `state_reason` and `closed_at` as captured when this review ran. They establish the current state and disposition, never what any field said at the close.\n2. The title and body (`context/description.md`): the stated outcome and its ticks as they stand now.\n3. The discussion (`context/comments.json`): the mirrored comments with their author, `created_at` and `updated_at`, as they stand now; Hephaestus''s own comments are left out. A comment can account for an item as fully as a tick. Its dates say when it was written and last edited, never that it existed at the close.\nSub-issue counts and other progress figures are not authored statements and decide nothing here; a sub-issue the body or a comment refers to counts only through what that text says. All of it is the record now; never claim what was true when the issue was closed. If the issue record or the discussion was not captured, or the discussion was captured only in part, report a collection gap and record no observation.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: every stated item is ticked or accounted for in the body or discussion. Quote the ticks or the text that accounts for them.\n- NOT_MET: the issue is closed, states a checkable outcome, and part of it is neither ticked nor accounted for in the body or discussion. Quote the unaccounted items.\n- UNDETERMINED: complete captured text leaves it genuinely ambiguous whether a statement covers an item, or what the current disposition is; name the deciding question.\nOne observation per review, on the issue''s current authored record.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking bookkeeping. MINOR, the usual band: a few stated items neither ticked nor accounted for. MAJOR: most of the stated outcome neither ticked nor accounted for. Identical evidence yields identical severity.\n\n## Grounding\nQuote the stated items as written, their tick state, the `state` value, and any text you rely on with its author and dates, and say that this is the record as captured now. Never claim an item was or was not delivered, never claim the record looked this way at the close, and never read the closed state as a tick.\n\n## Defer\nWhether the issue stated a checkable outcome in the first place belongs to `issue-has-checkable-outcome`; whether a merged change brought its linked issue''s outcome into line belongs to `merge-confirms-the-linked-issue-outcome`; what the record showed at the moment of the close is a question for a person (`issue-closed-with-unmet-outcome`). Here only: does the closed issue''s current authored record account for its stated outcome?","precomputeScript":null,"automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"IMPLEMENTATION_NOT_OBSERVED","description":"Issue evidence does not establish whether the described work was implemented correctly."}],"insufficiencyReason":null},"whyItMatters":"A closed issue is where the team looks to learn what was delivered. When its record says which items were done and what happened to the rest, the next person neither guesses nor repeats the digging.","whatGoodLooksLike":"Once an issue is closed, its list is ticked as far as the work went or a comment confirms what was done, and anything not done is named as dropped or deferred.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 220\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Silent close</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"16\" y=\"61\" font-size=\"15\">Issue #57</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"104.75\" y=\"44.75\" width=\"70.5\" height=\"22.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"116\" y=\"61\" font-size=\"15\">Closed</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"16.75\" y=\"80.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"93\" font-size=\"15\">Search</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"16.75\" y=\"104.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"117\" font-size=\"15\">Export</text>\n  <path class=\"pv-fill-surface pv-stroke-muted\" d=\"M36.75 144.75H291.25A12 12 0 0 1 303.25 156.75V179.25A12 12 0 0 1 291.25 191.25H24.75V156.75A12 12 0 0 1 36.75 144.75Z\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/>\n  <text class=\"pv-fill-muted\" x=\"40\" y=\"173\" font-size=\"15\">No comment</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"216\" font-size=\"15\">Others guess</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Recorded close</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"352\" y=\"61\" font-size=\"15\">Issue #57</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"440.75\" y=\"44.75\" width=\"70.5\" height=\"22.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"452\" y=\"61\" font-size=\"15\">Closed</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"352.75\" y=\"80.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <path class=\"pv-stroke-accent\" d=\"M356 88.5l3 3 5.5-6\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"93\" font-size=\"15\">Search</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"352.75\" y=\"104.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"117\" font-size=\"15\">Export</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M372.75 144.75H627.25A12 12 0 0 1 639.25 156.75V179.25A12 12 0 0 1 627.25 191.25H360.75V156.75A12 12 0 0 1 372.75 144.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"376\" y=\"173\" font-size=\"15\">Export deferred to #64</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"216\" font-size=\"15\">Others know</text>\n</svg>\n","alt":"Silent close: closed Issue #57 has nothing ticked and no comment, so others guess. Recorded close: Search is ticked and a comment says “Export deferred to #64”, so others know."},"guide":{"markdown":"## How to do it\n\n- Go through each item that the issue states.\n- For each finished item, tick its box or clearly confirm it in the body or a comment.\n- For each item that is not done, name it in a comment and say if it was dropped or deferred. For example, instead of closing with “Done”, write “Export and import are done. Bulk delete is deferred to a new issue.”\n- If the issue is already closed and its record is incomplete, add the comment now. The record that a reader sees today is the one that counts.\n\n## When it does not apply\n\n- The issue is still open.\n- The issue was closed as not planned, as a duplicate, or because other work replaced it. Its close reason or a comment about this close says so.\n- The issue states no outcome that someone can check, such as a topic name with no clear finish.\n\nIt still applies when the issue has no checklist and only its title says what must be true when the work is done.\n\n## Common mistakes\n\n- Letting the closed state speak for the issue. Closing it, or merging the pull request or merge request that closes it, does not say which items were done. Instead, tick the items or confirm them in a comment.\n- Leaving unfinished items unticked with no word about them. A reader cannot tell if they were done, dropped, or forgotten. Instead, name each one and say what became of it.\n- Writing a confirmation, such as “Search is done”, that covers only part of the list. Instead, make clear which finished work the confirmation covers.\n- Ticking an item that you did not finish, so that the list looks complete. Instead, leave it open and say that it was deferred.\n\n## Sources\n\n- [Communication, collaboration, and bugs: the social nature of issue tracking in small, collocated teams](https://grouplab.cpsc.ucalgary.ca/grouplab/uploads/Publications/Publications/2010-IssueTracking.CSCW.pdf), Bertram, Voida, Greenberg and Walker, 2010. Teams went back to an issue’s history later to learn what was decided and why.\n- [The Scrum Guide](https://scrumguides.org/scrum-guide.html), Schwaber and Sutherland, 2020. In Scrum, work that fails the team’s agreed quality checks returns to their list of future work.\n- [What are work item statuses, priorities, and resolutions?](https://support.atlassian.com/jira-cloud-administration/docs/what-are-issue-statuses-priorities-and-resolutions/), Atlassian. A resolution records how the work ended: it was done, it will not be done, or it is a duplicate.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Record the outcome of a closed issue","signals":["scm.issue.closed","scm.issue.updated"],"evidenceRequirements":[{"sourceKind":"scm.issue.comments","stance":"EXHAUSTIVE"},{"sourceKind":"scm.issue.core","stance":"EXHAUSTIVE"}],"reviewWhen":{"state":["CLOSED"]},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured issue: its title, description, labels and the discussion the practice names. Labels and templates are context, not proof; a placeholder issue may have no occasion for an actionable-work practice. Do not infer that a bug reproduces or that an outcome was implemented.\n\nFor a practice about requested work, establish the current request from the complete issue body and the discussion the practice names. Brief, vague or title-only requests still pass this premise.\n\nWhen genuinely conflicting current statements leave that request unresolved, record UNDETERMINED for the request-dependent judgment, cite the conflict, and judge neither statement under the standard. Position or date alone does not resolve it. If an explicit authored withdrawal leaves no work requested, record NOT_APPLICABLE for that judgment and treat earlier requirements as history. Judge a remaining request under the practice''s standard. Historical and closure practices retain their own subjects, including accounting for dropped or deferred work.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the authored record of a closed issue — its body and discussion as captured now — accounts for the outcome the issue states.\n\n## The standard\nJudge one bookkeeping act on an issue that is CLOSED as this review reads it: do its body and discussion, as they stand now, account for the outcome the issue itself states? An outcome is stated when the issue gives an observable completion condition you can quote: an acceptance item, a Definition of Done, a Given-When-Then scenario, or an explicit outcome statement in its title or prose. A concrete title alone can state that condition; no checklist or separate body is required. A topic or activity name without a discernible completion condition does not state a checkable outcome, so there is no closure accounting to assess here. A stated item is accounted for when it is ticked, or when the body or a comment clearly confirms it done — a short confirmation is enough when it unambiguously covers the item — or, if it was not done, explicitly says which work was dropped or deferred. A remainder needs accounting only when there is one. Judge what the record says, never whether the work was done or done correctly: a tick or a confirmation records a claim, and an unticked item may describe finished work. The closed state or a closing pull or merge request accounts for nothing by itself, and a statement that names the feature counts only for the items it plainly covers. The person who closed the issue may not be its author; describe the record, never who failed to write it.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when: the captured issue is not closed; its current disposition is not planned, duplicate or superseded; or it states no checkable outcome you can quote. The current disposition is the current `state_reason`, or a comment that clearly speaks to the present close; a comment from before an earlier reopen does not decide it, and `completed` alone does not disprove an explicit current disposition statement: some providers synthesize it for every non-duplicate closure. If current statements genuinely conflict, use UNDETERMINED.\n\n## Sources\n1. The issue record (`context/metadata.json`): `state`, `state_reason` and `closed_at` as captured when this review ran. They establish the current state and disposition, never what any field said at the close.\n2. The title and body (`context/description.md`): the stated outcome and its ticks as they stand now.\n3. The discussion (`context/comments.json`): the mirrored comments with their author, `created_at` and `updated_at`, as they stand now; Hephaestus''s own comments are left out. A comment can account for an item as fully as a tick. Its dates say when it was written and last edited, never that it existed at the close.\nSub-issue counts and other progress figures are not authored statements and decide nothing here; a sub-issue the body or a comment refers to counts only through what that text says. All of it is the record now; never claim what was true when the issue was closed. If the issue record or the discussion was not captured, or the discussion was captured only in part, report a collection gap and record no observation.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: every stated item is ticked or accounted for in the body or discussion. Quote the ticks or the text that accounts for them.\n- NOT_MET: the issue is closed, states a checkable outcome, and part of it is neither ticked nor accounted for in the body or discussion. Quote the unaccounted items.\n- UNDETERMINED: complete captured text leaves it genuinely ambiguous whether a statement covers an item, or what the current disposition is; name the deciding question.\nOne observation per review, on the issue''s current authored record.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking bookkeeping. MINOR, the usual band: a few stated items neither ticked nor accounted for. MAJOR: most of the stated outcome neither ticked nor accounted for. Identical evidence yields identical severity.\n\n## Grounding\nQuote the stated items as written, their tick state, the `state` value, and any text you rely on with its author and dates, and say that this is the record as captured now. Never claim an item was or was not delivered, never claim the record looked this way at the close, and never read the closed state as a tick.\n\n## Defer\nWhether the issue stated a checkable outcome in the first place belongs to `issue-has-checkable-outcome`; whether a merged change brought its linked issue''s outcome into line belongs to `merge-confirms-the-linked-issue-outcome`; what the record showed at the moment of the close is a question for a person (`issue-closed-with-unmet-outcome`). Here only: does the closed issue''s current authored record account for its stated outcome?","precomputeScript":null,"automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"IMPLEMENTATION_NOT_OBSERVED","description":"Issue evidence does not establish whether the described work was implemented correctly."}],"insufficiencyReason":null},"whyItMatters":"A closed issue is where the team looks to learn what was delivered. When its record says which items were done and what happened to the rest, the next person neither guesses nor repeats the digging.","whatGoodLooksLike":"Once an issue is closed, its list is ticked as far as the work went or a comment confirms what was done, and anything not done is named as dropped or deferred.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 220\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Silent close</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"16\" y=\"61\" font-size=\"15\">Issue #57</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"104.75\" y=\"44.75\" width=\"70.5\" height=\"22.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"116\" y=\"61\" font-size=\"15\">Closed</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"16.75\" y=\"80.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"93\" font-size=\"15\">Search</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"16.75\" y=\"104.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"117\" font-size=\"15\">Export</text>\n  <path class=\"pv-fill-surface pv-stroke-muted\" d=\"M36.75 144.75H291.25A12 12 0 0 1 303.25 156.75V179.25A12 12 0 0 1 291.25 191.25H24.75V156.75A12 12 0 0 1 36.75 144.75Z\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/>\n  <text class=\"pv-fill-muted\" x=\"40\" y=\"173\" font-size=\"15\">No comment</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"216\" font-size=\"15\">Others guess</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Recorded close</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"302.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"352\" y=\"61\" font-size=\"15\">Issue #57</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"440.75\" y=\"44.75\" width=\"70.5\" height=\"22.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"452\" y=\"61\" font-size=\"15\">Closed</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"352.75\" y=\"80.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <path class=\"pv-stroke-accent\" d=\"M356 88.5l3 3 5.5-6\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"93\" font-size=\"15\">Search</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"352.75\" y=\"104.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"117\" font-size=\"15\">Export</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M372.75 144.75H627.25A12 12 0 0 1 639.25 156.75V179.25A12 12 0 0 1 627.25 191.25H360.75V156.75A12 12 0 0 1 372.75 144.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"376\" y=\"173\" font-size=\"15\">Export deferred to #64</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"216\" font-size=\"15\">Others know</text>\n</svg>\n","alt":"Silent close: closed Issue #57 has nothing ticked and no comment, so others guess. Recorded close: Search is ticked and a comment says “Export deferred to #64”, so others know."},"guide":{"markdown":"## How to do it\n\n- Go through each item that the issue states.\n- For each finished item, tick its box or clearly confirm it in the body or a comment.\n- For each item that is not done, name it in a comment and say if it was dropped or deferred. For example, instead of closing with “Done”, write “Export and import are done. Bulk delete is deferred to a new issue.”\n- If the issue is already closed and its record is incomplete, add the comment now. The record that a reader sees today is the one that counts.\n\n## When it does not apply\n\n- The issue is still open.\n- The issue was closed as not planned, as a duplicate, or because other work replaced it. Its close reason or a comment about this close says so.\n- The issue states no outcome that someone can check, such as a topic name with no clear finish.\n\nIt still applies when the issue has no checklist and only its title says what must be true when the work is done.\n\n## Common mistakes\n\n- Letting the closed state speak for the issue. Closing it, or merging the pull request or merge request that closes it, does not say which items were done. Instead, tick the items or confirm them in a comment.\n- Leaving unfinished items unticked with no word about them. A reader cannot tell if they were done, dropped, or forgotten. Instead, name each one and say what became of it.\n- Writing a confirmation, such as “Search is done”, that covers only part of the list. Instead, make clear which finished work the confirmation covers.\n- Ticking an item that you did not finish, so that the list looks complete. Instead, leave it open and say that it was deferred.\n\n## Sources\n\n- [Communication, collaboration, and bugs: the social nature of issue tracking in small, collocated teams](https://grouplab.cpsc.ucalgary.ca/grouplab/uploads/Publications/Publications/2010-IssueTracking.CSCW.pdf), Bertram, Voida, Greenberg and Walker, 2010. Teams went back to an issue’s history later to learn what was decided and why.\n- [The Scrum Guide](https://scrumguides.org/scrum-guide.html), Schwaber and Sutherland, 2020. In Scrum, work that fails the team’s agreed quality checks returns to their list of future work.\n- [What are work item statuses, priorities, and resolutions?](https://support.atlassian.com/jira-cloud-administration/docs/what-are-issue-statuses-priorities-and-resolutions/), Atlassian. A resolution records how the work ended: it was done, it will not be done, or it is a duplicate.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Each closed issue records what became of its outcome"'::jsonb),'v5:cb58ca7f838757f03a47e8016730b8f50d16d2688b8539aa1f94c3697c6eeb0f','practice:v3:0d77832b43770e6b538269025756d75cf0a56c4812f8e3cba14c616b01385747');
INSERT INTO _cutover_bundle VALUES('PRACTICE','links-the-change-to-its-issue','scm.pull_request','{"name":"Link the change to the issue it implements","signals":["scm.pull_request.opened","scm.pull_request.ready"],"evidenceRequirements":[{"sourceKind":"scm.linked-work-items","stance":"CONTEXTUAL"},{"sourceKind":"scm.pull-request.core","stance":"EXHAUSTIVE"},{"sourceKind":"workspace.project-inventory","stance":"EXHAUSTIVE"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured pull or merge request at its pinned revision: the change itself, the description as written, the commits, the review discussion and the linked context the practice names. Distinguish what the author wrote from what a reviewer, a template or the provider''s current state says.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the pull request names the issue it implements, so the work can be read against what was asked.\n\n## The standard\nJudge one thing: does this pull request say which issue it implements, in a way the platform links? A link is the issue''s number in the title (`#12: …`), a reference in the body the author wrote — a plain mention such as `Related to #12` or a closing reference such as `Closes #12`, `Fixes #12`, `Resolves #12` or the provider''s equivalent —, a branch created from the issue (`12-add-login`), or a captured linked work item. A number inside the form''s template or an example is not the author''s reference. A link makes the issue readable from the review. Closing the issue when the change merges is a separate, provider-recognized relationship and not what this practice asks for: a plain reference settles traceability, including for work that delivers only part of the issue, and never needs to become a closing keyword. A change with none of these stands alone. Judge the presence of the link, never the quality of the issue it points to or whether the change fulfils it.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the work has no issue to link: the repository tracks no issues (`context/project_inventory.json` lists none), or the change is of a kind that answers no issue by convention — a release or version bump, a dependency update from a bot, a revert, a merge of one long-lived branch into another. A change a person made to the product is expected to answer an issue; a missing issue is then the lapse, not the absence of an occasion.\n\n## Sources\n1. The title, source branch and body (`context/metadata.json`, `context/description.md`): the number references and closing keywords as written. They establish the link the author made. They never establish that the issue exists or that the change fulfils it.\n2. The linked work items (`context/linked_work_items/<n>.md`, and `context/linked_work_items.json` with `how` per item) when captured: the items the platform resolved from those references, and for each whether the provider records it as a closing candidate for this change (`how: closesOnMerge`) or the text merely mentions it (`how: mentions`). Either kind is a link: a closing candidate links the issue whatever the text says, and a mention links it without closing it. Their absence establishes nothing when no reference was written.\n3. The inventory (`context/project_inventory.json`): whether the project tracks issues at all, and, for a change with no reference, whether an open issue plainly describes this work — quote its `#number \"title\"` if you find one, or say you scanned it and found none.\n4. The commits (`context/commits.json`): a further place an issue number may appear. They establish a reference the author left in history, nothing more. The precomputed leads below these criteria list every number referenced, where it was written, and whether the inventory or the linked items hold an issue of that number with its title and state.\nA reference in the title, body, branch or linked work can settle traceability without commit history. If no captured source shows a reference, an unavailable commit inventory cannot establish that history contains none. Report that collection gap and record no observation; do the same when the record or project inventory is unavailable for a change with no reference.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: the title, body, branch or a captured linked item names a verified issue target, including a deliberate cross-project link. Quote the reference.\n- NOT_MET: a reference is written but cannot be what it claims — it resolves to no issue, or claims to implement an issue whose captured contents clearly concern different work. A deliberate cross-project issue link can satisfy traceability; its closing behavior depends on the provider. Quote the reference and name the fact that breaks it.\n- NOT_MET: the change is product work by a person and no title, body, branch, commit or linked item names an issue, after scanning all of them. Say what you scanned.\n- UNDETERMINED: a reference whose target you cannot resolve because the inventory was not captured and the number could be a pull request as well as an issue; name what would settle it.\nOne observation per review.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: product work with no reference where an open issue for it plainly exists in the inventory, or a reference that resolves to no issue or to different work. MAJOR: product work with no issue at all in a project that tracks its work in issues. Identical evidence yields identical severity.\n\n## Grounding\nQuote the reference as written in the title, body, branch name or commit subject, or the linked item''s `#number \"title\"`. NOT_MET names every source scanned. Never invent an issue number, and never claim an issue''s content from its number alone.\n\n## Defer\nWhether the change fulfils the issue''s acceptance criteria belongs to `honours-linked-issue-acceptance-criteria`; the description''s what and why belong to `describe-what-and-why`. Here only: is the change linked to the issue it implements?","precomputeScript":"// Precompute FACTS for links-the-change-to-its-issue: where this pull request names an issue — title,\n// body, source branch, commit subjects, linked work items — each resolved against the project\n// inventory and the linked items, and, when it names none, whether the project tracks issues at all.\n// The review decides whether a reference is a link; the script says where each candidate was found\n// and what the inventory holds under that number in that repository.\nimport {\n\tcontextFile,\n\tisOpenState,\n\treadProjectInventory,\n\trepositoryIssues,\n\ttype InventoryItem,\n} from \"../lib/context.ts\";\nimport { text } from \"../lib/practice-contract.ts\";\nimport {\n\tbranchIssueReferences,\n\tclosingReferences,\n\tissueNumberReferences,\n\twithoutHtmlComments,\n} from \"../lib/references.ts\";\nimport { readLinkedWorkItems } from \"../lib/review.ts\";\nimport type { DiffFile, Hint, PullRequestMetadata } from \"../lib/types.ts\";\n\n/**\n * Qualified references cannot become local `#N` candidates. GitLab''s `project#N` shortcut needs\n * provider namespace authority the captured metadata does not carry, so its target remains unknown.\n */\nconst QUALIFIED_REF =\n\t/(?<![\\w./-])(?<target>[\\w.-]+(?:\\/[\\w.-]+)*)#(?<number>\\d+)(?![\\w]|\\.[0-9])/gu;\n\nconst byNumber = (rows: InventoryItem[] | null) =>\n\trows === null ? null : new Map(rows.map((issue) => [issue.number, issue]));\n\nexport default async function linksTheChangeToItsIssue(\n\t_repoPath: string,\n\t_diffFiles: Map<string, DiffFile>,\n\tmetadata: PullRequestMetadata,\n\tcontextDir: string | undefined,\n\t_changeDir: string | undefined,\n\tcontextReference: string,\n) {\n\tconst focal = text(metadata.repository_full_name);\n\tconst linked = await readLinkedWorkItems(contextDir);\n\tconst inventory = await readProjectInventory(contextDir);\n\t// A plain #N is the admitted repository''s, by its id; a qualified path names a repository of the same\n\t// provider. A full name alone is unique only within one provider, so no id leaves the scope unknown.\n\tconst { repository_id: repositoryId, provider_id: providerId } = metadata;\n\tconst focalIssues = repositoryIssues(\n\t\tinventory,\n\t\ttypeof repositoryId === \"number\" ? { repositoryId } : null,\n\t);\n\tconst issuesOf = (path: string) =>\n\t\tbyNumber(\n\t\t\trepositoryIssues(\n\t\t\t\tinventory,\n\t\t\t\ttypeof providerId === \"number\" ? { providerId, fullName: path } : null,\n\t\t\t),\n\t\t);\n\tconst local = byNumber(focalIssues);\n\tconst hints: Hint[] = [];\n\tconst row = (\n\t\twhere: string,\n\t\tpattern: string,\n\t\treference: string,\n\t\tissue: InventoryItem | undefined,\n\t\tflags: Hint[\"flags\"],\n\t) => {\n\t\thints.push({\n\t\t\tfile: where,\n\t\t\tline: 0,\n\t\t\tpattern,\n\t\t\tcontext: `${reference}${issue === undefined ? \"\" : ` ${issue.title}`}`,\n\t\t\tinDiff: false,\n\t\t\tflags,\n\t\t});\n\t};\n\tconst add = (where: string, numbers: number[], closing: boolean) => {\n\t\tfor (const n of numbers) {\n\t\t\tconst issue = local?.get(n);\n\t\t\tconst candidates = (linked ?? []).filter((item) => item.number === n);\n\t\t\tconst matched = issue?.url !== undefined && candidates.some((item) => item.url === issue.url);\n\t\t\trow(where, closing ? \"closing reference\" : \"issue reference\", `#${n}`, issue, {\n\t\t\t\tnumber: n,\n\t\t\t\twhere,\n\t\t\t\tinInventory: local === null ? \"unknown\" : issue !== undefined,\n\t\t\t\ttitle: issue?.title ?? \"\",\n\t\t\t\tstate: issue?.state ?? \"\",\n\t\t\t\tinLinkedItems: candidates.length === 0 ? false : matched || \"unknown\",\n\t\t\t});\n\t\t}\n\t};\n\tconst qualified = (where: string, source: string) => {\n\t\tconst seen = new Set<string>();\n\t\tfor (const match of withoutHtmlComments(source).matchAll(QUALIFIED_REF)) {\n\t\t\tconst target = match.groups?.target ?? \"\";\n\t\t\tconst n = Number(match.groups?.number);\n\t\t\tconst reference = `${target}#${n}`;\n\t\t\tif (!Number.isSafeInteger(n) || n <= 0 || seen.has(reference)) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tseen.add(reference);\n\t\t\tconst rows = target.includes(\"/\") ? issuesOf(target) : null;\n\t\t\tconst issue = rows?.get(n);\n\t\t\trow(where, \"qualified issue reference\", reference, issue, {\n\t\t\t\tnumber: n,\n\t\t\t\ttarget,\n\t\t\t\twhere,\n\t\t\t\tinInventory: rows === null ? \"unknown\" : issue !== undefined,\n\t\t\t\ttitle: issue?.title ?? \"\",\n\t\t\t\tstate: issue?.state ?? \"\",\n\t\t\t});\n\t\t}\n\t};\n\tconst unqualified = (source: string) => source.replaceAll(QUALIFIED_REF, \" \");\n\t// The provider''s closing candidates come first: a link made in the UI or through a cross-project\n\t// reference matches nothing in the text. A candidate may belong to another repository, so it is\n\t// placed in the inventory only by its address, never by its number.\n\tconst providerLinks = (linked ?? []).filter((item) => item.how === \"closesOnMerge\");\n\tconst providerFile = `${contextFile(contextReference, \"linked_work_items.json\")} (how: closesOnMerge)`;\n\tfor (const item of providerLinks) {\n\t\tconst matches =\n\t\t\titem.url === undefined ||\n\t\t\t!Number.isSafeInteger(providerId) ||\n\t\t\ttypeof providerId !== \"number\" ||\n\t\t\tproviderId <= 0\n\t\t\t\t? []\n\t\t\t\t: (inventory?.issues?.filter(\n\t\t\t\t\t\t(candidate) =>\n\t\t\t\t\t\t\tcandidate.url === item.url &&\n\t\t\t\t\t\t\tcandidate.providerId === providerId &&\n\t\t\t\t\t\t\tcandidate.repositoryId !== undefined,\n\t\t\t\t\t) ?? []);\n\t\tconst issue = matches.length === 1 ? matches[0] : undefined;\n\t\trow(providerFile, \"closing reference\", `#${item.number}`, issue, {\n\t\t\tnumber: item.number,\n\t\t\ttarget: issue?.repository ?? item.url ?? \"unknown\",\n\t\t\twhere: providerFile,\n\t\t\tinInventory: issue === undefined ? \"unknown\" : true,\n\t\t\ttitle: item.title,\n\t\t\tstate: item.state ?? issue?.state ?? \"\",\n\t\t\tinLinkedItems: true,\n\t\t});\n\t}\n\tconst title = text(metadata.title);\n\tconst body = text(metadata.body);\n\tconst branch = metadata.source_branch;\n\tconst titleFile = `${contextFile(contextReference, \"metadata.json\")} (title)`;\n\tconst descriptionFile = contextFile(contextReference, \"description.md\");\n\tadd(titleFile, issueNumberReferences(unqualified(title)), false);\n\tqualified(titleFile, title);\n\tconst closing = closingReferences(unqualified(body));\n\tadd(descriptionFile, closing, true);\n\tadd(\n\t\tdescriptionFile,\n\t\tissueNumberReferences(unqualified(body)).filter((n) => !closing.includes(n)),\n\t\tfalse,\n\t);\n\tqualified(descriptionFile, body);\n\tadd(\n\t\t`${contextFile(contextReference, \"metadata.json\")} (source_branch)`,\n\t\tbranchIssueReferences(branch),\n\t\tfalse,\n\t);\n\tconst referenceOf = (h: Hint) =>\n\t\t`${typeof h.flags.target === \"string\" ? h.flags.target : focal}#${String(h.flags.number)}`;\n\tconst references = new Set(hints.map(referenceOf));\n\tconst metrics = {\n\t\treferencesFound: references.size,\n\t\treferencesInInventory: new Set(\n\t\t\thints.filter((h) => h.flags.inInventory === true).map(referenceOf),\n\t\t).size,\n\t\tclosingReferences: hints.filter((h) => h.pattern === \"closing reference\").length,\n\t\tproviderClosingLinks: providerLinks.length,\n\t\tlinkedWorkItems: linked?.length ?? -1,\n\t\tinventoryIssues: focalIssues?.length ?? -1,\n\t\tinventoryOpenIssues: focalIssues?.filter((i) => isOpenState(i.state)).length ?? -1,\n\t};\n\tconst candidates = providerLinks\n\t\t.map((item) => ` #${String(item.number)} (state ${item.state ?? \"not recorded\"})`)\n\t\t.join(\",\");\n\tconst linkedSummary =\n\t\tlinked === null\n\t\t\t? \"linked_work_items.json not captured\"\n\t\t\t: `${String(linked.length)} captured, ${String(providerLinks.length)} of them provider closing candidates${candidates}`;\n\t// What the inventory holds for this repository: absent, not attributable to it, or its own counts.\n\tconst held = (absent: string, counts: string) => {\n\t\tif (inventory === null) {\n\t\t\treturn absent;\n\t\t}\n\t\treturn focalIssues === null\n\t\t\t? `the inventory does not say which of its issues belong to ${focal === \"\" ? \"this repository\" : focal}`\n\t\t\t: counts;\n\t};\n\tconst directions: string[] = [];\n\tif (references.size > 0) {\n\t\tdirections.push(\n\t\t\t`Issue-shaped references found: ${[...references].join(\", \")}, one row each with what the inventory holds under that number in the repository the reference names, this one (${focal}) for a plain #number (${held(\"no inventory captured\", `${String(metrics.inventoryIssues)} issues in ${focal}`)}), and whether it is among the linked items (${linkedSummary}).`,\n\t\t);\n\t} else {\n\t\tdirections.push(\n\t\t\t`No #number, closing keyword or branch number in the title, body or branch (${branch}); ${linked === null ? \"linked_work_items.json was not captured\" : `${String(linked.length)} linked work item(s) captured`}. Read ${contextFile(contextReference, \"commits.json\")} for a reference in history, then the inventory (${held(\"not captured\", `${String(metrics.inventoryIssues)} issues, ${String(metrics.inventoryOpenIssues)} open, in ${focal}`)}) for an open issue that plainly describes this work.`,\n\t\t);\n\t}\n\treturn { hints: hints.slice(0, 20), metrics, directions };\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A change that names the issue it answers can be read against what was asked and leaves a trail anyone can follow later. When the platform recognizes the reference as closing, the issue also closes when the change merges; a plain mention links the two but does not establish automatic closure. One without a reference makes the reviewer guess what the work was for.","whatGoodLooksLike":"The title, the description or the branch names the issue by number, with a closing keyword in the body when the change completes it, so the platform can close the issue with the merge and the two stay linked.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 156\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Unlinked change</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"150.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(16 48)\"><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"3\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M4 5.5v5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"12\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M12 10.5V6a3 3 0 0 0-3-3H7.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></g>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"61\" font-size=\"15\">Pull request</text>\n  <text class=\"pv-fill-muted\" x=\"16\" y=\"85\" font-size=\"15\">Add login</text>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"96\" width=\"112\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"108\" width=\"88\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"168.75\" y=\"32.75\" width=\"134.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/>\n  <text class=\"pv-fill-muted\" x=\"236\" y=\"85\" font-size=\"15\" text-anchor=\"middle\">No issue</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"152\" font-size=\"15\">Reviewer guesses</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Linked change</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"150.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(352 48)\"><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"3\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M4 5.5v5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"12\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M12 10.5V6a3 3 0 0 0-3-3H7.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></g>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"61\" font-size=\"15\">Pull request</text>\n  <text class=\"pv-fill-accent\" x=\"352\" y=\"85\" font-size=\"15\">#12 Add login</text>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"96\" width=\"112\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"108\" width=\"88\" height=\"6\" rx=\"3\"/>\n  <path class=\"pv-stroke-accent\" d=\"M488 56h16\" fill=\"none\" stroke-width=\"2\"/>\n  <circle class=\"pv-fill-accent\" cx=\"488\" cy=\"56\" r=\"4\"/>\n  <circle class=\"pv-fill-accent\" cx=\"504\" cy=\"56\" r=\"4\"/>\n  <rect class=\"pv-fill-surface pv-stroke-accent\" x=\"504.75\" y=\"32.75\" width=\"134.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(520 48)\"><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"6.75\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-fill-ink\" cx=\"8\" cy=\"8\" r=\"1.75\"/></g>\n  <text class=\"pv-fill-ink\" x=\"548\" y=\"61\" font-size=\"15\">Issue #12</text>\n  <rect class=\"pv-fill-muted\" x=\"520\" y=\"80\" width=\"72\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"520\" y=\"92\" width=\"88\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"520\" y=\"104\" width=\"48\" height=\"6\" rx=\"3\"/>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"152\" font-size=\"15\">Read against the ask</text>\n</svg>\n","alt":"A pull request titled “Add login” has no issue, so the reviewer guesses. A pull request titled “#12 Add login” is joined to Issue #12, so it is read against the ask."},"guide":{"markdown":"## How to do it\n\n- Before you open the pull or merge request, search the open issues for the one that this work answers.\n- Name the issue by its number in the title, the description or the branch name. For example, instead of the title “Add login timeout” and nothing else, write “Related to #12” in the description.\n- If you start the work from the issue, create the branch from it. On GitLab, start the branch name with the issue number, such as `12-add-login`, in the issue’s project.\n- Use a closing keyword such as “Closes #12” only when the change completes the issue. A plain mention links the change to the issue but leaves the issue open.\n- If the issue lives in another project, use its full reference, such as `group/project#12`.\n\n## When it does not apply\n\n- Your project does not track its work in issues.\n- The change is a release or a version bump.\n- The change is a dependency update that a bot opened.\n- The change reverts an earlier change.\n- The change merges one long-lived branch into another.\n\nIt still applies when a person changes the product and no issue exists for the work. Then the missing issue is the gap.\n\n## Common mistakes\n\n- Thinking that only a closing keyword counts. A plain mention such as “Related to #12” links the change too, even for part of an issue. Instead, keep the closing keyword for a change that finishes the issue.\n- Leaving the number from the description template or an example in place. Instead, replace it with the number of your issue.\n- Writing a number that is not the issue, such as a typo or a pull request number. Instead, open the link and check that it is the right issue.\n- Opening product work with no reference while an open issue already describes it. Instead, name that issue.\n\n## Sources\n\n- [Linking a pull request to an issue](https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/linking-a-pull-request-to-an-issue), GitHub Docs. A closing keyword in a pull request to the default branch links the issue and closes it when merged.\n- [Crosslinking issues](https://docs.gitlab.com/user/project/issues/crosslinking_issues/), GitLab Docs. Mentioning an issue in a merge request description or commit message links the work to that issue.\n- [Writing good CL descriptions](https://google.github.io/eng-practices/review/developer/cl-descriptions.html), Google Engineering Practices. Google suggests that a description include background such as bug numbers, for future readers.\n- [Traceability in the wild: automatically augmenting incomplete trace links](https://doi.org/10.1145/3180155.3180207), Rath and others, 2018. Across six open-source projects, about 60% of commits named an issue, leaving gaps between issues and code.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Link the change to the issue it implements","signals":["scm.pull_request.opened","scm.pull_request.ready"],"evidenceRequirements":[{"sourceKind":"scm.linked-work-items","stance":"CONTEXTUAL"},{"sourceKind":"scm.pull-request.core","stance":"EXHAUSTIVE"},{"sourceKind":"workspace.project-inventory","stance":"EXHAUSTIVE"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured pull or merge request at its pinned revision: the change itself, the description as written, the commits, the review discussion and the linked context the practice names. Distinguish what the author wrote from what a reviewer, a template or the provider''s current state says.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the pull request names the issue it implements, so the work can be read against what was asked.\n\n## The standard\nJudge one thing: does this pull request say which issue it implements, in a way the platform links? A link is the issue''s number in the title (`#12: …`), a reference in the body the author wrote — a plain mention such as `Related to #12` or a closing reference such as `Closes #12`, `Fixes #12`, `Resolves #12` or the provider''s equivalent —, a branch created from the issue (`12-add-login`), or a captured linked work item. A number inside the form''s template or an example is not the author''s reference. A link makes the issue readable from the review. Closing the issue when the change merges is a separate, provider-recognized relationship and not what this practice asks for: a plain reference settles traceability, including for work that delivers only part of the issue, and never needs to become a closing keyword. A change with none of these stands alone. Judge the presence of the link, never the quality of the issue it points to or whether the change fulfils it.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the work has no issue to link: the repository tracks no issues (`context/project_inventory.json` lists none), or the change is of a kind that answers no issue by convention — a release or version bump, a dependency update from a bot, a revert, a merge of one long-lived branch into another. A change a person made to the product is expected to answer an issue; a missing issue is then the lapse, not the absence of an occasion.\n\n## Sources\n1. The title, source branch and body (`context/metadata.json`, `context/description.md`): the number references and closing keywords as written. They establish the link the author made. They never establish that the issue exists or that the change fulfils it.\n2. The linked work items (`context/linked_work_items/<n>.md`, and `context/linked_work_items.json` with `how` per item) when captured: the items the platform resolved from those references, and for each whether the provider records it as a closing candidate for this change (`how: closesOnMerge`) or the text merely mentions it (`how: mentions`). Either kind is a link: a closing candidate links the issue whatever the text says, and a mention links it without closing it. Their absence establishes nothing when no reference was written.\n3. The inventory (`context/project_inventory.json`): whether the project tracks issues at all, and, for a change with no reference, whether an open issue plainly describes this work — quote its `#number \"title\"` if you find one, or say you scanned it and found none.\n4. The commits (`context/commits.json`): a further place an issue number may appear. They establish a reference the author left in history, nothing more. The precomputed leads below these criteria list every number referenced, where it was written, and whether the inventory or the linked items hold an issue of that number with its title and state.\nA reference in the title, body, branch or linked work can settle traceability without commit history. If no captured source shows a reference, an unavailable commit inventory cannot establish that history contains none. Report that collection gap and record no observation; do the same when the record or project inventory is unavailable for a change with no reference.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: the title, body, branch or a captured linked item names a verified issue target, including a deliberate cross-project link. Quote the reference.\n- NOT_MET: a reference is written but cannot be what it claims — it resolves to no issue, or claims to implement an issue whose captured contents clearly concern different work. A deliberate cross-project issue link can satisfy traceability; its closing behavior depends on the provider. Quote the reference and name the fact that breaks it.\n- NOT_MET: the change is product work by a person and no title, body, branch, commit or linked item names an issue, after scanning all of them. Say what you scanned.\n- UNDETERMINED: a reference whose target you cannot resolve because the inventory was not captured and the number could be a pull request as well as an issue; name what would settle it.\nOne observation per review.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: product work with no reference where an open issue for it plainly exists in the inventory, or a reference that resolves to no issue or to different work. MAJOR: product work with no issue at all in a project that tracks its work in issues. Identical evidence yields identical severity.\n\n## Grounding\nQuote the reference as written in the title, body, branch name or commit subject, or the linked item''s `#number \"title\"`. NOT_MET names every source scanned. Never invent an issue number, and never claim an issue''s content from its number alone.\n\n## Defer\nWhether the change fulfils the issue''s acceptance criteria belongs to `honours-linked-issue-acceptance-criteria`; the description''s what and why belong to `describe-what-and-why`. Here only: is the change linked to the issue it implements?","precomputeScript":"// Precompute FACTS for links-the-change-to-its-issue: where this pull request names an issue — title,\n// body, source branch, commit subjects, linked work items — each resolved against the project\n// inventory and the linked items, and, when it names none, whether the project tracks issues at all.\n// The review decides whether a reference is a link; the script says where each candidate was found\n// and what the inventory holds under that number in that repository.\nimport {\n\tcontextFile,\n\tisOpenState,\n\treadProjectInventory,\n\trepositoryIssues,\n\ttype InventoryItem,\n} from \"../lib/context.ts\";\nimport { text } from \"../lib/practice-contract.ts\";\nimport {\n\tbranchIssueReferences,\n\tclosingReferences,\n\tissueNumberReferences,\n\twithoutHtmlComments,\n} from \"../lib/references.ts\";\nimport { readLinkedWorkItems } from \"../lib/review.ts\";\nimport type { DiffFile, Hint, PullRequestMetadata } from \"../lib/types.ts\";\n\n/**\n * Qualified references cannot become local `#N` candidates. GitLab''s `project#N` shortcut needs\n * provider namespace authority the captured metadata does not carry, so its target remains unknown.\n */\nconst QUALIFIED_REF =\n\t/(?<![\\w./-])(?<target>[\\w.-]+(?:\\/[\\w.-]+)*)#(?<number>\\d+)(?![\\w]|\\.[0-9])/gu;\n\nconst byNumber = (rows: InventoryItem[] | null) =>\n\trows === null ? null : new Map(rows.map((issue) => [issue.number, issue]));\n\nexport default async function linksTheChangeToItsIssue(\n\t_repoPath: string,\n\t_diffFiles: Map<string, DiffFile>,\n\tmetadata: PullRequestMetadata,\n\tcontextDir: string | undefined,\n\t_changeDir: string | undefined,\n\tcontextReference: string,\n) {\n\tconst focal = text(metadata.repository_full_name);\n\tconst linked = await readLinkedWorkItems(contextDir);\n\tconst inventory = await readProjectInventory(contextDir);\n\t// A plain #N is the admitted repository''s, by its id; a qualified path names a repository of the same\n\t// provider. A full name alone is unique only within one provider, so no id leaves the scope unknown.\n\tconst { repository_id: repositoryId, provider_id: providerId } = metadata;\n\tconst focalIssues = repositoryIssues(\n\t\tinventory,\n\t\ttypeof repositoryId === \"number\" ? { repositoryId } : null,\n\t);\n\tconst issuesOf = (path: string) =>\n\t\tbyNumber(\n\t\t\trepositoryIssues(\n\t\t\t\tinventory,\n\t\t\t\ttypeof providerId === \"number\" ? { providerId, fullName: path } : null,\n\t\t\t),\n\t\t);\n\tconst local = byNumber(focalIssues);\n\tconst hints: Hint[] = [];\n\tconst row = (\n\t\twhere: string,\n\t\tpattern: string,\n\t\treference: string,\n\t\tissue: InventoryItem | undefined,\n\t\tflags: Hint[\"flags\"],\n\t) => {\n\t\thints.push({\n\t\t\tfile: where,\n\t\t\tline: 0,\n\t\t\tpattern,\n\t\t\tcontext: `${reference}${issue === undefined ? \"\" : ` ${issue.title}`}`,\n\t\t\tinDiff: false,\n\t\t\tflags,\n\t\t});\n\t};\n\tconst add = (where: string, numbers: number[], closing: boolean) => {\n\t\tfor (const n of numbers) {\n\t\t\tconst issue = local?.get(n);\n\t\t\tconst candidates = (linked ?? []).filter((item) => item.number === n);\n\t\t\tconst matched = issue?.url !== undefined && candidates.some((item) => item.url === issue.url);\n\t\t\trow(where, closing ? \"closing reference\" : \"issue reference\", `#${n}`, issue, {\n\t\t\t\tnumber: n,\n\t\t\t\twhere,\n\t\t\t\tinInventory: local === null ? \"unknown\" : issue !== undefined,\n\t\t\t\ttitle: issue?.title ?? \"\",\n\t\t\t\tstate: issue?.state ?? \"\",\n\t\t\t\tinLinkedItems: candidates.length === 0 ? false : matched || \"unknown\",\n\t\t\t});\n\t\t}\n\t};\n\tconst qualified = (where: string, source: string) => {\n\t\tconst seen = new Set<string>();\n\t\tfor (const match of withoutHtmlComments(source).matchAll(QUALIFIED_REF)) {\n\t\t\tconst target = match.groups?.target ?? \"\";\n\t\t\tconst n = Number(match.groups?.number);\n\t\t\tconst reference = `${target}#${n}`;\n\t\t\tif (!Number.isSafeInteger(n) || n <= 0 || seen.has(reference)) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tseen.add(reference);\n\t\t\tconst rows = target.includes(\"/\") ? issuesOf(target) : null;\n\t\t\tconst issue = rows?.get(n);\n\t\t\trow(where, \"qualified issue reference\", reference, issue, {\n\t\t\t\tnumber: n,\n\t\t\t\ttarget,\n\t\t\t\twhere,\n\t\t\t\tinInventory: rows === null ? \"unknown\" : issue !== undefined,\n\t\t\t\ttitle: issue?.title ?? \"\",\n\t\t\t\tstate: issue?.state ?? \"\",\n\t\t\t});\n\t\t}\n\t};\n\tconst unqualified = (source: string) => source.replaceAll(QUALIFIED_REF, \" \");\n\t// The provider''s closing candidates come first: a link made in the UI or through a cross-project\n\t// reference matches nothing in the text. A candidate may belong to another repository, so it is\n\t// placed in the inventory only by its address, never by its number.\n\tconst providerLinks = (linked ?? []).filter((item) => item.how === \"closesOnMerge\");\n\tconst providerFile = `${contextFile(contextReference, \"linked_work_items.json\")} (how: closesOnMerge)`;\n\tfor (const item of providerLinks) {\n\t\tconst matches =\n\t\t\titem.url === undefined ||\n\t\t\t!Number.isSafeInteger(providerId) ||\n\t\t\ttypeof providerId !== \"number\" ||\n\t\t\tproviderId <= 0\n\t\t\t\t? []\n\t\t\t\t: (inventory?.issues?.filter(\n\t\t\t\t\t\t(candidate) =>\n\t\t\t\t\t\t\tcandidate.url === item.url &&\n\t\t\t\t\t\t\tcandidate.providerId === providerId &&\n\t\t\t\t\t\t\tcandidate.repositoryId !== undefined,\n\t\t\t\t\t) ?? []);\n\t\tconst issue = matches.length === 1 ? matches[0] : undefined;\n\t\trow(providerFile, \"closing reference\", `#${item.number}`, issue, {\n\t\t\tnumber: item.number,\n\t\t\ttarget: issue?.repository ?? item.url ?? \"unknown\",\n\t\t\twhere: providerFile,\n\t\t\tinInventory: issue === undefined ? \"unknown\" : true,\n\t\t\ttitle: item.title,\n\t\t\tstate: item.state ?? issue?.state ?? \"\",\n\t\t\tinLinkedItems: true,\n\t\t});\n\t}\n\tconst title = text(metadata.title);\n\tconst body = text(metadata.body);\n\tconst branch = metadata.source_branch;\n\tconst titleFile = `${contextFile(contextReference, \"metadata.json\")} (title)`;\n\tconst descriptionFile = contextFile(contextReference, \"description.md\");\n\tadd(titleFile, issueNumberReferences(unqualified(title)), false);\n\tqualified(titleFile, title);\n\tconst closing = closingReferences(unqualified(body));\n\tadd(descriptionFile, closing, true);\n\tadd(\n\t\tdescriptionFile,\n\t\tissueNumberReferences(unqualified(body)).filter((n) => !closing.includes(n)),\n\t\tfalse,\n\t);\n\tqualified(descriptionFile, body);\n\tadd(\n\t\t`${contextFile(contextReference, \"metadata.json\")} (source_branch)`,\n\t\tbranchIssueReferences(branch),\n\t\tfalse,\n\t);\n\tconst referenceOf = (h: Hint) =>\n\t\t`${typeof h.flags.target === \"string\" ? h.flags.target : focal}#${String(h.flags.number)}`;\n\tconst references = new Set(hints.map(referenceOf));\n\tconst metrics = {\n\t\treferencesFound: references.size,\n\t\treferencesInInventory: new Set(\n\t\t\thints.filter((h) => h.flags.inInventory === true).map(referenceOf),\n\t\t).size,\n\t\tclosingReferences: hints.filter((h) => h.pattern === \"closing reference\").length,\n\t\tproviderClosingLinks: providerLinks.length,\n\t\tlinkedWorkItems: linked?.length ?? -1,\n\t\tinventoryIssues: focalIssues?.length ?? -1,\n\t\tinventoryOpenIssues: focalIssues?.filter((i) => isOpenState(i.state)).length ?? -1,\n\t};\n\tconst candidates = providerLinks\n\t\t.map((item) => ` #${String(item.number)} (state ${item.state ?? \"not recorded\"})`)\n\t\t.join(\",\");\n\tconst linkedSummary =\n\t\tlinked === null\n\t\t\t? \"linked_work_items.json not captured\"\n\t\t\t: `${String(linked.length)} captured, ${String(providerLinks.length)} of them provider closing candidates${candidates}`;\n\t// What the inventory holds for this repository: absent, not attributable to it, or its own counts.\n\tconst held = (absent: string, counts: string) => {\n\t\tif (inventory === null) {\n\t\t\treturn absent;\n\t\t}\n\t\treturn focalIssues === null\n\t\t\t? `the inventory does not say which of its issues belong to ${focal === \"\" ? \"this repository\" : focal}`\n\t\t\t: counts;\n\t};\n\tconst directions: string[] = [];\n\tif (references.size > 0) {\n\t\tdirections.push(\n\t\t\t`Issue-shaped references found: ${[...references].join(\", \")}, one row each with what the inventory holds under that number in the repository the reference names, this one (${focal}) for a plain #number (${held(\"no inventory captured\", `${String(metrics.inventoryIssues)} issues in ${focal}`)}), and whether it is among the linked items (${linkedSummary}).`,\n\t\t);\n\t} else {\n\t\tdirections.push(\n\t\t\t`No #number, closing keyword or branch number in the title, body or branch (${branch}); ${linked === null ? \"linked_work_items.json was not captured\" : `${String(linked.length)} linked work item(s) captured`}. Read ${contextFile(contextReference, \"commits.json\")} for a reference in history, then the inventory (${held(\"not captured\", `${String(metrics.inventoryIssues)} issues, ${String(metrics.inventoryOpenIssues)} open, in ${focal}`)}) for an open issue that plainly describes this work.`,\n\t\t);\n\t}\n\treturn { hints: hints.slice(0, 20), metrics, directions };\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A change that names the issue it answers can be read against what was asked and leaves a trail anyone can follow later. When the platform recognizes the reference as closing, the issue also closes when the change merges; a plain mention links the two but does not establish automatic closure. One without a reference makes the reviewer guess what the work was for.","whatGoodLooksLike":"The title, the description or the branch names the issue by number, with a closing keyword in the body when the change completes it, so the platform can close the issue with the merge and the two stay linked.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 156\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Unlinked change</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"150.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(16 48)\"><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"3\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M4 5.5v5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"12\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M12 10.5V6a3 3 0 0 0-3-3H7.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></g>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"61\" font-size=\"15\">Pull request</text>\n  <text class=\"pv-fill-muted\" x=\"16\" y=\"85\" font-size=\"15\">Add login</text>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"96\" width=\"112\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"108\" width=\"88\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"168.75\" y=\"32.75\" width=\"134.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/>\n  <text class=\"pv-fill-muted\" x=\"236\" y=\"85\" font-size=\"15\" text-anchor=\"middle\">No issue</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"152\" font-size=\"15\">Reviewer guesses</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Linked change</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"150.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(352 48)\"><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"3\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M4 5.5v5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"12\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M12 10.5V6a3 3 0 0 0-3-3H7.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></g>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"61\" font-size=\"15\">Pull request</text>\n  <text class=\"pv-fill-accent\" x=\"352\" y=\"85\" font-size=\"15\">#12 Add login</text>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"96\" width=\"112\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"108\" width=\"88\" height=\"6\" rx=\"3\"/>\n  <path class=\"pv-stroke-accent\" d=\"M488 56h16\" fill=\"none\" stroke-width=\"2\"/>\n  <circle class=\"pv-fill-accent\" cx=\"488\" cy=\"56\" r=\"4\"/>\n  <circle class=\"pv-fill-accent\" cx=\"504\" cy=\"56\" r=\"4\"/>\n  <rect class=\"pv-fill-surface pv-stroke-accent\" x=\"504.75\" y=\"32.75\" width=\"134.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(520 48)\"><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"6.75\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-fill-ink\" cx=\"8\" cy=\"8\" r=\"1.75\"/></g>\n  <text class=\"pv-fill-ink\" x=\"548\" y=\"61\" font-size=\"15\">Issue #12</text>\n  <rect class=\"pv-fill-muted\" x=\"520\" y=\"80\" width=\"72\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"520\" y=\"92\" width=\"88\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"520\" y=\"104\" width=\"48\" height=\"6\" rx=\"3\"/>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"152\" font-size=\"15\">Read against the ask</text>\n</svg>\n","alt":"A pull request titled “Add login” has no issue, so the reviewer guesses. A pull request titled “#12 Add login” is joined to Issue #12, so it is read against the ask."},"guide":{"markdown":"## How to do it\n\n- Before you open the pull or merge request, search the open issues for the one that this work answers.\n- Name the issue by its number in the title, the description or the branch name. For example, instead of the title “Add login timeout” and nothing else, write “Related to #12” in the description.\n- If you start the work from the issue, create the branch from it. On GitLab, start the branch name with the issue number, such as `12-add-login`, in the issue’s project.\n- Use a closing keyword such as “Closes #12” only when the change completes the issue. A plain mention links the change to the issue but leaves the issue open.\n- If the issue lives in another project, use its full reference, such as `group/project#12`.\n\n## When it does not apply\n\n- Your project does not track its work in issues.\n- The change is a release or a version bump.\n- The change is a dependency update that a bot opened.\n- The change reverts an earlier change.\n- The change merges one long-lived branch into another.\n\nIt still applies when a person changes the product and no issue exists for the work. Then the missing issue is the gap.\n\n## Common mistakes\n\n- Thinking that only a closing keyword counts. A plain mention such as “Related to #12” links the change too, even for part of an issue. Instead, keep the closing keyword for a change that finishes the issue.\n- Leaving the number from the description template or an example in place. Instead, replace it with the number of your issue.\n- Writing a number that is not the issue, such as a typo or a pull request number. Instead, open the link and check that it is the right issue.\n- Opening product work with no reference while an open issue already describes it. Instead, name that issue.\n\n## Sources\n\n- [Linking a pull request to an issue](https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/linking-a-pull-request-to-an-issue), GitHub Docs. A closing keyword in a pull request to the default branch links the issue and closes it when merged.\n- [Crosslinking issues](https://docs.gitlab.com/user/project/issues/crosslinking_issues/), GitLab Docs. Mentioning an issue in a merge request description or commit message links the work to that issue.\n- [Writing good CL descriptions](https://google.github.io/eng-practices/review/developer/cl-descriptions.html), Google Engineering Practices. Google suggests that a description include background such as bug numbers, for future readers.\n- [Traceability in the wild: automatically augmenting incomplete trace links](https://doi.org/10.1145/3180155.3180207), Rath and others, 2018. Across six open-source projects, about 60% of commits named an issue, leaving gaps between issues and code.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Every change names the issue it implements"'::jsonb),'v5:8b666c9bda300be3c1b9c2576b704d6a587ea17f26db88f4749936497b3e9088','practice:v3:b62f16eeb5558466f01afde0ed646b094ec6a3f0d4c58e9cb47e0291f668d6d3');
INSERT INTO _cutover_bundle VALUES('PRACTICE','merge-confirms-the-linked-issue-outcome','scm.pull_request','{"name":"Confirm the linked issue''s outcome","signals":["scm.pull_request.merged"],"evidenceRequirements":[{"sourceKind":"scm.general-review-comments","stance":"CONTEXTUAL"},{"sourceKind":"scm.linked-work-items","stance":"REQUIRED"},{"sourceKind":"scm.pull-request.core","stance":"EXHAUSTIVE"},{"sourceKind":"scm.pull-request.diff","stance":"REQUIRED"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured pull or merge request at its pinned revision: the change itself, the description as written, the commits, the review discussion and the linked context the practice names. Distinguish what the author wrote from what a reviewer, a template or the provider''s current state says.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: for merged work, the captured record confirms the linked issue''s stated outcome — its adopted outcome items reported as delivered or named as deferred — so the tracker accounts for what was delivered.\n\n## The standard\nJudge one thing about this merged pull request: does the captured record bring the linked issue''s own definition of done into line with what landed? The merge establishes the occasion; this review assesses confirmation in the capture, not the issue body at merge time. An issue that stated a checkable outcome (an acceptance checklist, a Definition of Done, a Given-When-Then block, tracked sub-issues) is confirmed when the captured record accounts for each outcome item the change adopts — reported as delivered or named as deferred — in the issue, in the pull request body, or in a closing comment. Content decides, not form: a tick, a checked item, an authored delivery bullet or a sentence counts when its wording substantively names a specific adopted outcome item, even under a template heading and while the issue''s own boxes stay unticked; no checkbox, heading, closing word or formula is required. A check that names none of the items (builds, reviewed, lint clean), a bare closing reference, a line that names only the feature (\"added the search screen\"), or an inventory of changes whose link to the items must be inferred from the code confirms nothing about them. Work that delivers part of what it adopts is confirmed only when the delivered part is named and the rest is named as deferred; an adopted item left unmentioned is unaccounted for. It need not close the issue or tick an item twice. Assess only this bookkeeping act, never whether the work is correct: a tick or a delivery line is the author''s report, not proof that an item works, was checked or is fulfilled, nor of when it was made; an unticked item may describe delivered work, and a ticked one may not.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when: the pull request is not merged; a complete linked-work inventory establishes no relevant item, or the linked item states no checkable outcome you can quote (a task list, an acceptance or Definition-of-Done block, a Given-When-Then, or a non-zero sub-issue rollup); or the linked item was closed as not planned, duplicate or superseded, since its outcome was deliberately abandoned. A linked item with an outcome and a merge are the occasion — every captured item this change explicitly implements, closing candidates and adopted partial work alike; a mention alone does not establish that this change must account for the item; the precomputed leads list each with its items and ticks. A user story without a task list, an outcome heading or sub-issues is no occasion, however plainly the diff delivers it.\n\n## Sources\n1. The pull request record (`context/metadata.json`): `state` and `merged_at`. It establishes that and when the change merged. It never establishes the issue''s state.\n2. Each linked item (`context/linked_work_items/<n>.md`: number, title, state, body; `how` in `linked_work_items.json` says whether the provider records it as a closing candidate): the checkable outcome as written, with its ticks as captured. It establishes what was stated and which items are ticked. Confirmation captured after the merge counts. A missing confirmation describes this capture; it does not establish that confirmation never happened or that it was missing at merge time. Its body is the text as mirrored at capture, and its opening and closing dates are not when any line of it was written. A closed state alone confirms nothing; the ticks or the words do.\n3. The body (`context/description.md`) and the discussion (`context/general_comments.json`): a done/deferred account as the standard describes it. They establish what the author said was delivered. They never establish that it was.\n4. The diff (`work/change/diff.patch`): read only to ground a heavier severity when a named item is plainly not touched. It never establishes that an item is met.\nIf the linked item''s body or the record''s merge time is unavailable, report a collection gap and record no observation.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: the capture accounts for every adopted outcome item as the standard says, as delivered or deferred. Quote the ticks, lines or sentence that name each item. Judge the recorded done/deferred mapping, not whether the code actually delivers the item.\n- NOT_MET: the change merged, the linked item states a checkable outcome, and the capture leaves at least one adopted item unaccounted for as the standard says — unticked and unnamed, whether the issue is closed or open. Quote the unaccounted items and the merge time.\n- UNDETERMINED: complete captured text leaves the done/deferred mapping genuinely ambiguous; name the deciding question. A truncated capture of a required checklist is a collection gap and produces no observation.\nOne observation per review.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: one or two items left unaccounted for in the capture with the work plainly delivered, or an authored account that names the outcome loosely. MAJOR: most of the stated outcome is unaccounted for in the captured closed issue, or the captured issue is open with nothing said. Identical evidence yields identical severity.\n\n## Grounding\nQuote the outcome items from the linked item as written, the tick state, the merge time from the record, and any authored line that accounts for them. Never claim an item is met, unmet or accounted for from the code; never infer a tick that is not in the capture; never read a closed state as a tick. Credit a tick or an authored line in the item''s body or the description as captured; say it was there before, at or after the merge only when independently dated evidence establishes that, since the creation date of a body, a description or a comment alone does not date text edited later. A later capture that confirms the outcome does not undo an earlier observation that read it unconfirmed; each stands for the capture it read.\n\n## Defer\nWhether a closing pull request''s own handoff says which acceptance criteria it covers belongs to `honours-linked-issue-acceptance-criteria`; the issue''s own closing decision, when someone closes it by hand, belongs to `issue-closed-with-unmet-outcome`. Here only: does the captured record confirm the linked issue''s outcome for the merged work?","precomputeScript":"import { contextFile } from \"../lib/context.ts\";\nimport { subIssueRollup } from \"../lib/issue-classification.ts\";\nimport { text } from \"../lib/practice-contract.ts\";\n// Precompute FACTS for merge-confirms-the-linked-issue-outcome: every captured linked issue, one row\n// each — its task-list items as captured, ticked and unticked, its state, and how the change names it.\n// Which of them this change implements is the criteria''s to decide; a row is a candidate, not an\n// occasion.\nimport {\n\tbranchIssueReferences,\n\tclosingReferences,\n\tissueNumberReferences,\n} from \"../lib/references.ts\";\nimport { checkableItems, mergeFacts, readLinkedWorkItems } from \"../lib/review.ts\";\nimport type { DiffFile, Hint, PullRequestMetadata } from \"../lib/types.ts\";\n\n/** Headings under which an issue states what \"done\" means without a task list. */\nconst OUTCOME_HEADING =\n\t/^\\s*#+\\s*(?:acceptance criteria|definition of done|dod|expected (?:outcome|result|behaviou?r)|given\\b)/imu;\n\n/** How the change names a linked issue, strongest form first. */\nfunction howLinked(\n\tnumber: number,\n\tclosing: ReadonlySet<number>,\n\tnamed: ReadonlySet<number>,\n): string {\n\tif (closing.has(number)) {\n\t\treturn \"named with a closing keyword in the body\";\n\t}\n\treturn named.has(number)\n\t\t? \"named by the title, body or branch\"\n\t\t: \"linked through a commit or another item\";\n}\n\nexport default async function mergeConfirmsTheLinkedIssueOutcome(\n\t_repoPath: string,\n\t_diffFiles: Map<string, DiffFile>,\n\tmetadata: PullRequestMetadata,\n\tcontextDir: string | undefined,\n\t_changeDir: string | undefined,\n\tcontextReference: string,\n) {\n\tconst body = text(metadata.body);\n\tconst closing = new Set(closingReferences(body));\n\tconst named = new Set([\n\t\t...issueNumberReferences(text(metadata.title)),\n\t\t...issueNumberReferences(body),\n\t\t...branchIssueReferences(metadata.source_branch),\n\t]);\n\tconst captured = await readLinkedWorkItems(contextDir);\n\tconst linked = captured ?? [];\n\tconst hints: Hint[] = [];\n\tfor (const item of linked) {\n\t\tconst items = checkableItems(item.body);\n\t\tconst ticked = items.filter((i) => i.checked).length;\n\t\tconst heading = OUTCOME_HEADING.test(item.body);\n\t\tconst rollup = subIssueRollup({\n\t\t\tsub_issues_total: item.subIssuesTotal,\n\t\t\tsub_issues_completed: item.subIssuesCompleted,\n\t\t\tsub_issues_source: item.subIssuesSource,\n\t\t});\n\t\tconst subIssues = rollup.total;\n\t\tconst checkable = items.length > 0 || heading || (subIssues ?? 0) > 0;\n\t\tlet pattern = checkable ? \"checkable outcome\" : \"no checkable outcome\";\n\t\tif (subIssues === undefined || (item.subIssuesSource === \"children\" && subIssues === 0)) {\n\t\t\tpattern = checkable ? pattern : \"no task list or outcome heading\";\n\t\t}\n\t\tconst rollupFlags: Hint[\"flags\"] = subIssues === undefined ? {} : { subIssuesTotal: subIssues };\n\t\t// The provider''s own link outranks what the text says: a link made in the UI matches no `#N`.\n\t\tconst how =\n\t\t\titem.how === \"closesOnMerge\"\n\t\t\t\t? \"a provider closing candidate\"\n\t\t\t\t: howLinked(item.number, closing, named);\n\t\thints.push({\n\t\t\tfile: contextFile(contextReference, `linked_work_items/${String(item.number)}.md`),\n\t\t\tline: items[0]?.line ?? 0,\n\t\t\tpattern,\n\t\t\tcontext: `#${String(item.number)} ${item.title} — ${how}; ${String(items.length)} task-list item(s), ${String(ticked)} ticked as captured${heading ? \"; an outcome heading\" : \"\"}; ${rollup.text}; state ${item.state ?? \"unknown\"}`,\n\t\t\tinDiff: false,\n\t\t\tflags: {\n\t\t\t\tnumber: item.number,\n\t\t\t\thow,\n\t\t\t\ttaskItems: items.length,\n\t\t\t\tticked,\n\t\t\t\tunticked: items.length - ticked,\n\t\t\t\toutcomeHeading: heading,\n\t\t\t\t...rollupFlags,\n\t\t\t\tstate: item.state ?? \"\",\n\t\t\t},\n\t\t});\n\t}\n\tconst candidates = hints.filter((h) => h.pattern === \"checkable outcome\");\n\tconst directions: string[] = [];\n\tif (!mergeFacts(metadata).merged) {\n\t\tdirections.push(\"The change is not merged; the practice''s occasion is the merge.\");\n\t} else if (captured === null) {\n\t\tdirections.push(\n\t\t\t\"linked_work_items.json was not captured: a collection gap, not a change without a linked issue.\",\n\t\t);\n\t} else if (candidates.length === 0) {\n\t\tdirections.push(\n\t\t\tlinked.length === 0\n\t\t\t\t? \"The capture holds no linked issue; there is no stated outcome to confirm.\"\n\t\t\t\t: \"No captured linked issue carries a task list, an acceptance or Definition-of-Done heading or a positive captured sub-issue count; a rollup the provider does not report says nothing about sub-issues.\",\n\t\t);\n\t} else {\n\t\tdirections.push(\n\t\t\t`${String(candidates.length)} captured linked issue(s) state a checkable outcome. Each is a candidate: the criteria decide which of them this change implements, from the provider''s closing link and the author''s own words; a mention alone asks nothing of it. For an issue it implements, assess confirmation in the captured record: its items ticked as captured, or the description or a closing comment naming which items are done and where the rest moves. Work delivered in the diff but neither ticked nor named is unconfirmed. A confirmation captured after the merge counts; when it was written is unknown unless independently dated evidence establishes it.`,\n\t\t);\n\t}\n\treturn {\n\t\thints,\n\t\tmetrics: {\n\t\t\tlinkedItems: linked.length,\n\t\t\tcheckableItems: candidates.length,\n\t\t\tuntickedItems: candidates.reduce((sum, h) => sum + Number(h.flags.unticked), 0),\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A linked issue with its outcome unconfirmed tells the next person little about what was delivered. After a change merges, recording what landed and naming what moves elsewhere keeps the tracker true.","whatGoodLooksLike":"After a change merges, its linked issue accounts for what landed: delivered outcomes are marked or reported, any remainder is named, and the issue''s state matches.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":"honours-linked-issue-acceptance-criteria"},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 164\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Outcome unconfirmed</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"150.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(16 48)\"><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"3\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M4 5.5v5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"12\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M12 10.5V6a3 3 0 0 0-3-3H7.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></g>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"61\" font-size=\"15\">Merged</text>\n  <text class=\"pv-fill-muted\" x=\"16\" y=\"93\" font-size=\"15\">Added search</text>\n  <path class=\"pv-stroke-muted\" d=\"M152 56h32\" fill=\"none\" stroke-width=\"2\"/>\n  <circle class=\"pv-fill-muted\" cx=\"152\" cy=\"56\" r=\"4\"/>\n  <circle class=\"pv-fill-muted\" cx=\"184\" cy=\"56\" r=\"4\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"184.75\" y=\"32.75\" width=\"118.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"200\" y=\"61\" font-size=\"15\">Issue #57</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"200.75\" y=\"80.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"228\" y=\"93\" font-size=\"15\">Search</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"200.75\" y=\"104.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"228\" y=\"117\" font-size=\"15\">Export</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"160\" font-size=\"15\">Tracker stale</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Outcome confirmed</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"150.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(352 48)\"><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"3\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M4 5.5v5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"12\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M12 10.5V6a3 3 0 0 0-3-3H7.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></g>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"61\" font-size=\"15\">Merged</text>\n  <text class=\"pv-fill-accent\" x=\"352\" y=\"93\" font-size=\"15\">Export deferred</text>\n  <text class=\"pv-fill-accent\" x=\"352\" y=\"111\" font-size=\"15\">to #318</text>\n  <path class=\"pv-stroke-muted\" d=\"M488 56h32\" fill=\"none\" stroke-width=\"2\"/>\n  <circle class=\"pv-fill-muted\" cx=\"488\" cy=\"56\" r=\"4\"/>\n  <circle class=\"pv-fill-muted\" cx=\"520\" cy=\"56\" r=\"4\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"520.75\" y=\"32.75\" width=\"118.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"536\" y=\"61\" font-size=\"15\">Issue #57</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"536.75\" y=\"80.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <path class=\"pv-stroke-accent\" d=\"M540 88.5l3 3 5.5-6\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <text class=\"pv-fill-ink\" x=\"564\" y=\"93\" font-size=\"15\">Search</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"536.75\" y=\"104.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"564\" y=\"117\" font-size=\"15\">Export</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"160\" font-size=\"15\">Tracker current</text>\n</svg>\n","alt":"A merged pull request says only “Added search” and linked Issue #57 has nothing ticked, so the tracker is stale. When Search is ticked and the pull request says “Export deferred to #318”, the tracker is current."},"guide":{"markdown":"## How to do it\n\n- After the merge, find the checkable items in each issue that your change implements.\n- Record each delivered item with a tick or a sentence that names it.\n- If only part of an item is done, tick or name that part.\n- Name what remains and say that it is deferred. For example, instead of “Added the search screen”, write “Search box and filters are done. Saved searches move to #318.”\n- Put this record in the issue, in your description, or in a comment.\n\n## When it does not apply\n\n- The pull request or merge request is not merged.\n- Your change does not implement any linked issue. A plain mention of an issue does not count.\n- The linked issue states no outcome you can check. It has no task list and no sub-issues. It has no section that says what counts as done or lists steps with expected results. A user story alone does not count.\n- The linked issue was closed as not planned, as a duplicate, or as replaced by other work.\n\nIt still applies when the issue is already closed, and when your change delivers only part of an item.\n\n## Common mistakes\n\n- Thinking that you must tick every box. A plain sentence that says what is done and what is deferred works just as well.\n- Letting the closed issue speak for you. On GitHub, a closing keyword closes the linked issue when you merge into the default branch. Its boxes stay as they were. Instead, tick the delivered items or add a closing sentence.\n- Ticking template boxes such as “builds”, “reviewed” or “lint clean”. They name no item of the issue. Instead, tick boxes whose words match the issue’s items.\n- Naming only the feature, such as “added the search screen”. Instead, name the items that are done and the ones that move on.\n\n## Sources\n\n- [The Scrum Guide](https://scrumguides.org/scrum-guide.html), Ken Schwaber and Jeff Sutherland, 2020. In Scrum, work that fails the team’s agreed quality checks returns to their list of future work.\n- [Task lists](https://docs.gitlab.com/user/markdown/#task-lists), GitLab Docs. You can mark tasks complete, incomplete or inapplicable in issues, merge requests and comments.\n- [Linking a pull request to an issue](https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/linking-a-pull-request-to-an-issue), GitHub Docs. A closing keyword closes the linked issue when the pull request merges into the default branch.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Confirm the linked issue''s outcome","signals":["scm.pull_request.merged"],"evidenceRequirements":[{"sourceKind":"scm.general-review-comments","stance":"CONTEXTUAL"},{"sourceKind":"scm.linked-work-items","stance":"REQUIRED"},{"sourceKind":"scm.pull-request.core","stance":"EXHAUSTIVE"},{"sourceKind":"scm.pull-request.diff","stance":"REQUIRED"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured pull or merge request at its pinned revision: the change itself, the description as written, the commits, the review discussion and the linked context the practice names. Distinguish what the author wrote from what a reviewer, a template or the provider''s current state says.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: for merged work, the captured record confirms the linked issue''s stated outcome — its adopted outcome items reported as delivered or named as deferred — so the tracker accounts for what was delivered.\n\n## The standard\nJudge one thing about this merged pull request: does the captured record bring the linked issue''s own definition of done into line with what landed? The merge establishes the occasion; this review assesses confirmation in the capture, not the issue body at merge time. An issue that stated a checkable outcome (an acceptance checklist, a Definition of Done, a Given-When-Then block, tracked sub-issues) is confirmed when the captured record accounts for each outcome item the change adopts — reported as delivered or named as deferred — in the issue, in the pull request body, or in a closing comment. Content decides, not form: a tick, a checked item, an authored delivery bullet or a sentence counts when its wording substantively names a specific adopted outcome item, even under a template heading and while the issue''s own boxes stay unticked; no checkbox, heading, closing word or formula is required. A check that names none of the items (builds, reviewed, lint clean), a bare closing reference, a line that names only the feature (\"added the search screen\"), or an inventory of changes whose link to the items must be inferred from the code confirms nothing about them. Work that delivers part of what it adopts is confirmed only when the delivered part is named and the rest is named as deferred; an adopted item left unmentioned is unaccounted for. It need not close the issue or tick an item twice. Assess only this bookkeeping act, never whether the work is correct: a tick or a delivery line is the author''s report, not proof that an item works, was checked or is fulfilled, nor of when it was made; an unticked item may describe delivered work, and a ticked one may not.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when: the pull request is not merged; a complete linked-work inventory establishes no relevant item, or the linked item states no checkable outcome you can quote (a task list, an acceptance or Definition-of-Done block, a Given-When-Then, or a non-zero sub-issue rollup); or the linked item was closed as not planned, duplicate or superseded, since its outcome was deliberately abandoned. A linked item with an outcome and a merge are the occasion — every captured item this change explicitly implements, closing candidates and adopted partial work alike; a mention alone does not establish that this change must account for the item; the precomputed leads list each with its items and ticks. A user story without a task list, an outcome heading or sub-issues is no occasion, however plainly the diff delivers it.\n\n## Sources\n1. The pull request record (`context/metadata.json`): `state` and `merged_at`. It establishes that and when the change merged. It never establishes the issue''s state.\n2. Each linked item (`context/linked_work_items/<n>.md`: number, title, state, body; `how` in `linked_work_items.json` says whether the provider records it as a closing candidate): the checkable outcome as written, with its ticks as captured. It establishes what was stated and which items are ticked. Confirmation captured after the merge counts. A missing confirmation describes this capture; it does not establish that confirmation never happened or that it was missing at merge time. Its body is the text as mirrored at capture, and its opening and closing dates are not when any line of it was written. A closed state alone confirms nothing; the ticks or the words do.\n3. The body (`context/description.md`) and the discussion (`context/general_comments.json`): a done/deferred account as the standard describes it. They establish what the author said was delivered. They never establish that it was.\n4. The diff (`work/change/diff.patch`): read only to ground a heavier severity when a named item is plainly not touched. It never establishes that an item is met.\nIf the linked item''s body or the record''s merge time is unavailable, report a collection gap and record no observation.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: the capture accounts for every adopted outcome item as the standard says, as delivered or deferred. Quote the ticks, lines or sentence that name each item. Judge the recorded done/deferred mapping, not whether the code actually delivers the item.\n- NOT_MET: the change merged, the linked item states a checkable outcome, and the capture leaves at least one adopted item unaccounted for as the standard says — unticked and unnamed, whether the issue is closed or open. Quote the unaccounted items and the merge time.\n- UNDETERMINED: complete captured text leaves the done/deferred mapping genuinely ambiguous; name the deciding question. A truncated capture of a required checklist is a collection gap and produces no observation.\nOne observation per review.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: one or two items left unaccounted for in the capture with the work plainly delivered, or an authored account that names the outcome loosely. MAJOR: most of the stated outcome is unaccounted for in the captured closed issue, or the captured issue is open with nothing said. Identical evidence yields identical severity.\n\n## Grounding\nQuote the outcome items from the linked item as written, the tick state, the merge time from the record, and any authored line that accounts for them. Never claim an item is met, unmet or accounted for from the code; never infer a tick that is not in the capture; never read a closed state as a tick. Credit a tick or an authored line in the item''s body or the description as captured; say it was there before, at or after the merge only when independently dated evidence establishes that, since the creation date of a body, a description or a comment alone does not date text edited later. A later capture that confirms the outcome does not undo an earlier observation that read it unconfirmed; each stands for the capture it read.\n\n## Defer\nWhether a closing pull request''s own handoff says which acceptance criteria it covers belongs to `honours-linked-issue-acceptance-criteria`; the issue''s own closing decision, when someone closes it by hand, belongs to `issue-closed-with-unmet-outcome`. Here only: does the captured record confirm the linked issue''s outcome for the merged work?","precomputeScript":"import { contextFile } from \"../lib/context.ts\";\nimport { subIssueRollup } from \"../lib/issue-classification.ts\";\nimport { text } from \"../lib/practice-contract.ts\";\n// Precompute FACTS for merge-confirms-the-linked-issue-outcome: every captured linked issue, one row\n// each — its task-list items as captured, ticked and unticked, its state, and how the change names it.\n// Which of them this change implements is the criteria''s to decide; a row is a candidate, not an\n// occasion.\nimport {\n\tbranchIssueReferences,\n\tclosingReferences,\n\tissueNumberReferences,\n} from \"../lib/references.ts\";\nimport { checkableItems, mergeFacts, readLinkedWorkItems } from \"../lib/review.ts\";\nimport type { DiffFile, Hint, PullRequestMetadata } from \"../lib/types.ts\";\n\n/** Headings under which an issue states what \"done\" means without a task list. */\nconst OUTCOME_HEADING =\n\t/^\\s*#+\\s*(?:acceptance criteria|definition of done|dod|expected (?:outcome|result|behaviou?r)|given\\b)/imu;\n\n/** How the change names a linked issue, strongest form first. */\nfunction howLinked(\n\tnumber: number,\n\tclosing: ReadonlySet<number>,\n\tnamed: ReadonlySet<number>,\n): string {\n\tif (closing.has(number)) {\n\t\treturn \"named with a closing keyword in the body\";\n\t}\n\treturn named.has(number)\n\t\t? \"named by the title, body or branch\"\n\t\t: \"linked through a commit or another item\";\n}\n\nexport default async function mergeConfirmsTheLinkedIssueOutcome(\n\t_repoPath: string,\n\t_diffFiles: Map<string, DiffFile>,\n\tmetadata: PullRequestMetadata,\n\tcontextDir: string | undefined,\n\t_changeDir: string | undefined,\n\tcontextReference: string,\n) {\n\tconst body = text(metadata.body);\n\tconst closing = new Set(closingReferences(body));\n\tconst named = new Set([\n\t\t...issueNumberReferences(text(metadata.title)),\n\t\t...issueNumberReferences(body),\n\t\t...branchIssueReferences(metadata.source_branch),\n\t]);\n\tconst captured = await readLinkedWorkItems(contextDir);\n\tconst linked = captured ?? [];\n\tconst hints: Hint[] = [];\n\tfor (const item of linked) {\n\t\tconst items = checkableItems(item.body);\n\t\tconst ticked = items.filter((i) => i.checked).length;\n\t\tconst heading = OUTCOME_HEADING.test(item.body);\n\t\tconst rollup = subIssueRollup({\n\t\t\tsub_issues_total: item.subIssuesTotal,\n\t\t\tsub_issues_completed: item.subIssuesCompleted,\n\t\t\tsub_issues_source: item.subIssuesSource,\n\t\t});\n\t\tconst subIssues = rollup.total;\n\t\tconst checkable = items.length > 0 || heading || (subIssues ?? 0) > 0;\n\t\tlet pattern = checkable ? \"checkable outcome\" : \"no checkable outcome\";\n\t\tif (subIssues === undefined || (item.subIssuesSource === \"children\" && subIssues === 0)) {\n\t\t\tpattern = checkable ? pattern : \"no task list or outcome heading\";\n\t\t}\n\t\tconst rollupFlags: Hint[\"flags\"] = subIssues === undefined ? {} : { subIssuesTotal: subIssues };\n\t\t// The provider''s own link outranks what the text says: a link made in the UI matches no `#N`.\n\t\tconst how =\n\t\t\titem.how === \"closesOnMerge\"\n\t\t\t\t? \"a provider closing candidate\"\n\t\t\t\t: howLinked(item.number, closing, named);\n\t\thints.push({\n\t\t\tfile: contextFile(contextReference, `linked_work_items/${String(item.number)}.md`),\n\t\t\tline: items[0]?.line ?? 0,\n\t\t\tpattern,\n\t\t\tcontext: `#${String(item.number)} ${item.title} — ${how}; ${String(items.length)} task-list item(s), ${String(ticked)} ticked as captured${heading ? \"; an outcome heading\" : \"\"}; ${rollup.text}; state ${item.state ?? \"unknown\"}`,\n\t\t\tinDiff: false,\n\t\t\tflags: {\n\t\t\t\tnumber: item.number,\n\t\t\t\thow,\n\t\t\t\ttaskItems: items.length,\n\t\t\t\tticked,\n\t\t\t\tunticked: items.length - ticked,\n\t\t\t\toutcomeHeading: heading,\n\t\t\t\t...rollupFlags,\n\t\t\t\tstate: item.state ?? \"\",\n\t\t\t},\n\t\t});\n\t}\n\tconst candidates = hints.filter((h) => h.pattern === \"checkable outcome\");\n\tconst directions: string[] = [];\n\tif (!mergeFacts(metadata).merged) {\n\t\tdirections.push(\"The change is not merged; the practice''s occasion is the merge.\");\n\t} else if (captured === null) {\n\t\tdirections.push(\n\t\t\t\"linked_work_items.json was not captured: a collection gap, not a change without a linked issue.\",\n\t\t);\n\t} else if (candidates.length === 0) {\n\t\tdirections.push(\n\t\t\tlinked.length === 0\n\t\t\t\t? \"The capture holds no linked issue; there is no stated outcome to confirm.\"\n\t\t\t\t: \"No captured linked issue carries a task list, an acceptance or Definition-of-Done heading or a positive captured sub-issue count; a rollup the provider does not report says nothing about sub-issues.\",\n\t\t);\n\t} else {\n\t\tdirections.push(\n\t\t\t`${String(candidates.length)} captured linked issue(s) state a checkable outcome. Each is a candidate: the criteria decide which of them this change implements, from the provider''s closing link and the author''s own words; a mention alone asks nothing of it. For an issue it implements, assess confirmation in the captured record: its items ticked as captured, or the description or a closing comment naming which items are done and where the rest moves. Work delivered in the diff but neither ticked nor named is unconfirmed. A confirmation captured after the merge counts; when it was written is unknown unless independently dated evidence establishes it.`,\n\t\t);\n\t}\n\treturn {\n\t\thints,\n\t\tmetrics: {\n\t\t\tlinkedItems: linked.length,\n\t\t\tcheckableItems: candidates.length,\n\t\t\tuntickedItems: candidates.reduce((sum, h) => sum + Number(h.flags.unticked), 0),\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A linked issue with its outcome unconfirmed tells the next person little about what was delivered. After a change merges, recording what landed and naming what moves elsewhere keeps the tracker true.","whatGoodLooksLike":"After a change merges, its linked issue accounts for what landed: delivered outcomes are marked or reported, any remainder is named, and the issue''s state matches.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":"honours-linked-issue-acceptance-criteria"},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 164\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Outcome unconfirmed</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"150.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(16 48)\"><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"3\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M4 5.5v5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"12\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M12 10.5V6a3 3 0 0 0-3-3H7.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></g>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"61\" font-size=\"15\">Merged</text>\n  <text class=\"pv-fill-muted\" x=\"16\" y=\"93\" font-size=\"15\">Added search</text>\n  <path class=\"pv-stroke-muted\" d=\"M152 56h32\" fill=\"none\" stroke-width=\"2\"/>\n  <circle class=\"pv-fill-muted\" cx=\"152\" cy=\"56\" r=\"4\"/>\n  <circle class=\"pv-fill-muted\" cx=\"184\" cy=\"56\" r=\"4\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"184.75\" y=\"32.75\" width=\"118.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"200\" y=\"61\" font-size=\"15\">Issue #57</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"200.75\" y=\"80.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"228\" y=\"93\" font-size=\"15\">Search</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"200.75\" y=\"104.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"228\" y=\"117\" font-size=\"15\">Export</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"160\" font-size=\"15\">Tracker stale</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Outcome confirmed</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"150.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(352 48)\"><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"3\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M4 5.5v5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"12\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M12 10.5V6a3 3 0 0 0-3-3H7.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></g>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"61\" font-size=\"15\">Merged</text>\n  <text class=\"pv-fill-accent\" x=\"352\" y=\"93\" font-size=\"15\">Export deferred</text>\n  <text class=\"pv-fill-accent\" x=\"352\" y=\"111\" font-size=\"15\">to #318</text>\n  <path class=\"pv-stroke-muted\" d=\"M488 56h32\" fill=\"none\" stroke-width=\"2\"/>\n  <circle class=\"pv-fill-muted\" cx=\"488\" cy=\"56\" r=\"4\"/>\n  <circle class=\"pv-fill-muted\" cx=\"520\" cy=\"56\" r=\"4\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"520.75\" y=\"32.75\" width=\"118.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"536\" y=\"61\" font-size=\"15\">Issue #57</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"536.75\" y=\"80.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <path class=\"pv-stroke-accent\" d=\"M540 88.5l3 3 5.5-6\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <text class=\"pv-fill-ink\" x=\"564\" y=\"93\" font-size=\"15\">Search</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"536.75\" y=\"104.75\" width=\"14.5\" height=\"14.5\" rx=\"3\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"564\" y=\"117\" font-size=\"15\">Export</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"160\" font-size=\"15\">Tracker current</text>\n</svg>\n","alt":"A merged pull request says only “Added search” and linked Issue #57 has nothing ticked, so the tracker is stale. When Search is ticked and the pull request says “Export deferred to #318”, the tracker is current."},"guide":{"markdown":"## How to do it\n\n- After the merge, find the checkable items in each issue that your change implements.\n- Record each delivered item with a tick or a sentence that names it.\n- If only part of an item is done, tick or name that part.\n- Name what remains and say that it is deferred. For example, instead of “Added the search screen”, write “Search box and filters are done. Saved searches move to #318.”\n- Put this record in the issue, in your description, or in a comment.\n\n## When it does not apply\n\n- The pull request or merge request is not merged.\n- Your change does not implement any linked issue. A plain mention of an issue does not count.\n- The linked issue states no outcome you can check. It has no task list and no sub-issues. It has no section that says what counts as done or lists steps with expected results. A user story alone does not count.\n- The linked issue was closed as not planned, as a duplicate, or as replaced by other work.\n\nIt still applies when the issue is already closed, and when your change delivers only part of an item.\n\n## Common mistakes\n\n- Thinking that you must tick every box. A plain sentence that says what is done and what is deferred works just as well.\n- Letting the closed issue speak for you. On GitHub, a closing keyword closes the linked issue when you merge into the default branch. Its boxes stay as they were. Instead, tick the delivered items or add a closing sentence.\n- Ticking template boxes such as “builds”, “reviewed” or “lint clean”. They name no item of the issue. Instead, tick boxes whose words match the issue’s items.\n- Naming only the feature, such as “added the search screen”. Instead, name the items that are done and the ones that move on.\n\n## Sources\n\n- [The Scrum Guide](https://scrumguides.org/scrum-guide.html), Ken Schwaber and Jeff Sutherland, 2020. In Scrum, work that fails the team’s agreed quality checks returns to their list of future work.\n- [Task lists](https://docs.gitlab.com/user/markdown/#task-lists), GitLab Docs. You can mark tasks complete, incomplete or inapplicable in issues, merge requests and comments.\n- [Linking a pull request to an issue](https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/linking-a-pull-request-to-an-issue), GitHub Docs. A closing keyword closes the linked issue when the pull request merges into the default branch.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"The linked issue accounts for merged work"'::jsonb),'v5:7d52199fc41fae85eb814538769526f7dea44b16e55148795180eef8eadb217b','practice:v3:c8375c22579e041cda22393c257303a2fe10634778cc1f00310f257874fc3da1');
INSERT INTO _cutover_bundle VALUES('PRACTICE','defers-review-asks-into-tracked-work','scm.pull_request','{"name":"Track the review asks you defer","signals":["scm.pull_request.merged"],"evidenceRequirements":[{"sourceKind":"scm.general-review-comments","stance":"EXHAUSTIVE"},{"sourceKind":"scm.linked-work-items","stance":"CONTEXTUAL"},{"sourceKind":"scm.pull-request.comments","stance":"EXHAUSTIVE"},{"sourceKind":"scm.pull-request.core","stance":"EXHAUSTIVE"},{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.review-threads","stance":"EXHAUSTIVE"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured pull or merge request at its pinned revision: the change itself, the description as written, the commits, the review discussion and the linked context the practice names. Distinguish what the author wrote from what a reviewer, a template or the provider''s current state says.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: a review ask the author defers rather than addresses is turned into tracked work or explicitly waived by the reviewer, never resolved on a bare promise.\n\n## The standard\nJudge one thing: when a reviewer asked for something in a thread and the author did not do it in this change, what happened to the ask at the merge? A deferral is tracked when the thread, the body or a comment names an issue for it (`#number`, a link, \"tracked in …\") or the reviewer explicitly agrees to drop it (\"fine to skip\", \"not needed\", a reviewer statement accepting the author''s stated reason). An approval given on the condition that the ask be done later (\"Approved, as long as you add the tests in a follow-up\") keeps the ask alive: it is a deferral that needs a tracked item, never a waiver. A deferral is bare when the ask is resolved or the change merged with only \"later\", \"next PR\", \"will do\" or silence. Judge only asks the author deferred; an ask the author addressed in the diff, or answered with a reason the reviewer accepted, is not a deferral.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when: the pull request is not merged; the complete captured inline and general review record contains no ask the author left unaddressed in the change — every ask was addressed in the diff or answered with a reason the reviewer accepted. A question that requests no change (\"what is this for?\") is not an ask, whether or not it was answered, and neither is a remark aimed at later work (\"something to keep in mind next time\") or a suggestion the reviewer plainly leaves to the author''s choice: it asks nothing of this change. Polite wording (\"could you\", \"consider\", \"if possible\") does not make a request optional; judge what the reviewer asked of this change. The author is the `author` login of `context/metadata.json`; a comment by any other login is a reviewer''s, and a reviewer''s own \"ignore\" or \"fine\" on an ask — theirs or a bot''s — is a waiver. A merged change with at least one deferred ask is the occasion.\n\n## Sources\n1. The inline review comments (`context/comments.json`: `path`, `line`, `body`, `author`, `created_at`) and the conversation (`context/general_comments.json`): every ask and every reply, with authors and dates. They establish which asks were made, which were answered, and with what words. The threads (`context/review_threads.json`) carry each thread''s path, line and resolution and no words; a resolution by the author establishes nothing about the substance, and a resolution by the reviewer after the author''s stated reason is the reviewer accepting it. The precomputed leads below these criteria list every comment by someone other than the author, one row each, with whether the change touches its file, whether the author replied, whether the reviewer had a later word on the thread or approved after it: decide every row that asks something.\n2. The diff (`work/change/diff.patch`): whether an ask was addressed in the change — the file and line the thread anchors to, read as changed or not. It establishes addressed versus not; it never establishes a waiver.\n3. The body and the discussion (`context/description.md`, `context/general_comments.json`): a follow-up list, an issue reference for the deferral, or the reviewer''s agreement. They establish tracking or a waiver when quotable.\n4. The linked work items (`context/linked_work_items/<n>.md`) when captured: an issue that names the deferred ask. It establishes the tracking; its absence establishes nothing when a comment names an issue by number.\nIf the change merged but the threads are absent or truncated, report a collection gap and record no observation.\n\n## Judge\nEnumerate every ask by someone other than the author first and decide each against the diff — a two-part ask half-addressed leaves one part deferred, and a thread marked RESOLVED decides nothing. An ask about the pull request itself rather than its code — mark it ready, retitle it, link an issue, fill in the description — is addressed when the captured record shows it done: the draft flag, the title, the description or the link. A draft cannot be merged, so a merged pull request settles a request to mark it ready; no transition time is needed. An ask about the code is addressed only by a changed line that does what was asked; an unchanged anchor alone does not establish that the ask was unaddressed: a guard or other relevant change elsewhere can satisfy it. Inspect the request''s substance and the complete changed code before deciding. An ask the author answered with a reason is deferred bare unless the reviewer explicitly accepts the reason; a later approval without such evidence is not a waiver. Then assess the standard against all relevant evidence.\n- MET: at least one ask is deferred, and every deferred ask is tracked by a named issue or explicitly waived by the reviewer. Quote the ask and the tracking reference or the waiver.\n- NOT_MET: at least one ask was deferred on a bare promise or in silence — resolved or merged past with no issue and no reviewer waiver. Quote the ask and the author''s last word on it, or note the silence.\n- UNDETERMINED: the thread''s last word could be a waiver or a deferral and the reviewer''s approval carries no comment; name the fact that would settle it.\nOne observation per review, on the single most consequential bare deferral when there are several.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: a small ask (a rename, a comment, a nit) deferred bare. MAJOR: a correctness, safety or test ask deferred on a bare promise and the change merged. Identical evidence yields identical severity.\n\n## Grounding\nQuote the reviewer''s ask and the author''s reply verbatim with their authors and dates, and the issue reference or waiver when there is one. Never infer a waiver from an approval alone, and never claim an ask was addressed without the changed line that addresses it.\n\n## Defer\nWhether the author replied to comments at all belongs to `engaging-with-inline-review-comments`; a thread left unresolved at the merge belongs to `merged-past-unresolved-review-threads`. Here only: where did the deferred asks go?","precomputeScript":"import { contextFile } from \"../lib/context.ts\";\n// Precompute FACTS for defers-review-asks-into-tracked-work: every ask a reviewer made, one row\n// each, with what the record shows beside it — whether the change touches the file the ask is on,\n// whether the author replied and what the reply names, whether the reviewer had a later word on it\n// or approved after it, whether the thread was marked resolved. The review decides for each row\n// whether the ask was addressed, deferred into tracked work, waived or merged past; a thread''s\n// RESOLVED mark is who clicked it, not what happened to the ask.\nimport { issueNumberReferences } from \"../lib/references.ts\";\nimport {\n\ttype GeneralComment,\n\ttype ReviewComment,\n\tchangeNear,\n\texcerpt,\n\tlater,\n\treadGeneralComments,\n\treadReviewComments,\n\treadReviewThreads,\n\treviewerCommentRows,\n} from \"../lib/review.ts\";\nimport type { DiffFile, Hint, PullRequestMetadata } from \"../lib/types.ts\";\n\n/** Words a reply uses to put an ask off rather than answer it. */\nconst DEFERRAL =\n\t/\\b(?:later|next (?:mr|pr|merge request|pull request|sprint|iteration)|follow[- ]?up|will (?:do|add|fix|revisit|look)|todo|not (?:in|for) this (?:mr|pr)|separate (?:mr|pr|issue)|future)\\b/iu;\n\n/** Words a reviewer uses to drop an ask rather than keep it. */\nconst WAIVER =\n\t/\\b(?:fine to skip|not needed|no need|never mind|nevermind|ignore|optional|nit|non[- ]blocking|up to you|can be skipped)\\b/iu;\n\nexport default async function defersReviewAsksIntoTrackedWork(\n\t_repoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\tmetadata: PullRequestMetadata,\n\tcontextDir: string | undefined,\n\t_changeDir: string | undefined,\n\tcontextReference: string,\n) {\n\tconst author = metadata.author ?? \"\";\n\tconst inline = await readReviewComments(contextDir);\n\tconst general = await readGeneralComments(contextDir);\n\tconst record = await readReviewThreads(contextDir);\n\tconst decisions = record?.decisions ?? [];\n\tconst hints: Hint[] = [];\n\tconst byOthers = (comment: { author?: string }) =>\n\t\tcomment.author !== undefined && comment.author !== author;\n\tconst approvedAfter = (at: string | undefined) =>\n\t\tdecisions.some(\n\t\t\t(d) => d.state === \"APPROVED\" && d.dismissed !== true && later(d.submittedAt, at),\n\t\t);\n\t// An inline ask: the first comment in a thread by someone other than the author. The author''s\n\t// later comments in the thread are its answers; the others'' later comments there are the\n\t// reviewer''s last word on it, not new asks.\n\tconst inlineAsks = reviewerCommentRows(inline ?? [], record?.threads ?? [], author).filter(\n\t\t(r) => r.opensThread,\n\t);\n\tfor (const ask of inlineAsks) {\n\t\thints.push(\n\t\t\trow(ask.comment, ask.replies, ask.followUps, diffFiles, contextReference, {\n\t\t\t\tthreadResolved: ask.thread?.state === \"RESOLVED\",\n\t\t\t\tapprovedAfterAsk: approvedAfter(ask.comment.createdAt),\n\t\t\t}),\n\t\t);\n\t}\n\t// A conversation ask: a general comment by someone other than the author; the author''s later\n\t// general comments are the candidate answers, the others'' later ones the follow-ups.\n\tconst conversationAsks = (general ?? []).filter(byOthers);\n\tfor (const ask of conversationAsks) {\n\t\tconst afterAsk = (c: GeneralComment) => later(c.createdAt, ask.createdAt);\n\t\tconst replies = (general ?? []).filter((c) => c.author === author && afterAsk(c));\n\t\tconst followUps = (general ?? []).filter((c) => byOthers(c) && afterAsk(c));\n\t\thints.push(\n\t\t\trow({ ...ask, path: \"\", outdated: false }, replies, followUps, diffFiles, contextReference, {\n\t\t\t\tthreadResolved: false,\n\t\t\t\tapprovedAfterAsk: approvedAfter(ask.createdAt),\n\t\t\t}),\n\t\t);\n\t}\n\tconst directions: string[] = [];\n\tif (inline === null || general === null) {\n\t\tdirections.push(\n\t\t\t\"A required comments file is missing or malformed (comments.json or general_comments.json): report a collection gap and record no observation; an unread source does not establish that no ask exists.\",\n\t\t);\n\t} else if (hints.length === 0) {\n\t\tdirections.push(\n\t\t\t`No comment by anyone other than the author in the captured record (${inline.length} inline comment(s), ${general.length} conversation comment(s)): with no ask, the occasion did not arise.`,\n\t\t);\n\t} else {\n\t\tdirections.push(\n\t\t\t`${String(hints.length)} comment(s) by others are listed, one row each; a remark that asks nothing of this change is not an ask. Decide every ask: one about the code is addressed when the head diff carries the change asked for; one about the pull request itself — mark it ready, retitle it, link an issue, fill in the description — when the captured record shows it done (metadata.json, description.md, the linked work items), and a merged pull request was not a draft when it merged; deferred into tracked work when the author''s reply names an issue or the description defers it to one; waived when the reviewer drops the ask in their own words, in the ask or in a follow-up, otherwise deferred bare. A later approval alone does not establish a waiver. A RESOLVED thread says nothing by itself, and \"approved on the condition that you do it next time\" is a deferral to track, not a waiver.`,\n\t\t\t\"A two-part ask is two asks: address one part and the other still stands.\",\n\t\t);\n\t}\n\treturn {\n\t\thints,\n\t\tmetrics: {\n\t\t\tasks: hints.length,\n\t\t\tinlineAsks: inlineAsks.length,\n\t\t\tconversationAsks: conversationAsks.length,\n\t\t\tasksWithAuthorReply: hints.filter((h) => h.flags.authorReplied === true).length,\n\t\t\tasksNamingAnIssueInReply: hints.filter((h) => h.flags.issueNamedInReply === true).length,\n\t\t\tcommentsFileAbsent: inline === null ? 1 : 0,\n\t\t\tgeneralCommentsFileAbsent: general === null ? 1 : 0,\n\t\t},\n\t\tdirections,\n\t};\n}\n\nfunction row(\n\task: ReviewComment | (GeneralComment & { path: string; outdated: boolean }),\n\treplies: readonly { body: string }[],\n\tfollowUps: readonly { body: string }[],\n\tdiffFiles: Map<string, DiffFile>,\n\tcontextReference: string,\n\trecord: { threadResolved: boolean; approvedAfterAsk: boolean },\n): Hint {\n\tconst replyText = replies.map((r) => r.body).join(\"\\n\");\n\tconst followUpText = followUps.map((r) => r.body).join(\"\\n\");\n\tconst line = \"line\" in ask ? ask.line : undefined;\n\tconst flags: Hint[\"flags\"] = {\n\t\tby: ask.author ?? \"\",\n\t\tat: ask.createdAt ?? \"\",\n\t\tauthorReplied: replies.length > 0,\n\t\tissueNamedInReply: issueNumberReferences(replyText).length > 0,\n\t\tdeferralWordsInReply: DEFERRAL.test(replyText),\n\t\twaiverWordsInAsk: WAIVER.test(ask.body),\n\t\treviewerFollowedUp: followUps.length > 0,\n\t\twaiverWordsInFollowUp: WAIVER.test(followUpText),\n\t\tapprovedAfterAsk: record.approvedAfterAsk,\n\t\tthreadResolved: record.threadResolved,\n\t};\n\tif (ask.path !== \"\") {\n\t\tflags.fileInChange = diffFiles.has(ask.path);\n\t\tflags.changeNearLine = changeNear(diffFiles.get(ask.path), line);\n\t\tflags.outdated = ask.outdated;\n\t}\n\treturn {\n\t\tfile: ask.path === \"\" ? contextFile(contextReference, \"general_comments.json\") : ask.path,\n\t\tline: line ?? 0,\n\t\tpattern: ask.path === \"\" ? \"conversation ask\" : \"inline ask\",\n\t\tcontext: excerpt(ask.body),\n\t\tinDiff: false,\n\t\tflags,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A reviewer''s ask answered with ''later'' and nothing else is a promise that evaporates at the merge. Turning a deferred ask into a tracked issue, or getting the reviewer''s explicit agreement to drop it, keeps the review''s value after the thread is resolved.","whatGoodLooksLike":"Every review ask the author does not address in the change is either turned into an issue the thread links, or explicitly waived by the reviewer; nothing is resolved with a bare ''will do later''.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 104\">\n  <rect class=\"pv-fill-surface pv-stroke-ink\" x=\"0.75\" y=\"32.75\" width=\"134.5\" height=\"38.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"16\" y=\"57\" font-size=\"15\">Deferred ask</text>\n  <path class=\"pv-stroke-muted\" d=\"M136 52h20v-32h28\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M192 20l-8-5v10z\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"200.75\" y=\"0.75\" width=\"214.5\" height=\"38.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"216\" y=\"25\" font-size=\"15\">“Will do later”</text>\n  <path class=\"pv-stroke-muted\" d=\"M424 20h16\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M448 20l-8-5v10z\"/>\n  <text class=\"pv-fill-muted\" x=\"460\" y=\"25\" font-size=\"15\">Lost at merge</text>\n  <path class=\"pv-stroke-accent\" d=\"M156 52v32h28\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-accent\" d=\"M192 84l-8-5v10z\"/>\n  <rect class=\"pv-fill-accent-soft pv-stroke-accent\" x=\"200.75\" y=\"64.75\" width=\"214.5\" height=\"38.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"216\" y=\"89\" font-size=\"15\" font-weight=\"600\">“Tracked in #482”</text>\n  <path class=\"pv-stroke-accent\" d=\"M424 84h16\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-accent\" d=\"M448 84l-8-5v10z\"/>\n  <text class=\"pv-fill-ink\" x=\"460\" y=\"89\" font-size=\"15\">Issue #482 keeps it</text>\n</svg>\n","alt":"When a deferred ask gets only “Will do later”, it is lost at merge. When the reply says “Tracked in #482”, Issue #482 keeps it."},"guide":{"markdown":"## How to do it\n\n- Before you merge, check which review asks your change leaves undone.\n- When an ask waits, link an issue that tracks it in the thread. For example, instead of replying “Will do in the next change”, reply “Tracked in #482”.\n- If no issue tracks the ask, open one from the review comment. The issue then shows where the ask came from.\n- When you think an ask is not needed, ask the reviewer in the thread to accept your reason.\n- When you do only part of an ask, track the part that is left.\n\n## When it does not apply\n\n- The pull request or merge request did not merge.\n- Your change does every ask, or you gave a reason for each ask left undone and the reviewer accepted it.\n- The comment asks nothing of this change. Examples are a question such as “what is this for?” and a remark for next time.\n- The reviewer leaves the suggestion to your choice.\n\nIt still applies when an ask sounds polite, such as “could you” or “consider”, or when a review bot made it. It also applies when the reviewer approved on the condition that you do the ask later.\n\n## Common mistakes\n\n- Taking an approval as permission to drop the ask. “Approved, as long as you add the tests later” keeps the ask open. Open an issue for the tests and link it.\n- Giving your reason and then merging. An approval with no word on your reason is not agreement. Ask the reviewer to confirm.\n- Resolving the thread with “later”. A resolved thread does not say where the ask went. Link the issue first, then resolve the thread.\n- Trusting yourself to remember. A promise in a thread is easy to lose after the merge. Put it in the tracker, where the team can see it.\n\n## Sources\n\n- [Handling pushback in code reviews](https://google.github.io/eng-practices/review/reviewer/pushback.html#later), Google Engineering Practices. File a bug for cleanup that must wait, so that it does not get lost.\n- [Creating an issue from a comment](https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/creating-an-issue#creating-an-issue-from-a-comment), GitHub Docs. You can open an issue from a pull request comment.\n- [Move open threads to an issue](https://docs.gitlab.com/user/project/merge_requests/#move-open-threads-to-an-issue), GitLab Docs. An open thread can become a new issue that the merge request links.\n- [Potential technical debt and its resolution in code reviews](https://doi.org/10.1145/3544902.3546253), Fu and others, 2022. In OpenStack and Qt, some potential technical debt that reviewers found was still unresolved when the code merged.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Track the review asks you defer","signals":["scm.pull_request.merged"],"evidenceRequirements":[{"sourceKind":"scm.general-review-comments","stance":"EXHAUSTIVE"},{"sourceKind":"scm.linked-work-items","stance":"CONTEXTUAL"},{"sourceKind":"scm.pull-request.comments","stance":"EXHAUSTIVE"},{"sourceKind":"scm.pull-request.core","stance":"EXHAUSTIVE"},{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.review-threads","stance":"EXHAUSTIVE"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured pull or merge request at its pinned revision: the change itself, the description as written, the commits, the review discussion and the linked context the practice names. Distinguish what the author wrote from what a reviewer, a template or the provider''s current state says.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: a review ask the author defers rather than addresses is turned into tracked work or explicitly waived by the reviewer, never resolved on a bare promise.\n\n## The standard\nJudge one thing: when a reviewer asked for something in a thread and the author did not do it in this change, what happened to the ask at the merge? A deferral is tracked when the thread, the body or a comment names an issue for it (`#number`, a link, \"tracked in …\") or the reviewer explicitly agrees to drop it (\"fine to skip\", \"not needed\", a reviewer statement accepting the author''s stated reason). An approval given on the condition that the ask be done later (\"Approved, as long as you add the tests in a follow-up\") keeps the ask alive: it is a deferral that needs a tracked item, never a waiver. A deferral is bare when the ask is resolved or the change merged with only \"later\", \"next PR\", \"will do\" or silence. Judge only asks the author deferred; an ask the author addressed in the diff, or answered with a reason the reviewer accepted, is not a deferral.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when: the pull request is not merged; the complete captured inline and general review record contains no ask the author left unaddressed in the change — every ask was addressed in the diff or answered with a reason the reviewer accepted. A question that requests no change (\"what is this for?\") is not an ask, whether or not it was answered, and neither is a remark aimed at later work (\"something to keep in mind next time\") or a suggestion the reviewer plainly leaves to the author''s choice: it asks nothing of this change. Polite wording (\"could you\", \"consider\", \"if possible\") does not make a request optional; judge what the reviewer asked of this change. The author is the `author` login of `context/metadata.json`; a comment by any other login is a reviewer''s, and a reviewer''s own \"ignore\" or \"fine\" on an ask — theirs or a bot''s — is a waiver. A merged change with at least one deferred ask is the occasion.\n\n## Sources\n1. The inline review comments (`context/comments.json`: `path`, `line`, `body`, `author`, `created_at`) and the conversation (`context/general_comments.json`): every ask and every reply, with authors and dates. They establish which asks were made, which were answered, and with what words. The threads (`context/review_threads.json`) carry each thread''s path, line and resolution and no words; a resolution by the author establishes nothing about the substance, and a resolution by the reviewer after the author''s stated reason is the reviewer accepting it. The precomputed leads below these criteria list every comment by someone other than the author, one row each, with whether the change touches its file, whether the author replied, whether the reviewer had a later word on the thread or approved after it: decide every row that asks something.\n2. The diff (`work/change/diff.patch`): whether an ask was addressed in the change — the file and line the thread anchors to, read as changed or not. It establishes addressed versus not; it never establishes a waiver.\n3. The body and the discussion (`context/description.md`, `context/general_comments.json`): a follow-up list, an issue reference for the deferral, or the reviewer''s agreement. They establish tracking or a waiver when quotable.\n4. The linked work items (`context/linked_work_items/<n>.md`) when captured: an issue that names the deferred ask. It establishes the tracking; its absence establishes nothing when a comment names an issue by number.\nIf the change merged but the threads are absent or truncated, report a collection gap and record no observation.\n\n## Judge\nEnumerate every ask by someone other than the author first and decide each against the diff — a two-part ask half-addressed leaves one part deferred, and a thread marked RESOLVED decides nothing. An ask about the pull request itself rather than its code — mark it ready, retitle it, link an issue, fill in the description — is addressed when the captured record shows it done: the draft flag, the title, the description or the link. A draft cannot be merged, so a merged pull request settles a request to mark it ready; no transition time is needed. An ask about the code is addressed only by a changed line that does what was asked; an unchanged anchor alone does not establish that the ask was unaddressed: a guard or other relevant change elsewhere can satisfy it. Inspect the request''s substance and the complete changed code before deciding. An ask the author answered with a reason is deferred bare unless the reviewer explicitly accepts the reason; a later approval without such evidence is not a waiver. Then assess the standard against all relevant evidence.\n- MET: at least one ask is deferred, and every deferred ask is tracked by a named issue or explicitly waived by the reviewer. Quote the ask and the tracking reference or the waiver.\n- NOT_MET: at least one ask was deferred on a bare promise or in silence — resolved or merged past with no issue and no reviewer waiver. Quote the ask and the author''s last word on it, or note the silence.\n- UNDETERMINED: the thread''s last word could be a waiver or a deferral and the reviewer''s approval carries no comment; name the fact that would settle it.\nOne observation per review, on the single most consequential bare deferral when there are several.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: a small ask (a rename, a comment, a nit) deferred bare. MAJOR: a correctness, safety or test ask deferred on a bare promise and the change merged. Identical evidence yields identical severity.\n\n## Grounding\nQuote the reviewer''s ask and the author''s reply verbatim with their authors and dates, and the issue reference or waiver when there is one. Never infer a waiver from an approval alone, and never claim an ask was addressed without the changed line that addresses it.\n\n## Defer\nWhether the author replied to comments at all belongs to `engaging-with-inline-review-comments`; a thread left unresolved at the merge belongs to `merged-past-unresolved-review-threads`. Here only: where did the deferred asks go?","precomputeScript":"import { contextFile } from \"../lib/context.ts\";\n// Precompute FACTS for defers-review-asks-into-tracked-work: every ask a reviewer made, one row\n// each, with what the record shows beside it — whether the change touches the file the ask is on,\n// whether the author replied and what the reply names, whether the reviewer had a later word on it\n// or approved after it, whether the thread was marked resolved. The review decides for each row\n// whether the ask was addressed, deferred into tracked work, waived or merged past; a thread''s\n// RESOLVED mark is who clicked it, not what happened to the ask.\nimport { issueNumberReferences } from \"../lib/references.ts\";\nimport {\n\ttype GeneralComment,\n\ttype ReviewComment,\n\tchangeNear,\n\texcerpt,\n\tlater,\n\treadGeneralComments,\n\treadReviewComments,\n\treadReviewThreads,\n\treviewerCommentRows,\n} from \"../lib/review.ts\";\nimport type { DiffFile, Hint, PullRequestMetadata } from \"../lib/types.ts\";\n\n/** Words a reply uses to put an ask off rather than answer it. */\nconst DEFERRAL =\n\t/\\b(?:later|next (?:mr|pr|merge request|pull request|sprint|iteration)|follow[- ]?up|will (?:do|add|fix|revisit|look)|todo|not (?:in|for) this (?:mr|pr)|separate (?:mr|pr|issue)|future)\\b/iu;\n\n/** Words a reviewer uses to drop an ask rather than keep it. */\nconst WAIVER =\n\t/\\b(?:fine to skip|not needed|no need|never mind|nevermind|ignore|optional|nit|non[- ]blocking|up to you|can be skipped)\\b/iu;\n\nexport default async function defersReviewAsksIntoTrackedWork(\n\t_repoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\tmetadata: PullRequestMetadata,\n\tcontextDir: string | undefined,\n\t_changeDir: string | undefined,\n\tcontextReference: string,\n) {\n\tconst author = metadata.author ?? \"\";\n\tconst inline = await readReviewComments(contextDir);\n\tconst general = await readGeneralComments(contextDir);\n\tconst record = await readReviewThreads(contextDir);\n\tconst decisions = record?.decisions ?? [];\n\tconst hints: Hint[] = [];\n\tconst byOthers = (comment: { author?: string }) =>\n\t\tcomment.author !== undefined && comment.author !== author;\n\tconst approvedAfter = (at: string | undefined) =>\n\t\tdecisions.some(\n\t\t\t(d) => d.state === \"APPROVED\" && d.dismissed !== true && later(d.submittedAt, at),\n\t\t);\n\t// An inline ask: the first comment in a thread by someone other than the author. The author''s\n\t// later comments in the thread are its answers; the others'' later comments there are the\n\t// reviewer''s last word on it, not new asks.\n\tconst inlineAsks = reviewerCommentRows(inline ?? [], record?.threads ?? [], author).filter(\n\t\t(r) => r.opensThread,\n\t);\n\tfor (const ask of inlineAsks) {\n\t\thints.push(\n\t\t\trow(ask.comment, ask.replies, ask.followUps, diffFiles, contextReference, {\n\t\t\t\tthreadResolved: ask.thread?.state === \"RESOLVED\",\n\t\t\t\tapprovedAfterAsk: approvedAfter(ask.comment.createdAt),\n\t\t\t}),\n\t\t);\n\t}\n\t// A conversation ask: a general comment by someone other than the author; the author''s later\n\t// general comments are the candidate answers, the others'' later ones the follow-ups.\n\tconst conversationAsks = (general ?? []).filter(byOthers);\n\tfor (const ask of conversationAsks) {\n\t\tconst afterAsk = (c: GeneralComment) => later(c.createdAt, ask.createdAt);\n\t\tconst replies = (general ?? []).filter((c) => c.author === author && afterAsk(c));\n\t\tconst followUps = (general ?? []).filter((c) => byOthers(c) && afterAsk(c));\n\t\thints.push(\n\t\t\trow({ ...ask, path: \"\", outdated: false }, replies, followUps, diffFiles, contextReference, {\n\t\t\t\tthreadResolved: false,\n\t\t\t\tapprovedAfterAsk: approvedAfter(ask.createdAt),\n\t\t\t}),\n\t\t);\n\t}\n\tconst directions: string[] = [];\n\tif (inline === null || general === null) {\n\t\tdirections.push(\n\t\t\t\"A required comments file is missing or malformed (comments.json or general_comments.json): report a collection gap and record no observation; an unread source does not establish that no ask exists.\",\n\t\t);\n\t} else if (hints.length === 0) {\n\t\tdirections.push(\n\t\t\t`No comment by anyone other than the author in the captured record (${inline.length} inline comment(s), ${general.length} conversation comment(s)): with no ask, the occasion did not arise.`,\n\t\t);\n\t} else {\n\t\tdirections.push(\n\t\t\t`${String(hints.length)} comment(s) by others are listed, one row each; a remark that asks nothing of this change is not an ask. Decide every ask: one about the code is addressed when the head diff carries the change asked for; one about the pull request itself — mark it ready, retitle it, link an issue, fill in the description — when the captured record shows it done (metadata.json, description.md, the linked work items), and a merged pull request was not a draft when it merged; deferred into tracked work when the author''s reply names an issue or the description defers it to one; waived when the reviewer drops the ask in their own words, in the ask or in a follow-up, otherwise deferred bare. A later approval alone does not establish a waiver. A RESOLVED thread says nothing by itself, and \"approved on the condition that you do it next time\" is a deferral to track, not a waiver.`,\n\t\t\t\"A two-part ask is two asks: address one part and the other still stands.\",\n\t\t);\n\t}\n\treturn {\n\t\thints,\n\t\tmetrics: {\n\t\t\tasks: hints.length,\n\t\t\tinlineAsks: inlineAsks.length,\n\t\t\tconversationAsks: conversationAsks.length,\n\t\t\tasksWithAuthorReply: hints.filter((h) => h.flags.authorReplied === true).length,\n\t\t\tasksNamingAnIssueInReply: hints.filter((h) => h.flags.issueNamedInReply === true).length,\n\t\t\tcommentsFileAbsent: inline === null ? 1 : 0,\n\t\t\tgeneralCommentsFileAbsent: general === null ? 1 : 0,\n\t\t},\n\t\tdirections,\n\t};\n}\n\nfunction row(\n\task: ReviewComment | (GeneralComment & { path: string; outdated: boolean }),\n\treplies: readonly { body: string }[],\n\tfollowUps: readonly { body: string }[],\n\tdiffFiles: Map<string, DiffFile>,\n\tcontextReference: string,\n\trecord: { threadResolved: boolean; approvedAfterAsk: boolean },\n): Hint {\n\tconst replyText = replies.map((r) => r.body).join(\"\\n\");\n\tconst followUpText = followUps.map((r) => r.body).join(\"\\n\");\n\tconst line = \"line\" in ask ? ask.line : undefined;\n\tconst flags: Hint[\"flags\"] = {\n\t\tby: ask.author ?? \"\",\n\t\tat: ask.createdAt ?? \"\",\n\t\tauthorReplied: replies.length > 0,\n\t\tissueNamedInReply: issueNumberReferences(replyText).length > 0,\n\t\tdeferralWordsInReply: DEFERRAL.test(replyText),\n\t\twaiverWordsInAsk: WAIVER.test(ask.body),\n\t\treviewerFollowedUp: followUps.length > 0,\n\t\twaiverWordsInFollowUp: WAIVER.test(followUpText),\n\t\tapprovedAfterAsk: record.approvedAfterAsk,\n\t\tthreadResolved: record.threadResolved,\n\t};\n\tif (ask.path !== \"\") {\n\t\tflags.fileInChange = diffFiles.has(ask.path);\n\t\tflags.changeNearLine = changeNear(diffFiles.get(ask.path), line);\n\t\tflags.outdated = ask.outdated;\n\t}\n\treturn {\n\t\tfile: ask.path === \"\" ? contextFile(contextReference, \"general_comments.json\") : ask.path,\n\t\tline: line ?? 0,\n\t\tpattern: ask.path === \"\" ? \"conversation ask\" : \"inline ask\",\n\t\tcontext: excerpt(ask.body),\n\t\tinDiff: false,\n\t\tflags,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A reviewer''s ask answered with ''later'' and nothing else is a promise that evaporates at the merge. Turning a deferred ask into a tracked issue, or getting the reviewer''s explicit agreement to drop it, keeps the review''s value after the thread is resolved.","whatGoodLooksLike":"Every review ask the author does not address in the change is either turned into an issue the thread links, or explicitly waived by the reviewer; nothing is resolved with a bare ''will do later''.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 104\">\n  <rect class=\"pv-fill-surface pv-stroke-ink\" x=\"0.75\" y=\"32.75\" width=\"134.5\" height=\"38.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"16\" y=\"57\" font-size=\"15\">Deferred ask</text>\n  <path class=\"pv-stroke-muted\" d=\"M136 52h20v-32h28\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M192 20l-8-5v10z\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"200.75\" y=\"0.75\" width=\"214.5\" height=\"38.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"216\" y=\"25\" font-size=\"15\">“Will do later”</text>\n  <path class=\"pv-stroke-muted\" d=\"M424 20h16\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M448 20l-8-5v10z\"/>\n  <text class=\"pv-fill-muted\" x=\"460\" y=\"25\" font-size=\"15\">Lost at merge</text>\n  <path class=\"pv-stroke-accent\" d=\"M156 52v32h28\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-accent\" d=\"M192 84l-8-5v10z\"/>\n  <rect class=\"pv-fill-accent-soft pv-stroke-accent\" x=\"200.75\" y=\"64.75\" width=\"214.5\" height=\"38.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"216\" y=\"89\" font-size=\"15\" font-weight=\"600\">“Tracked in #482”</text>\n  <path class=\"pv-stroke-accent\" d=\"M424 84h16\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-accent\" d=\"M448 84l-8-5v10z\"/>\n  <text class=\"pv-fill-ink\" x=\"460\" y=\"89\" font-size=\"15\">Issue #482 keeps it</text>\n</svg>\n","alt":"When a deferred ask gets only “Will do later”, it is lost at merge. When the reply says “Tracked in #482”, Issue #482 keeps it."},"guide":{"markdown":"## How to do it\n\n- Before you merge, check which review asks your change leaves undone.\n- When an ask waits, link an issue that tracks it in the thread. For example, instead of replying “Will do in the next change”, reply “Tracked in #482”.\n- If no issue tracks the ask, open one from the review comment. The issue then shows where the ask came from.\n- When you think an ask is not needed, ask the reviewer in the thread to accept your reason.\n- When you do only part of an ask, track the part that is left.\n\n## When it does not apply\n\n- The pull request or merge request did not merge.\n- Your change does every ask, or you gave a reason for each ask left undone and the reviewer accepted it.\n- The comment asks nothing of this change. Examples are a question such as “what is this for?” and a remark for next time.\n- The reviewer leaves the suggestion to your choice.\n\nIt still applies when an ask sounds polite, such as “could you” or “consider”, or when a review bot made it. It also applies when the reviewer approved on the condition that you do the ask later.\n\n## Common mistakes\n\n- Taking an approval as permission to drop the ask. “Approved, as long as you add the tests later” keeps the ask open. Open an issue for the tests and link it.\n- Giving your reason and then merging. An approval with no word on your reason is not agreement. Ask the reviewer to confirm.\n- Resolving the thread with “later”. A resolved thread does not say where the ask went. Link the issue first, then resolve the thread.\n- Trusting yourself to remember. A promise in a thread is easy to lose after the merge. Put it in the tracker, where the team can see it.\n\n## Sources\n\n- [Handling pushback in code reviews](https://google.github.io/eng-practices/review/reviewer/pushback.html#later), Google Engineering Practices. File a bug for cleanup that must wait, so that it does not get lost.\n- [Creating an issue from a comment](https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/creating-an-issue#creating-an-issue-from-a-comment), GitHub Docs. You can open an issue from a pull request comment.\n- [Move open threads to an issue](https://docs.gitlab.com/user/project/merge_requests/#move-open-threads-to-an-issue), GitLab Docs. An open thread can become a new issue that the merge request links.\n- [Potential technical debt and its resolution in code reviews](https://doi.org/10.1145/3544902.3546253), Fu and others, 2022. In OpenStack and Qt, some potential technical debt that reviewers found was still unresolved when the code merged.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Deferred review asks become tracked issues"'::jsonb),'v5:7fab223b471cc13aeaec1e14e98ac8649be449ba51c325d2407af8340f57e1c2','practice:v3:f57da0d2baffba0534bd582a3a5058d492ae9519749f8080779216fcda249dc6');
INSERT INTO _cutover_bundle VALUES('PRACTICE','merges-only-after-approval','scm.pull_request','{"name":"Merge only after someone else approved","signals":["scm.pull_request.merged"],"evidenceRequirements":[{"sourceKind":"scm.general-review-comments","stance":"CONTEXTUAL"},{"sourceKind":"scm.pull-request.core","stance":"REQUIRED"},{"sourceKind":"scm.review-threads","stance":"EXHAUSTIVE"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"MERGER","precondition":null,"criteria":"Review this practice against the captured pull or merge request at its pinned revision: the change itself, the description as written, the commits, the review discussion and the linked context the practice names. Distinguish what the author wrote from what a reviewer, a template or the provider''s current state says.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the merge happens after a current approval from someone other than the author, and never over an outstanding request for changes.\n\n## The standard\nJudge one thing about the moment this pull request merged: was there, at that moment, an approval from another person — an account other than the author''s whose decision is not marked `bot` — that still stood? An approval stands when it was submitted before the merge and nothing later withdrew it — no dismissal, no revocation (`UNAPPROVED`) and no request for changes by the same reviewer after it. A request for changes stands when it was submitted before the merge and no later approval by the same reviewer replaced it. A decision marked `bot` is an automated account''s recorded act, never another person''s review: its approval is not an approval here, and its request for changes does not stand against another person''s approval. A complete bounded event record with no dismissal, revocation or later request for changes establishes no recorded withdrawal within that boundary. A latest-state snapshot alone does not establish complete historical event coverage. Merging with a standing approval and no standing request for changes is the practice; merging with none, or over a standing request for changes, is the lapse. Judge the decisions as recorded, never whether the review was thorough — that belongs to the review practices. That the author presses the merge button on their own pull request is the ordinary course in most teams and is never the lapse here; the only lapse is merging without another person''s standing approval. The subject is the person who merged, whether or not that person authored the change.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when: the pull request is not merged; or the repository plainly works without review — no reviewer was requested, no review decision or review thread exists on this pull request, and the inventory shows a single-person project. A pull request with a reviewer requested, a review decision or a review comment is the occasion; a decision marked `bot` is still a review decision for this gate.\n\n## Sources\n1. The pull request record (`context/metadata.json`): `merged_at`, `merged_by`, `author`. It establishes who merged and when. When `merged_by` is absent, record no observation: the review cannot name the merger. A different recorded merger is still the subject.\n2. The review decisions (`context/review_threads.json`, `reviewDecisions` oldest first: `state`, `author`, `submittedAt`, `body` when one was written, `dismissed`) and the threads: each captured decision with its author and time. `decisionHistoryComplete` is `false`, since a decision withdrawn or replaced earlier may be missing. `submittedAt` is the decision event time, absent when unknown. On GitLab, a native approval date is recovered from a standing approval after merge; a native date before `merged_at` is therefore a positive witness that the approval stood at merge. Last-known rows alone do not establish current review readiness when `metadata.json` omits `review_decision`. Do not erase a sufficient historical witness merely because current readiness later became unknown. The record''s silence about a withdrawal never proves that none happened. A current `DISMISSED` state or `dismissed` flag with no withdrawal time establishes only the state at capture, not whether dismissal preceded merge. A dismissal withdraws only the decision of the reviewer it belongs to. On GitHub, a dismissed review keeps its original state beside `dismissed`; a `DISMISSED` state alone leaves that original state unknown. On GitLab, the sync records `DISMISSED` only on an approval row, never on a request for changes. A `truncated` record is a collection gap for this practice. The precomputed leads below these criteria list the merge and one row per decision with `beforeMerge`, `isAuthor`, `dismissed` and `bot` computed, and each reviewer''s last captured decision apart: decide from the rows, and quote the decision and the merge from the record.\n3. The inventory (`context/project_inventory.json`): whether other people work in this project, for the occasion only.\nIf `merged_at` or the decisions are unavailable, report a collection gap and record no observation.\n\n## Judge\nAssess conformance to the standard in this context, reviewer by reviewer: first whether another person''s approval stood at merge, then whether another person''s request for changes stood or may have stood at merge. Each reviewer''s own rows decide that reviewer''s standing: one reviewer''s dismissal, withdrawal or unknown time never unsettles another reviewer''s confirmed approval, and `decisionHistoryComplete: false` alone neither withdraws a confirmed approval nor stands for a request for changes.\n- MET: at least one confirmed standing APPROVED decision by another person — a login other than the author''s, not marked `bot` — submitted before `merged_at`, with no later dismissal, revocation or request for changes by that reviewer, and no captured request for changes by another person that stood or may have stood at merge. An approval marked `bot` never makes this cell. Who pressed merge does not enter into it. Quote the approval and the merge time.\n- NOT_MET: evidence that covers the merge moment establishes no qualifying approval, or establishes another person''s request for changes that still stood at merge. Absence of a human approval in a current snapshot, including a snapshot with only bot approvals, does not establish absence at merge when historical coverage is incomplete. Quote the merge time and the evidence that settles the state at that moment. History the record does not hold never decides this cell.\n- UNDETERMINED: the captured record cannot settle a deciding event''s order or standing membership at merge. When no approval by another person is confirmed as standing, this includes an approval by another person that is undated, dated after `merged_at` or dismissed with no dated withdrawal — an earlier approval may have stood at the merge and been replaced since — and absent human approvals with incomplete historical coverage: a previously standing human approval may have been withdrawn after merge. Even beside a confirmed approval, it includes another person''s captured request for changes, or a dismissed decision whose original state is unknown, that may have stood at merge because the record cannot settle its time or its replacement. Current review readiness and historical approval-at-merge are separate facts. An original review submission timestamp does not date a later withdrawal. A truncated required record is a collection gap, not UNDETERMINED.\nOne observation per review.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: merged with no approval where a reviewer was requested and had not answered. MAJOR: merged over a standing request for changes, or after an approval was dismissed and not renewed. Identical evidence yields identical severity.\n\n## Grounding\nQuote `merged_at`, `merged_by` and each decision as recorded with its `author`, `state` and `submittedAt`. Identity is the login as recorded, compared as text: the same login is the same account. Whether an account is automated is the captured `bot` marker, never the login''s shape or a display name; a decision without the marker counts as its reviewer''s own. Never infer that a reviewer is the author from a display name, a repository path or a namespace; never infer an approval from a comment or a thumbs-up; never treat the author''s own approval as one.\n\n## Defer\nWhether review threads were resolved belongs to `merged-past-unresolved-review-threads`. Here only: did another person approve before the merge?","precomputeScript":"// Precompute FACTS for merges-only-after-approval: the merge as the record holds it — who merged,\n// when, the provider''s own review decision — captured decision rows placed against the merge instant.\n// Currentness and history coverage remain separate from this advisory ordering.\nimport {\n\tdecisionRows,\n\tlastDecisionPerReviewer,\n\tmergeFacts,\n\tmergeRow,\n\treadReviewThreads,\n} from \"../lib/review.ts\";\nimport type { DiffFile, PullRequestMetadata } from \"../lib/types.ts\";\n\nexport default async function mergesOnlyAfterApproval(\n\t_repoPath: string,\n\t_diffFiles: Map<string, DiffFile>,\n\tmetadata: PullRequestMetadata,\n\tcontextDir: string | undefined,\n\t_changeDir: string | undefined,\n\tcontextReference: string,\n) {\n\tconst merge = mergeFacts(metadata);\n\tconst record = await readReviewThreads(contextDir);\n\tconst decisions = record?.decisions ?? [];\n\tconst rows = decisionRows(decisions, merge, contextReference);\n\tconst last = decisionRows(lastDecisionPerReviewer(decisions), merge, contextReference).map(\n\t\t(row) => ({\n\t\t\t...row,\n\t\t\tpattern: \"last decision by reviewer\",\n\t\t}),\n\t);\n\tconst approvalsBeforeMergeByOthers = rows.filter(\n\t\t(r) =>\n\t\t\tr.flags.state === \"APPROVED\" &&\n\t\t\tr.flags.beforeMerge === true &&\n\t\t\tr.flags.isAuthor !== true &&\n\t\t\tr.flags.dismissed !== true &&\n\t\t\tr.flags.bot !== true,\n\t).length;\n\tconst unknownDecisionTimes = decisions.filter((d) => d.submittedAt === undefined).length;\n\tconst directions: string[] = [];\n\tif (!merge.merged) {\n\t\tdirections.push(\"The pull request is not merged: the occasion did not arise.\");\n\t} else if (record === null) {\n\t\tdirections.push(\n\t\t\t\"No review threads file was captured (review_threads.json): the decision record is not available here.\",\n\t\t);\n\t} else {\n\t\tdirections.push(\n\t\t\t`Merged${merge.mergedBy === undefined ? \"\" : ` by ${merge.mergedBy}`}${merge.mergedByIsAuthor ? \" (the author)\" : \"\"}${merge.mergedAt === undefined ? \"\" : ` at ${merge.mergedAt}`}; ${decisions.length} captured decision(s), ${approvalsBeforeMergeByOthers} of them an undismissed APPROVED before the merge by an account other than the author''s that is not marked bot; the last captured decision of each reviewer whose decision times are all known is listed apart.`,\n\t\t);\n\t\tif (unknownDecisionTimes > 0) {\n\t\t\tdirections.push(\n\t\t\t\t`${unknownDecisionTimes} decision time(s) are unknown: the dated approval count is a lower bound, and no historical last decision is established for those reviewers.`,\n\t\t\t);\n\t\t}\n\t\tdirections.push(\n\t\t\t\"Read decisionHistoryComplete in review_threads.json: row ordering does not establish complete historical coverage. Apply the practice criteria to that qualification.\",\n\t\t);\n\t}\n\treturn {\n\t\thints: [mergeRow(metadata, merge, contextReference), ...rows, ...last],\n\t\tmetrics: {\n\t\t\tmerged: merge.merged ? 1 : 0,\n\t\t\tmergedByIsAuthor: merge.mergedByIsAuthor ? 1 : 0,\n\t\t\tdecisions: decisions.length,\n\t\t\tunknownDecisionTimes,\n\t\t\tapprovalsBeforeMergeByOthers,\n\t\t\tdecisionsByBots: decisions.filter((d) => d.bot).length,\n\t\t\tthreadsFileAbsent: record === null ? 1 : 0,\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A change merged before anyone approved it skips the one check the team agreed on: a second pair of eyes before the code is everyone''s. It is also how a reviewer''s outstanding request for changes gets buried. Waiting for the approval, and re-requesting it after a rework, is what keeps the review real.","whatGoodLooksLike":"The person who merges does so after an approval from someone other than the author that is still current — no later request for changes, no dismissal — and after a rework asks for the approval again before merging.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 172\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Merged without approval</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"110.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(16 48)\"><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"3\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M4 5.5v5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"12\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M12 10.5V6a3 3 0 0 0-3-3H7.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></g>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"61\" font-size=\"15\">Pull request</text>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"80\" width=\"232\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"92\" width=\"176\" height=\"6\" rx=\"3\"/>\n  <circle class=\"pv-fill-muted\" cx=\"24\" cy=\"120\" r=\"8\"/>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"125\" font-size=\"15\">Reviewer</text>\n  <text class=\"pv-fill-muted\" x=\"140\" y=\"125\" font-size=\"15\">“Looks good”</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"168\" font-size=\"15\">Team check skipped</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Merged after approval</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"302.5\" height=\"110.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(352 48)\"><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"3\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M4 5.5v5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"12\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M12 10.5V6a3 3 0 0 0-3-3H7.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></g>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"61\" font-size=\"15\">Pull request</text>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"80\" width=\"232\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"92\" width=\"176\" height=\"6\" rx=\"3\"/>\n  <circle class=\"pv-fill-muted\" cx=\"360\" cy=\"120\" r=\"8\"/>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"125\" font-size=\"15\">Reviewer</text>\n  <path class=\"pv-stroke-accent\" d=\"M476 120.5l3.5 3.5 6.5-7\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <text class=\"pv-fill-accent\" x=\"498\" y=\"125\" font-size=\"15\">Approved</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"168\" font-size=\"15\">Team check kept</text>\n</svg>\n","alt":"Merged without approval: a pull request has only a reviewer’s “Looks good”, so the team check is skipped. Merged after approval: the reviewer’s “Approved” comes first, so the team check is kept."},"guide":{"markdown":"## How to do it\n\n- Before you merge, check that a person other than the author approved the pull request or merge request. Approvals from the author or a bot do not count.\n- If you see only a thumbs-up or a “looks good” comment, ask for an approval in the review.\n- If an approval was dismissed, or the same reviewer later requested changes, ask for a new approval.\n- After you fix a person’s request for changes, ask that reviewer to approve again. For example, instead of merging when your fix passes the tests, wait for their approval.\n- Then merge. You can press merge on your own work.\n\n## When it does not apply\n\n- The pull request or merge request did not merge.\n- You work alone on the project. Nobody was asked to review this work, and it has no review or review comment.\n\nIt still applies when a reviewer was asked, or when someone left a review or a review comment, even a bot.\n\n## Common mistakes\n\n- Thinking that the author must not press merge. Authors often merge their own work. Instead, make sure that someone else approved it first.\n- Merging on an old approval. An approval that the same reviewer later withdrew by requesting changes, or that someone dismissed, no longer stands. Instead, ask for a new approval after your rework.\n- Merging while a person’s request for changes still stands. Another person’s approval does not cancel it. Instead, wait until the reviewer who asked for changes approves. A bot’s request does not block a person’s approval.\n- Counting a bot’s approval as a review. A bot is not a second person. Instead, ask a person to approve.\n\n## Sources\n\n- [About protected branches](https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-protected-branches/about-protected-branches), GitHub Docs. A protected branch can require approval before merge and dismiss old approvals after changes.\n- [Merge request approval settings](https://docs.gitlab.com/user/project/merge_requests/approvals/settings/), GitLab Docs. A project can stop authors from approving their own merge requests, and remove approvals when you add changes.\n- [Code-Review check](https://github.com/ossf/scorecard/blob/main/docs/checks.md#code-review), OpenSSF Scorecard. The check looks for human review before merge and excludes bot reviews.\n- [An empirical study of the impact of modern code review practices on software quality](https://doi.org/10.1007/s10664-015-9381-9), McIntosh, Kamei, Adams and Hassan, 2016. In Qt, VTK and ITK, the share of changes that were reviewed had a significant link with defects after release.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Merge only after someone else approved","signals":["scm.pull_request.merged"],"evidenceRequirements":[{"sourceKind":"scm.general-review-comments","stance":"CONTEXTUAL"},{"sourceKind":"scm.pull-request.core","stance":"REQUIRED"},{"sourceKind":"scm.review-threads","stance":"EXHAUSTIVE"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"MERGER","precondition":null,"criteria":"Review this practice against the captured pull or merge request at its pinned revision: the change itself, the description as written, the commits, the review discussion and the linked context the practice names. Distinguish what the author wrote from what a reviewer, a template or the provider''s current state says.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the merge happens after a current approval from someone other than the author, and never over an outstanding request for changes.\n\n## The standard\nJudge one thing about the moment this pull request merged: was there, at that moment, an approval from another person — an account other than the author''s whose decision is not marked `bot` — that still stood? An approval stands when it was submitted before the merge and nothing later withdrew it — no dismissal, no revocation (`UNAPPROVED`) and no request for changes by the same reviewer after it. A request for changes stands when it was submitted before the merge and no later approval by the same reviewer replaced it. A decision marked `bot` is an automated account''s recorded act, never another person''s review: its approval is not an approval here, and its request for changes does not stand against another person''s approval. A complete bounded event record with no dismissal, revocation or later request for changes establishes no recorded withdrawal within that boundary. A latest-state snapshot alone does not establish complete historical event coverage. Merging with a standing approval and no standing request for changes is the practice; merging with none, or over a standing request for changes, is the lapse. Judge the decisions as recorded, never whether the review was thorough — that belongs to the review practices. That the author presses the merge button on their own pull request is the ordinary course in most teams and is never the lapse here; the only lapse is merging without another person''s standing approval. The subject is the person who merged, whether or not that person authored the change.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when: the pull request is not merged; or the repository plainly works without review — no reviewer was requested, no review decision or review thread exists on this pull request, and the inventory shows a single-person project. A pull request with a reviewer requested, a review decision or a review comment is the occasion; a decision marked `bot` is still a review decision for this gate.\n\n## Sources\n1. The pull request record (`context/metadata.json`): `merged_at`, `merged_by`, `author`. It establishes who merged and when. When `merged_by` is absent, record no observation: the review cannot name the merger. A different recorded merger is still the subject.\n2. The review decisions (`context/review_threads.json`, `reviewDecisions` oldest first: `state`, `author`, `submittedAt`, `body` when one was written, `dismissed`) and the threads: each captured decision with its author and time. `decisionHistoryComplete` is `false`, since a decision withdrawn or replaced earlier may be missing. `submittedAt` is the decision event time, absent when unknown. On GitLab, a native approval date is recovered from a standing approval after merge; a native date before `merged_at` is therefore a positive witness that the approval stood at merge. Last-known rows alone do not establish current review readiness when `metadata.json` omits `review_decision`. Do not erase a sufficient historical witness merely because current readiness later became unknown. The record''s silence about a withdrawal never proves that none happened. A current `DISMISSED` state or `dismissed` flag with no withdrawal time establishes only the state at capture, not whether dismissal preceded merge. A dismissal withdraws only the decision of the reviewer it belongs to. On GitHub, a dismissed review keeps its original state beside `dismissed`; a `DISMISSED` state alone leaves that original state unknown. On GitLab, the sync records `DISMISSED` only on an approval row, never on a request for changes. A `truncated` record is a collection gap for this practice. The precomputed leads below these criteria list the merge and one row per decision with `beforeMerge`, `isAuthor`, `dismissed` and `bot` computed, and each reviewer''s last captured decision apart: decide from the rows, and quote the decision and the merge from the record.\n3. The inventory (`context/project_inventory.json`): whether other people work in this project, for the occasion only.\nIf `merged_at` or the decisions are unavailable, report a collection gap and record no observation.\n\n## Judge\nAssess conformance to the standard in this context, reviewer by reviewer: first whether another person''s approval stood at merge, then whether another person''s request for changes stood or may have stood at merge. Each reviewer''s own rows decide that reviewer''s standing: one reviewer''s dismissal, withdrawal or unknown time never unsettles another reviewer''s confirmed approval, and `decisionHistoryComplete: false` alone neither withdraws a confirmed approval nor stands for a request for changes.\n- MET: at least one confirmed standing APPROVED decision by another person — a login other than the author''s, not marked `bot` — submitted before `merged_at`, with no later dismissal, revocation or request for changes by that reviewer, and no captured request for changes by another person that stood or may have stood at merge. An approval marked `bot` never makes this cell. Who pressed merge does not enter into it. Quote the approval and the merge time.\n- NOT_MET: evidence that covers the merge moment establishes no qualifying approval, or establishes another person''s request for changes that still stood at merge. Absence of a human approval in a current snapshot, including a snapshot with only bot approvals, does not establish absence at merge when historical coverage is incomplete. Quote the merge time and the evidence that settles the state at that moment. History the record does not hold never decides this cell.\n- UNDETERMINED: the captured record cannot settle a deciding event''s order or standing membership at merge. When no approval by another person is confirmed as standing, this includes an approval by another person that is undated, dated after `merged_at` or dismissed with no dated withdrawal — an earlier approval may have stood at the merge and been replaced since — and absent human approvals with incomplete historical coverage: a previously standing human approval may have been withdrawn after merge. Even beside a confirmed approval, it includes another person''s captured request for changes, or a dismissed decision whose original state is unknown, that may have stood at merge because the record cannot settle its time or its replacement. Current review readiness and historical approval-at-merge are separate facts. An original review submission timestamp does not date a later withdrawal. A truncated required record is a collection gap, not UNDETERMINED.\nOne observation per review.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: merged with no approval where a reviewer was requested and had not answered. MAJOR: merged over a standing request for changes, or after an approval was dismissed and not renewed. Identical evidence yields identical severity.\n\n## Grounding\nQuote `merged_at`, `merged_by` and each decision as recorded with its `author`, `state` and `submittedAt`. Identity is the login as recorded, compared as text: the same login is the same account. Whether an account is automated is the captured `bot` marker, never the login''s shape or a display name; a decision without the marker counts as its reviewer''s own. Never infer that a reviewer is the author from a display name, a repository path or a namespace; never infer an approval from a comment or a thumbs-up; never treat the author''s own approval as one.\n\n## Defer\nWhether review threads were resolved belongs to `merged-past-unresolved-review-threads`. Here only: did another person approve before the merge?","precomputeScript":"// Precompute FACTS for merges-only-after-approval: the merge as the record holds it — who merged,\n// when, the provider''s own review decision — captured decision rows placed against the merge instant.\n// Currentness and history coverage remain separate from this advisory ordering.\nimport {\n\tdecisionRows,\n\tlastDecisionPerReviewer,\n\tmergeFacts,\n\tmergeRow,\n\treadReviewThreads,\n} from \"../lib/review.ts\";\nimport type { DiffFile, PullRequestMetadata } from \"../lib/types.ts\";\n\nexport default async function mergesOnlyAfterApproval(\n\t_repoPath: string,\n\t_diffFiles: Map<string, DiffFile>,\n\tmetadata: PullRequestMetadata,\n\tcontextDir: string | undefined,\n\t_changeDir: string | undefined,\n\tcontextReference: string,\n) {\n\tconst merge = mergeFacts(metadata);\n\tconst record = await readReviewThreads(contextDir);\n\tconst decisions = record?.decisions ?? [];\n\tconst rows = decisionRows(decisions, merge, contextReference);\n\tconst last = decisionRows(lastDecisionPerReviewer(decisions), merge, contextReference).map(\n\t\t(row) => ({\n\t\t\t...row,\n\t\t\tpattern: \"last decision by reviewer\",\n\t\t}),\n\t);\n\tconst approvalsBeforeMergeByOthers = rows.filter(\n\t\t(r) =>\n\t\t\tr.flags.state === \"APPROVED\" &&\n\t\t\tr.flags.beforeMerge === true &&\n\t\t\tr.flags.isAuthor !== true &&\n\t\t\tr.flags.dismissed !== true &&\n\t\t\tr.flags.bot !== true,\n\t).length;\n\tconst unknownDecisionTimes = decisions.filter((d) => d.submittedAt === undefined).length;\n\tconst directions: string[] = [];\n\tif (!merge.merged) {\n\t\tdirections.push(\"The pull request is not merged: the occasion did not arise.\");\n\t} else if (record === null) {\n\t\tdirections.push(\n\t\t\t\"No review threads file was captured (review_threads.json): the decision record is not available here.\",\n\t\t);\n\t} else {\n\t\tdirections.push(\n\t\t\t`Merged${merge.mergedBy === undefined ? \"\" : ` by ${merge.mergedBy}`}${merge.mergedByIsAuthor ? \" (the author)\" : \"\"}${merge.mergedAt === undefined ? \"\" : ` at ${merge.mergedAt}`}; ${decisions.length} captured decision(s), ${approvalsBeforeMergeByOthers} of them an undismissed APPROVED before the merge by an account other than the author''s that is not marked bot; the last captured decision of each reviewer whose decision times are all known is listed apart.`,\n\t\t);\n\t\tif (unknownDecisionTimes > 0) {\n\t\t\tdirections.push(\n\t\t\t\t`${unknownDecisionTimes} decision time(s) are unknown: the dated approval count is a lower bound, and no historical last decision is established for those reviewers.`,\n\t\t\t);\n\t\t}\n\t\tdirections.push(\n\t\t\t\"Read decisionHistoryComplete in review_threads.json: row ordering does not establish complete historical coverage. Apply the practice criteria to that qualification.\",\n\t\t);\n\t}\n\treturn {\n\t\thints: [mergeRow(metadata, merge, contextReference), ...rows, ...last],\n\t\tmetrics: {\n\t\t\tmerged: merge.merged ? 1 : 0,\n\t\t\tmergedByIsAuthor: merge.mergedByIsAuthor ? 1 : 0,\n\t\t\tdecisions: decisions.length,\n\t\t\tunknownDecisionTimes,\n\t\t\tapprovalsBeforeMergeByOthers,\n\t\t\tdecisionsByBots: decisions.filter((d) => d.bot).length,\n\t\t\tthreadsFileAbsent: record === null ? 1 : 0,\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A change merged before anyone approved it skips the one check the team agreed on: a second pair of eyes before the code is everyone''s. It is also how a reviewer''s outstanding request for changes gets buried. Waiting for the approval, and re-requesting it after a rework, is what keeps the review real.","whatGoodLooksLike":"The person who merges does so after an approval from someone other than the author that is still current — no later request for changes, no dismissal — and after a rework asks for the approval again before merging.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 172\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Merged without approval</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"110.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(16 48)\"><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"3\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M4 5.5v5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"12\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M12 10.5V6a3 3 0 0 0-3-3H7.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></g>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"61\" font-size=\"15\">Pull request</text>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"80\" width=\"232\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"92\" width=\"176\" height=\"6\" rx=\"3\"/>\n  <circle class=\"pv-fill-muted\" cx=\"24\" cy=\"120\" r=\"8\"/>\n  <text class=\"pv-fill-ink\" x=\"44\" y=\"125\" font-size=\"15\">Reviewer</text>\n  <text class=\"pv-fill-muted\" x=\"140\" y=\"125\" font-size=\"15\">“Looks good”</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"168\" font-size=\"15\">Team check skipped</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Merged after approval</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"302.5\" height=\"110.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <g transform=\"translate(352 48)\"><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"3\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M4 5.5v5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"4\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"12\" cy=\"13\" r=\"2.5\" fill=\"none\" stroke-width=\"1.5\"/><path class=\"pv-stroke-ink\" d=\"M12 10.5V6a3 3 0 0 0-3-3H7.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></g>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"61\" font-size=\"15\">Pull request</text>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"80\" width=\"232\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"92\" width=\"176\" height=\"6\" rx=\"3\"/>\n  <circle class=\"pv-fill-muted\" cx=\"360\" cy=\"120\" r=\"8\"/>\n  <text class=\"pv-fill-ink\" x=\"380\" y=\"125\" font-size=\"15\">Reviewer</text>\n  <path class=\"pv-stroke-accent\" d=\"M476 120.5l3.5 3.5 6.5-7\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <text class=\"pv-fill-accent\" x=\"498\" y=\"125\" font-size=\"15\">Approved</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"168\" font-size=\"15\">Team check kept</text>\n</svg>\n","alt":"Merged without approval: a pull request has only a reviewer’s “Looks good”, so the team check is skipped. Merged after approval: the reviewer’s “Approved” comes first, so the team check is kept."},"guide":{"markdown":"## How to do it\n\n- Before you merge, check that a person other than the author approved the pull request or merge request. Approvals from the author or a bot do not count.\n- If you see only a thumbs-up or a “looks good” comment, ask for an approval in the review.\n- If an approval was dismissed, or the same reviewer later requested changes, ask for a new approval.\n- After you fix a person’s request for changes, ask that reviewer to approve again. For example, instead of merging when your fix passes the tests, wait for their approval.\n- Then merge. You can press merge on your own work.\n\n## When it does not apply\n\n- The pull request or merge request did not merge.\n- You work alone on the project. Nobody was asked to review this work, and it has no review or review comment.\n\nIt still applies when a reviewer was asked, or when someone left a review or a review comment, even a bot.\n\n## Common mistakes\n\n- Thinking that the author must not press merge. Authors often merge their own work. Instead, make sure that someone else approved it first.\n- Merging on an old approval. An approval that the same reviewer later withdrew by requesting changes, or that someone dismissed, no longer stands. Instead, ask for a new approval after your rework.\n- Merging while a person’s request for changes still stands. Another person’s approval does not cancel it. Instead, wait until the reviewer who asked for changes approves. A bot’s request does not block a person’s approval.\n- Counting a bot’s approval as a review. A bot is not a second person. Instead, ask a person to approve.\n\n## Sources\n\n- [About protected branches](https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-protected-branches/about-protected-branches), GitHub Docs. A protected branch can require approval before merge and dismiss old approvals after changes.\n- [Merge request approval settings](https://docs.gitlab.com/user/project/merge_requests/approvals/settings/), GitLab Docs. A project can stop authors from approving their own merge requests, and remove approvals when you add changes.\n- [Code-Review check](https://github.com/ossf/scorecard/blob/main/docs/checks.md#code-review), OpenSSF Scorecard. The check looks for human review before merge and excludes bot reviews.\n- [An empirical study of the impact of modern code review practices on software quality](https://doi.org/10.1007/s10664-015-9381-9), McIntosh, Kamei, Adams and Hassan, 2016. In Qt, VTK and ITK, the share of changes that were reviewed had a significant link with defects after release.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Nothing merges without a current approval from someone else"'::jsonb),'v5:d5cca0e5b9762c4a4b1f882e1f9c55edf785d653c1d8e56ae05136012875a73d','practice:v3:0ae7b8d37eb4957c2c1a5784c78d370466f9e438a89f4aa28b75c24c33ef5281');
INSERT INTO _cutover_bundle VALUES('PRACTICE','plans-the-work-in-an-issue-first','scm.pull_request','{"name":"Record the plan before the first commit","signals":["scm.pull_request.opened","scm.pull_request.ready"],"evidenceRequirements":[{"sourceKind":"scm.linked-work-items","stance":"REQUIRED"},{"sourceKind":"scm.pull-request.core","stance":"REQUIRED"},{"sourceKind":"scm.pull-request.diff","stance":"REQUIRED"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured pull or merge request at its pinned revision: the change itself, the description as written, the commits, the review discussion and the linked context the practice names. Distinguish what the author wrote from what a reviewer, a template or the provider''s current state says.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the tracked issue this change implements exists no later than the earliest captured authored commit, without inferring actual work-start or motive.\n\n## The standard\nJudge one thing: did the issue this pull request implements exist no later than the first recorded commit? The earliest captured commit author date (`context/commits.json`, `authoredAt`) is the recorded timing proxy. It does not establish when actual work began, and the pull request creation time is a handoff time, not a substitute for it. The issue''s opening is its `createdAt` in the linked work item. An issue opened before the first captured commit precedes that recorded step; an issue opened after it follows that step. Neither timing establishes the author''s intent or the order of unrecorded work. Judge only the recorded order of the two dates, never the quality of the issue or of the change.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when: no named issue is one this pull request implements — a captured item or one among the `unresolvedReferences` — because the description names none, or rules each out (`Not related to #N`, an aside about other work); or the change is of a kind that answers no issue by convention — a release, a bot dependency update, a revert. Only a candidate issue the precomputed leads list can be that issue: one captured as this repository''s closing candidate (`how: closesOnMerge`, including a link made in the provider''s UI), or named by a closing keyword, the title, the branch or the author''s own `Related to #N`. One named only by `Related to` counts when the description or the issue shows this change delivers part of that issue''s work, not when the sentence is about other work. A number the leads do not list is no occasion — a bare `#N`, a `Related to` in a quotation, code or HTML comment, another project''s issue. A related issue is captured as a mention, not a closing candidate: never say it closed or will close with this merge. Whether an issue is linked at all belongs to `links-the-change-to-its-issue`; here the linked issue is the occasion.\n\n## Sources\n1. The linked work item (`context/linked_work_items/<n>.md`, its opening line `Opened <time>`, and `linked_work_items.json`, `createdAt`): when the issue was opened. It establishes the plan''s date.\n2. The commits (`context/commits.json`, `authoredAt`): author dates of recorded commits. Require a usable author date for every captured commit and compare the earliest; neither a commit date nor a handoff timestamp substitutes for missing author dates. These dates do not establish actual work-start.\n3. The pull request record (`context/metadata.json`): the identity of the reviewed work, never a substitute start time.\n4. The precomputed leads below these criteria: each candidate issue, how it was named, its opening time, the earliest commit''s author date and the hours between them, computed; read the two dates from it and check them against the sources above.\nFailed or missing required linked-work-item or commit capture is a collection gap and produces no observation. Successfully captured records with missing native dates leave the timing UNDETERMINED.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: the issue''s `createdAt` is no later than the earliest captured commit''s usable `authoredAt`, and every captured commit has a usable author date. Quote both times.\n- NOT_MET: the issue''s `createdAt` is later than the earliest captured commit''s usable `authoredAt`, and every captured commit has a usable author date. Quote both times.\n- UNDETERMINED: the complete captured commit record is empty or any captured commit has no usable author date, so the timing proxy cannot be established; or the issue this change implements has no opening time here — its number is among the `unresolvedReferences`, so this repository holds no synchronized issue under it, or its linked item carries no `createdAt`. Record as the open question which issue that is and when it was opened, and as what would settle it that issue''s opening time in this repository; never claim it exists, predates the work or closes. Or several named issues remain plausible as the one this change implements, their dates fall in different outcomes, and the description and issues do not settle which. Name them; never choose the favourable one.\nOne observation per review, on the issue the change implements; when several plausible issues fall in the same cell, on the one a closing candidate names, else the title, else the branch, else the `Related to`.\n\n## Severity\nNOT_MET only; never above MINOR on this alone — non-blocking. Calibrate the nudge to the recorded planning gap and its coordination cost; elapsed time alone does not establish an intention or raise severity.\n\n## Grounding\nCite the linked item''s `Opened <time>` line and the reviewed pull request record; cite the earliest usable author date and SHA from the captured `context/commits.json` artifact. Never infer an order from issue and pull request numbers; never read a commit date where an author date exists.\n\n## Defer\nWhether the change names its issue belongs to `links-the-change-to-its-issue`; whether the issue states a checkable outcome belongs to `issue-has-checkable-outcome`. Here only: did the issue exist before the first recorded commit?","precomputeScript":"// Precompute FACTS for plans-the-work-in-an-issue-first: when each issue the change names as its own\n// was opened, when the change''s earliest commit was authored, and the time between them. The practice\n// asks one question of two timestamps; the script puts both beside each other so the review reads\n// them rather than reasons around them.\nimport { readCapturedCommits } from \"../lib/change.ts\";\nimport { contextFile } from \"../lib/context.ts\";\nimport { text } from \"../lib/practice-contract.ts\";\nimport {\n\tbranchIssueReferences,\n\tclosingReferences,\n\tissueNumberReferences,\n\trelatedReferences,\n} from \"../lib/references.ts\";\nimport { millisBetween, readLinkedWorkItemCapture } from \"../lib/review.ts\";\nimport type { DiffFile, Hint, PullRequestMetadata } from \"../lib/types.ts\";\n\n/** The two moments in one sentence, the way the cell reads them. */\nfunction relationOf(issueToFirstCommit: number | null): string {\n\tif (issueToFirstCommit === null) {\n\t\treturn \"the captured commits do not establish the earliest authored time; the order is UNDETERMINED\";\n\t}\n\treturn issueToFirstCommit >= 0\n\t\t? `the earliest commit was authored ${hours(issueToFirstCommit)} h after the issue was opened`\n\t\t: `the issue was opened ${hours(-issueToFirstCommit)} h after the earliest commit was authored`;\n}\n\n/** Hours with one decimal, signed: positive when `to` is later than `from`. */\nfunction hours(millis: number): string {\n\treturn (millis / 3_600_000).toFixed(1);\n}\n\nexport default async function plansTheWorkInAnIssueFirst(\n\t_repoPath: string,\n\t_diffFiles: Map<string, DiffFile>,\n\tmetadata: PullRequestMetadata,\n\tcontextDir: string | undefined,\n\t_changeDir: string | undefined,\n\tcontextReference: string,\n) {\n\tconst hints: Hint[] = [];\n\tconst directions: string[] = [];\n\tconst body = text(metadata.body);\n\tconst title = text(metadata.title);\n\tconst capture = await readLinkedWorkItemCapture(contextDir);\n\tconst linked = capture?.items ?? null;\n\tconst named = new Map<number, string[]>();\n\tconst name = (how: string, numbers: number[]) => {\n\t\tfor (const n of numbers) {\n\t\t\tnamed.set(n, [...(named.get(n) ?? []), how]);\n\t\t}\n\t};\n\tname(\n\t\t\"provider closing link\",\n\t\t(linked ?? []).filter((item) => item.how === \"closesOnMerge\").map((item) => item.number),\n\t);\n\tname(\"closing keyword\", closingReferences(body));\n\tname(\"title\", issueNumberReferences(title));\n\tname(\"branch\", branchIssueReferences(metadata.source_branch));\n\tname(\"Related to\", relatedReferences(body));\n\tconst capturedCommits = await readCapturedCommits(contextDir);\n\tconst commitsCaptured = capturedCommits !== null;\n\tconst commits = capturedCommits ?? [];\n\tconst authored = commits\n\t\t.filter((commit) => Number.isFinite(Date.parse(commit.authoredAt)))\n\t\t.toSorted((a, b) => Date.parse(a.authoredAt) - Date.parse(b.authoredAt));\n\tconst first = authored.length === commits.length ? authored[0] : undefined;\n\tlet earliestDeltaMinutes = Number.NaN;\n\tfor (const item of linked ?? []) {\n\t\tconst namedBy = named.get(item.number)?.join(\", \");\n\t\tif (namedBy === undefined) {\n\t\t\tcontinue;\n\t\t}\n\t\tconst toFirstCommit = millisBetween(item.createdAt, first?.authoredAt);\n\t\tconst flags: Hint[\"flags\"] = {\n\t\t\tnumber: item.number,\n\t\t\tnamedBy,\n\t\t\tproviderLink: item.how ?? \"\",\n\t\t\topenedAt: item.createdAt ?? \"\",\n\t\t};\n\t\tif (first !== undefined) {\n\t\t\tflags.firstCommit = first.sha.slice(0, 7);\n\t\t\tflags.firstCommitAuthoredAt = first.authoredAt;\n\t\t}\n\t\tif (toFirstCommit !== null) {\n\t\t\tflags.hoursFromIssueToFirstCommit = hours(toFirstCommit);\n\t\t\tconst minutes = -toFirstCommit / 60_000;\n\t\t\tif (Number.isNaN(earliestDeltaMinutes) || minutes > earliestDeltaMinutes) {\n\t\t\t\tearliestDeltaMinutes = minutes;\n\t\t\t}\n\t\t}\n\t\tlet relation =\n\t\t\t\"the commit record is missing or malformed: a collection gap, not a timing observation\";\n\t\tif (commitsCaptured) {\n\t\t\trelation =\n\t\t\t\titem.createdAt === undefined\n\t\t\t\t\t? \"its opening time is not captured, so the order cannot be read\"\n\t\t\t\t\t: relationOf(toFirstCommit);\n\t\t}\n\t\thints.push({\n\t\t\tfile: contextFile(contextReference, `linked_work_items/${String(item.number)}.md`),\n\t\t\tline: 0,\n\t\t\tpattern: \"candidate issue\",\n\t\t\tcontext: `#${String(item.number)} (named by ${namedBy}; captured as ${item.how ?? \"an unclassified link\"}) opened ${item.createdAt ?? \"(unknown)\"}; ${relation}`,\n\t\t\tinDiff: false,\n\t\t\tflags,\n\t\t});\n\t}\n\tconst numbers = [...named.keys()].map((n) => `#${String(n)}`).join(\", \");\n\t// A named number this repository holds no synchronized issue for may be an issue not yet\n\t// synchronized or a reference elsewhere; the record cannot say which.\n\tconst unresolved = [...named.keys()].filter((n) => capture?.unresolved.includes(n) ?? false);\n\tif (!commitsCaptured) {\n\t\tdirections.push(\n\t\t\t\"The commit record is missing or malformed: report a collection gap and record no observation, never UNDETERMINED.\",\n\t\t);\n\t} else if (capture === null) {\n\t\tdirections.push(\n\t\t\t`${contextFile(contextReference, \"linked_work_items.json\")} was not captured: a collection gap, not a change without an issue.`,\n\t\t);\n\t} else if (hints.length === 0 && unresolved.length === 0) {\n\t\tdirections.push(\n\t\t\t\"No issue of this repository is named by a provider closing link, a closing keyword, the title, the branch or a `Related to #N`; without an issue this change implements there is nothing to have planned in.\",\n\t\t);\n\t} else {\n\t\tif (unresolved.length > 0) {\n\t\t\tdirections.push(\n\t\t\t\t`The named issue(s) ${unresolved.map((n) => `#${String(n)}`).join(\", \")} are among the capture''s unresolved references: this repository holds no synchronized issue with that number, so no opening time. Whether one is the issue this change implements is read from the description: if it is, the order stays open (UNDETERMINED, never a timing judgement on another issue instead); if the description rules it out, it is no occasion.`,\n\t\t\t);\n\t\t}\n\t\tif (hints.length > 0) {\n\t\t\tdirections.push(\n\t\t\t\t`The cell is decided by the issue''s opening time against the earliest authored commit of the change (${contextFile(contextReference, \"commits.json\")}), never against the pull request''s creation: a pull request is opened when the work is handed off, and the practice asks whether the plan preceded the work.`,\n\t\t\t\t\"Compare the issue opening and earliest captured authored commit exactly. These dates establish the recorded order, not when all work began or why the issue was written.\",\n\t\t\t\t...(first === undefined\n\t\t\t\t\t? [\n\t\t\t\t\t\t\t\"If the complete captured commit record is empty or any commit lacks a usable authored date, the earliest time cannot be established and the timing is UNDETERMINED. The pull request''s creation dates the handoff, not the start of work; it cannot replace the missing date. Missing commit capture is a collection gap, not UNDETERMINED.\",\n\t\t\t\t\t\t]\n\t\t\t\t\t: []),\n\t\t\t);\n\t\t\tif (hints.some((hint) => hint.flags.namedBy === \"Related to\")) {\n\t\t\t\tdirections.push(\n\t\t\t\t\t\"An issue named only by `Related to` is the occasion only when the description or the issue shows this change implements part of it, not when the sentence is about other work. It was captured as a mention, not a closing candidate: nothing here says the issue closed or will close on merge.\",\n\t\t\t\t);\n\t\t\t}\n\t\t\tif (hints.length > 1) {\n\t\t\t\tdirections.push(\n\t\t\t\t\t`Several issues are named (${numbers}): judge the one this change implements, read from the description and the issues. If more than one remains plausible and their timing falls in different cells, do not choose the favourable one.`,\n\t\t\t\t);\n\t\t\t}\n\t\t}\n\t}\n\treturn {\n\t\thints,\n\t\tmetrics: {\n\t\t\tnamedIssues: named.size,\n\t\t\tunresolvedNamedIssues: unresolved.length,\n\t\t\tlinkedItems: linked?.length ?? -1,\n\t\t\tcommits: commits.length,\n\t\t\tissueOpenedAfterFirstCommitMinutes: Number.isNaN(earliestDeltaMinutes)\n\t\t\t\t? -1\n\t\t\t\t: Math.max(0, Math.round(earliestDeltaMinutes)),\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A tracked issue written before the first recorded commit gives reviewers a prior statement of the work. Commit timestamps provide a recorded ordering, not proof of when someone actually started thinking or coding.","whatGoodLooksLike":"The tracked issue this change implements has an opening timestamp no later than the earliest captured commit author timestamp. The record names both times without inferring intent or unrecorded work.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 200\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Commit first</text>\n  <circle class=\"pv-fill-surface pv-stroke-muted\" cx=\"12\" cy=\"44\" r=\"11.25\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"12\" y=\"49\" font-size=\"15\" text-anchor=\"middle\">1</text>\n  <path class=\"pv-stroke-muted\" d=\"M32 44h288\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M328 44l-8-5v10z\"/>\n  <g transform=\"translate(0 66)\"><path class=\"pv-stroke-ink\" d=\"M0 8h4.5M11.5 8H16\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"3.5\" fill=\"none\" stroke-width=\"1.5\"/></g>\n  <text class=\"pv-fill-ink\" x=\"28\" y=\"80\" font-size=\"16\" font-weight=\"600\">Commit</text>\n  <circle class=\"pv-fill-surface pv-stroke-muted\" cx=\"348\" cy=\"44\" r=\"11.25\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"348\" y=\"49\" font-size=\"15\" text-anchor=\"middle\">2</text>\n  <g transform=\"translate(336 66)\"><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"6.75\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-fill-ink\" cx=\"8\" cy=\"8\" r=\"1.75\"/></g>\n  <text class=\"pv-fill-ink\" x=\"364\" y=\"80\" font-size=\"16\" font-weight=\"600\">Issue</text>\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"132\" font-size=\"16\" font-weight=\"600\">Issue first</text>\n  <circle class=\"pv-fill-accent\" cx=\"12\" cy=\"160\" r=\"12\"/>\n  <text class=\"pv-fill-surface\" x=\"12\" y=\"165\" font-size=\"15\" font-weight=\"600\" text-anchor=\"middle\">1</text>\n  <path class=\"pv-stroke-muted\" d=\"M32 160h288\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M328 160l-8-5v10z\"/>\n  <g transform=\"translate(0 182)\"><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"6.75\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-fill-ink\" cx=\"8\" cy=\"8\" r=\"1.75\"/></g>\n  <text class=\"pv-fill-ink\" x=\"28\" y=\"196\" font-size=\"16\" font-weight=\"600\">Issue</text>\n  <circle class=\"pv-fill-surface pv-stroke-muted\" cx=\"348\" cy=\"160\" r=\"11.25\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"348\" y=\"165\" font-size=\"15\" text-anchor=\"middle\">2</text>\n  <g transform=\"translate(336 182)\"><path class=\"pv-stroke-ink\" d=\"M0 8h4.5M11.5 8H16\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"3.5\" fill=\"none\" stroke-width=\"1.5\"/></g>\n  <text class=\"pv-fill-ink\" x=\"364\" y=\"196\" font-size=\"16\" font-weight=\"600\">Commit</text>\n</svg>\n","alt":"Commit first: the first commit comes before the issue opens. Issue first: the issue opens before the first commit."},"guide":{"markdown":"## How to do it\n\n- Before your first commit, open an issue that says what you plan to change. For example, instead of committing a first draft and then filing the issue, file the issue first.\n- You can start your branch from the issue page. GitHub and GitLab can both create a branch there.\n- Compare the issue’s opening time with the author date of your earliest commit in the change.\n\n![Open the issue and say what you plan. You can then start a branch from the issue page. Your first commit comes after the issue opens.](figures/issue-to-commit.svg)\n\n## When it does not apply\n\n- Your pull request or merge request carries out no issue. You name none, or you say that each named issue is other work, such as “Not related to #12”.\n- The change is a release, a dependency update from a bot, or a revert.\n- You mention the issue only as a plain number, or only inside a quote, code or a hidden comment.\n- The issue belongs to another project.\n\nIt still applies when you name the issue only with “Related to” and the change does part of that issue’s work.\n\n## Common mistakes\n\n- Opening the issue just before you open the pull request or merge request. Your first commit counts, not the moment you ask for review. Instead, open the issue before you commit.\n- Waiting to open the issue until the plan is complete. Only the order counts here, not the length of the issue. Instead, open a short issue first and add details as you learn.\n- Comparing the issue with only the commit that adds its work. Earlier commits in the same change still count. Instead, compare with your earliest commit.\n\n## Sources\n\n- [How to contribute to open source](https://opensource.guide/how-to-contribute/), GitHub Open Source Guides. Before you work on a large contribution, open an issue to ask about it.\n- [Merge requests workflow](https://docs.gitlab.com/development/contributing/merge_request_workflow/), GitLab Docs. For a new feature idea, GitLab asks contributors to create an issue first, if there is not one already.\n- [Creating a branch to work on an issue](https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/creating-a-branch-for-an-issue), GitHub Docs. You can create a branch from the issue page, and a pull request from that branch links to the issue.\n- [Create a merge request](https://docs.gitlab.com/user/project/merge_requests/creating_merge_requests/), GitLab Docs. From an issue, you can create a branch and a merge request together, both marked as related to that issue.\n","figures":{"issue-to-commit":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 76\">\n  <circle class=\"pv-fill-accent\" cx=\"12\" cy=\"12\" r=\"12\"/>\n  <text class=\"pv-fill-surface\" x=\"12\" y=\"17\" font-size=\"15\" font-weight=\"600\" text-anchor=\"middle\">1</text>\n  <path class=\"pv-stroke-muted\" d=\"M32 12h176\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M216 12l-8-5v10z\"/>\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"48\" font-size=\"16\" font-weight=\"600\">Open the issue</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"72\" font-size=\"15\">Say what you plan</text>\n  <circle class=\"pv-fill-surface pv-stroke-muted\" cx=\"236\" cy=\"12\" r=\"11.25\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"236\" y=\"17\" font-size=\"15\" text-anchor=\"middle\">2</text>\n  <path class=\"pv-stroke-muted\" d=\"M256 12h176\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M440 12l-8-5v10z\"/>\n  <text class=\"pv-fill-ink\" x=\"224\" y=\"48\" font-size=\"16\" font-weight=\"600\">Optional branch</text>\n  <text class=\"pv-fill-muted\" x=\"224\" y=\"72\" font-size=\"15\">From the issue page</text>\n  <circle class=\"pv-fill-surface pv-stroke-muted\" cx=\"460\" cy=\"12\" r=\"11.25\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"460\" y=\"17\" font-size=\"15\" text-anchor=\"middle\">3</text>\n  <text class=\"pv-fill-ink\" x=\"448\" y=\"48\" font-size=\"16\" font-weight=\"600\">First commit</text>\n  <text class=\"pv-fill-muted\" x=\"448\" y=\"72\" font-size=\"15\">After the issue opens</text>\n</svg>\n"}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Record the plan before the first commit","signals":["scm.pull_request.opened","scm.pull_request.ready"],"evidenceRequirements":[{"sourceKind":"scm.linked-work-items","stance":"REQUIRED"},{"sourceKind":"scm.pull-request.core","stance":"REQUIRED"},{"sourceKind":"scm.pull-request.diff","stance":"REQUIRED"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured pull or merge request at its pinned revision: the change itself, the description as written, the commits, the review discussion and the linked context the practice names. Distinguish what the author wrote from what a reviewer, a template or the provider''s current state says.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the tracked issue this change implements exists no later than the earliest captured authored commit, without inferring actual work-start or motive.\n\n## The standard\nJudge one thing: did the issue this pull request implements exist no later than the first recorded commit? The earliest captured commit author date (`context/commits.json`, `authoredAt`) is the recorded timing proxy. It does not establish when actual work began, and the pull request creation time is a handoff time, not a substitute for it. The issue''s opening is its `createdAt` in the linked work item. An issue opened before the first captured commit precedes that recorded step; an issue opened after it follows that step. Neither timing establishes the author''s intent or the order of unrecorded work. Judge only the recorded order of the two dates, never the quality of the issue or of the change.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when: no named issue is one this pull request implements — a captured item or one among the `unresolvedReferences` — because the description names none, or rules each out (`Not related to #N`, an aside about other work); or the change is of a kind that answers no issue by convention — a release, a bot dependency update, a revert. Only a candidate issue the precomputed leads list can be that issue: one captured as this repository''s closing candidate (`how: closesOnMerge`, including a link made in the provider''s UI), or named by a closing keyword, the title, the branch or the author''s own `Related to #N`. One named only by `Related to` counts when the description or the issue shows this change delivers part of that issue''s work, not when the sentence is about other work. A number the leads do not list is no occasion — a bare `#N`, a `Related to` in a quotation, code or HTML comment, another project''s issue. A related issue is captured as a mention, not a closing candidate: never say it closed or will close with this merge. Whether an issue is linked at all belongs to `links-the-change-to-its-issue`; here the linked issue is the occasion.\n\n## Sources\n1. The linked work item (`context/linked_work_items/<n>.md`, its opening line `Opened <time>`, and `linked_work_items.json`, `createdAt`): when the issue was opened. It establishes the plan''s date.\n2. The commits (`context/commits.json`, `authoredAt`): author dates of recorded commits. Require a usable author date for every captured commit and compare the earliest; neither a commit date nor a handoff timestamp substitutes for missing author dates. These dates do not establish actual work-start.\n3. The pull request record (`context/metadata.json`): the identity of the reviewed work, never a substitute start time.\n4. The precomputed leads below these criteria: each candidate issue, how it was named, its opening time, the earliest commit''s author date and the hours between them, computed; read the two dates from it and check them against the sources above.\nFailed or missing required linked-work-item or commit capture is a collection gap and produces no observation. Successfully captured records with missing native dates leave the timing UNDETERMINED.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: the issue''s `createdAt` is no later than the earliest captured commit''s usable `authoredAt`, and every captured commit has a usable author date. Quote both times.\n- NOT_MET: the issue''s `createdAt` is later than the earliest captured commit''s usable `authoredAt`, and every captured commit has a usable author date. Quote both times.\n- UNDETERMINED: the complete captured commit record is empty or any captured commit has no usable author date, so the timing proxy cannot be established; or the issue this change implements has no opening time here — its number is among the `unresolvedReferences`, so this repository holds no synchronized issue under it, or its linked item carries no `createdAt`. Record as the open question which issue that is and when it was opened, and as what would settle it that issue''s opening time in this repository; never claim it exists, predates the work or closes. Or several named issues remain plausible as the one this change implements, their dates fall in different outcomes, and the description and issues do not settle which. Name them; never choose the favourable one.\nOne observation per review, on the issue the change implements; when several plausible issues fall in the same cell, on the one a closing candidate names, else the title, else the branch, else the `Related to`.\n\n## Severity\nNOT_MET only; never above MINOR on this alone — non-blocking. Calibrate the nudge to the recorded planning gap and its coordination cost; elapsed time alone does not establish an intention or raise severity.\n\n## Grounding\nCite the linked item''s `Opened <time>` line and the reviewed pull request record; cite the earliest usable author date and SHA from the captured `context/commits.json` artifact. Never infer an order from issue and pull request numbers; never read a commit date where an author date exists.\n\n## Defer\nWhether the change names its issue belongs to `links-the-change-to-its-issue`; whether the issue states a checkable outcome belongs to `issue-has-checkable-outcome`. Here only: did the issue exist before the first recorded commit?","precomputeScript":"// Precompute FACTS for plans-the-work-in-an-issue-first: when each issue the change names as its own\n// was opened, when the change''s earliest commit was authored, and the time between them. The practice\n// asks one question of two timestamps; the script puts both beside each other so the review reads\n// them rather than reasons around them.\nimport { readCapturedCommits } from \"../lib/change.ts\";\nimport { contextFile } from \"../lib/context.ts\";\nimport { text } from \"../lib/practice-contract.ts\";\nimport {\n\tbranchIssueReferences,\n\tclosingReferences,\n\tissueNumberReferences,\n\trelatedReferences,\n} from \"../lib/references.ts\";\nimport { millisBetween, readLinkedWorkItemCapture } from \"../lib/review.ts\";\nimport type { DiffFile, Hint, PullRequestMetadata } from \"../lib/types.ts\";\n\n/** The two moments in one sentence, the way the cell reads them. */\nfunction relationOf(issueToFirstCommit: number | null): string {\n\tif (issueToFirstCommit === null) {\n\t\treturn \"the captured commits do not establish the earliest authored time; the order is UNDETERMINED\";\n\t}\n\treturn issueToFirstCommit >= 0\n\t\t? `the earliest commit was authored ${hours(issueToFirstCommit)} h after the issue was opened`\n\t\t: `the issue was opened ${hours(-issueToFirstCommit)} h after the earliest commit was authored`;\n}\n\n/** Hours with one decimal, signed: positive when `to` is later than `from`. */\nfunction hours(millis: number): string {\n\treturn (millis / 3_600_000).toFixed(1);\n}\n\nexport default async function plansTheWorkInAnIssueFirst(\n\t_repoPath: string,\n\t_diffFiles: Map<string, DiffFile>,\n\tmetadata: PullRequestMetadata,\n\tcontextDir: string | undefined,\n\t_changeDir: string | undefined,\n\tcontextReference: string,\n) {\n\tconst hints: Hint[] = [];\n\tconst directions: string[] = [];\n\tconst body = text(metadata.body);\n\tconst title = text(metadata.title);\n\tconst capture = await readLinkedWorkItemCapture(contextDir);\n\tconst linked = capture?.items ?? null;\n\tconst named = new Map<number, string[]>();\n\tconst name = (how: string, numbers: number[]) => {\n\t\tfor (const n of numbers) {\n\t\t\tnamed.set(n, [...(named.get(n) ?? []), how]);\n\t\t}\n\t};\n\tname(\n\t\t\"provider closing link\",\n\t\t(linked ?? []).filter((item) => item.how === \"closesOnMerge\").map((item) => item.number),\n\t);\n\tname(\"closing keyword\", closingReferences(body));\n\tname(\"title\", issueNumberReferences(title));\n\tname(\"branch\", branchIssueReferences(metadata.source_branch));\n\tname(\"Related to\", relatedReferences(body));\n\tconst capturedCommits = await readCapturedCommits(contextDir);\n\tconst commitsCaptured = capturedCommits !== null;\n\tconst commits = capturedCommits ?? [];\n\tconst authored = commits\n\t\t.filter((commit) => Number.isFinite(Date.parse(commit.authoredAt)))\n\t\t.toSorted((a, b) => Date.parse(a.authoredAt) - Date.parse(b.authoredAt));\n\tconst first = authored.length === commits.length ? authored[0] : undefined;\n\tlet earliestDeltaMinutes = Number.NaN;\n\tfor (const item of linked ?? []) {\n\t\tconst namedBy = named.get(item.number)?.join(\", \");\n\t\tif (namedBy === undefined) {\n\t\t\tcontinue;\n\t\t}\n\t\tconst toFirstCommit = millisBetween(item.createdAt, first?.authoredAt);\n\t\tconst flags: Hint[\"flags\"] = {\n\t\t\tnumber: item.number,\n\t\t\tnamedBy,\n\t\t\tproviderLink: item.how ?? \"\",\n\t\t\topenedAt: item.createdAt ?? \"\",\n\t\t};\n\t\tif (first !== undefined) {\n\t\t\tflags.firstCommit = first.sha.slice(0, 7);\n\t\t\tflags.firstCommitAuthoredAt = first.authoredAt;\n\t\t}\n\t\tif (toFirstCommit !== null) {\n\t\t\tflags.hoursFromIssueToFirstCommit = hours(toFirstCommit);\n\t\t\tconst minutes = -toFirstCommit / 60_000;\n\t\t\tif (Number.isNaN(earliestDeltaMinutes) || minutes > earliestDeltaMinutes) {\n\t\t\t\tearliestDeltaMinutes = minutes;\n\t\t\t}\n\t\t}\n\t\tlet relation =\n\t\t\t\"the commit record is missing or malformed: a collection gap, not a timing observation\";\n\t\tif (commitsCaptured) {\n\t\t\trelation =\n\t\t\t\titem.createdAt === undefined\n\t\t\t\t\t? \"its opening time is not captured, so the order cannot be read\"\n\t\t\t\t\t: relationOf(toFirstCommit);\n\t\t}\n\t\thints.push({\n\t\t\tfile: contextFile(contextReference, `linked_work_items/${String(item.number)}.md`),\n\t\t\tline: 0,\n\t\t\tpattern: \"candidate issue\",\n\t\t\tcontext: `#${String(item.number)} (named by ${namedBy}; captured as ${item.how ?? \"an unclassified link\"}) opened ${item.createdAt ?? \"(unknown)\"}; ${relation}`,\n\t\t\tinDiff: false,\n\t\t\tflags,\n\t\t});\n\t}\n\tconst numbers = [...named.keys()].map((n) => `#${String(n)}`).join(\", \");\n\t// A named number this repository holds no synchronized issue for may be an issue not yet\n\t// synchronized or a reference elsewhere; the record cannot say which.\n\tconst unresolved = [...named.keys()].filter((n) => capture?.unresolved.includes(n) ?? false);\n\tif (!commitsCaptured) {\n\t\tdirections.push(\n\t\t\t\"The commit record is missing or malformed: report a collection gap and record no observation, never UNDETERMINED.\",\n\t\t);\n\t} else if (capture === null) {\n\t\tdirections.push(\n\t\t\t`${contextFile(contextReference, \"linked_work_items.json\")} was not captured: a collection gap, not a change without an issue.`,\n\t\t);\n\t} else if (hints.length === 0 && unresolved.length === 0) {\n\t\tdirections.push(\n\t\t\t\"No issue of this repository is named by a provider closing link, a closing keyword, the title, the branch or a `Related to #N`; without an issue this change implements there is nothing to have planned in.\",\n\t\t);\n\t} else {\n\t\tif (unresolved.length > 0) {\n\t\t\tdirections.push(\n\t\t\t\t`The named issue(s) ${unresolved.map((n) => `#${String(n)}`).join(\", \")} are among the capture''s unresolved references: this repository holds no synchronized issue with that number, so no opening time. Whether one is the issue this change implements is read from the description: if it is, the order stays open (UNDETERMINED, never a timing judgement on another issue instead); if the description rules it out, it is no occasion.`,\n\t\t\t);\n\t\t}\n\t\tif (hints.length > 0) {\n\t\t\tdirections.push(\n\t\t\t\t`The cell is decided by the issue''s opening time against the earliest authored commit of the change (${contextFile(contextReference, \"commits.json\")}), never against the pull request''s creation: a pull request is opened when the work is handed off, and the practice asks whether the plan preceded the work.`,\n\t\t\t\t\"Compare the issue opening and earliest captured authored commit exactly. These dates establish the recorded order, not when all work began or why the issue was written.\",\n\t\t\t\t...(first === undefined\n\t\t\t\t\t? [\n\t\t\t\t\t\t\t\"If the complete captured commit record is empty or any commit lacks a usable authored date, the earliest time cannot be established and the timing is UNDETERMINED. The pull request''s creation dates the handoff, not the start of work; it cannot replace the missing date. Missing commit capture is a collection gap, not UNDETERMINED.\",\n\t\t\t\t\t\t]\n\t\t\t\t\t: []),\n\t\t\t);\n\t\t\tif (hints.some((hint) => hint.flags.namedBy === \"Related to\")) {\n\t\t\t\tdirections.push(\n\t\t\t\t\t\"An issue named only by `Related to` is the occasion only when the description or the issue shows this change implements part of it, not when the sentence is about other work. It was captured as a mention, not a closing candidate: nothing here says the issue closed or will close on merge.\",\n\t\t\t\t);\n\t\t\t}\n\t\t\tif (hints.length > 1) {\n\t\t\t\tdirections.push(\n\t\t\t\t\t`Several issues are named (${numbers}): judge the one this change implements, read from the description and the issues. If more than one remains plausible and their timing falls in different cells, do not choose the favourable one.`,\n\t\t\t\t);\n\t\t\t}\n\t\t}\n\t}\n\treturn {\n\t\thints,\n\t\tmetrics: {\n\t\t\tnamedIssues: named.size,\n\t\t\tunresolvedNamedIssues: unresolved.length,\n\t\t\tlinkedItems: linked?.length ?? -1,\n\t\t\tcommits: commits.length,\n\t\t\tissueOpenedAfterFirstCommitMinutes: Number.isNaN(earliestDeltaMinutes)\n\t\t\t\t? -1\n\t\t\t\t: Math.max(0, Math.round(earliestDeltaMinutes)),\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A tracked issue written before the first recorded commit gives reviewers a prior statement of the work. Commit timestamps provide a recorded ordering, not proof of when someone actually started thinking or coding.","whatGoodLooksLike":"The tracked issue this change implements has an opening timestamp no later than the earliest captured commit author timestamp. The record names both times without inferring intent or unrecorded work.","groupSlug":"issue-traceability-and-lifecycle","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 200\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Commit first</text>\n  <circle class=\"pv-fill-surface pv-stroke-muted\" cx=\"12\" cy=\"44\" r=\"11.25\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"12\" y=\"49\" font-size=\"15\" text-anchor=\"middle\">1</text>\n  <path class=\"pv-stroke-muted\" d=\"M32 44h288\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M328 44l-8-5v10z\"/>\n  <g transform=\"translate(0 66)\"><path class=\"pv-stroke-ink\" d=\"M0 8h4.5M11.5 8H16\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"3.5\" fill=\"none\" stroke-width=\"1.5\"/></g>\n  <text class=\"pv-fill-ink\" x=\"28\" y=\"80\" font-size=\"16\" font-weight=\"600\">Commit</text>\n  <circle class=\"pv-fill-surface pv-stroke-muted\" cx=\"348\" cy=\"44\" r=\"11.25\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"348\" y=\"49\" font-size=\"15\" text-anchor=\"middle\">2</text>\n  <g transform=\"translate(336 66)\"><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"6.75\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-fill-ink\" cx=\"8\" cy=\"8\" r=\"1.75\"/></g>\n  <text class=\"pv-fill-ink\" x=\"364\" y=\"80\" font-size=\"16\" font-weight=\"600\">Issue</text>\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"132\" font-size=\"16\" font-weight=\"600\">Issue first</text>\n  <circle class=\"pv-fill-accent\" cx=\"12\" cy=\"160\" r=\"12\"/>\n  <text class=\"pv-fill-surface\" x=\"12\" y=\"165\" font-size=\"15\" font-weight=\"600\" text-anchor=\"middle\">1</text>\n  <path class=\"pv-stroke-muted\" d=\"M32 160h288\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M328 160l-8-5v10z\"/>\n  <g transform=\"translate(0 182)\"><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"6.75\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-fill-ink\" cx=\"8\" cy=\"8\" r=\"1.75\"/></g>\n  <text class=\"pv-fill-ink\" x=\"28\" y=\"196\" font-size=\"16\" font-weight=\"600\">Issue</text>\n  <circle class=\"pv-fill-surface pv-stroke-muted\" cx=\"348\" cy=\"160\" r=\"11.25\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"348\" y=\"165\" font-size=\"15\" text-anchor=\"middle\">2</text>\n  <g transform=\"translate(336 182)\"><path class=\"pv-stroke-ink\" d=\"M0 8h4.5M11.5 8H16\" fill=\"none\" stroke-width=\"1.5\"/><circle class=\"pv-stroke-ink\" cx=\"8\" cy=\"8\" r=\"3.5\" fill=\"none\" stroke-width=\"1.5\"/></g>\n  <text class=\"pv-fill-ink\" x=\"364\" y=\"196\" font-size=\"16\" font-weight=\"600\">Commit</text>\n</svg>\n","alt":"Commit first: the first commit comes before the issue opens. Issue first: the issue opens before the first commit."},"guide":{"markdown":"## How to do it\n\n- Before your first commit, open an issue that says what you plan to change. For example, instead of committing a first draft and then filing the issue, file the issue first.\n- You can start your branch from the issue page. GitHub and GitLab can both create a branch there.\n- Compare the issue’s opening time with the author date of your earliest commit in the change.\n\n![Open the issue and say what you plan. You can then start a branch from the issue page. Your first commit comes after the issue opens.](figures/issue-to-commit.svg)\n\n## When it does not apply\n\n- Your pull request or merge request carries out no issue. You name none, or you say that each named issue is other work, such as “Not related to #12”.\n- The change is a release, a dependency update from a bot, or a revert.\n- You mention the issue only as a plain number, or only inside a quote, code or a hidden comment.\n- The issue belongs to another project.\n\nIt still applies when you name the issue only with “Related to” and the change does part of that issue’s work.\n\n## Common mistakes\n\n- Opening the issue just before you open the pull request or merge request. Your first commit counts, not the moment you ask for review. Instead, open the issue before you commit.\n- Waiting to open the issue until the plan is complete. Only the order counts here, not the length of the issue. Instead, open a short issue first and add details as you learn.\n- Comparing the issue with only the commit that adds its work. Earlier commits in the same change still count. Instead, compare with your earliest commit.\n\n## Sources\n\n- [How to contribute to open source](https://opensource.guide/how-to-contribute/), GitHub Open Source Guides. Before you work on a large contribution, open an issue to ask about it.\n- [Merge requests workflow](https://docs.gitlab.com/development/contributing/merge_request_workflow/), GitLab Docs. For a new feature idea, GitLab asks contributors to create an issue first, if there is not one already.\n- [Creating a branch to work on an issue](https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/creating-a-branch-for-an-issue), GitHub Docs. You can create a branch from the issue page, and a pull request from that branch links to the issue.\n- [Create a merge request](https://docs.gitlab.com/user/project/merge_requests/creating_merge_requests/), GitLab Docs. From an issue, you can create a branch and a merge request together, both marked as related to that issue.\n","figures":{"issue-to-commit":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 76\">\n  <circle class=\"pv-fill-accent\" cx=\"12\" cy=\"12\" r=\"12\"/>\n  <text class=\"pv-fill-surface\" x=\"12\" y=\"17\" font-size=\"15\" font-weight=\"600\" text-anchor=\"middle\">1</text>\n  <path class=\"pv-stroke-muted\" d=\"M32 12h176\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M216 12l-8-5v10z\"/>\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"48\" font-size=\"16\" font-weight=\"600\">Open the issue</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"72\" font-size=\"15\">Say what you plan</text>\n  <circle class=\"pv-fill-surface pv-stroke-muted\" cx=\"236\" cy=\"12\" r=\"11.25\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"236\" y=\"17\" font-size=\"15\" text-anchor=\"middle\">2</text>\n  <path class=\"pv-stroke-muted\" d=\"M256 12h176\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M440 12l-8-5v10z\"/>\n  <text class=\"pv-fill-ink\" x=\"224\" y=\"48\" font-size=\"16\" font-weight=\"600\">Optional branch</text>\n  <text class=\"pv-fill-muted\" x=\"224\" y=\"72\" font-size=\"15\">From the issue page</text>\n  <circle class=\"pv-fill-surface pv-stroke-muted\" cx=\"460\" cy=\"12\" r=\"11.25\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"460\" y=\"17\" font-size=\"15\" text-anchor=\"middle\">3</text>\n  <text class=\"pv-fill-ink\" x=\"448\" y=\"48\" font-size=\"16\" font-weight=\"600\">First commit</text>\n  <text class=\"pv-fill-muted\" x=\"448\" y=\"72\" font-size=\"15\">After the issue opens</text>\n</svg>\n"}}}'::jsonb)),'{guidance,goingWell}','"The issue exists before the first recorded commit"'::jsonb),'v5:2c9021782d031aa996ae60e1c7bf8fba47b82514592bebd445582ddff5641885','practice:v3:bdc79402ccd9b001fb6a86f81df546cbd375963594f6ba78b2ddf2c6f818a226');
INSERT INTO _cutover_bundle VALUES('GROUP','ios-app-craft',NULL,'{"name":"Building iOS apps well","description":"Write SwiftUI the way it is designed to be written: views that describe the screen from state they are handed, state owned where it belongs, concurrency that is structured, an interface everyone can use, a preview for every screen, and permissions declared truthfully. These practices run only on changes that touch Swift code.","icon":"Monitor","color":"orange"}'::jsonb,'{"name":"Building iOS apps well","description":"Write SwiftUI the way it is designed to be written: views that describe the screen from state they are handed, state owned where it belongs, concurrency that is structured, an interface everyone can use, a preview for every screen, and permissions declared truthfully. These practices run only on changes that touch Swift code.","icon":"Monitor","color":"orange"}'::jsonb,'2a71ab1780a1d08ee292cd534d96e8679ed6e4871923b1b5ad2edfc9eec7e820','group:v1:2a71ab1780a1d08ee292cd534d96e8679ed6e4871923b1b5ad2edfc9eec7e820');
INSERT INTO _cutover_bundle VALUES('PRACTICE','keeps-views-free-of-networking-and-persistence','scm.pull_request','{"name":"Keep networking and persistence out of views","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":{"skipReason":"the change touches no Swift source file","anyOf":[{"changedPathMatches":["**/*.swift"]}]},"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: added SwiftUI view code delegates I/O appropriately or uses the framework''s supported view-side persistence idiom.\n\n## The standard\nJudge one thing about the SwiftUI code this change adds: does a `View` type perform I/O itself? I/O in a view is a `URLSession` or `URLRequest` call, `JSONDecoder`/`JSONEncoder` use, `UserDefaults` or `FileManager` access, `Data(contentsOf:)`, a Core Data fetch request, or a `fetch`/`load`/`save` implemented inside a `struct … : View` — in `body`, a modifier closure (`.task`, `.onAppear`, a button action) or a method of the view. A view that calls a model''s method (`store.load()`, `viewModel.save(item)`) or passes a `Binding` is not performing I/O, and the framework''s own view-side storage — SwiftData''s `@Query` and `modelContext.insert`/`delete` through `@Environment(\\.modelContext)`, Core Data''s `@FetchRequest`, and SwiftUI''s `@AppStorage` and `@SceneStorage` — is the framework''s designed use of a view, not I/O the view took on. The judgement is about where the work lives, never about the architecture''s name.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the change adds no code inside a SwiftUI view type: no added line lies within a `struct … : View` (or a `some View` computed property) — a model-only, service-only, test-only or non-Swift change carries no surface. Added lines inside a view type are the occasion, whether or not they perform I/O.\n\n## Sources\n1. The diff (`work/change/diff.patch`) with `[L<n>]` markers: the added lines and the type each hunk lies in, read from the hunk header and the surrounding declaration. It establishes which added lines are inside a view type and which call I/O. It never establishes what unchanged code does.\n2. The checkout (`<repositoryRoot>`): the enclosing type of a hunk when the diff context does not show it, and whether a called method belongs to a model or store. Read it only to place a line; it never adds an I/O call the diff does not show.\n3. The precomputed leads below these criteria: the I/O calls it found inside view types, as leads to inspect, never as conclusions.\nIf the diff of a Swift file is truncated where a view type is edited, report a collection gap and record no observation.\n\n## Judge\nScan the added lines inside view types first, then assess the standard.\nThe undesirable behaviour is I/O inside a view. Assess conformance to the standard in this context.\n- NOT_MET: an added line inside a view type performs I/O itself — a `URLSession`/`URLRequest` call, `JSONDecoder`, `UserDefaults`, `FileManager`, `Data(contentsOf:)`, a direct Core Data fetch or an inline fetch-and-parse. Framework view-side storage named above is not direct I/O. Quote the line and name the view type.\n- MET: a complete bounded review of the added view code shows no direct I/O outside the supported framework view-side storage named above. The view may need no I/O at all, or it delegates required I/O to a model, store or service. Cite the added view code and its enclosing declaration; quote a delegating call only when one exists.\n- UNDETERMINED: the hunk shows the call but neither the context nor the checkout shows whether the enclosing type is a view; name the declaration that would settle it.\nOne observation per review, on the single most consequential I/O line when there are several.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: one read (`UserDefaults`, a decode) inside a view, or I/O in a small preview-only or prototype view. MAJOR: a network request or a persistence write implemented inside a shipped view, or the same I/O repeated in several views. Identical evidence yields identical severity.\n\n## Grounding\nQuote the `[L<n>]` added line that performs the I/O and the `struct … : View` declaration it lies in, For MET, cite the added view code and its enclosing declaration, and record the diff as the source searched: every added line inside a view type was read. Include a delegating call when relevant. Never claim I/O from a method name alone (`load()` may be a model call); never claim a type is a view without its declaration; never count the supported framework view-side storage named above as direct I/O.\n\n## Defer\nDuplicated logic across views belongs to `removes-duplication-instead-of-copy-pasting`; oversized view bodies to `keeps-functions-small-and-single-purpose`. Here only: does the view do I/O itself?","precomputeScript":"// Precompute HINTS for keeps-views-free-of-networking-and-persistence: locate I/O calls ADDED inside\n// SwiftUI view types — requests, decoding, files, preferences, Core Data. SwiftData''s view-side idiom\n// (`@Query`, `modelContext.insert`) is the framework''s own and is not listed. Each is a candidate the review places;\n// a `load()` call on a store is not I/O in the view, and the script says which type a line lies in so\n// the review does not have to find the declaration itself.\nimport { sampleNote, scanAddedLines, type SourcePattern } from \"../lib/source-scan.ts\";\nimport type { DiffFile, PullRequestMetadata } from \"../lib/types.ts\";\n\n/** A SwiftUI view: a type conforming to `View`, or an `App`/`Scene`, which also declare a body. */\nconst SWIFTUI_VIEW = /\\b(?:View|App|Scene)\\b/u;\n\nconst IO_IN_VIEW: readonly SourcePattern[] = [\n\t[\"URLSession request\", /\\bURLSession\\b|\\bURLRequest\\s*\\(/u],\n\t[\"JSON coding\", /\\bJSON(?:Decoder|Encoder)\\s*\\(/u],\n\t[\"Core Data fetch\", /\\bNSFetchRequest\\b|\\.fetch\\s*\\(\\s*NSFetchRequest/u],\n\t[\"UserDefaults access\", /\\bUserDefaults\\b/u],\n\t[\"FileManager access\", /\\bFileManager\\b/u],\n\t[\"Data(contentsOf:)\", /\\bData\\(contentsOf:/u],\n];\n\nexport default async function keepsViewsFreeOfNetworkingAndPersistence(\n\trepoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n) {\n\tconst scan = await scanAddedLines(repoPath, diffFiles, {\n\t\tlanguages: [\"swift\"],\n\t\tpatterns: IO_IN_VIEW,\n\t\tscope: SWIFTUI_VIEW,\n\t\tonlyInScope: true,\n\t});\n\tconst directions: string[] = [...sampleNote(scan)];\n\tif (scan.matched > 0) {\n\t\tdirections.push(\n\t\t\t`${scan.matched} candidate I/O calls were added inside or possibly inside view types. Read each hint''s enclosing type. A line in a store or model is not the view''s I/O. SwiftUI @AppStorage and @SceneStorage, Core Data @FetchRequest, and the supported SwiftData view-side APIs are not direct I/O.`,\n\t\t);\n\t}\n\tif (scan.filesWithoutCheckout > 0) {\n\t\tdirections.push(\n\t\t\t`${scan.filesWithoutCheckout} Swift file(s) could not be read from the checkout; their hints carry enclosing=unknown and need the diff context to place.`,\n\t\t);\n\t}\n\treturn {\n\t\thints: scan.hints,\n\t\tmetrics: {\n\t\t\tioCallsInViews: scan.matched,\n\t\t\tviewLinesAdded: scan.linesInScope,\n\t\t\tswiftLinesAdded: scan.linesAdded,\n\t\t\tfilesWithoutCheckout: scan.filesWithoutCheckout,\n\t\t\tfilesScanned: scan.filesScanned,\n\t\t\tlinesAdded: scan.linesAdded,\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A SwiftUI view that fetches, decodes or saves is a view nobody can preview, test or reuse, and its logic is invisible to the next screen that needs the same data. Keeping that work in a model or store is what lets the view stay a description of the screen.","whatGoodLooksLike":"Views describe the screen from state they are handed; requests, decoding and file or preference access live in a model, store or service the view talks to through a method or a binding, and SwiftData is used through its own view-side idiom.","groupSlug":"ios-app-craft","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 164\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">View fetches and saves</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"142.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"16\" y=\"61\" font-size=\"15\">SearchView</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"16\" y=\"93\" font-size=\"15\">URLSession</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"16\" y=\"117\" font-size=\"15\">UserDefaults</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"160.75\" y=\"32.75\" width=\"142.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"176\" y=\"61\" font-size=\"15\">SearchModel</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"160\" font-size=\"15\">Hard to preview</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Model fetches and saves</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"142.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"352\" y=\"61\" font-size=\"15\">SearchView</text>\n  <text class=\"pv-fill-ink pv-mono\" x=\"352\" y=\"93\" font-size=\"15\">model.load()</text>\n  <text class=\"pv-fill-ink pv-mono\" x=\"352\" y=\"117\" font-size=\"15\">model.save()</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"496.75\" y=\"32.75\" width=\"142.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"512\" y=\"61\" font-size=\"15\">SearchModel</text>\n  <text class=\"pv-fill-accent pv-mono\" x=\"512\" y=\"93\" font-size=\"15\">URLSession</text>\n  <text class=\"pv-fill-accent pv-mono\" x=\"512\" y=\"117\" font-size=\"15\">UserDefaults</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"160\" font-size=\"15\">Easy to preview</text>\n</svg>\n","alt":"When the view fetches and saves, URLSession and UserDefaults sit in SearchView, so it is hard to preview. When the model does, SearchView calls model.load() and model.save(), and both sit in SearchModel, so it is easy to preview."},"guide":{"markdown":"## How to do it\n\n- Put I/O in a model, a store or a service. I/O means reading or writing data, such as network requests, decoding, and file or `UserDefaults` access. The view calls a method or passes a binding. A binding lets the view read and change data that another type owns.\n- Start the work from a modifier by calling the model. For example, instead of calling `URLSession` in a view’s `.task`, write `.task { await store.load() }` and keep the request in the store.\n- In a button action, call a method of the model, such as `viewModel.save(item)`. The action does not encode the item or write the file.\n- Hand the view the state it shows, such as the loaded items. Then a preview or a test can pass in sample state, with no network and no disk.\n- Use the framework’s own view-side storage in the view. It is `@Query`, `@FetchRequest`, `modelContext.insert` and `delete` through `@Environment(\\.modelContext)`, `@AppStorage` and `@SceneStorage`.\n\n## When it does not apply\n\n- Your change adds no line inside a SwiftUI view type: a `struct` that conforms to `View`, or a computed property that returns `some View`.\n- Your change touches only models, services, tests or files that are not Swift.\n\nIt still applies when the lines you add to a view do no I/O.\n\n## Common mistakes\n\n- Looking for one architecture, such as a view model for each screen. The practice asks only where the work runs. Instead, check that any request or write runs outside the view, in whatever model, store or service you already have.\n- Moving `@Query`, `@FetchRequest`, `@AppStorage` or `@SceneStorage` out of a view to follow this practice. They are the framework’s own way for a view to read and store data. Instead, keep them in the view.\n- Moving the request into a private method of the view, such as `fetchItems()`. The method is still part of the view. Instead, move it to the model and call it from the view.\n- Reading `UserDefaults` or calling `FileManager` in a view for one value. Instead, use `@AppStorage` for a setting, or let the model read the value.\n\n## Sources\n\n- [Managing model data in your app](https://developer.apple.com/documentation/swiftui/managing-model-data-in-your-app), Apple. A data model keeps the data apart from the views that show it, which makes the app easier to test.\n- [Data Essentials in SwiftUI](https://developer.apple.com/videos/play/wwdc2020/10040/), Apple, 2020. A separate model handles storage, syncing and side effects, while a view’s `body` only describes the screen.\n- [SwiftData](https://developer.apple.com/documentation/swiftdata), Apple. SwiftData provides `Query` for stored models, and a view reaches the model context through its environment.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Keep networking and persistence out of views","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":{"skipReason":"the change touches no Swift source file","anyOf":[{"changedPathMatches":["**/*.swift"]}]},"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: added SwiftUI view code delegates I/O appropriately or uses the framework''s supported view-side persistence idiom.\n\n## The standard\nJudge one thing about the SwiftUI code this change adds: does a `View` type perform I/O itself? I/O in a view is a `URLSession` or `URLRequest` call, `JSONDecoder`/`JSONEncoder` use, `UserDefaults` or `FileManager` access, `Data(contentsOf:)`, a Core Data fetch request, or a `fetch`/`load`/`save` implemented inside a `struct … : View` — in `body`, a modifier closure (`.task`, `.onAppear`, a button action) or a method of the view. A view that calls a model''s method (`store.load()`, `viewModel.save(item)`) or passes a `Binding` is not performing I/O, and the framework''s own view-side storage — SwiftData''s `@Query` and `modelContext.insert`/`delete` through `@Environment(\\.modelContext)`, Core Data''s `@FetchRequest`, and SwiftUI''s `@AppStorage` and `@SceneStorage` — is the framework''s designed use of a view, not I/O the view took on. The judgement is about where the work lives, never about the architecture''s name.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the change adds no code inside a SwiftUI view type: no added line lies within a `struct … : View` (or a `some View` computed property) — a model-only, service-only, test-only or non-Swift change carries no surface. Added lines inside a view type are the occasion, whether or not they perform I/O.\n\n## Sources\n1. The diff (`work/change/diff.patch`) with `[L<n>]` markers: the added lines and the type each hunk lies in, read from the hunk header and the surrounding declaration. It establishes which added lines are inside a view type and which call I/O. It never establishes what unchanged code does.\n2. The checkout (`<repositoryRoot>`): the enclosing type of a hunk when the diff context does not show it, and whether a called method belongs to a model or store. Read it only to place a line; it never adds an I/O call the diff does not show.\n3. The precomputed leads below these criteria: the I/O calls it found inside view types, as leads to inspect, never as conclusions.\nIf the diff of a Swift file is truncated where a view type is edited, report a collection gap and record no observation.\n\n## Judge\nScan the added lines inside view types first, then assess the standard.\nThe undesirable behaviour is I/O inside a view. Assess conformance to the standard in this context.\n- NOT_MET: an added line inside a view type performs I/O itself — a `URLSession`/`URLRequest` call, `JSONDecoder`, `UserDefaults`, `FileManager`, `Data(contentsOf:)`, a direct Core Data fetch or an inline fetch-and-parse. Framework view-side storage named above is not direct I/O. Quote the line and name the view type.\n- MET: a complete bounded review of the added view code shows no direct I/O outside the supported framework view-side storage named above. The view may need no I/O at all, or it delegates required I/O to a model, store or service. Cite the added view code and its enclosing declaration; quote a delegating call only when one exists.\n- UNDETERMINED: the hunk shows the call but neither the context nor the checkout shows whether the enclosing type is a view; name the declaration that would settle it.\nOne observation per review, on the single most consequential I/O line when there are several.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: one read (`UserDefaults`, a decode) inside a view, or I/O in a small preview-only or prototype view. MAJOR: a network request or a persistence write implemented inside a shipped view, or the same I/O repeated in several views. Identical evidence yields identical severity.\n\n## Grounding\nQuote the `[L<n>]` added line that performs the I/O and the `struct … : View` declaration it lies in, For MET, cite the added view code and its enclosing declaration, and record the diff as the source searched: every added line inside a view type was read. Include a delegating call when relevant. Never claim I/O from a method name alone (`load()` may be a model call); never claim a type is a view without its declaration; never count the supported framework view-side storage named above as direct I/O.\n\n## Defer\nDuplicated logic across views belongs to `removes-duplication-instead-of-copy-pasting`; oversized view bodies to `keeps-functions-small-and-single-purpose`. Here only: does the view do I/O itself?","precomputeScript":"// Precompute HINTS for keeps-views-free-of-networking-and-persistence: locate I/O calls ADDED inside\n// SwiftUI view types — requests, decoding, files, preferences, Core Data. SwiftData''s view-side idiom\n// (`@Query`, `modelContext.insert`) is the framework''s own and is not listed. Each is a candidate the review places;\n// a `load()` call on a store is not I/O in the view, and the script says which type a line lies in so\n// the review does not have to find the declaration itself.\nimport { sampleNote, scanAddedLines, type SourcePattern } from \"../lib/source-scan.ts\";\nimport type { DiffFile, PullRequestMetadata } from \"../lib/types.ts\";\n\n/** A SwiftUI view: a type conforming to `View`, or an `App`/`Scene`, which also declare a body. */\nconst SWIFTUI_VIEW = /\\b(?:View|App|Scene)\\b/u;\n\nconst IO_IN_VIEW: readonly SourcePattern[] = [\n\t[\"URLSession request\", /\\bURLSession\\b|\\bURLRequest\\s*\\(/u],\n\t[\"JSON coding\", /\\bJSON(?:Decoder|Encoder)\\s*\\(/u],\n\t[\"Core Data fetch\", /\\bNSFetchRequest\\b|\\.fetch\\s*\\(\\s*NSFetchRequest/u],\n\t[\"UserDefaults access\", /\\bUserDefaults\\b/u],\n\t[\"FileManager access\", /\\bFileManager\\b/u],\n\t[\"Data(contentsOf:)\", /\\bData\\(contentsOf:/u],\n];\n\nexport default async function keepsViewsFreeOfNetworkingAndPersistence(\n\trepoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n) {\n\tconst scan = await scanAddedLines(repoPath, diffFiles, {\n\t\tlanguages: [\"swift\"],\n\t\tpatterns: IO_IN_VIEW,\n\t\tscope: SWIFTUI_VIEW,\n\t\tonlyInScope: true,\n\t});\n\tconst directions: string[] = [...sampleNote(scan)];\n\tif (scan.matched > 0) {\n\t\tdirections.push(\n\t\t\t`${scan.matched} candidate I/O calls were added inside or possibly inside view types. Read each hint''s enclosing type. A line in a store or model is not the view''s I/O. SwiftUI @AppStorage and @SceneStorage, Core Data @FetchRequest, and the supported SwiftData view-side APIs are not direct I/O.`,\n\t\t);\n\t}\n\tif (scan.filesWithoutCheckout > 0) {\n\t\tdirections.push(\n\t\t\t`${scan.filesWithoutCheckout} Swift file(s) could not be read from the checkout; their hints carry enclosing=unknown and need the diff context to place.`,\n\t\t);\n\t}\n\treturn {\n\t\thints: scan.hints,\n\t\tmetrics: {\n\t\t\tioCallsInViews: scan.matched,\n\t\t\tviewLinesAdded: scan.linesInScope,\n\t\t\tswiftLinesAdded: scan.linesAdded,\n\t\t\tfilesWithoutCheckout: scan.filesWithoutCheckout,\n\t\t\tfilesScanned: scan.filesScanned,\n\t\t\tlinesAdded: scan.linesAdded,\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A SwiftUI view that fetches, decodes or saves is a view nobody can preview, test or reuse, and its logic is invisible to the next screen that needs the same data. Keeping that work in a model or store is what lets the view stay a description of the screen.","whatGoodLooksLike":"Views describe the screen from state they are handed; requests, decoding and file or preference access live in a model, store or service the view talks to through a method or a binding, and SwiftData is used through its own view-side idiom.","groupSlug":"ios-app-craft","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 164\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">View fetches and saves</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"142.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"16\" y=\"61\" font-size=\"15\">SearchView</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"16\" y=\"93\" font-size=\"15\">URLSession</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"16\" y=\"117\" font-size=\"15\">UserDefaults</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"160.75\" y=\"32.75\" width=\"142.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"176\" y=\"61\" font-size=\"15\">SearchModel</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"160\" font-size=\"15\">Hard to preview</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Model fetches and saves</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"142.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"352\" y=\"61\" font-size=\"15\">SearchView</text>\n  <text class=\"pv-fill-ink pv-mono\" x=\"352\" y=\"93\" font-size=\"15\">model.load()</text>\n  <text class=\"pv-fill-ink pv-mono\" x=\"352\" y=\"117\" font-size=\"15\">model.save()</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"496.75\" y=\"32.75\" width=\"142.5\" height=\"102.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"512\" y=\"61\" font-size=\"15\">SearchModel</text>\n  <text class=\"pv-fill-accent pv-mono\" x=\"512\" y=\"93\" font-size=\"15\">URLSession</text>\n  <text class=\"pv-fill-accent pv-mono\" x=\"512\" y=\"117\" font-size=\"15\">UserDefaults</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"160\" font-size=\"15\">Easy to preview</text>\n</svg>\n","alt":"When the view fetches and saves, URLSession and UserDefaults sit in SearchView, so it is hard to preview. When the model does, SearchView calls model.load() and model.save(), and both sit in SearchModel, so it is easy to preview."},"guide":{"markdown":"## How to do it\n\n- Put I/O in a model, a store or a service. I/O means reading or writing data, such as network requests, decoding, and file or `UserDefaults` access. The view calls a method or passes a binding. A binding lets the view read and change data that another type owns.\n- Start the work from a modifier by calling the model. For example, instead of calling `URLSession` in a view’s `.task`, write `.task { await store.load() }` and keep the request in the store.\n- In a button action, call a method of the model, such as `viewModel.save(item)`. The action does not encode the item or write the file.\n- Hand the view the state it shows, such as the loaded items. Then a preview or a test can pass in sample state, with no network and no disk.\n- Use the framework’s own view-side storage in the view. It is `@Query`, `@FetchRequest`, `modelContext.insert` and `delete` through `@Environment(\\.modelContext)`, `@AppStorage` and `@SceneStorage`.\n\n## When it does not apply\n\n- Your change adds no line inside a SwiftUI view type: a `struct` that conforms to `View`, or a computed property that returns `some View`.\n- Your change touches only models, services, tests or files that are not Swift.\n\nIt still applies when the lines you add to a view do no I/O.\n\n## Common mistakes\n\n- Looking for one architecture, such as a view model for each screen. The practice asks only where the work runs. Instead, check that any request or write runs outside the view, in whatever model, store or service you already have.\n- Moving `@Query`, `@FetchRequest`, `@AppStorage` or `@SceneStorage` out of a view to follow this practice. They are the framework’s own way for a view to read and store data. Instead, keep them in the view.\n- Moving the request into a private method of the view, such as `fetchItems()`. The method is still part of the view. Instead, move it to the model and call it from the view.\n- Reading `UserDefaults` or calling `FileManager` in a view for one value. Instead, use `@AppStorage` for a setting, or let the model read the value.\n\n## Sources\n\n- [Managing model data in your app](https://developer.apple.com/documentation/swiftui/managing-model-data-in-your-app), Apple. A data model keeps the data apart from the views that show it, which makes the app easier to test.\n- [Data Essentials in SwiftUI](https://developer.apple.com/videos/play/wwdc2020/10040/), Apple, 2020. A separate model handles storage, syncing and side effects, while a view’s `body` only describes the screen.\n- [SwiftData](https://developer.apple.com/documentation/swiftdata), Apple. SwiftData provides `Query` for stored models, and a view reaches the model context through its environment.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Views render the state they are handed and never fetch or persist"'::jsonb),'v5:6310be35b66e084aaa7d0c20e535426bc0d922b3fa7a64226cddaf4d551db7cd','practice:v3:d7933bc67423b11704d50ac3d19787f96e5c2cff8edeace4f9214ff13b4d632f');
INSERT INTO _cutover_bundle VALUES('PRACTICE','owns-state-at-the-right-level','scm.pull_request','{"name":"Own SwiftUI state at the right level","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":{"skipReason":"the change touches no Swift source file","anyOf":[{"changedPathMatches":["**/*.swift"]}]},"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: each piece of SwiftUI state declared where it is owned — view-local values as `@State`, shared models observed and injected, edits through `Binding`, derived values computed rather than stored.\n\n## The standard\nJudge the state declarations this change adds to SwiftUI views against four rules. (1) A value one view owns and mutates is `@State` (or `@AppStorage` for a persisted setting); a `let` or plain `var` that the view mutates is a lapse. (2) A model shared by more than one view is one object: `@Observable` (or `ObservableObject`) created once by its owner and reached through `@Environment`, `@Bindable` or a passed reference — a child view that creates its own instance of a shared model (`@State private var store = Store()` in a child, `StateObject` for a model the parent already holds) is a lapse. (3) A child that edits a parent''s value takes a `Binding` (`@Binding`, `$value`), not a copy it mutates. (4) A value derivable from other state (a count, a filtered list, a formatted string) is a computed property, not a second stored variable kept in sync by hand. Judge declarations and how they are wired, never naming or file layout.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the change adds no state declaration or state wiring to a SwiftUI view: no added `@State`, `@Binding`, `@Environment`, `@Bindable`, `@AppStorage`, `@Observable`, `ObservableObject`, `StateObject`, `ObservedObject`, or a mutable stored property inside a view type. A change to a view''s layout alone carries no surface.\n\n## Sources\n1. The diff (`work/change/diff.patch`) with `[L<n>]` markers: the added declarations and the wiring that hands state between views (`init` arguments, `.environment(…)`, `$` bindings). It establishes what was declared where. It never establishes what unchanged views hold.\n2. The checkout (`<repositoryRoot>`): whether a model type is `@Observable`, whether a parent already owns an instance a child recreates, and whether a stored value is derivable from other declared state. Read it to place a declaration; it never adds a declaration the diff does not show.\n3. The precomputed leads below these criteria: the declarations it found inside view types, as leads, never conclusions.\nIf the diff is truncated where a view''s declarations are edited, report a collection gap and record no observation.\n\n## Judge\nEnumerate the added state declarations first, then assess the standard.\n- MET: every added declaration follows the four rules — local values `@State`, shared models observed once and injected, edits through bindings, derived values computed. Quote the declaration you accepted as the representative.\n- NOT_MET: a declaration breaks a rule — a mutable stored property in a view without `@State`; a child creating a second instance of a model the parent owns; a copied value the child mutates where a `Binding` was needed; a stored value kept in sync by hand with the state it derives from. Quote the declaration and name the rule.\n- UNDETERMINED: whether a model is shared or owned by this view alone cannot be told from the diff and the checkout; name the type and the fact that would settle it.\nOne observation per review, on the single most consequential declaration when several break a rule.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: a derived value stored, or a mutable `var` that should be `@State` in a leaf view. MAJOR: a shared model recreated in a child (state that silently resets or diverges), or a copied value edited where the parent''s value was meant to change. Identical evidence yields identical severity.\n\n## Grounding\nQuote the `[L<n>]` declaration and, for a shared-model lapse, the parent''s declaration of the same model. Never claim a model is shared without a second view that holds it; never claim a value is derivable without naming the state it derives from.\n\n## Defer\nI/O inside views belongs to `keeps-views-free-of-networking-and-persistence`; concurrency belongs to `uses-structured-concurrency-safely`. Here only: is the state declared where it is owned?","precomputeScript":"// Precompute HINTS for owns-state-at-the-right-level: every state declaration and wiring ADDED in Swift\n// files, placed in its enclosing type. The rules (local values @State, shared models observed once,\n// edits through Binding, derived values computed) are the review''s to apply; the script enumerates\n// the declarations so none is missed and counts a model created inside a view type as a lead.\nimport { sampleNote, scanAddedLines, type SourcePattern } from \"../lib/source-scan.ts\";\nimport type { DiffFile, PullRequestMetadata } from \"../lib/types.ts\";\n\nconst SWIFTUI_VIEW = /\\b(?:View|App|Scene)\\b/u;\n\nconst STATE_DECLARATIONS: readonly SourcePattern[] = [\n\t[\"@State creating an object\", /@State(?:Object)?\\b[^=]*=\\s*[A-Z][A-Za-z0-9_]*\\s*\\(/u],\n\t[\"@State\", /@State\\b/u],\n\t[\"@StateObject\", /@StateObject\\b/u],\n\t[\"@ObservedObject\", /@ObservedObject\\b/u],\n\t[\"@Binding\", /@Binding\\b/u],\n\t[\"@Bindable\", /@Bindable\\b/u],\n\t[\"@Environment\", /@Environment(?:Object)?\\b/u],\n\t[\"@AppStorage\", /@AppStorage\\b/u],\n\t[\"@Query\", /@Query\\b/u],\n\t[\"@Observable type\", /@Observable\\b/u],\n\t[\"ObservableObject type\", /\\bObservableObject\\b/u],\n\t[\"@Published\", /@Published\\b/u],\n\t[\n\t\t\"mutable stored property\",\n\t\t/^\\s*(?:private\\s+|fileprivate\\s+|internal\\s+)?var\\s+[A-Za-z_][A-Za-z0-9_]*\\s*(?::\\s*[^{=\\n]+)?(?:=\\s*[^{\\n]+)?\\s*$/u,\n\t],\n\t[\"environment injection\", /\\.environment(?:Object)?\\s*\\(/u],\n];\n\nexport default async function ownsStateAtTheRightLevel(\n\trepoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n) {\n\tconst scan = await scanAddedLines(repoPath, diffFiles, {\n\t\tlanguages: [\"swift\"],\n\t\tpatterns: STATE_DECLARATIONS,\n\t\tscope: SWIFTUI_VIEW,\n\t\tmaxHints: 60,\n\t});\n\tconst inViews = scan.hints.filter((h) => h.flags.inScope === true);\n\tconst objectsCreatedInViews = inViews.filter(\n\t\t(h) => h.pattern === \"@State creating an object\" || h.pattern === \"@StateObject\",\n\t).length;\n\tconst storedVarsInViews = inViews.filter((h) => h.pattern === \"mutable stored property\").length;\n\tconst directions: string[] = [...sampleNote(scan)];\n\tif (scan.matched > 0) {\n\t\tdirections.push(\n\t\t\t`${scan.matched} state declaration(s) or wiring line(s) added; ${inViews.length} of the listed rows lie inside view types. Walk each against the four rules.`,\n\t\t);\n\t}\n\tif (objectsCreatedInViews > 0) {\n\t\tdirections.push(\n\t\t\t`${objectsCreatedInViews} object(s) created in a view''s @State/@StateObject — check in the checkout whether a parent already owns an instance of the same type.`,\n\t\t);\n\t}\n\tif (storedVarsInViews > 0) {\n\t\tdirections.push(\n\t\t\t`${storedVarsInViews} plain stored var(s) in a view type — a view mutating one of these without @State is a rule-1 lapse; a let-like var the view never mutates is not.`,\n\t\t);\n\t}\n\treturn {\n\t\thints: scan.hints,\n\t\tmetrics: {\n\t\t\tstateDeclarationsAdded: scan.matched,\n\t\t\tstateDeclarationsInViews: inViews.length,\n\t\t\tobjectsCreatedInViews,\n\t\t\tstoredVarsInViews,\n\t\t\tfilesWithoutCheckout: scan.filesWithoutCheckout,\n\t\t\tfilesScanned: scan.filesScanned,\n\t\t\tlinesAdded: scan.linesAdded,\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"State declared in the wrong place is the root of the bugs that make SwiftUI feel unpredictable: a model recreated on every render, a value copied into two views that drift apart, a derived value stored and forgotten. Declaring each piece of state where it is owned keeps the screen a function of its data.","whatGoodLooksLike":"Value state a single view owns is `@State`; a shared model is `@Observable` and injected through the environment or passed down, never recreated in a child; a child that edits a parent''s value takes a `Binding`; a derived value is computed, not stored.","groupSlug":"ios-app-craft","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 212\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Cart per view</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"126.5\" height=\"150.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"16\" y=\"61\" font-size=\"15\">CartView</text>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"76\" width=\"64\" height=\"10\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"132\" width=\"88\" height=\"10\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"148\" width=\"72\" height=\"10\" rx=\"3\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"160.75\" y=\"32.75\" width=\"142.5\" height=\"70.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"176\" y=\"61\" font-size=\"15\">ListView</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"176\" y=\"85\" font-size=\"15\">Cart()</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"160.75\" y=\"112.75\" width=\"142.5\" height=\"70.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"176\" y=\"141\" font-size=\"15\">BadgeView</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"176\" y=\"165\" font-size=\"15\">Cart()</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"208\" font-size=\"15\">Views drift apart</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Cart passed down</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"126.5\" height=\"150.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"352\" y=\"61\" font-size=\"15\">CartView</text>\n  <text class=\"pv-fill-accent pv-mono\" x=\"352\" y=\"85\" font-size=\"15\">Cart()</text>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"132\" width=\"88\" height=\"10\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"148\" width=\"72\" height=\"10\" rx=\"3\"/>\n  <path class=\"pv-stroke-muted\" d=\"M472 68h8\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M488 68l-8-5v10z\"/>\n  <path class=\"pv-stroke-muted\" d=\"M472 148h8\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M488 148l-8-5v10z\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"496.75\" y=\"32.75\" width=\"142.5\" height=\"70.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"512\" y=\"61\" font-size=\"15\">ListView</text>\n  <text class=\"pv-fill-ink pv-mono\" x=\"512\" y=\"85\" font-size=\"15\">cart</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"496.75\" y=\"112.75\" width=\"142.5\" height=\"70.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"512\" y=\"141\" font-size=\"15\">BadgeView</text>\n  <text class=\"pv-fill-ink pv-mono\" x=\"512\" y=\"165\" font-size=\"15\">cart</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"208\" font-size=\"15\">Views agree</text>\n</svg>\n","alt":"Cart per view: ListView and BadgeView each create their own Cart(), so the views drift apart. Cart passed down: CartView creates Cart() once and passes the cart to both child views, so the views agree."},"guide":{"markdown":"## How to do it\n\n- Identify the view that owns each piece of state that your change adds.\n- Use `@State private var` for a value that one view owns and changes, or `@AppStorage` for a setting that must persist.\n- Create a shared model once, in its owner. Pass it to children as an argument or through the environment.\n- When a child changes its parent’s value, give the child a binding. For example, instead of `@State var isOn` in a toggle row, use `@Binding var isOn` and pass `$isOn` from the parent.\n- When a value comes from other state, such as a count or a filtered list, make it a computed property.\n\n## When it does not apply\n\n- Your change adds no state to a SwiftUI view, and no wiring that hands state from one view to another. It adds no `@State`, `@Binding`, `@Environment`, `@Bindable`, `@AppStorage`, `@Observable`, `ObservableObject`, `StateObject` or `ObservedObject`, and no `var` that a view changes.\n- Your change only alters the layout of a view.\n\n## Common mistakes\n\n- Looking at names or at the file a view is in. Neither decides where state belongs. Instead, look at where each value is declared and how it reaches other views.\n- Creating a shared model again in a child, such as `@State private var store = Store()` in a row. The row then has its own store, which can reset or differ from the parent’s. Instead, pass the parent’s store in, or read it with `@Environment`.\n- Copying a parent’s value into the child’s own `@State` and editing the copy. The parent never sees the edit. Instead, take a `@Binding`.\n- Keeping a count in its own `@State` and updating it by hand. One missed update leaves a wrong number on the screen. Instead, compute the count from the list.\n\n## Sources\n\n- [Managing user interface state](https://developer.apple.com/documentation/swiftui/managing-user-interface-state), Apple. Store shared state in the closest common parent of the views that need it, as one source of truth.\n- [State](https://developer.apple.com/documentation/swiftui/state), Apple. Private state in the highest view that needs it reaches editable children through a `Binding`.\n- [Managing model data in your app](https://developer.apple.com/documentation/swiftui/managing-model-data-in-your-app), Apple. Create an observable model once with `@State`, then pass it down or add it to the environment.\n- [Data flow through SwiftUI](https://developer.apple.com/videos/play/wwdc2019/226/), Apple, WWDC 2019. One source of truth avoids the bugs that come from copies that you keep in sync by hand.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Own SwiftUI state at the right level","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":{"skipReason":"the change touches no Swift source file","anyOf":[{"changedPathMatches":["**/*.swift"]}]},"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: each piece of SwiftUI state declared where it is owned — view-local values as `@State`, shared models observed and injected, edits through `Binding`, derived values computed rather than stored.\n\n## The standard\nJudge the state declarations this change adds to SwiftUI views against four rules. (1) A value one view owns and mutates is `@State` (or `@AppStorage` for a persisted setting); a `let` or plain `var` that the view mutates is a lapse. (2) A model shared by more than one view is one object: `@Observable` (or `ObservableObject`) created once by its owner and reached through `@Environment`, `@Bindable` or a passed reference — a child view that creates its own instance of a shared model (`@State private var store = Store()` in a child, `StateObject` for a model the parent already holds) is a lapse. (3) A child that edits a parent''s value takes a `Binding` (`@Binding`, `$value`), not a copy it mutates. (4) A value derivable from other state (a count, a filtered list, a formatted string) is a computed property, not a second stored variable kept in sync by hand. Judge declarations and how they are wired, never naming or file layout.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the change adds no state declaration or state wiring to a SwiftUI view: no added `@State`, `@Binding`, `@Environment`, `@Bindable`, `@AppStorage`, `@Observable`, `ObservableObject`, `StateObject`, `ObservedObject`, or a mutable stored property inside a view type. A change to a view''s layout alone carries no surface.\n\n## Sources\n1. The diff (`work/change/diff.patch`) with `[L<n>]` markers: the added declarations and the wiring that hands state between views (`init` arguments, `.environment(…)`, `$` bindings). It establishes what was declared where. It never establishes what unchanged views hold.\n2. The checkout (`<repositoryRoot>`): whether a model type is `@Observable`, whether a parent already owns an instance a child recreates, and whether a stored value is derivable from other declared state. Read it to place a declaration; it never adds a declaration the diff does not show.\n3. The precomputed leads below these criteria: the declarations it found inside view types, as leads, never conclusions.\nIf the diff is truncated where a view''s declarations are edited, report a collection gap and record no observation.\n\n## Judge\nEnumerate the added state declarations first, then assess the standard.\n- MET: every added declaration follows the four rules — local values `@State`, shared models observed once and injected, edits through bindings, derived values computed. Quote the declaration you accepted as the representative.\n- NOT_MET: a declaration breaks a rule — a mutable stored property in a view without `@State`; a child creating a second instance of a model the parent owns; a copied value the child mutates where a `Binding` was needed; a stored value kept in sync by hand with the state it derives from. Quote the declaration and name the rule.\n- UNDETERMINED: whether a model is shared or owned by this view alone cannot be told from the diff and the checkout; name the type and the fact that would settle it.\nOne observation per review, on the single most consequential declaration when several break a rule.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: a derived value stored, or a mutable `var` that should be `@State` in a leaf view. MAJOR: a shared model recreated in a child (state that silently resets or diverges), or a copied value edited where the parent''s value was meant to change. Identical evidence yields identical severity.\n\n## Grounding\nQuote the `[L<n>]` declaration and, for a shared-model lapse, the parent''s declaration of the same model. Never claim a model is shared without a second view that holds it; never claim a value is derivable without naming the state it derives from.\n\n## Defer\nI/O inside views belongs to `keeps-views-free-of-networking-and-persistence`; concurrency belongs to `uses-structured-concurrency-safely`. Here only: is the state declared where it is owned?","precomputeScript":"// Precompute HINTS for owns-state-at-the-right-level: every state declaration and wiring ADDED in Swift\n// files, placed in its enclosing type. The rules (local values @State, shared models observed once,\n// edits through Binding, derived values computed) are the review''s to apply; the script enumerates\n// the declarations so none is missed and counts a model created inside a view type as a lead.\nimport { sampleNote, scanAddedLines, type SourcePattern } from \"../lib/source-scan.ts\";\nimport type { DiffFile, PullRequestMetadata } from \"../lib/types.ts\";\n\nconst SWIFTUI_VIEW = /\\b(?:View|App|Scene)\\b/u;\n\nconst STATE_DECLARATIONS: readonly SourcePattern[] = [\n\t[\"@State creating an object\", /@State(?:Object)?\\b[^=]*=\\s*[A-Z][A-Za-z0-9_]*\\s*\\(/u],\n\t[\"@State\", /@State\\b/u],\n\t[\"@StateObject\", /@StateObject\\b/u],\n\t[\"@ObservedObject\", /@ObservedObject\\b/u],\n\t[\"@Binding\", /@Binding\\b/u],\n\t[\"@Bindable\", /@Bindable\\b/u],\n\t[\"@Environment\", /@Environment(?:Object)?\\b/u],\n\t[\"@AppStorage\", /@AppStorage\\b/u],\n\t[\"@Query\", /@Query\\b/u],\n\t[\"@Observable type\", /@Observable\\b/u],\n\t[\"ObservableObject type\", /\\bObservableObject\\b/u],\n\t[\"@Published\", /@Published\\b/u],\n\t[\n\t\t\"mutable stored property\",\n\t\t/^\\s*(?:private\\s+|fileprivate\\s+|internal\\s+)?var\\s+[A-Za-z_][A-Za-z0-9_]*\\s*(?::\\s*[^{=\\n]+)?(?:=\\s*[^{\\n]+)?\\s*$/u,\n\t],\n\t[\"environment injection\", /\\.environment(?:Object)?\\s*\\(/u],\n];\n\nexport default async function ownsStateAtTheRightLevel(\n\trepoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n) {\n\tconst scan = await scanAddedLines(repoPath, diffFiles, {\n\t\tlanguages: [\"swift\"],\n\t\tpatterns: STATE_DECLARATIONS,\n\t\tscope: SWIFTUI_VIEW,\n\t\tmaxHints: 60,\n\t});\n\tconst inViews = scan.hints.filter((h) => h.flags.inScope === true);\n\tconst objectsCreatedInViews = inViews.filter(\n\t\t(h) => h.pattern === \"@State creating an object\" || h.pattern === \"@StateObject\",\n\t).length;\n\tconst storedVarsInViews = inViews.filter((h) => h.pattern === \"mutable stored property\").length;\n\tconst directions: string[] = [...sampleNote(scan)];\n\tif (scan.matched > 0) {\n\t\tdirections.push(\n\t\t\t`${scan.matched} state declaration(s) or wiring line(s) added; ${inViews.length} of the listed rows lie inside view types. Walk each against the four rules.`,\n\t\t);\n\t}\n\tif (objectsCreatedInViews > 0) {\n\t\tdirections.push(\n\t\t\t`${objectsCreatedInViews} object(s) created in a view''s @State/@StateObject — check in the checkout whether a parent already owns an instance of the same type.`,\n\t\t);\n\t}\n\tif (storedVarsInViews > 0) {\n\t\tdirections.push(\n\t\t\t`${storedVarsInViews} plain stored var(s) in a view type — a view mutating one of these without @State is a rule-1 lapse; a let-like var the view never mutates is not.`,\n\t\t);\n\t}\n\treturn {\n\t\thints: scan.hints,\n\t\tmetrics: {\n\t\t\tstateDeclarationsAdded: scan.matched,\n\t\t\tstateDeclarationsInViews: inViews.length,\n\t\t\tobjectsCreatedInViews,\n\t\t\tstoredVarsInViews,\n\t\t\tfilesWithoutCheckout: scan.filesWithoutCheckout,\n\t\t\tfilesScanned: scan.filesScanned,\n\t\t\tlinesAdded: scan.linesAdded,\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"State declared in the wrong place is the root of the bugs that make SwiftUI feel unpredictable: a model recreated on every render, a value copied into two views that drift apart, a derived value stored and forgotten. Declaring each piece of state where it is owned keeps the screen a function of its data.","whatGoodLooksLike":"Value state a single view owns is `@State`; a shared model is `@Observable` and injected through the environment or passed down, never recreated in a child; a child that edits a parent''s value takes a `Binding`; a derived value is computed, not stored.","groupSlug":"ios-app-craft","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 212\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Cart per view</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"126.5\" height=\"150.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"16\" y=\"61\" font-size=\"15\">CartView</text>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"76\" width=\"64\" height=\"10\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"132\" width=\"88\" height=\"10\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"148\" width=\"72\" height=\"10\" rx=\"3\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"160.75\" y=\"32.75\" width=\"142.5\" height=\"70.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"176\" y=\"61\" font-size=\"15\">ListView</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"176\" y=\"85\" font-size=\"15\">Cart()</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"160.75\" y=\"112.75\" width=\"142.5\" height=\"70.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"176\" y=\"141\" font-size=\"15\">BadgeView</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"176\" y=\"165\" font-size=\"15\">Cart()</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"208\" font-size=\"15\">Views drift apart</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Cart passed down</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"126.5\" height=\"150.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"352\" y=\"61\" font-size=\"15\">CartView</text>\n  <text class=\"pv-fill-accent pv-mono\" x=\"352\" y=\"85\" font-size=\"15\">Cart()</text>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"132\" width=\"88\" height=\"10\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"148\" width=\"72\" height=\"10\" rx=\"3\"/>\n  <path class=\"pv-stroke-muted\" d=\"M472 68h8\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M488 68l-8-5v10z\"/>\n  <path class=\"pv-stroke-muted\" d=\"M472 148h8\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M488 148l-8-5v10z\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"496.75\" y=\"32.75\" width=\"142.5\" height=\"70.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"512\" y=\"61\" font-size=\"15\">ListView</text>\n  <text class=\"pv-fill-ink pv-mono\" x=\"512\" y=\"85\" font-size=\"15\">cart</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"496.75\" y=\"112.75\" width=\"142.5\" height=\"70.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"512\" y=\"141\" font-size=\"15\">BadgeView</text>\n  <text class=\"pv-fill-ink pv-mono\" x=\"512\" y=\"165\" font-size=\"15\">cart</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"208\" font-size=\"15\">Views agree</text>\n</svg>\n","alt":"Cart per view: ListView and BadgeView each create their own Cart(), so the views drift apart. Cart passed down: CartView creates Cart() once and passes the cart to both child views, so the views agree."},"guide":{"markdown":"## How to do it\n\n- Identify the view that owns each piece of state that your change adds.\n- Use `@State private var` for a value that one view owns and changes, or `@AppStorage` for a setting that must persist.\n- Create a shared model once, in its owner. Pass it to children as an argument or through the environment.\n- When a child changes its parent’s value, give the child a binding. For example, instead of `@State var isOn` in a toggle row, use `@Binding var isOn` and pass `$isOn` from the parent.\n- When a value comes from other state, such as a count or a filtered list, make it a computed property.\n\n## When it does not apply\n\n- Your change adds no state to a SwiftUI view, and no wiring that hands state from one view to another. It adds no `@State`, `@Binding`, `@Environment`, `@Bindable`, `@AppStorage`, `@Observable`, `ObservableObject`, `StateObject` or `ObservedObject`, and no `var` that a view changes.\n- Your change only alters the layout of a view.\n\n## Common mistakes\n\n- Looking at names or at the file a view is in. Neither decides where state belongs. Instead, look at where each value is declared and how it reaches other views.\n- Creating a shared model again in a child, such as `@State private var store = Store()` in a row. The row then has its own store, which can reset or differ from the parent’s. Instead, pass the parent’s store in, or read it with `@Environment`.\n- Copying a parent’s value into the child’s own `@State` and editing the copy. The parent never sees the edit. Instead, take a `@Binding`.\n- Keeping a count in its own `@State` and updating it by hand. One missed update leaves a wrong number on the screen. Instead, compute the count from the list.\n\n## Sources\n\n- [Managing user interface state](https://developer.apple.com/documentation/swiftui/managing-user-interface-state), Apple. Store shared state in the closest common parent of the views that need it, as one source of truth.\n- [State](https://developer.apple.com/documentation/swiftui/state), Apple. Private state in the highest view that needs it reaches editable children through a `Binding`.\n- [Managing model data in your app](https://developer.apple.com/documentation/swiftui/managing-model-data-in-your-app), Apple. Create an observable model once with `@State`, then pass it down or add it to the environment.\n- [Data flow through SwiftUI](https://developer.apple.com/videos/play/wwdc2019/226/), Apple, WWDC 2019. One source of truth avoids the bugs that come from copies that you keep in sync by hand.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Each piece of state lives at the level that owns it"'::jsonb),'v5:cec5f6f454f30385d72871dc23fccd442d0d50ad4bb5a99e999c18b068b2ad90','practice:v3:5d75f904bca59b2eae3a441b8ae0cd55c48db08342c3c63b8562f96bd6344f79');
INSERT INTO _cutover_bundle VALUES('PRACTICE','makes-ui-accessible-by-default','scm.pull_request','{"name":"Make the UI accessible by default","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":{"skipReason":"the change touches no Swift source file","anyOf":[{"changedPathMatches":["**/*.swift"]}]},"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the added SwiftUI interface is usable with a screen reader and at large text sizes — icon-only controls and meaningful images labelled, text sized semantically, layout free of size caps that clip.\n\n## The standard\nJudge the interface code this change adds against a closed list of accessibility facts. (1) An icon-only control — a `Button`, `Toggle`, `Link` or tappable `Image` whose visible content is an `Image(systemName:)` or an asset image with no text — carries an `accessibilityLabel` (or a `Label` with a text title). (2) An image that carries information carries a label. Judge its role in the accessibility element it belongs to: an image whose information that element''s text already gives — artwork beside the title it shows, in a container read as one element by `.accessibilityElement(children: .combine)` — adds nothing for a screen-reader user and is correctly hidden with `.accessibilityHidden(true)`; a label would repeat the text. An image used only for decoration, with no relevant information to convey, may also be hidden. An image that conveys relevant information absent from its accessible text is informative, whatever its source. (3) Text, and an SF Symbol shown with it, use a semantic font (`.font(.body)`, `.headline`, `.title2`, …) or a scaled custom font, not `.font(.system(size: 14))` or a fixed-size custom font — a symbol sized in points stays small when the text around it grows. (4) No text container is capped in height (`.frame(height:)`, `.lineLimit(1)` on body copy) in a way that clips at larger text. (5) A state shown by colour alone (red for error, green for done) is also shown by text, an icon or a trait. Judge added lines only; an existing lapse the change did not touch is not this change''s.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the change adds no interface code: no added `Image`, `Button`, `Toggle`, `Text`, `Label`, `.font(`, `.frame(` or colour-state line inside a SwiftUI view. Added interface lines are the occasion, whether or not they carry a lapse.\n\n## Sources\n1. The diff (`work/change/diff.patch`) with `[L<n>]` markers: the added interface lines and the modifiers attached to them in the same expression. It establishes what each control and text carries. A modifier on the same view chain counts; one on a distant ancestor does not establish a label for an inner icon.\n2. The checkout (`<repositoryRoot>`): the element an image belongs to and the text it holds, which settle whether the image is decorative or informative, and which font overload a custom font uses: `.custom(_:size:)` scales with the body style, `.custom(_:size:relativeTo:)` scales with the style it names, and only `.custom(_:fixedSize:)` stays fixed. Read it to classify; it never adds a control the diff does not show.\n3. The precomputed leads below these criteria: the icon-only controls, fixed-size fonts and height caps it found, as leads, never conclusions.\nIf the diff is truncated where a view body is edited, report a collection gap and record no observation.\n\n## Judge\nEnumerate the added controls, images and text first, then assess the standard.\n- MET: every added icon-only control and informative image is labelled, added text uses a semantic or scaling font, no added cap clips text, and no added state relies on colour alone. Quote a representative labelled control or scaling font.\n- NOT_MET: at least one added item breaks the list — an unlabelled icon-only control, an informative image left unlabelled or hidden, a fixed-size font, a clipping cap, a colour-only state. Quote the line and name the rule.\n- UNDETERMINED: an image whose informative or decorative role the checkout does not settle; name the asset.\nOne observation per review, on the single most consequential lapse when there are several; count the rest in the summary.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: one unlabelled icon or one fixed-size font. MAJOR: a primary action of the screen unreachable by screen reader, or a screen whose main text cannot scale. Identical evidence yields identical severity.\n\n## Grounding\nQuote the `[L<n>]` line of the control, image, font or cap. Never claim a label is missing without reading the whole view chain the control sits in; never call an image informative without naming what it shows that no text in its element gives; never claim clipping from a `.frame` on a non-text container.\n\n## Defer\nLocalisation of the strings belongs to no practice here; magic numbers in layout to none. Here only: can everyone use what was added?","precomputeScript":"// Precompute HINTS for makes-ui-accessible-by-default: the interface lines ADDED in Swift files that the\n// closed list in the criteria asks about — icon-only controls, images, fixed-size fonts, height caps,\n// colour-only state — and the accessibility modifiers added alongside them. The review reads the view\n// chain; the script counts what there is to read and how many labels arrived with it.\nimport { countLabel, sampleNote, scanAddedLines, type SourcePattern } from \"../lib/source-scan.ts\";\nimport type { DiffFile, PullRequestMetadata } from \"../lib/types.ts\";\n\n// Font.custom(_:size:) scales with the body style, custom(_:size:relativeTo:) with the style it names;\n// only custom(_:fixedSize:) does not scale. Font.system(size:) is fixed at the size it is given.\nconst INTERFACE_LINES: readonly SourcePattern[] = [\n\t[\n\t\t\"accessibility modifier\",\n\t\t/\\.accessibility(?:Label|Hint|Hidden|AddTraits|Value|Identifier)\\s*\\(/u,\n\t],\n\t[\"Label with text\", /\\bLabel\\s*\\(\\s*\"/u],\n\t[\"Image(systemName:)\", /\\bImage\\s*\\(\\s*systemName:/u],\n\t[\"Image(asset)\", /\\bImage\\s*\\(\\s*(?:\"|decorative:|[a-z]\\w*\\.)/u],\n\t[\"fixed-size custom font\", /\\.custom\\s*\\([^)]*\\bfixedSize:/u],\n\t[\"system font with a point size\", /\\.system\\s*\\(\\s*size:/u],\n\t[\"scaled custom font\", /\\.custom\\s*\\([^)]*\\bsize:/u],\n\t[\n\t\t\"semantic font\",\n\t\t/\\.font\\s*\\(\\s*\\.(?:largeTitle|title[23]?|headline|subheadline|body|callout|footnote|caption2?)\\b/u,\n\t],\n\t[\"height cap\", /\\.frame\\s*\\([^)]*\\bheight:\\s*\\d/u],\n\t[\"lineLimit\", /\\.lineLimit\\s*\\(\\s*\\d/u],\n\t[\n\t\t\"colour by state\",\n\t\t/\\.foregroundStyle\\s*\\(\\s*[^)]*\\?\\s*\\.(?:red|green|orange|yellow)|\\.foregroundColor\\s*\\(\\s*[^)]*\\?\\s*\\.(?:red|green|orange|yellow)/u,\n\t],\n\t[\"Button\", /\\bButton\\s*[({]/u],\n\t[\"Toggle\", /\\bToggle\\s*\\(/u],\n];\n\nexport default async function makesUiAccessibleByDefault(\n\trepoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n) {\n\tconst scan = await scanAddedLines(repoPath, diffFiles, {\n\t\tlanguages: [\"swift\"],\n\t\tpatterns: INTERFACE_LINES,\n\t\tmaxHints: 60,\n\t});\n\tconst count = (label: string) => countLabel(scan, label);\n\tconst metrics = {\n\t\tinterfaceLinesAdded: scan.matched,\n\t\tsymbolImages: count(\"Image(systemName:)\"),\n\t\tassetImages: count(\"Image(asset)\"),\n\t\taccessibilityModifiers: count(\"accessibility modifier\"),\n\t\tfixedSizeCustomFonts: count(\"fixed-size custom font\"),\n\t\tsystemFontsWithPointSize: count(\"system font with a point size\"),\n\t\tscaledCustomFonts: count(\"scaled custom font\"),\n\t\tsemanticFonts: count(\"semantic font\"),\n\t\theightCaps: count(\"height cap\"),\n\t\tcolourByState: count(\"colour by state\"),\n\t\tfilesWithoutCheckout: scan.filesWithoutCheckout,\n\t\tfilesScanned: scan.filesScanned,\n\t\tlinesAdded: scan.linesAdded,\n\t};\n\tconst directions: string[] = [...sampleNote(scan)];\n\tif (metrics.symbolImages + metrics.assetImages > 0) {\n\t\tdirections.push(\n\t\t\t`${metrics.symbolImages + metrics.assetImages} image(s) added against ${metrics.accessibilityModifiers} accessibility modifier(s) — for each image inside a Button, Toggle or tap gesture, read the whole view chain for a label or a Label title.`,\n\t\t);\n\t}\n\tif (metrics.fixedSizeCustomFonts > 0) {\n\t\tdirections.push(\n\t\t\t`${metrics.fixedSizeCustomFonts} custom font(s) with fixedSize: added — these do not scale with the user''s text size.`,\n\t\t);\n\t}\n\tif (metrics.systemFontsWithPointSize > 0) {\n\t\tdirections.push(\n\t\t\t`${metrics.systemFontsWithPointSize} system font(s) with a point size added — fixed unless the size itself scales (a @ScaledMetric value); read where each size comes from. A custom font given size: scales with the body style and is not fixed.`,\n\t\t);\n\t}\n\tif (metrics.heightCaps > 0) {\n\t\tdirections.push(\n\t\t\t`${metrics.heightCaps} height cap(s) added — a cap clips only when the container holds text.`,\n\t\t);\n\t}\n\treturn { hints: scan.hints, metrics, directions };\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A control a screen reader cannot name, a label that cannot grow with the user''s text size, an image that says nothing — each locks a group of people out of the screen, and each is a line the author could have written when the view was made. Accessibility added later is the expensive kind.","whatGoodLooksLike":"Every icon-only control and meaningful image has a label; text uses semantic fonts so Dynamic Type works; nothing is fixed to a size that clips at larger text; colour is never the only signal.","groupSlug":"ios-app-craft","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 180\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Icon with no label</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"110.5\" height=\"118.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <rect class=\"pv-fill-muted\" x=\"40\" y=\"48\" width=\"32\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"70\" width=\"80\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"82\" width=\"56\" height=\"6\" rx=\"3\"/>\n  <circle class=\"pv-fill-surface pv-stroke-ink\" cx=\"56\" cy=\"120\" r=\"15.25\" stroke-width=\"1.5\"/>\n  <path class=\"pv-stroke-ink\" d=\"M52 117h-3v10h14v-10h-3M56 122v-11M52.5 114.5 56 111l3.5 3.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <path class=\"pv-stroke-muted\" d=\"M120 120h8\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M136 120l-8-5v10z\"/>\n  <text class=\"pv-fill-ink\" x=\"144\" y=\"81\" font-size=\"15\">Screen reader says</text>\n  <path class=\"pv-fill-surface pv-stroke-muted\" d=\"M156.75 96.75H291.25A12 12 0 0 1 303.25 108.75V131.25A12 12 0 0 1 291.25 143.25H144.75V108.75A12 12 0 0 1 156.75 96.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"160\" y=\"125\" font-size=\"15\">“Button”</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"176\" font-size=\"15\">User guesses</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Icon with a label</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"110.5\" height=\"118.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <rect class=\"pv-fill-muted\" x=\"376\" y=\"48\" width=\"32\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"70\" width=\"80\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"82\" width=\"56\" height=\"6\" rx=\"3\"/>\n  <circle class=\"pv-fill-surface pv-stroke-ink\" cx=\"392\" cy=\"120\" r=\"15.25\" stroke-width=\"1.5\"/>\n  <path class=\"pv-stroke-ink\" d=\"M388 117h-3v10h14v-10h-3M392 122v-11M388.5 114.5 392 111l3.5 3.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <path class=\"pv-stroke-muted\" d=\"M456 120h8\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M472 120l-8-5v10z\"/>\n  <text class=\"pv-fill-ink\" x=\"480\" y=\"81\" font-size=\"15\">Screen reader says</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M492.75 96.75H627.25A12 12 0 0 1 639.25 108.75V131.25A12 12 0 0 1 627.25 143.25H480.75V108.75A12 12 0 0 1 492.75 96.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"496\" y=\"125\" font-size=\"15\">“Share, button”</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"176\" font-size=\"15\">User can share</text>\n</svg>\n","alt":"For an icon with no label, the screen reader says “Button”, so the user guesses. For an icon with a label, the screen reader says “Share, button”, so the user can share."},"guide":{"markdown":"## How to do it\n\n- Give each control that shows only an icon a label that says what it does. For example, instead of a button that holds only `Image(systemName: \"trash\")`, add `.accessibilityLabel(\"Delete\")` to it, or use `Label(\"Delete\", systemImage: \"trash\")`.\n- Label an image that carries information that the nearby text does not give.\n- Use `.accessibilityHidden(true)` for an image that only decorates, or whose meaning the text already gives.\n- Use a text style, such as `.font(.body)` or `.font(.headline)`, for text and for any SF Symbol beside it. SF Symbols are Apple’s built-in icons. A text style grows with the text size that the person chooses.\n- Leave room for text to grow. A `.frame(height:)` or `.lineLimit(1)` on body text is a problem only when it cuts the text off at larger sizes.\n- When color shows a state, such as red for an error, also show the state with text or an icon.\n\n## When it does not apply\n\n- Your change adds no interface code to a SwiftUI view. It adds no `Image`, `Button`, `Toggle`, `Text` or `Label`. It adds no `.font(` or `.frame(` line, and no state shown by color.\n\nIt still applies when every interface line you add already follows this practice.\n\n## Common mistakes\n\n- Treating every `.frame(height:)` as a problem. A fixed height on an image or a shape is fine. Only a height cap on text can clip it at a larger text size.\n- Putting `.accessibilityLabel` on a stack around a row of icon buttons. That label does not name the icons inside it. Instead, put a label on each control.\n- Sizing an SF Symbol in points, such as `.font(.system(size: 14))`, next to text that scales. The symbol stays small when the text grows. Instead, give it the text style of the text.\n- Choosing `.custom(_:fixedSize:)` for a custom font. It is the only custom font call that never grows. Instead, use `.custom(_:size:relativeTo:)` with the text style that the text replaces.\n\n## Sources\n\n- [VoiceOver](https://developer.apple.com/design/human-interface-guidelines/voiceover), Apple Human Interface Guidelines. Give every key control a label, describe meaningful images, and hide images that only decorate.\n- [Typography: Supporting Dynamic Type](https://developer.apple.com/design/human-interface-guidelines/typography#Supporting-Dynamic-Type), Apple Human Interface Guidelines. Layouts adapt to every text size, icons grow with the text, and text truncation stays to a minimum.\n- [Applying custom fonts to text](https://developer.apple.com/documentation/swiftui/applying-custom-fonts-to-text), Apple SwiftUI documentation. A custom font from `custom(_:size:)` scales with the body style, and `relativeTo` picks the style to scale with.\n- [Accessibility](https://developer.apple.com/design/human-interface-guidelines/accessibility), Apple Human Interface Guidelines. Convey information with more than color alone, and let people enlarge the text.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Make the UI accessible by default","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":{"skipReason":"the change touches no Swift source file","anyOf":[{"changedPathMatches":["**/*.swift"]}]},"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the added SwiftUI interface is usable with a screen reader and at large text sizes — icon-only controls and meaningful images labelled, text sized semantically, layout free of size caps that clip.\n\n## The standard\nJudge the interface code this change adds against a closed list of accessibility facts. (1) An icon-only control — a `Button`, `Toggle`, `Link` or tappable `Image` whose visible content is an `Image(systemName:)` or an asset image with no text — carries an `accessibilityLabel` (or a `Label` with a text title). (2) An image that carries information carries a label. Judge its role in the accessibility element it belongs to: an image whose information that element''s text already gives — artwork beside the title it shows, in a container read as one element by `.accessibilityElement(children: .combine)` — adds nothing for a screen-reader user and is correctly hidden with `.accessibilityHidden(true)`; a label would repeat the text. An image used only for decoration, with no relevant information to convey, may also be hidden. An image that conveys relevant information absent from its accessible text is informative, whatever its source. (3) Text, and an SF Symbol shown with it, use a semantic font (`.font(.body)`, `.headline`, `.title2`, …) or a scaled custom font, not `.font(.system(size: 14))` or a fixed-size custom font — a symbol sized in points stays small when the text around it grows. (4) No text container is capped in height (`.frame(height:)`, `.lineLimit(1)` on body copy) in a way that clips at larger text. (5) A state shown by colour alone (red for error, green for done) is also shown by text, an icon or a trait. Judge added lines only; an existing lapse the change did not touch is not this change''s.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the change adds no interface code: no added `Image`, `Button`, `Toggle`, `Text`, `Label`, `.font(`, `.frame(` or colour-state line inside a SwiftUI view. Added interface lines are the occasion, whether or not they carry a lapse.\n\n## Sources\n1. The diff (`work/change/diff.patch`) with `[L<n>]` markers: the added interface lines and the modifiers attached to them in the same expression. It establishes what each control and text carries. A modifier on the same view chain counts; one on a distant ancestor does not establish a label for an inner icon.\n2. The checkout (`<repositoryRoot>`): the element an image belongs to and the text it holds, which settle whether the image is decorative or informative, and which font overload a custom font uses: `.custom(_:size:)` scales with the body style, `.custom(_:size:relativeTo:)` scales with the style it names, and only `.custom(_:fixedSize:)` stays fixed. Read it to classify; it never adds a control the diff does not show.\n3. The precomputed leads below these criteria: the icon-only controls, fixed-size fonts and height caps it found, as leads, never conclusions.\nIf the diff is truncated where a view body is edited, report a collection gap and record no observation.\n\n## Judge\nEnumerate the added controls, images and text first, then assess the standard.\n- MET: every added icon-only control and informative image is labelled, added text uses a semantic or scaling font, no added cap clips text, and no added state relies on colour alone. Quote a representative labelled control or scaling font.\n- NOT_MET: at least one added item breaks the list — an unlabelled icon-only control, an informative image left unlabelled or hidden, a fixed-size font, a clipping cap, a colour-only state. Quote the line and name the rule.\n- UNDETERMINED: an image whose informative or decorative role the checkout does not settle; name the asset.\nOne observation per review, on the single most consequential lapse when there are several; count the rest in the summary.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: one unlabelled icon or one fixed-size font. MAJOR: a primary action of the screen unreachable by screen reader, or a screen whose main text cannot scale. Identical evidence yields identical severity.\n\n## Grounding\nQuote the `[L<n>]` line of the control, image, font or cap. Never claim a label is missing without reading the whole view chain the control sits in; never call an image informative without naming what it shows that no text in its element gives; never claim clipping from a `.frame` on a non-text container.\n\n## Defer\nLocalisation of the strings belongs to no practice here; magic numbers in layout to none. Here only: can everyone use what was added?","precomputeScript":"// Precompute HINTS for makes-ui-accessible-by-default: the interface lines ADDED in Swift files that the\n// closed list in the criteria asks about — icon-only controls, images, fixed-size fonts, height caps,\n// colour-only state — and the accessibility modifiers added alongside them. The review reads the view\n// chain; the script counts what there is to read and how many labels arrived with it.\nimport { countLabel, sampleNote, scanAddedLines, type SourcePattern } from \"../lib/source-scan.ts\";\nimport type { DiffFile, PullRequestMetadata } from \"../lib/types.ts\";\n\n// Font.custom(_:size:) scales with the body style, custom(_:size:relativeTo:) with the style it names;\n// only custom(_:fixedSize:) does not scale. Font.system(size:) is fixed at the size it is given.\nconst INTERFACE_LINES: readonly SourcePattern[] = [\n\t[\n\t\t\"accessibility modifier\",\n\t\t/\\.accessibility(?:Label|Hint|Hidden|AddTraits|Value|Identifier)\\s*\\(/u,\n\t],\n\t[\"Label with text\", /\\bLabel\\s*\\(\\s*\"/u],\n\t[\"Image(systemName:)\", /\\bImage\\s*\\(\\s*systemName:/u],\n\t[\"Image(asset)\", /\\bImage\\s*\\(\\s*(?:\"|decorative:|[a-z]\\w*\\.)/u],\n\t[\"fixed-size custom font\", /\\.custom\\s*\\([^)]*\\bfixedSize:/u],\n\t[\"system font with a point size\", /\\.system\\s*\\(\\s*size:/u],\n\t[\"scaled custom font\", /\\.custom\\s*\\([^)]*\\bsize:/u],\n\t[\n\t\t\"semantic font\",\n\t\t/\\.font\\s*\\(\\s*\\.(?:largeTitle|title[23]?|headline|subheadline|body|callout|footnote|caption2?)\\b/u,\n\t],\n\t[\"height cap\", /\\.frame\\s*\\([^)]*\\bheight:\\s*\\d/u],\n\t[\"lineLimit\", /\\.lineLimit\\s*\\(\\s*\\d/u],\n\t[\n\t\t\"colour by state\",\n\t\t/\\.foregroundStyle\\s*\\(\\s*[^)]*\\?\\s*\\.(?:red|green|orange|yellow)|\\.foregroundColor\\s*\\(\\s*[^)]*\\?\\s*\\.(?:red|green|orange|yellow)/u,\n\t],\n\t[\"Button\", /\\bButton\\s*[({]/u],\n\t[\"Toggle\", /\\bToggle\\s*\\(/u],\n];\n\nexport default async function makesUiAccessibleByDefault(\n\trepoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n) {\n\tconst scan = await scanAddedLines(repoPath, diffFiles, {\n\t\tlanguages: [\"swift\"],\n\t\tpatterns: INTERFACE_LINES,\n\t\tmaxHints: 60,\n\t});\n\tconst count = (label: string) => countLabel(scan, label);\n\tconst metrics = {\n\t\tinterfaceLinesAdded: scan.matched,\n\t\tsymbolImages: count(\"Image(systemName:)\"),\n\t\tassetImages: count(\"Image(asset)\"),\n\t\taccessibilityModifiers: count(\"accessibility modifier\"),\n\t\tfixedSizeCustomFonts: count(\"fixed-size custom font\"),\n\t\tsystemFontsWithPointSize: count(\"system font with a point size\"),\n\t\tscaledCustomFonts: count(\"scaled custom font\"),\n\t\tsemanticFonts: count(\"semantic font\"),\n\t\theightCaps: count(\"height cap\"),\n\t\tcolourByState: count(\"colour by state\"),\n\t\tfilesWithoutCheckout: scan.filesWithoutCheckout,\n\t\tfilesScanned: scan.filesScanned,\n\t\tlinesAdded: scan.linesAdded,\n\t};\n\tconst directions: string[] = [...sampleNote(scan)];\n\tif (metrics.symbolImages + metrics.assetImages > 0) {\n\t\tdirections.push(\n\t\t\t`${metrics.symbolImages + metrics.assetImages} image(s) added against ${metrics.accessibilityModifiers} accessibility modifier(s) — for each image inside a Button, Toggle or tap gesture, read the whole view chain for a label or a Label title.`,\n\t\t);\n\t}\n\tif (metrics.fixedSizeCustomFonts > 0) {\n\t\tdirections.push(\n\t\t\t`${metrics.fixedSizeCustomFonts} custom font(s) with fixedSize: added — these do not scale with the user''s text size.`,\n\t\t);\n\t}\n\tif (metrics.systemFontsWithPointSize > 0) {\n\t\tdirections.push(\n\t\t\t`${metrics.systemFontsWithPointSize} system font(s) with a point size added — fixed unless the size itself scales (a @ScaledMetric value); read where each size comes from. A custom font given size: scales with the body style and is not fixed.`,\n\t\t);\n\t}\n\tif (metrics.heightCaps > 0) {\n\t\tdirections.push(\n\t\t\t`${metrics.heightCaps} height cap(s) added — a cap clips only when the container holds text.`,\n\t\t);\n\t}\n\treturn { hints: scan.hints, metrics, directions };\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A control a screen reader cannot name, a label that cannot grow with the user''s text size, an image that says nothing — each locks a group of people out of the screen, and each is a line the author could have written when the view was made. Accessibility added later is the expensive kind.","whatGoodLooksLike":"Every icon-only control and meaningful image has a label; text uses semantic fonts so Dynamic Type works; nothing is fixed to a size that clips at larger text; colour is never the only signal.","groupSlug":"ios-app-craft","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 180\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Icon with no label</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"110.5\" height=\"118.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <rect class=\"pv-fill-muted\" x=\"40\" y=\"48\" width=\"32\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"70\" width=\"80\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"82\" width=\"56\" height=\"6\" rx=\"3\"/>\n  <circle class=\"pv-fill-surface pv-stroke-ink\" cx=\"56\" cy=\"120\" r=\"15.25\" stroke-width=\"1.5\"/>\n  <path class=\"pv-stroke-ink\" d=\"M52 117h-3v10h14v-10h-3M56 122v-11M52.5 114.5 56 111l3.5 3.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <path class=\"pv-stroke-muted\" d=\"M120 120h8\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M136 120l-8-5v10z\"/>\n  <text class=\"pv-fill-ink\" x=\"144\" y=\"81\" font-size=\"15\">Screen reader says</text>\n  <path class=\"pv-fill-surface pv-stroke-muted\" d=\"M156.75 96.75H291.25A12 12 0 0 1 303.25 108.75V131.25A12 12 0 0 1 291.25 143.25H144.75V108.75A12 12 0 0 1 156.75 96.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"160\" y=\"125\" font-size=\"15\">“Button”</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"176\" font-size=\"15\">User guesses</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Icon with a label</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"110.5\" height=\"118.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <rect class=\"pv-fill-muted\" x=\"376\" y=\"48\" width=\"32\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"70\" width=\"80\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"82\" width=\"56\" height=\"6\" rx=\"3\"/>\n  <circle class=\"pv-fill-surface pv-stroke-ink\" cx=\"392\" cy=\"120\" r=\"15.25\" stroke-width=\"1.5\"/>\n  <path class=\"pv-stroke-ink\" d=\"M388 117h-3v10h14v-10h-3M392 122v-11M388.5 114.5 392 111l3.5 3.5\" fill=\"none\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n  <path class=\"pv-stroke-muted\" d=\"M456 120h8\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M472 120l-8-5v10z\"/>\n  <text class=\"pv-fill-ink\" x=\"480\" y=\"81\" font-size=\"15\">Screen reader says</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M492.75 96.75H627.25A12 12 0 0 1 639.25 108.75V131.25A12 12 0 0 1 627.25 143.25H480.75V108.75A12 12 0 0 1 492.75 96.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"496\" y=\"125\" font-size=\"15\">“Share, button”</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"176\" font-size=\"15\">User can share</text>\n</svg>\n","alt":"For an icon with no label, the screen reader says “Button”, so the user guesses. For an icon with a label, the screen reader says “Share, button”, so the user can share."},"guide":{"markdown":"## How to do it\n\n- Give each control that shows only an icon a label that says what it does. For example, instead of a button that holds only `Image(systemName: \"trash\")`, add `.accessibilityLabel(\"Delete\")` to it, or use `Label(\"Delete\", systemImage: \"trash\")`.\n- Label an image that carries information that the nearby text does not give.\n- Use `.accessibilityHidden(true)` for an image that only decorates, or whose meaning the text already gives.\n- Use a text style, such as `.font(.body)` or `.font(.headline)`, for text and for any SF Symbol beside it. SF Symbols are Apple’s built-in icons. A text style grows with the text size that the person chooses.\n- Leave room for text to grow. A `.frame(height:)` or `.lineLimit(1)` on body text is a problem only when it cuts the text off at larger sizes.\n- When color shows a state, such as red for an error, also show the state with text or an icon.\n\n## When it does not apply\n\n- Your change adds no interface code to a SwiftUI view. It adds no `Image`, `Button`, `Toggle`, `Text` or `Label`. It adds no `.font(` or `.frame(` line, and no state shown by color.\n\nIt still applies when every interface line you add already follows this practice.\n\n## Common mistakes\n\n- Treating every `.frame(height:)` as a problem. A fixed height on an image or a shape is fine. Only a height cap on text can clip it at a larger text size.\n- Putting `.accessibilityLabel` on a stack around a row of icon buttons. That label does not name the icons inside it. Instead, put a label on each control.\n- Sizing an SF Symbol in points, such as `.font(.system(size: 14))`, next to text that scales. The symbol stays small when the text grows. Instead, give it the text style of the text.\n- Choosing `.custom(_:fixedSize:)` for a custom font. It is the only custom font call that never grows. Instead, use `.custom(_:size:relativeTo:)` with the text style that the text replaces.\n\n## Sources\n\n- [VoiceOver](https://developer.apple.com/design/human-interface-guidelines/voiceover), Apple Human Interface Guidelines. Give every key control a label, describe meaningful images, and hide images that only decorate.\n- [Typography: Supporting Dynamic Type](https://developer.apple.com/design/human-interface-guidelines/typography#Supporting-Dynamic-Type), Apple Human Interface Guidelines. Layouts adapt to every text size, icons grow with the text, and text truncation stays to a minimum.\n- [Applying custom fonts to text](https://developer.apple.com/documentation/swiftui/applying-custom-fonts-to-text), Apple SwiftUI documentation. A custom font from `custom(_:size:)` scales with the body style, and `relativeTo` picks the style to scale with.\n- [Accessibility](https://developer.apple.com/design/human-interface-guidelines/accessibility), Apple Human Interface Guidelines. Convey information with more than color alone, and let people enlarge the text.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Every control carries a label and text scales with the user"'::jsonb),'v5:ce2fbd511be0e82994871736f45f63fe159420ea8672ba6af43ca2b198af4a31','practice:v3:20c54b6157ca61add42deaf9c38ceda40b14ca46fb3e4dd66ef3144a624e5e06');
INSERT INTO _cutover_bundle VALUES('PRACTICE','uses-structured-concurrency-safely','scm.pull_request','{"name":"Use structured concurrency safely","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":{"skipReason":"the change touches no Swift source file","anyOf":[{"changedPathMatches":["**/*.swift"]}]},"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: async work tied to the lifetime that owns it, UI state mutated on the main actor, and no fire-and-forget task where structure was available.\n\n## The standard\nJudge the concurrency code this change adds against a closed list. (1) View-lifecycle work belongs in `.task { }` or an equivalent observed cancellation lifecycle. A `Task { }` in a synchronous button action is a native bridge to asynchronous work, not a defect by itself. Judge whether its lifetime and cancellation fit the operation: work that must stop with the view has an effective cancellation path, while a user-initiated operation can legitimately complete after the view disappears. A stored handle or a written reason can establish intent but is not mandatory when the captured code already establishes the lifecycle. (2) State the UI reads is mutated on the main actor: a type that holds view state is isolated to the main actor — by `@MainActor`, by the target''s default actor isolation or by what it inherits, including SwiftUI `View` when the project''s SDK declares it main-actor isolated — or the mutation is `await MainActor.run`; a mutation of `@Published`/`@Observable` UI state from a background context is a lapse. (3) Detached work and dispatch queues have an evidenced need for their independent execution or scheduling; the captured code may establish that need without a redundant comment. (4) A result needed by the operation is consumed; a task can perform a side effect without its handle being stored. Judge added lines; existing concurrency the change did not touch is not this change''s.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the change adds no concurrency: no added `async`, `await`, `Task`, `.task`, `@MainActor`, `MainActor.run`, `Task.detached`, `DispatchQueue` or actor declaration. Added concurrency is the occasion, whether or not it carries a lapse.\n\n## Sources\n1. The diff (`work/change/diff.patch`) with `[L<n>]` markers: the added concurrency constructs and where they sit (a view modifier, a model method, a service). It establishes what was written. It never establishes the actor a type is isolated to when that declaration is outside the diff.\n2. The checkout (`<repositoryRoot>`): the declaration of the type a mutation lands in and the target''s default actor isolation, and whether a `Task` handle is stored. Read it to place a construct; it never adds one.\n3. The precomputed leads below these criteria: the `Task {` blocks, `.onAppear` with async work, detached tasks and dispatch queues it found, as leads, never conclusions.\nIf the diff is truncated where async code is added, report a collection gap and record no observation.\n\n## Judge\nEnumerate the added constructs first, then assess the standard.\n- MET: every added construct follows the list — view-lifecycle work cancelled appropriately, user-triggered async work with an appropriate lifetime, UI state isolated correctly, and needed results consumed. Quote a representative construct.\n- NOT_MET: an added construct breaks the list — view-lifecycle work that can outlive its owner without appropriate cancellation, UI state mutated off the main actor, detached work or a dispatch queue with no evidenced need, an unconsumed result needed by the operation. Quote the line and name the rule.\n- UNDETERMINED: an added line mutates UI state from an async context and the isolation of its type is in neither the diff nor the checkout; name the type. An added call into an unchanged method is judged as a call, never by what that method does inside.\nOne observation per review, on the single most consequential lapse when there are several.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: a lifecycle mismatch on a short local operation. MAJOR: a network request in an uncancelled task that writes view state, or UI state mutated from a background context. Identical evidence yields identical severity.\n\n## Grounding\nQuote the `[L<n>]` construct and, for an actor lapse, the declaration of the type mutated. Never claim a mutation is off the main actor without the type''s isolation; never claim a task is fire-and-forget when a handle is stored in the same hunk.\n\n## Defer\nSwallowed errors in async code belong to `handles-errors-instead-of-swallowing-them`; crash-shaped constructs to `avoids-unsafe-panics-and-chosen-crashes`. Here only: is the concurrency structured?","precomputeScript":"// Precompute HINTS for uses-structured-concurrency-safely: every concurrency construct ADDED in Swift\n// files, placed in its enclosing type, and the lines of the project files that mention a default actor\n// isolation. Whether the work must outlive the view, and whether a mutation lands on the main actor, is\n// the review''s to decide from the checkout.\nimport { readFile } from \"node:fs/promises\";\nimport path from \"node:path\";\n\nimport { globFilesSync } from \"../lib/files.ts\";\nimport { countLabel, sampleNote, scanAddedLines, type SourcePattern } from \"../lib/source-scan.ts\";\nimport type { DiffFile, PullRequestMetadata } from \"../lib/types.ts\";\n\nconst SWIFTUI_VIEW = /\\b(?:View|App|Scene)\\b/u;\n\nconst CONCURRENCY: readonly SourcePattern[] = [\n\t[\"Task.detached\", /\\bTask\\.detached\\b/u],\n\t[\"stored task handle\", /(?:let|var)\\s+\\w+\\s*(?::\\s*Task<[^>]*>)?\\s*=\\s*Task\\s*[{(]/u],\n\t[\"Task { }\", /\\bTask\\s*(?:\\(priority:[^)]*\\))?\\s*\\{/u],\n\t[\".task modifier\", /\\.task\\s*(?:\\(id:[^)]*\\))?\\s*\\{/u],\n\t[\".onAppear\", /\\.onAppear\\s*\\{/u],\n\t[\"DispatchQueue\", /\\bDispatchQueue\\b/u],\n\t[\"@MainActor\", /@MainActor\\b/u],\n\t[\"MainActor.run\", /\\bMainActor\\.run\\b/u],\n\t[\"actor declaration\", /^\\s*(?:\\w+\\s+)*actor\\s+\\w+/u],\n\t[\"async function\", /\\bfunc\\s+\\w+[^{]*\\basync\\b/u],\n\t[\"await\", /\\bawait\\b/u],\n];\n\n/** Text naming a default actor isolation: an Xcode build setting or a SwiftPM target setting. */\nconst DEFAULT_ISOLATION = /SWIFT_DEFAULT_ACTOR_ISOLATION\\s*[:=]|defaultIsolation\\s*\\(/u;\n\n/**\n * Lines of the first few project files that mention a default actor isolation, as `path:line text`. The\n * setting belongs to one target or SwiftPM module and build configuration, and a line may be commented\n * out, so a line found here is a place to read, not the isolation of any changed type.\n */\nasync function defaultIsolationLines(repoPath: string): Promise<string[]> {\n\tlet files: string[];\n\ttry {\n\t\tfiles = [\n\t\t\t...globFilesSync(\"**/project.yml\", repoPath),\n\t\t\t...globFilesSync(\"**/project.yaml\", repoPath),\n\t\t\t...globFilesSync(\"**/*.xcodeproj/project.pbxproj\", repoPath),\n\t\t\t...globFilesSync(\"**/Package.swift\", repoPath),\n\t\t].filter((f) => !/(?:^|\\/)(?:Pods|\\.build|DerivedData|Carthage)\\//u.test(f));\n\t} catch {\n\t\treturn [];\n\t}\n\tconst found: string[] = [];\n\tfor (const file of files.slice(0, 20)) {\n\t\tlet text: string;\n\t\ttry {\n\t\t\ttext = await readFile(path.join(repoPath, file), \"utf8\");\n\t\t} catch {\n\t\t\tcontinue;\n\t\t}\n\t\tfor (const [index, line] of text.split(/\\r?\\n/u).entries()) {\n\t\t\tif (DEFAULT_ISOLATION.test(line)) {\n\t\t\t\tfound.push(`${file}:${String(index + 1)} ${line.trim().slice(0, 120)}`);\n\t\t\t}\n\t\t}\n\t}\n\treturn found.slice(0, 10);\n}\n\nexport default async function usesStructuredConcurrencySafely(\n\trepoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n) {\n\tconst scan = await scanAddedLines(repoPath, diffFiles, {\n\t\tlanguages: [\"swift\"],\n\t\tpatterns: CONCURRENCY,\n\t\tscope: SWIFTUI_VIEW,\n\t\tmaxHints: 60,\n\t});\n\tconst count = (label: string) => countLabel(scan, label);\n\tconst unstructuredInViews = scan.hints.filter(\n\t\t(h) => h.pattern === \"Task { }\" && h.flags.inScope === true,\n\t).length;\n\tconst metrics = {\n\t\tconcurrencyLinesAdded: scan.matched,\n\t\ttaskBlocks: count(\"Task { }\"),\n\t\ttaskBlocksInListedViewRows: unstructuredInViews,\n\t\ttaskModifiers: count(\".task modifier\"),\n\t\tdetachedTasks: count(\"Task.detached\"),\n\t\tdispatchQueues: count(\"DispatchQueue\"),\n\t\tmainActorMarks: count(\"@MainActor\") + count(\"MainActor.run\"),\n\t\tfilesWithoutCheckout: scan.filesWithoutCheckout,\n\t\tfilesScanned: scan.filesScanned,\n\t\tlinesAdded: scan.linesAdded,\n\t};\n\tconst directions: string[] = [...sampleNote(scan)];\n\tif (unstructuredInViews > 0) {\n\t\tdirections.push(\n\t\t\t`${unstructuredInViews} Task { } block(s) added inside view types — read the lifetime each needs: work tied to the view belongs to a lifecycle that cancels it, while a Task started from a user action may legitimately finish after the view is gone.`,\n\t\t);\n\t}\n\tif (metrics.detachedTasks + metrics.dispatchQueues > 0) {\n\t\tdirections.push(\n\t\t\t`${metrics.detachedTasks} detached task(s) and ${metrics.dispatchQueues} dispatch queue use(s) — read whether the code shows a need for independent execution or scheduling; no written reason is required when it does.`,\n\t\t);\n\t}\n\tif (scan.matched > 0) {\n\t\tconst settings = await defaultIsolationLines(repoPath);\n\t\tdirections.push(\n\t\t\tsettings.length > 0\n\t\t\t\t? `Default actor isolation text in project files: ${settings.join(\"; \")}. Each applies only to its own target or SwiftPM module and build configuration, and a commented line sets nothing: read which target and configuration build the changed file before relying on any of them.`\n\t\t\t\t: \"No default actor isolation text was found in the project files read, which leaves the module''s default unknown rather than nonisolated.\",\n\t\t\t\"A type''s isolation comes from its declaration, its module''s setting or what it inherits. A missing @MainActor on an added line does not by itself put a mutation off the main actor. Check the SDK before relying on inherited SwiftUI View isolation. Swallowed failures belong to handles-errors-instead-of-swallowing-them, not this practice.\",\n\t\t);\n\t}\n\treturn { hints: scan.hints, metrics, directions };\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"An unstructured task that outlives its view, UI state mutated off the main actor, a fire-and-forget request that cannot be cancelled — these are the crashes and stale screens that appear only on a slow network. Swift''s structured concurrency prevents them when it is used the way it is designed.","whatGoodLooksLike":"View-lifecycle work runs in `.task` or another effective cancellation lifecycle. A synchronous user action can start a Task whose lifetime fits the operation; UI state stays correctly isolated and needed results or failures are handled.","groupSlug":"ios-app-craft","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 192\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Unscoped task</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"16\" y=\"61\" font-size=\"15\">DetailView</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"16\" y=\"89\" font-size=\"15\">.onAppear {</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"32\" y=\"109\" font-size=\"15\">Task {…}</text>\n  <rect class=\"pv-fill-surface pv-stroke-ink\" x=\"0.75\" y=\"152.75\" width=\"134.5\" height=\"38.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"16\" y=\"177\" font-size=\"15\">View closes</text>\n  <path class=\"pv-stroke-muted\" d=\"M144 172h16\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M168 172l-8-5v10z\"/>\n  <text class=\"pv-fill-muted\" x=\"180\" y=\"177\" font-size=\"15\">Fetch still runs</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">View-scoped task</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"302.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"352\" y=\"61\" font-size=\"15\">DetailView</text>\n  <text class=\"pv-fill-accent pv-mono\" x=\"352\" y=\"89\" font-size=\"15\">.task {…}</text>\n  <rect class=\"pv-fill-surface pv-stroke-ink\" x=\"336.75\" y=\"152.75\" width=\"134.5\" height=\"38.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"352\" y=\"177\" font-size=\"15\">View closes</text>\n  <path class=\"pv-stroke-accent\" d=\"M480 172h16\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-accent\" d=\"M504 172l-8-5v10z\"/>\n  <text class=\"pv-fill-ink\" x=\"516\" y=\"177\" font-size=\"15\">Fetch canceled</text>\n</svg>\n","alt":"An unscoped task, Task {…} inside .onAppear in DetailView, keeps the fetch running when the view closes. A view-scoped task, .task {…} on DetailView, cancels the fetch when the view closes."},"guide":{"markdown":"## How to do it\n\n- Start the work that a screen needs in `.task` on its view. SwiftUI cancels that task when the view goes away. For example, instead of `.onAppear { Task { await model.load() } }`, write `.task { await model.load() }`.\n- Match the lifetime of a button-started task to its operation. A `Task { }` in the button action is a valid way to start it. Work that must stop with the screen needs a way to be canceled. A save that the user asked for can finish after the screen closes.\n- Keep changes to view state on the main actor. The model can already have this protection by inheritance or through the target’s default isolation. Otherwise, mark the model `@MainActor` or use `await MainActor.run`.\n- Use `Task.detached` or a `DispatchQueue` only when the work must run apart from its caller. Otherwise, use `async let` or a task group, so cancellation reaches the work.\n- If your code needs the result of a task, await the task’s value and use it.\n\n## When it does not apply\n\n- Your change adds no concurrency code to Swift files. That means no new `async`, `await`, `Task`, `.task`, `@MainActor`, `MainActor.run`, `Task.detached`, `DispatchQueue` or actor declaration. Concurrency code that your change does not touch does not count.\n\n## Common mistakes\n\n- Treating every `Task { }` as a bug. A task in a button action is the usual way to start async work. Not every task needs a stored handle or a comment. Instead, check that the lifetime of each task fits its work.\n- Setting a `@Published` property from a background queue or a detached task. SwiftUI can miss the change, and the screen shows old data. Instead, keep the model on the main actor and `await` the slow work.\n- Moving work into `Task.detached` to keep it off the main thread. The detached task drops its actor and the cancellation of its caller. Instead, `await` the slow call. The main actor stays free while it waits.\n\n## Sources\n\n- [Concurrency](https://docs.swift.org/swift-book/documentation/the-swift-programming-language/concurrency/), The Swift Programming Language, Swift project. Child tasks inherit cancellation from their parent, while you manage each unstructured task yourself.\n- [`task(name:priority:file:line:_:)`](https://developer.apple.com/documentation/swiftui/view/task(name:priority:file:line:_:)), SwiftUI documentation, Apple. SwiftUI cancels a view’s task if the view goes away before the task finishes.\n- [Discover concurrency in SwiftUI](https://developer.apple.com/videos/play/wwdc2021/10019/), Apple, WWDC 2021. Use `.task` to tie work to a view, and change an observable object only on the main actor.\n- [`Task.detached`](https://developer.apple.com/documentation/swift/task/detached(name:priority:operation:)-795w1), Swift standard library documentation, Apple. Use a detached task only when child tasks cannot do the work, and handle its cancellation yourself.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Use structured concurrency safely","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":{"skipReason":"the change touches no Swift source file","anyOf":[{"changedPathMatches":["**/*.swift"]}]},"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: async work tied to the lifetime that owns it, UI state mutated on the main actor, and no fire-and-forget task where structure was available.\n\n## The standard\nJudge the concurrency code this change adds against a closed list. (1) View-lifecycle work belongs in `.task { }` or an equivalent observed cancellation lifecycle. A `Task { }` in a synchronous button action is a native bridge to asynchronous work, not a defect by itself. Judge whether its lifetime and cancellation fit the operation: work that must stop with the view has an effective cancellation path, while a user-initiated operation can legitimately complete after the view disappears. A stored handle or a written reason can establish intent but is not mandatory when the captured code already establishes the lifecycle. (2) State the UI reads is mutated on the main actor: a type that holds view state is isolated to the main actor — by `@MainActor`, by the target''s default actor isolation or by what it inherits, including SwiftUI `View` when the project''s SDK declares it main-actor isolated — or the mutation is `await MainActor.run`; a mutation of `@Published`/`@Observable` UI state from a background context is a lapse. (3) Detached work and dispatch queues have an evidenced need for their independent execution or scheduling; the captured code may establish that need without a redundant comment. (4) A result needed by the operation is consumed; a task can perform a side effect without its handle being stored. Judge added lines; existing concurrency the change did not touch is not this change''s.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the change adds no concurrency: no added `async`, `await`, `Task`, `.task`, `@MainActor`, `MainActor.run`, `Task.detached`, `DispatchQueue` or actor declaration. Added concurrency is the occasion, whether or not it carries a lapse.\n\n## Sources\n1. The diff (`work/change/diff.patch`) with `[L<n>]` markers: the added concurrency constructs and where they sit (a view modifier, a model method, a service). It establishes what was written. It never establishes the actor a type is isolated to when that declaration is outside the diff.\n2. The checkout (`<repositoryRoot>`): the declaration of the type a mutation lands in and the target''s default actor isolation, and whether a `Task` handle is stored. Read it to place a construct; it never adds one.\n3. The precomputed leads below these criteria: the `Task {` blocks, `.onAppear` with async work, detached tasks and dispatch queues it found, as leads, never conclusions.\nIf the diff is truncated where async code is added, report a collection gap and record no observation.\n\n## Judge\nEnumerate the added constructs first, then assess the standard.\n- MET: every added construct follows the list — view-lifecycle work cancelled appropriately, user-triggered async work with an appropriate lifetime, UI state isolated correctly, and needed results consumed. Quote a representative construct.\n- NOT_MET: an added construct breaks the list — view-lifecycle work that can outlive its owner without appropriate cancellation, UI state mutated off the main actor, detached work or a dispatch queue with no evidenced need, an unconsumed result needed by the operation. Quote the line and name the rule.\n- UNDETERMINED: an added line mutates UI state from an async context and the isolation of its type is in neither the diff nor the checkout; name the type. An added call into an unchanged method is judged as a call, never by what that method does inside.\nOne observation per review, on the single most consequential lapse when there are several.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: a lifecycle mismatch on a short local operation. MAJOR: a network request in an uncancelled task that writes view state, or UI state mutated from a background context. Identical evidence yields identical severity.\n\n## Grounding\nQuote the `[L<n>]` construct and, for an actor lapse, the declaration of the type mutated. Never claim a mutation is off the main actor without the type''s isolation; never claim a task is fire-and-forget when a handle is stored in the same hunk.\n\n## Defer\nSwallowed errors in async code belong to `handles-errors-instead-of-swallowing-them`; crash-shaped constructs to `avoids-unsafe-panics-and-chosen-crashes`. Here only: is the concurrency structured?","precomputeScript":"// Precompute HINTS for uses-structured-concurrency-safely: every concurrency construct ADDED in Swift\n// files, placed in its enclosing type, and the lines of the project files that mention a default actor\n// isolation. Whether the work must outlive the view, and whether a mutation lands on the main actor, is\n// the review''s to decide from the checkout.\nimport { readFile } from \"node:fs/promises\";\nimport path from \"node:path\";\n\nimport { globFilesSync } from \"../lib/files.ts\";\nimport { countLabel, sampleNote, scanAddedLines, type SourcePattern } from \"../lib/source-scan.ts\";\nimport type { DiffFile, PullRequestMetadata } from \"../lib/types.ts\";\n\nconst SWIFTUI_VIEW = /\\b(?:View|App|Scene)\\b/u;\n\nconst CONCURRENCY: readonly SourcePattern[] = [\n\t[\"Task.detached\", /\\bTask\\.detached\\b/u],\n\t[\"stored task handle\", /(?:let|var)\\s+\\w+\\s*(?::\\s*Task<[^>]*>)?\\s*=\\s*Task\\s*[{(]/u],\n\t[\"Task { }\", /\\bTask\\s*(?:\\(priority:[^)]*\\))?\\s*\\{/u],\n\t[\".task modifier\", /\\.task\\s*(?:\\(id:[^)]*\\))?\\s*\\{/u],\n\t[\".onAppear\", /\\.onAppear\\s*\\{/u],\n\t[\"DispatchQueue\", /\\bDispatchQueue\\b/u],\n\t[\"@MainActor\", /@MainActor\\b/u],\n\t[\"MainActor.run\", /\\bMainActor\\.run\\b/u],\n\t[\"actor declaration\", /^\\s*(?:\\w+\\s+)*actor\\s+\\w+/u],\n\t[\"async function\", /\\bfunc\\s+\\w+[^{]*\\basync\\b/u],\n\t[\"await\", /\\bawait\\b/u],\n];\n\n/** Text naming a default actor isolation: an Xcode build setting or a SwiftPM target setting. */\nconst DEFAULT_ISOLATION = /SWIFT_DEFAULT_ACTOR_ISOLATION\\s*[:=]|defaultIsolation\\s*\\(/u;\n\n/**\n * Lines of the first few project files that mention a default actor isolation, as `path:line text`. The\n * setting belongs to one target or SwiftPM module and build configuration, and a line may be commented\n * out, so a line found here is a place to read, not the isolation of any changed type.\n */\nasync function defaultIsolationLines(repoPath: string): Promise<string[]> {\n\tlet files: string[];\n\ttry {\n\t\tfiles = [\n\t\t\t...globFilesSync(\"**/project.yml\", repoPath),\n\t\t\t...globFilesSync(\"**/project.yaml\", repoPath),\n\t\t\t...globFilesSync(\"**/*.xcodeproj/project.pbxproj\", repoPath),\n\t\t\t...globFilesSync(\"**/Package.swift\", repoPath),\n\t\t].filter((f) => !/(?:^|\\/)(?:Pods|\\.build|DerivedData|Carthage)\\//u.test(f));\n\t} catch {\n\t\treturn [];\n\t}\n\tconst found: string[] = [];\n\tfor (const file of files.slice(0, 20)) {\n\t\tlet text: string;\n\t\ttry {\n\t\t\ttext = await readFile(path.join(repoPath, file), \"utf8\");\n\t\t} catch {\n\t\t\tcontinue;\n\t\t}\n\t\tfor (const [index, line] of text.split(/\\r?\\n/u).entries()) {\n\t\t\tif (DEFAULT_ISOLATION.test(line)) {\n\t\t\t\tfound.push(`${file}:${String(index + 1)} ${line.trim().slice(0, 120)}`);\n\t\t\t}\n\t\t}\n\t}\n\treturn found.slice(0, 10);\n}\n\nexport default async function usesStructuredConcurrencySafely(\n\trepoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n) {\n\tconst scan = await scanAddedLines(repoPath, diffFiles, {\n\t\tlanguages: [\"swift\"],\n\t\tpatterns: CONCURRENCY,\n\t\tscope: SWIFTUI_VIEW,\n\t\tmaxHints: 60,\n\t});\n\tconst count = (label: string) => countLabel(scan, label);\n\tconst unstructuredInViews = scan.hints.filter(\n\t\t(h) => h.pattern === \"Task { }\" && h.flags.inScope === true,\n\t).length;\n\tconst metrics = {\n\t\tconcurrencyLinesAdded: scan.matched,\n\t\ttaskBlocks: count(\"Task { }\"),\n\t\ttaskBlocksInListedViewRows: unstructuredInViews,\n\t\ttaskModifiers: count(\".task modifier\"),\n\t\tdetachedTasks: count(\"Task.detached\"),\n\t\tdispatchQueues: count(\"DispatchQueue\"),\n\t\tmainActorMarks: count(\"@MainActor\") + count(\"MainActor.run\"),\n\t\tfilesWithoutCheckout: scan.filesWithoutCheckout,\n\t\tfilesScanned: scan.filesScanned,\n\t\tlinesAdded: scan.linesAdded,\n\t};\n\tconst directions: string[] = [...sampleNote(scan)];\n\tif (unstructuredInViews > 0) {\n\t\tdirections.push(\n\t\t\t`${unstructuredInViews} Task { } block(s) added inside view types — read the lifetime each needs: work tied to the view belongs to a lifecycle that cancels it, while a Task started from a user action may legitimately finish after the view is gone.`,\n\t\t);\n\t}\n\tif (metrics.detachedTasks + metrics.dispatchQueues > 0) {\n\t\tdirections.push(\n\t\t\t`${metrics.detachedTasks} detached task(s) and ${metrics.dispatchQueues} dispatch queue use(s) — read whether the code shows a need for independent execution or scheduling; no written reason is required when it does.`,\n\t\t);\n\t}\n\tif (scan.matched > 0) {\n\t\tconst settings = await defaultIsolationLines(repoPath);\n\t\tdirections.push(\n\t\t\tsettings.length > 0\n\t\t\t\t? `Default actor isolation text in project files: ${settings.join(\"; \")}. Each applies only to its own target or SwiftPM module and build configuration, and a commented line sets nothing: read which target and configuration build the changed file before relying on any of them.`\n\t\t\t\t: \"No default actor isolation text was found in the project files read, which leaves the module''s default unknown rather than nonisolated.\",\n\t\t\t\"A type''s isolation comes from its declaration, its module''s setting or what it inherits. A missing @MainActor on an added line does not by itself put a mutation off the main actor. Check the SDK before relying on inherited SwiftUI View isolation. Swallowed failures belong to handles-errors-instead-of-swallowing-them, not this practice.\",\n\t\t);\n\t}\n\treturn { hints: scan.hints, metrics, directions };\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"An unstructured task that outlives its view, UI state mutated off the main actor, a fire-and-forget request that cannot be cancelled — these are the crashes and stale screens that appear only on a slow network. Swift''s structured concurrency prevents them when it is used the way it is designed.","whatGoodLooksLike":"View-lifecycle work runs in `.task` or another effective cancellation lifecycle. A synchronous user action can start a Task whose lifetime fits the operation; UI state stays correctly isolated and needed results or failures are handled.","groupSlug":"ios-app-craft","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 192\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Unscoped task</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"302.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"16\" y=\"61\" font-size=\"15\">DetailView</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"16\" y=\"89\" font-size=\"15\">.onAppear {</text>\n  <text class=\"pv-fill-muted pv-mono\" x=\"32\" y=\"109\" font-size=\"15\">Task {…}</text>\n  <rect class=\"pv-fill-surface pv-stroke-ink\" x=\"0.75\" y=\"152.75\" width=\"134.5\" height=\"38.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"16\" y=\"177\" font-size=\"15\">View closes</text>\n  <path class=\"pv-stroke-muted\" d=\"M144 172h16\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M168 172l-8-5v10z\"/>\n  <text class=\"pv-fill-muted\" x=\"180\" y=\"177\" font-size=\"15\">Fetch still runs</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">View-scoped task</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"302.5\" height=\"94.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"352\" y=\"61\" font-size=\"15\">DetailView</text>\n  <text class=\"pv-fill-accent pv-mono\" x=\"352\" y=\"89\" font-size=\"15\">.task {…}</text>\n  <rect class=\"pv-fill-surface pv-stroke-ink\" x=\"336.75\" y=\"152.75\" width=\"134.5\" height=\"38.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"352\" y=\"177\" font-size=\"15\">View closes</text>\n  <path class=\"pv-stroke-accent\" d=\"M480 172h16\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-accent\" d=\"M504 172l-8-5v10z\"/>\n  <text class=\"pv-fill-ink\" x=\"516\" y=\"177\" font-size=\"15\">Fetch canceled</text>\n</svg>\n","alt":"An unscoped task, Task {…} inside .onAppear in DetailView, keeps the fetch running when the view closes. A view-scoped task, .task {…} on DetailView, cancels the fetch when the view closes."},"guide":{"markdown":"## How to do it\n\n- Start the work that a screen needs in `.task` on its view. SwiftUI cancels that task when the view goes away. For example, instead of `.onAppear { Task { await model.load() } }`, write `.task { await model.load() }`.\n- Match the lifetime of a button-started task to its operation. A `Task { }` in the button action is a valid way to start it. Work that must stop with the screen needs a way to be canceled. A save that the user asked for can finish after the screen closes.\n- Keep changes to view state on the main actor. The model can already have this protection by inheritance or through the target’s default isolation. Otherwise, mark the model `@MainActor` or use `await MainActor.run`.\n- Use `Task.detached` or a `DispatchQueue` only when the work must run apart from its caller. Otherwise, use `async let` or a task group, so cancellation reaches the work.\n- If your code needs the result of a task, await the task’s value and use it.\n\n## When it does not apply\n\n- Your change adds no concurrency code to Swift files. That means no new `async`, `await`, `Task`, `.task`, `@MainActor`, `MainActor.run`, `Task.detached`, `DispatchQueue` or actor declaration. Concurrency code that your change does not touch does not count.\n\n## Common mistakes\n\n- Treating every `Task { }` as a bug. A task in a button action is the usual way to start async work. Not every task needs a stored handle or a comment. Instead, check that the lifetime of each task fits its work.\n- Setting a `@Published` property from a background queue or a detached task. SwiftUI can miss the change, and the screen shows old data. Instead, keep the model on the main actor and `await` the slow work.\n- Moving work into `Task.detached` to keep it off the main thread. The detached task drops its actor and the cancellation of its caller. Instead, `await` the slow call. The main actor stays free while it waits.\n\n## Sources\n\n- [Concurrency](https://docs.swift.org/swift-book/documentation/the-swift-programming-language/concurrency/), The Swift Programming Language, Swift project. Child tasks inherit cancellation from their parent, while you manage each unstructured task yourself.\n- [`task(name:priority:file:line:_:)`](https://developer.apple.com/documentation/swiftui/view/task(name:priority:file:line:_:)), SwiftUI documentation, Apple. SwiftUI cancels a view’s task if the view goes away before the task finishes.\n- [Discover concurrency in SwiftUI](https://developer.apple.com/videos/play/wwdc2021/10019/), Apple, WWDC 2021. Use `.task` to tie work to a view, and change an observable object only on the main actor.\n- [`Task.detached`](https://developer.apple.com/documentation/swift/task/detached(name:priority:operation:)-795w1), Swift standard library documentation, Apple. Use a detached task only when child tasks cannot do the work, and handle its cancellation yourself.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Async work is scoped to its view and cancelled with it"'::jsonb),'v5:91a815cf1f5d427bcbed44ed561f93ad4483bddb9fce141c1808c6784f168ab3','practice:v3:12cd91239e3ef8c6c31e3d429b9abc9c9411c8aec6aea488aba26a494746c947');
INSERT INTO _cutover_bundle VALUES('PRACTICE','ships-a-preview-with-each-new-view','scm.pull_request','{"name":"Ship a preview with each new view","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":{"skipReason":"the change touches no Swift source file","anyOf":[{"changedPathMatches":["**/*.swift"]}]},"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the new SwiftUI presentation a change adds arriving with a `#Preview` (or `PreviewProvider`) that shows it with known representative sample data for whatever it shows from variable data, and its important states.\n\n## The standard\nJudge one thing: when this change adds new SwiftUI view types, can the presentation they add be seen in a preview from the same change? A preview is a `#Preview` block or a `PreviewProvider`. It covers a view it constructs, and a view that a host it constructs demonstrably renders: a new row, badge or section shown through a previewed host''s body is covered by that preview. Where the presentation shows variable data or state, the preview is representative when the source establishes known, meaningful values of the shape the presentation shows (a filled model, a non-empty list with varied entries) and you trace them into that presentation. Where those values live does not decide it: the preview may pass them, a sample helper may build them, or the previewed view or its owner may hold them as in-memory literals; no preview needs an initializer or injection only to receive values the source already establishes. A default expression alone is not a sample: an empty list, a placeholder model, a value whose content you cannot read, or an `@AppStorage` or other persisted default, which leaves what is stored unknown, establishes nothing representative, and neither does a fresh or live view model; a live fetch inside a preview is not sample data. Such a preview exists but is not representative. Fixed presentation — a view whose body shows only constant content — needs no sample: a preview that constructs it covers it. It is complete when presentation that has an empty, loading or error state is also supplied that state by a preview. A preview supplies a state it demonstrably reaches; trace it as you trace a host. A default-constructed view or model reaches the state its initial value and the work it starts lead to — an idle prompt before any input, for example — so default construction neither proves nor disproves a state until you trace it, and it supplies no sample for variable data. A state a preview only passes through, such as loading on the way to results, is not supplied; a preview supplies it by holding it, for example by giving the content view that state. A view that only owns lifecycle or effects — starting and cancelling work, holding the model — and passes everything it shows to a content view adds no presentation of its own: representative previews of that content view cover it, and it needs no new initializer, injection or architecture just so a preview can construct it. What such a wrapper renders itself — a navigation title, a toolbar, an overlay, other chrome, or a state the content view never receives — is its own presentation, and a preview must show it. A preview for an existing view the change edits is welcome but not required. Judge coverage and representativeness, never layout, naming, or which type a `#Preview` names.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the change adds no new view type: no added `struct … : View` declaration in a non-test file. An edit to an existing view, a model-only change or a preview-only change carries no surface.\n\n## Sources\n1. The diff (`work/change/diff.patch`) with the file list (`work/change/files.json`): the added `struct … : View` declarations and the `#Preview`/`PreviewProvider` blocks in the same change. It establishes which new views a preview constructs and which sample values and states it supplies.\n2. The checkout (`<repositoryRoot>`): a preview that lives in another file of the same change, sample-data helpers it uses, the body of a host it constructs, and the body of a new owner view. Read it to find the preview, to establish that a host renders a new view with the data the preview supplies, and to establish that an owner passes everything it shows to a previewed content view; it never supplies a preview the change did not add.\n3. The precomputed leads below these criteria: the new view types and the previews it found, as leads, never conclusions.\nIf the diff is truncated where a new view is declared, report a collection gap and record no observation.\n\n## Judge\nEnumerate the new view types first — every added `struct … : View`, `private` and file-scoped ones included — and for each name the presentation it adds and the preview that covers it. A view is covered by a preview that constructs it; a nested view, by a preview that constructs a host whose body you read renders it with that preview''s data; an effect-only owner, by tracing its body to the content view it passes everything to and naming that content''s previews, while any chrome or state the owner renders itself still needs a preview that shows it. Never assume a host renders a view you did not trace; a helper''s smallness goes to the severity, not to the outcome. Then assess the standard against all relevant evidence.\n- MET: every new view''s presentation is covered by a preview in the same change that supplies representative sample data for any variable data it shows, and its important states. Quote the declaration and its covering preview; for a nested view also the host line that renders it, for an effect-only owner the line in its body that delegates to the content view, and for values the view or its owner holds, the lines that hold them.\n- NOT_MET: every new view is covered, but a preview supplies presentation that shows variable data nothing representative — only an empty list for a list screen, a placeholder model, or defaults that establish no representative values — or, after you trace the state each preview in the change reaches, supplies no preview with a state the view plainly has. Quote the preview and name what it lacks.\n- NOT_MET: at least one new view''s presentation is covered by no preview in the change — presentation no preview covers, or a wrapper''s own chrome or state that no preview shows — after scanning every Swift file in the diff. Quote the declaration and say what you scanned.\n- UNDETERMINED: a preview exists in the checkout but the diff does not show whether this change added it, or whether a host renders the new view, or an owner only delegates, cannot be read; name the file.\nOne observation per review, on the single most consequential view when there are several.\n\n## Severity\nNOT_MET only; never above MINOR on this alone — non-blocking. MINOR: a new view with no preview or with an unrepresentative one. INFO: a small part of covered presentation left out — a row''s alternate state, a wrapper''s toolbar button — while the main presentation is previewed. Identical evidence yields identical severity.\n\n## Grounding\nQuote the `[L<n>]` `struct … : View` declaration and the covering `#Preview` line — with the host line that renders a nested view, or the owner''s line that delegates to its previewed content view — or for absent the declaration and the scan. The source is static: tracing what a host''s body renders reads its declaration, never shows that a preview was run, rendered or compiles, and a declared `@AppStorage` or other persisted default leaves what is actually stored or shown unknown. Never claim a host covers a view, or an owner only delegates, without quoting the line in its body that shows it.\n\n## Defer\nHow to verify the change as a whole belongs to `states-how-to-verify-the-change`; tests for logic to `ships-tests-with-the-change`. Here only: can the new screen be seen?","precomputeScript":"// Precompute HINTS for ships-a-preview-with-each-new-view: the view types this change declares and the\n// previews it adds, per file. The pairing is a fact the review checks; whether a preview''s data is\n// representative is the review''s to read.\nimport { isCommentLine } from \"../lib/declarations.ts\";\nimport { isTestPath, languageOf } from \"../lib/languages.ts\";\nimport type { DiffFile, Hint, PullRequestMetadata } from \"../lib/types.ts\";\n\nconst VIEW_DECLARATION =\n\t/^\\s*(?:@\\w+\\s+)*(?:(?:public|private|fileprivate|internal)\\s+)?struct\\s+(?<name>[A-Za-z_]\\w*)\\s*(?:<[^>]*>)?\\s*:\\s*[^{]*\\bView\\b/u;\nconst PREVIEW = /^\\s*#Preview\\b|:\\s*PreviewProvider\\b/u;\n\nexport default function shipsAPreviewWithEachNewView(\n\t_repoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n) {\n\tconst hints: Hint[] = [];\n\tlet newViews = 0;\n\tlet previewsAdded = 0;\n\tlet filesWithNewViewAndNoPreview = 0;\n\tfor (const [path, df] of diffFiles) {\n\t\tif (languageOf(path) !== \"swift\" || isTestPath(path)) {\n\t\t\tcontinue;\n\t\t}\n\t\tlet views = 0;\n\t\tlet previews = 0;\n\t\tfor (const [line, content] of df.addedLines) {\n\t\t\tif (isCommentLine(content, \"swift\")) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tconst view = VIEW_DECLARATION.exec(content);\n\t\t\tif (view) {\n\t\t\t\tviews += 1;\n\t\t\t\thints.push({\n\t\t\t\t\tfile: path,\n\t\t\t\t\tline,\n\t\t\t\t\tpattern: \"new view type\",\n\t\t\t\t\tcontext: content.trim().slice(0, 160),\n\t\t\t\t\tinDiff: true,\n\t\t\t\t\tflags: { name: view.groups?.name ?? \"\" },\n\t\t\t\t});\n\t\t\t} else if (PREVIEW.test(content)) {\n\t\t\t\tpreviews += 1;\n\t\t\t\thints.push({\n\t\t\t\t\tfile: path,\n\t\t\t\t\tline,\n\t\t\t\t\tpattern: \"preview\",\n\t\t\t\t\tcontext: content.trim().slice(0, 160),\n\t\t\t\t\tinDiff: true,\n\t\t\t\t\tflags: {},\n\t\t\t\t});\n\t\t\t}\n\t\t}\n\t\tnewViews += views;\n\t\tpreviewsAdded += previews;\n\t\tif (views > 0 && previews === 0) {\n\t\t\tfilesWithNewViewAndNoPreview += 1;\n\t\t}\n\t}\n\tconst directions: string[] = [];\n\tif (newViews > 0) {\n\t\tdirections.push(\n\t\t\t`${newViews} new view type(s) declared and ${previewsAdded} preview(s) added; ${filesWithNewViewAndNoPreview} file(s) declare a view and add no preview — a preview may live in another file of the change, so scan the whole diff before deciding. These counts pair no preview with a view. Read the previews and view bodies to trace the presentation coverage described in the criteria, including nested views and content delegated by an effect-only owner.`,\n\t\t);\n\t}\n\treturn {\n\t\thints: hints.slice(0, 40),\n\t\tmetrics: { newViews, previewsAdded, filesWithNewViewAndNoPreview },\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A SwiftUI view without a preview is a screen nobody can see without running the whole app to it, and the first thing the next person deletes when it breaks. A preview with representative data is the cheapest verification a view can have, and the way a reviewer sees what changed.","whatGoodLooksLike":"The new screens and presentation a change adds can be seen in a `#Preview` with representative sample data — including an empty, loading or error state when they have one — so they can be checked without launching the app.","groupSlug":"ios-app-craft","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 172\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Code only</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"158.5\" height=\"110.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"16\" y=\"61\" font-size=\"15\">ReceiptList</text>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"80\" width=\"112\" height=\"10\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"32\" y=\"96\" width=\"96\" height=\"10\" rx=\"3\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"192.75\" y=\"32.75\" width=\"110.5\" height=\"110.5\" rx=\"12\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/>\n  <text class=\"pv-fill-muted\" x=\"248\" y=\"93\" font-size=\"15\" text-anchor=\"middle\">No preview</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"168\" font-size=\"15\">Unseen until run</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Code and preview</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"158.5\" height=\"110.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"352\" y=\"61\" font-size=\"15\">ReceiptList</text>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"80\" width=\"112\" height=\"10\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"368\" y=\"96\" width=\"96\" height=\"10\" rx=\"3\"/>\n  <text class=\"pv-fill-accent pv-mono\" x=\"352\" y=\"129\" font-size=\"15\">#Preview</text>\n  <path class=\"pv-stroke-muted\" d=\"M504 88h8\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M520 88l-8-5v10z\"/>\n  <rect class=\"pv-fill-surface pv-stroke-accent\" x=\"528.75\" y=\"32.75\" width=\"110.5\" height=\"110.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <rect class=\"pv-fill-muted\" x=\"568\" y=\"48\" width=\"32\" height=\"6\" rx=\"3\"/>\n  <text class=\"pv-fill-ink\" x=\"544\" y=\"85\" font-size=\"15\">Coffee €3</text>\n  <text class=\"pv-fill-ink\" x=\"544\" y=\"109\" font-size=\"15\">Bagel €2</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"168\" font-size=\"15\">Seen in review</text>\n</svg>\n","alt":"Code only: ReceiptList has no preview, so it stays unseen until someone runs the app. Code and preview: a #Preview shows ReceiptList with Coffee €3 and Bagel €2, so it is seen in review."},"guide":{"markdown":"## How to do it\n\n- Cover the presentation of each new SwiftUI view with a `#Preview` or a `PreviewProvider` in the same change. A preview of a host view counts when it shows that presentation.\n- When the view shows variable data, supply known values that match what it shows. For example, instead of `TaskList(tasks: [])`, pass tasks with varied titles.\n- Take the sample values from the preview, a sample helper, or fixed values that the view or its owner holds. A live fetch does not give sample data.\n- Preview each empty, loading or error state that the new presentation supports.\n- Some new views only start work and hold the model, and pass all that they show to a content view. Preview what the outer view draws itself, such as a navigation title, a toolbar or an overlay. Previews of the content view cover the rest.\n\n## When it does not apply\n\n- Your change adds no new SwiftUI view. It declares no new `struct … : View` outside test files.\n- Your change only edits a view that already exists.\n- Your change only touches models or other code that is not a view.\n- Your change only adds or edits previews.\n\nIt still applies when the new view is `private` or used only inside one file.\n\n## Common mistakes\n\n- Using only an empty list or a placeholder to preview a view that shows variable data. The preview exists, but it shows nothing that you can check. Instead, give it varied values that look like real data.\n- Relying on a fresh or live view model, or on a stored value such as `@AppStorage`, for the data. Nobody knows what the preview then shows. Instead, give the preview known sample values.\n- Adding a new row or section to a screen and counting on the screen’s preview. That preview covers the new view only when the screen really draws it with the preview’s data. Instead, check that it does, or preview the new view on its own.\n\n## Sources\n\n- [Adding previews to your interface files](https://developer.apple.com/documentation/xcode/adding-previews-to-your-interface-files), Apple Developer Documentation. A preview shows a view without running the app, and it can use sample data kept apart from the app.\n- [Build programmatic UI with Xcode Previews](https://developer.apple.com/videos/play/wwdc2023/10252/), Kevin Cathey, Apple, WWDC 2023. A preview sets up data and passes it into the view, and it runs the real code of your project.\n- [What to look for in a code review](https://google.github.io/eng-practices/review/reviewer/looking-for.html), Google Engineering Practices. A user interface change is hard to judge from its code alone, so a reviewer can ask to see it.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Ship a preview with each new view","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":{"skipReason":"the change touches no Swift source file","anyOf":[{"changedPathMatches":["**/*.swift"]}]},"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the new SwiftUI presentation a change adds arriving with a `#Preview` (or `PreviewProvider`) that shows it with known representative sample data for whatever it shows from variable data, and its important states.\n\n## The standard\nJudge one thing: when this change adds new SwiftUI view types, can the presentation they add be seen in a preview from the same change? A preview is a `#Preview` block or a `PreviewProvider`. It covers a view it constructs, and a view that a host it constructs demonstrably renders: a new row, badge or section shown through a previewed host''s body is covered by that preview. Where the presentation shows variable data or state, the preview is representative when the source establishes known, meaningful values of the shape the presentation shows (a filled model, a non-empty list with varied entries) and you trace them into that presentation. Where those values live does not decide it: the preview may pass them, a sample helper may build them, or the previewed view or its owner may hold them as in-memory literals; no preview needs an initializer or injection only to receive values the source already establishes. A default expression alone is not a sample: an empty list, a placeholder model, a value whose content you cannot read, or an `@AppStorage` or other persisted default, which leaves what is stored unknown, establishes nothing representative, and neither does a fresh or live view model; a live fetch inside a preview is not sample data. Such a preview exists but is not representative. Fixed presentation — a view whose body shows only constant content — needs no sample: a preview that constructs it covers it. It is complete when presentation that has an empty, loading or error state is also supplied that state by a preview. A preview supplies a state it demonstrably reaches; trace it as you trace a host. A default-constructed view or model reaches the state its initial value and the work it starts lead to — an idle prompt before any input, for example — so default construction neither proves nor disproves a state until you trace it, and it supplies no sample for variable data. A state a preview only passes through, such as loading on the way to results, is not supplied; a preview supplies it by holding it, for example by giving the content view that state. A view that only owns lifecycle or effects — starting and cancelling work, holding the model — and passes everything it shows to a content view adds no presentation of its own: representative previews of that content view cover it, and it needs no new initializer, injection or architecture just so a preview can construct it. What such a wrapper renders itself — a navigation title, a toolbar, an overlay, other chrome, or a state the content view never receives — is its own presentation, and a preview must show it. A preview for an existing view the change edits is welcome but not required. Judge coverage and representativeness, never layout, naming, or which type a `#Preview` names.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the change adds no new view type: no added `struct … : View` declaration in a non-test file. An edit to an existing view, a model-only change or a preview-only change carries no surface.\n\n## Sources\n1. The diff (`work/change/diff.patch`) with the file list (`work/change/files.json`): the added `struct … : View` declarations and the `#Preview`/`PreviewProvider` blocks in the same change. It establishes which new views a preview constructs and which sample values and states it supplies.\n2. The checkout (`<repositoryRoot>`): a preview that lives in another file of the same change, sample-data helpers it uses, the body of a host it constructs, and the body of a new owner view. Read it to find the preview, to establish that a host renders a new view with the data the preview supplies, and to establish that an owner passes everything it shows to a previewed content view; it never supplies a preview the change did not add.\n3. The precomputed leads below these criteria: the new view types and the previews it found, as leads, never conclusions.\nIf the diff is truncated where a new view is declared, report a collection gap and record no observation.\n\n## Judge\nEnumerate the new view types first — every added `struct … : View`, `private` and file-scoped ones included — and for each name the presentation it adds and the preview that covers it. A view is covered by a preview that constructs it; a nested view, by a preview that constructs a host whose body you read renders it with that preview''s data; an effect-only owner, by tracing its body to the content view it passes everything to and naming that content''s previews, while any chrome or state the owner renders itself still needs a preview that shows it. Never assume a host renders a view you did not trace; a helper''s smallness goes to the severity, not to the outcome. Then assess the standard against all relevant evidence.\n- MET: every new view''s presentation is covered by a preview in the same change that supplies representative sample data for any variable data it shows, and its important states. Quote the declaration and its covering preview; for a nested view also the host line that renders it, for an effect-only owner the line in its body that delegates to the content view, and for values the view or its owner holds, the lines that hold them.\n- NOT_MET: every new view is covered, but a preview supplies presentation that shows variable data nothing representative — only an empty list for a list screen, a placeholder model, or defaults that establish no representative values — or, after you trace the state each preview in the change reaches, supplies no preview with a state the view plainly has. Quote the preview and name what it lacks.\n- NOT_MET: at least one new view''s presentation is covered by no preview in the change — presentation no preview covers, or a wrapper''s own chrome or state that no preview shows — after scanning every Swift file in the diff. Quote the declaration and say what you scanned.\n- UNDETERMINED: a preview exists in the checkout but the diff does not show whether this change added it, or whether a host renders the new view, or an owner only delegates, cannot be read; name the file.\nOne observation per review, on the single most consequential view when there are several.\n\n## Severity\nNOT_MET only; never above MINOR on this alone — non-blocking. MINOR: a new view with no preview or with an unrepresentative one. INFO: a small part of covered presentation left out — a row''s alternate state, a wrapper''s toolbar button — while the main presentation is previewed. Identical evidence yields identical severity.\n\n## Grounding\nQuote the `[L<n>]` `struct … : View` declaration and the covering `#Preview` line — with the host line that renders a nested view, or the owner''s line that delegates to its previewed content view — or for absent the declaration and the scan. The source is static: tracing what a host''s body renders reads its declaration, never shows that a preview was run, rendered or compiles, and a declared `@AppStorage` or other persisted default leaves what is actually stored or shown unknown. Never claim a host covers a view, or an owner only delegates, without quoting the line in its body that shows it.\n\n## Defer\nHow to verify the change as a whole belongs to `states-how-to-verify-the-change`; tests for logic to `ships-tests-with-the-change`. Here only: can the new screen be seen?","precomputeScript":"// Precompute HINTS for ships-a-preview-with-each-new-view: the view types this change declares and the\n// previews it adds, per file. The pairing is a fact the review checks; whether a preview''s data is\n// representative is the review''s to read.\nimport { isCommentLine } from \"../lib/declarations.ts\";\nimport { isTestPath, languageOf } from \"../lib/languages.ts\";\nimport type { DiffFile, Hint, PullRequestMetadata } from \"../lib/types.ts\";\n\nconst VIEW_DECLARATION =\n\t/^\\s*(?:@\\w+\\s+)*(?:(?:public|private|fileprivate|internal)\\s+)?struct\\s+(?<name>[A-Za-z_]\\w*)\\s*(?:<[^>]*>)?\\s*:\\s*[^{]*\\bView\\b/u;\nconst PREVIEW = /^\\s*#Preview\\b|:\\s*PreviewProvider\\b/u;\n\nexport default function shipsAPreviewWithEachNewView(\n\t_repoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n) {\n\tconst hints: Hint[] = [];\n\tlet newViews = 0;\n\tlet previewsAdded = 0;\n\tlet filesWithNewViewAndNoPreview = 0;\n\tfor (const [path, df] of diffFiles) {\n\t\tif (languageOf(path) !== \"swift\" || isTestPath(path)) {\n\t\t\tcontinue;\n\t\t}\n\t\tlet views = 0;\n\t\tlet previews = 0;\n\t\tfor (const [line, content] of df.addedLines) {\n\t\t\tif (isCommentLine(content, \"swift\")) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tconst view = VIEW_DECLARATION.exec(content);\n\t\t\tif (view) {\n\t\t\t\tviews += 1;\n\t\t\t\thints.push({\n\t\t\t\t\tfile: path,\n\t\t\t\t\tline,\n\t\t\t\t\tpattern: \"new view type\",\n\t\t\t\t\tcontext: content.trim().slice(0, 160),\n\t\t\t\t\tinDiff: true,\n\t\t\t\t\tflags: { name: view.groups?.name ?? \"\" },\n\t\t\t\t});\n\t\t\t} else if (PREVIEW.test(content)) {\n\t\t\t\tpreviews += 1;\n\t\t\t\thints.push({\n\t\t\t\t\tfile: path,\n\t\t\t\t\tline,\n\t\t\t\t\tpattern: \"preview\",\n\t\t\t\t\tcontext: content.trim().slice(0, 160),\n\t\t\t\t\tinDiff: true,\n\t\t\t\t\tflags: {},\n\t\t\t\t});\n\t\t\t}\n\t\t}\n\t\tnewViews += views;\n\t\tpreviewsAdded += previews;\n\t\tif (views > 0 && previews === 0) {\n\t\t\tfilesWithNewViewAndNoPreview += 1;\n\t\t}\n\t}\n\tconst directions: string[] = [];\n\tif (newViews > 0) {\n\t\tdirections.push(\n\t\t\t`${newViews} new view type(s) declared and ${previewsAdded} preview(s) added; ${filesWithNewViewAndNoPreview} file(s) declare a view and add no preview — a preview may live in another file of the change, so scan the whole diff before deciding. These counts pair no preview with a view. Read the previews and view bodies to trace the presentation coverage described in the criteria, including nested views and content delegated by an effect-only owner.`,\n\t\t);\n\t}\n\treturn {\n\t\thints: hints.slice(0, 40),\n\t\tmetrics: { newViews, previewsAdded, filesWithNewViewAndNoPreview },\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A SwiftUI view without a preview is a screen nobody can see without running the whole app to it, and the first thing the next person deletes when it breaks. A preview with representative data is the cheapest verification a view can have, and the way a reviewer sees what changed.","whatGoodLooksLike":"The new screens and presentation a change adds can be seen in a `#Preview` with representative sample data — including an empty, loading or error state when they have one — so they can be checked without launching the app.","groupSlug":"ios-app-craft","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 172\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Code only</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"158.5\" height=\"110.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"16\" y=\"61\" font-size=\"15\">ReceiptList</text>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"80\" width=\"112\" height=\"10\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"32\" y=\"96\" width=\"96\" height=\"10\" rx=\"3\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"192.75\" y=\"32.75\" width=\"110.5\" height=\"110.5\" rx=\"12\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/>\n  <text class=\"pv-fill-muted\" x=\"248\" y=\"93\" font-size=\"15\" text-anchor=\"middle\">No preview</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"168\" font-size=\"15\">Unseen until run</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Code and preview</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"158.5\" height=\"110.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink pv-mono\" x=\"352\" y=\"61\" font-size=\"15\">ReceiptList</text>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"80\" width=\"112\" height=\"10\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"368\" y=\"96\" width=\"96\" height=\"10\" rx=\"3\"/>\n  <text class=\"pv-fill-accent pv-mono\" x=\"352\" y=\"129\" font-size=\"15\">#Preview</text>\n  <path class=\"pv-stroke-muted\" d=\"M504 88h8\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M520 88l-8-5v10z\"/>\n  <rect class=\"pv-fill-surface pv-stroke-accent\" x=\"528.75\" y=\"32.75\" width=\"110.5\" height=\"110.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <rect class=\"pv-fill-muted\" x=\"568\" y=\"48\" width=\"32\" height=\"6\" rx=\"3\"/>\n  <text class=\"pv-fill-ink\" x=\"544\" y=\"85\" font-size=\"15\">Coffee €3</text>\n  <text class=\"pv-fill-ink\" x=\"544\" y=\"109\" font-size=\"15\">Bagel €2</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"168\" font-size=\"15\">Seen in review</text>\n</svg>\n","alt":"Code only: ReceiptList has no preview, so it stays unseen until someone runs the app. Code and preview: a #Preview shows ReceiptList with Coffee €3 and Bagel €2, so it is seen in review."},"guide":{"markdown":"## How to do it\n\n- Cover the presentation of each new SwiftUI view with a `#Preview` or a `PreviewProvider` in the same change. A preview of a host view counts when it shows that presentation.\n- When the view shows variable data, supply known values that match what it shows. For example, instead of `TaskList(tasks: [])`, pass tasks with varied titles.\n- Take the sample values from the preview, a sample helper, or fixed values that the view or its owner holds. A live fetch does not give sample data.\n- Preview each empty, loading or error state that the new presentation supports.\n- Some new views only start work and hold the model, and pass all that they show to a content view. Preview what the outer view draws itself, such as a navigation title, a toolbar or an overlay. Previews of the content view cover the rest.\n\n## When it does not apply\n\n- Your change adds no new SwiftUI view. It declares no new `struct … : View` outside test files.\n- Your change only edits a view that already exists.\n- Your change only touches models or other code that is not a view.\n- Your change only adds or edits previews.\n\nIt still applies when the new view is `private` or used only inside one file.\n\n## Common mistakes\n\n- Using only an empty list or a placeholder to preview a view that shows variable data. The preview exists, but it shows nothing that you can check. Instead, give it varied values that look like real data.\n- Relying on a fresh or live view model, or on a stored value such as `@AppStorage`, for the data. Nobody knows what the preview then shows. Instead, give the preview known sample values.\n- Adding a new row or section to a screen and counting on the screen’s preview. That preview covers the new view only when the screen really draws it with the preview’s data. Instead, check that it does, or preview the new view on its own.\n\n## Sources\n\n- [Adding previews to your interface files](https://developer.apple.com/documentation/xcode/adding-previews-to-your-interface-files), Apple Developer Documentation. A preview shows a view without running the app, and it can use sample data kept apart from the app.\n- [Build programmatic UI with Xcode Previews](https://developer.apple.com/videos/play/wwdc2023/10252/), Kevin Cathey, Apple, WWDC 2023. A preview sets up data and passes it into the view, and it runs the real code of your project.\n- [What to look for in a code review](https://google.github.io/eng-practices/review/reviewer/looking-for.html), Google Engineering Practices. A user interface change is hard to judge from its code alone, so a reviewer can ask to see it.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"New views ship with previews that show what they present"'::jsonb),'v5:a19cda53b5dcbb75938e9530070c3f12c188f750ebbdcbfbbc1924772d28f55e','practice:v3:bab95c21995ccab65a8255bf54d7de7e788f20ea695ec417bc8f17c06d481d93');
INSERT INTO _cutover_bundle VALUES('PRACTICE','declares-permissions-truthfully-at-point-of-use','scm.pull_request','{"name":"Declare permissions truthfully and ask at the point of use","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":{"skipReason":"the change touches no Swift source file","anyOf":[{"changedPathMatches":["**/*.swift"]}]},"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: a capability that needs the user''s permission arriving with a truthful usage description and a request made where the feature needs it.\n\n## The standard\nJudge the permission-bearing capabilities this change adds against three facts. (1) Declaration: when the platform requires usage-description keys for the access actually requested, the matching keys are present in `Info.plist`, `project.yml` or the target''s build settings. Determine the keys from the actual authorization API and deployment target, not an import or one fixed key per framework. For example, modern EventKit full or write-only calendar access uses the corresponding `NSCalendarsFullAccessUsageDescription` or `NSCalendarsWriteOnlyAccessUsageDescription`; legacy calendar APIs differ. Notification authorization needs no usage-description key, and the system photo picker needs no full-library authorization. (2) Truth: the description names what the app does with the access, not a placeholder (\"needed\", \"for the app\", an empty string). (3) Point of use: the authorization request (`requestWhenInUseAuthorization`, `requestAuthorization`, `PHPhotoLibrary.requestAuthorization`, …) is made from the feature that needs it, not from launch before the feature is reached. A root view can be that feature. Its `onAppear` is not early access when the view presents the feature that needs authorization. Judge added capabilities; an existing one the change did not touch is not this change''s.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the change adds no permission-bearing capability: no added permission-requiring access through `CoreLocation`, direct photo-library APIs, `AVFoundation` capture, `UserNotifications`, `EventKit`, `Contacts`, `HealthKit`, `AppTrackingTransparency` or an authorization request. `SwiftUI`''s `PhotosPicker` or `PHPickerViewController` alone needs no full-library permission and is not the occasion; an import alone does not establish restricted access.\n\n## Sources\n1. The diff (`work/change/diff.patch`) with the file list (`work/change/files.json`): the added capability code, authorization requests, and usage-description keys in `Info.plist`, `project.yml` or `*.pbxproj`. It establishes what was added where. It never establishes what the app already declared.\n2. The checkout (`<repositoryRoot>`): the existing `Info.plist`/`project.yml` for a key the change relies on but did not add, and the call site of the request. Read it to complete the picture; a key present there satisfies the declaration.\n3. The precomputed leads below these criteria: the permission-related references, requests and usage keys it found, as leads, never conclusions.\nIf the diff is truncated where the capability is added, or the project''s plist is unreadable, report a collection gap and record no observation.\n\n## Judge\nEnumerate the added capabilities first, then assess the standard.\n- MET: every added permission-requiring capability has a truthful usage key when required (in the change or checkout), and authorization is requested at the point of use. Quote the required key and request, or name the platform exemption.\n- NOT_MET: the key is present but the description is a placeholder, or the request runs before the feature that needs it is reached. Quote the description or the request site.\n- NOT_MET: an added capability requires a usage key but has none anywhere in the change or the checkout. Quote the capability line and say where you looked.\n- UNDETERMINED: the usage keys live in a build setting or generated file the checkout does not carry; name it.\nOne observation per review, on the single most consequential capability when there are several.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: a placeholder description, or a request made one screen early. MAJOR: a capability whose required usage key is missing everywhere, so its access cannot be authorized, or a request made at launch for a feature the user has not reached. Identical evidence yields identical severity.\n\n## Grounding\nQuote the `[L<n>]` capability or request line and the plist/project key as written. Never claim a key is missing without stating the files scanned; never claim a request site is launch without the call chain that reaches it.\n\n## Defer\nOver-broad permissions and insecure defaults belong to `avoids-insecure-defaults-and-over-broad-permissions`. Here only: is the permission declared truthfully and asked for at the point of use?","precomputeScript":"// Precompute HINTS for declares-permissions-truthfully-at-point-of-use: the permission-related references\n// and authorization requests ADDED in Swift files, and the usage-description keys located in the change\n// or in the first plist/project files of the checkout, each with its path. A reference names a type or\n// call to inspect; it does not show that the change requests restricted access. A key located in some file\n// does not show that the target in question declares it, nor does a key not located show that it does\n// not; the review reads the target, the actual API and the description.\nimport { readFile } from \"node:fs/promises\";\nimport path from \"node:path\";\n\nimport { globFilesSync } from \"../lib/files.ts\";\nimport { countLabel, sampleNote, scanAddedLines, type SourcePattern } from \"../lib/source-scan.ts\";\nimport type { DiffFile, Hint, PullRequestMetadata } from \"../lib/types.ts\";\n\n// reference kind -> [a permission-related type or call to inspect, usage keys that may declare its access].\n// A match is a place to look, not access: a type named in a signature or conformance requests nothing,\n// the system photo picker needs no library permission, and an image picker reaches the camera only when\n// the camera is its source.\nconst PERMISSION_REFERENCES: readonly [string, RegExp, string[]][] = [\n\t[\n\t\t\"Location\",\n\t\t/\\bCLLocationManager\\b/u,\n\t\t[\"NSLocationWhenInUseUsageDescription\", \"NSLocationAlwaysAndWhenInUseUsageDescription\"],\n\t],\n\t[\n\t\t\"Camera\",\n\t\t/\\bAVCaptureDevice\\b|\\bAVCaptureSession\\b|\\bsourceType\\s*[:=]\\s*\\.camera\\b|\\.isSourceTypeAvailable\\s*\\(\\s*\\.camera\\s*\\)/u,\n\t\t[\"NSCameraUsageDescription\"],\n\t],\n\t[\n\t\t\"Microphone\",\n\t\t/\\bAVAudioRecorder\\b|\\bAVAudioSession\\b.*record|\\.record\\(/u,\n\t\t[\"NSMicrophoneUsageDescription\"],\n\t],\n\t[\n\t\t\"PhotoLibrary\",\n\t\t/\\bPHPhotoLibrary\\b|\\bPHAsset\\b/u,\n\t\t[\"NSPhotoLibraryUsageDescription\", \"NSPhotoLibraryAddUsageDescription\"],\n\t],\n\t[\"Notifications\", /\\bUNUserNotificationCenter\\b/u, []],\n\t[\n\t\t\"Calendar\",\n\t\t/\\bEKEventStore\\b/u,\n\t\t[\n\t\t\t\"NSCalendarsUsageDescription\",\n\t\t\t\"NSCalendarsFullAccessUsageDescription\",\n\t\t\t\"NSCalendarsWriteOnlyAccessUsageDescription\",\n\t\t],\n\t],\n\t[\"Contacts\", /\\bCNContactStore\\b/u, [\"NSContactsUsageDescription\"]],\n\t[\n\t\t\"HealthKit\",\n\t\t/\\bHKHealthStore\\b/u,\n\t\t[\"NSHealthShareUsageDescription\", \"NSHealthUpdateUsageDescription\"],\n\t],\n\t[\"Tracking\", /\\bATTrackingManager\\b/u, [\"NSUserTrackingUsageDescription\"]],\n\t[\n\t\t\"Bluetooth\",\n\t\t/\\bCBCentralManager\\b|\\bCBPeripheralManager\\b/u,\n\t\t[\"NSBluetoothAlwaysUsageDescription\"],\n\t],\n\t[\"Motion\", /\\bCMMotionActivityManager\\b|\\bCMPedometer\\b/u, [\"NSMotionUsageDescription\"]],\n\t[\"Speech\", /\\bSFSpeechRecognizer\\b/u, [\"NSSpeechRecognitionUsageDescription\"]],\n\t[\"LocalNetwork\", /\\bNWBrowser\\b|\\bNetService\\b/u, [\"NSLocalNetworkUsageDescription\"]],\n];\n\nconst REQUEST: readonly SourcePattern[] = [\n\t[\n\t\t\"authorization request\",\n\t\t/\\brequest(?:WhenInUse|Always)?Authorization\\b|\\brequestAccess\\b|\\brequestTrackingAuthorization\\b|\\bPHPhotoLibrary\\.requestAuthorization\\b/u,\n\t],\n\t...PERMISSION_REFERENCES.map(([kind, re]): SourcePattern => [\n\t\t`permission-related reference ${kind}`,\n\t\tre,\n\t]),\n];\n\nconst USAGE_KEY = /\\b(?<key>NS\\w+UsageDescription)\\b/gu;\n\n/** How many plist/project files of the checkout are read for keys. */\nconst PROJECT_FILES_READ = 20;\n\ninterface CheckoutKeys {\n\tkeys: Map<string, string[]>;\n\tfilesFound: number;\n\tfilesRead: number;\n\tunreadable: number;\n}\n\nasync function usageKeysInCheckout(repoPath: string): Promise<CheckoutKeys> {\n\tconst keys = new Map<string, string[]>();\n\tlet files: string[] = [];\n\ttry {\n\t\tfiles = [\n\t\t\t...globFilesSync(\"**/Info.plist\", repoPath),\n\t\t\t...globFilesSync(\"**/project.yml\", repoPath),\n\t\t\t...globFilesSync(\"**/project.yaml\", repoPath),\n\t\t\t...globFilesSync(\"**/*.xcodeproj/project.pbxproj\", repoPath),\n\t\t].filter((f) => !/(?:^|\\/)(?:Pods|\\.build|DerivedData|Carthage)\\//u.test(f));\n\t} catch {\n\t\t// no readable checkout: no file read, so no key located\n\t}\n\tlet unreadable = 0;\n\tconst read = files.slice(0, PROJECT_FILES_READ);\n\tfor (const file of read) {\n\t\tlet text: string;\n\t\ttry {\n\t\t\ttext = await readFile(path.join(repoPath, file), \"utf8\");\n\t\t} catch {\n\t\t\tunreadable += 1;\n\t\t\tcontinue;\n\t\t}\n\t\tfor (const match of text.matchAll(USAGE_KEY)) {\n\t\t\tconst key = match.groups?.key ?? \"\";\n\t\t\tkeys.set(key, [...new Set([...(keys.get(key) ?? []), file])]);\n\t\t}\n\t}\n\treturn { keys, filesFound: files.length, filesRead: read.length - unreadable, unreadable };\n}\n\nexport default async function declaresPermissionsTruthfullyAtPointOfUse(\n\trepoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n) {\n\tconst scan = await scanAddedLines(repoPath, diffFiles, {\n\t\tlanguages: [\"swift\"],\n\t\tpatterns: REQUEST,\n\t});\n\tconst hints: Hint[] = [...scan.hints];\n\t// Usage keys the change itself adds, in any file.\n\tconst keysInChange = new Map<string, string>();\n\tfor (const [file, df] of diffFiles) {\n\t\tif (!/Info\\.plist$|project\\.ya?ml$|project\\.pbxproj$/u.test(file)) {\n\t\t\tcontinue;\n\t\t}\n\t\tfor (const [line, content] of df.addedLines) {\n\t\t\tfor (const match of content.matchAll(USAGE_KEY)) {\n\t\t\t\tconst key = match.groups?.key ?? \"\";\n\t\t\t\tkeysInChange.set(key, file);\n\t\t\t\thints.push({\n\t\t\t\t\tfile,\n\t\t\t\t\tline,\n\t\t\t\t\tpattern: \"usage key added\",\n\t\t\t\t\tcontext: content.trim().slice(0, 160),\n\t\t\t\t\tinDiff: true,\n\t\t\t\t\tflags: { key },\n\t\t\t\t});\n\t\t\t}\n\t\t}\n\t}\n\tconst checkout = await usageKeysInCheckout(repoPath);\n\tconst references = PERMISSION_REFERENCES.filter(([kind]) =>\n\t\tscan.counts.has(`permission-related reference ${kind}`),\n\t);\n\tconst located = (keys: string[]) =>\n\t\tkeys.flatMap((key) => {\n\t\t\tconst inChange = keysInChange.get(key);\n\t\t\tconst where = [\n\t\t\t\t...new Set([\n\t\t\t\t\t...(inChange === undefined ? [] : [inChange]),\n\t\t\t\t\t...(checkout.keys.get(key) ?? []),\n\t\t\t\t]),\n\t\t\t];\n\t\t\treturn where.length === 0 ? [] : [`${key} (${where.join(\", \")})`];\n\t\t});\n\tconst directions: string[] = [...sampleNote(scan)];\n\tif (references.length > 0) {\n\t\tconst read = `${String(checkout.filesRead)} of ${String(checkout.filesFound)} plist/project file(s) read${checkout.unreadable > 0 ? `, ${String(checkout.unreadable)} unreadable` : \"\"}`;\n\t\tdirections.push(\n\t\t\t`Permission-related references to inspect: ${references\n\t\t\t\t.map(([kind, , keys]) => {\n\t\t\t\t\tif (keys.length === 0) {\n\t\t\t\t\t\treturn `${kind} (no usage key applies)`;\n\t\t\t\t\t}\n\t\t\t\t\tconst found = located(keys);\n\t\t\t\t\treturn `${kind} — keys located: ${found.length > 0 ? found.join(\"; \") : \"none\"}`;\n\t\t\t\t})\n\t\t\t\t.join(\n\t\t\t\t\t\". \",\n\t\t\t\t)}. Searched the change and ${read}. A key located in a file does not show the target declares it, and a key not located does not show it is missing: read the target''s own Info.plist or build settings, and the key the actual API and deployment target require.`,\n\t\t);\n\t}\n\tconst requests = countLabel(scan, \"authorization request\");\n\tif (requests > 0) {\n\t\tdirections.push(\n\t\t\t`${requests} authorization requests were added. For each request, read the enclosing flag and the call chain. Decide whether it runs when the feature is reached or earlier. A root view can be the feature that needs authorization.`,\n\t\t);\n\t}\n\treturn {\n\t\thints: hints.slice(0, 40),\n\t\tmetrics: {\n\t\t\tpermissionReferenceKinds: references.length,\n\t\t\tauthorizationRequests: requests,\n\t\t\tusageKeysAdded: keysInChange.size,\n\t\t\tusageKeysLocatedInCheckout: checkout.keys.size,\n\t\t\tprojectFilesRead: checkout.filesRead,\n\t\t\tfilesScanned: scan.filesScanned,\n\t\t\tlinesAdded: scan.linesAdded,\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"Access that requires a usage description cannot be authorized without one. A specific explanation and a request made when the feature needs access help users make an informed choice. The declaration and the request are part of the feature.","whatGoodLooksLike":"When a change adds a capability that needs the user''s permission, the `Info.plist` usage description arrives in the same change, says truthfully what the app does with the access, and the permission is requested where the feature needs it, not at launch.","groupSlug":"ios-app-craft","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 180\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Asked at launch</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"94.5\" height=\"118.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <rect class=\"pv-fill-muted\" x=\"32\" y=\"48\" width=\"32\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"70\" width=\"64\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"82\" width=\"48\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"94\" width=\"56\" height=\"6\" rx=\"3\"/>\n  <path class=\"pv-stroke-muted\" d=\"M104 92h16\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M128 92l-8-5v10z\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"136.75\" y=\"32.75\" width=\"166.5\" height=\"118.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"152\" y=\"61\" font-size=\"15\">Camera</text>\n  <text class=\"pv-fill-muted\" x=\"152\" y=\"89\" font-size=\"15\">Access needed</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"152.75\" y=\"112.75\" width=\"70.5\" height=\"22.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"188\" y=\"129\" font-size=\"15\" text-anchor=\"middle\">Allow</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"176\" font-size=\"15\">User guesses why</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Asked when needed</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"94.5\" height=\"118.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <rect class=\"pv-fill-muted\" x=\"368\" y=\"48\" width=\"32\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"70\" width=\"64\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"82\" width=\"48\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-surface pv-stroke-ink\" x=\"352.75\" y=\"112.75\" width=\"62.5\" height=\"22.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"384\" y=\"129\" font-size=\"15\" text-anchor=\"middle\">Scan</text>\n  <path class=\"pv-stroke-muted\" d=\"M440 124h16\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M464 124l-8-5v10z\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"472.75\" y=\"32.75\" width=\"166.5\" height=\"118.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"488\" y=\"61\" font-size=\"15\">Camera</text>\n  <text class=\"pv-fill-accent\" x=\"488\" y=\"89\" font-size=\"15\">To scan receipts</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"488.75\" y=\"112.75\" width=\"70.5\" height=\"22.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"524\" y=\"129\" font-size=\"15\" text-anchor=\"middle\">Allow</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"176\" font-size=\"15\">User sees why</text>\n</svg>\n","alt":"Asked at launch, a camera prompt that says only “Access needed” leaves the user guessing why. Asked when needed, after the user taps Scan, a camera prompt that says “To scan receipts” lets the user see why."},"guide":{"markdown":"## How to do it\n\n- For each access that your change adds, add any missing usage key. The authorization API and the iOS version decide which key.\n- Put the key where the project keeps them: in `Info.plist`, in `project.yml`, or in the target’s build settings.\n- Write a plain usage description that says what the app does with the access. Instead of “Camera access is needed”, write “Scan receipts to add expenses.”\n- Ask for access from the feature that needs it, not at launch.\n- Before you add a key, check that the system needs one. Notifications need no usage description.\n\n## When it does not apply\n\n- Your change adds no access that needs the user’s permission. It adds no use of location, the photo library, camera or microphone capture, notifications, calendars, contacts, health data or tracking. It adds no authorization request.\n- Your change only adds the system photo picker, such as `PhotosPicker` or `PHPickerViewController`. It needs no access to the whole library.\n- Your change only imports a framework. An import alone asks for no access.\n\nIt still applies when the first screen is the feature that needs the permission.\n\n## Common mistakes\n\n- Adding one fixed key for each framework that you import. Instead, read which authorization call the code makes and which iOS version the app targets.\n- Asking for every permission when the app starts. The user has not reached the feature, so they cannot see why you ask. Instead, move each request to its feature.\n- Moving a request away from a first screen that needs the access. If the app opens on a map, asking for location when the map appears is the point of use. Instead, keep the request there.\n- Writing a placeholder such as “Needed for the app”, or leaving the text empty. Instead, name the task that the access makes possible, in words the user knows.\n\n## Sources\n\n- [Privacy](https://developer.apple.com/design/human-interface-guidelines/privacy), Apple Human Interface Guidelines. Ask for access when people use the feature that needs it. Avoid a launch request unless the app needs the access to function.\n- [Requesting access to protected resources](https://developer.apple.com/documentation/uikit/requesting-access-to-protected-resources), Apple Developer Documentation. The system asks once, and a missing purpose string can crash the app or lead to App Review rejection.\n- [App Review Guidelines](https://developer.apple.com/app-store/review/guidelines/), Apple, section 5.1.1 (ii). Purpose strings must clearly and completely describe how the app uses the data.\n- [Explanation beats context: the effect of timing and rationales on users’ runtime permission decisions](https://group.cispa.io/bugiel/publication/elbitar-usenix-21/elbitar-usenix-21.pdf), Elbitar and others, 2021. In a study with Android mockup apps, requests in context and requests with a reason were each granted more often.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Declare permissions truthfully and ask at the point of use","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":{"skipReason":"the change touches no Swift source file","anyOf":[{"changedPathMatches":["**/*.swift"]}]},"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: a capability that needs the user''s permission arriving with a truthful usage description and a request made where the feature needs it.\n\n## The standard\nJudge the permission-bearing capabilities this change adds against three facts. (1) Declaration: when the platform requires usage-description keys for the access actually requested, the matching keys are present in `Info.plist`, `project.yml` or the target''s build settings. Determine the keys from the actual authorization API and deployment target, not an import or one fixed key per framework. For example, modern EventKit full or write-only calendar access uses the corresponding `NSCalendarsFullAccessUsageDescription` or `NSCalendarsWriteOnlyAccessUsageDescription`; legacy calendar APIs differ. Notification authorization needs no usage-description key, and the system photo picker needs no full-library authorization. (2) Truth: the description names what the app does with the access, not a placeholder (\"needed\", \"for the app\", an empty string). (3) Point of use: the authorization request (`requestWhenInUseAuthorization`, `requestAuthorization`, `PHPhotoLibrary.requestAuthorization`, …) is made from the feature that needs it, not from launch before the feature is reached. A root view can be that feature. Its `onAppear` is not early access when the view presents the feature that needs authorization. Judge added capabilities; an existing one the change did not touch is not this change''s.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the change adds no permission-bearing capability: no added permission-requiring access through `CoreLocation`, direct photo-library APIs, `AVFoundation` capture, `UserNotifications`, `EventKit`, `Contacts`, `HealthKit`, `AppTrackingTransparency` or an authorization request. `SwiftUI`''s `PhotosPicker` or `PHPickerViewController` alone needs no full-library permission and is not the occasion; an import alone does not establish restricted access.\n\n## Sources\n1. The diff (`work/change/diff.patch`) with the file list (`work/change/files.json`): the added capability code, authorization requests, and usage-description keys in `Info.plist`, `project.yml` or `*.pbxproj`. It establishes what was added where. It never establishes what the app already declared.\n2. The checkout (`<repositoryRoot>`): the existing `Info.plist`/`project.yml` for a key the change relies on but did not add, and the call site of the request. Read it to complete the picture; a key present there satisfies the declaration.\n3. The precomputed leads below these criteria: the permission-related references, requests and usage keys it found, as leads, never conclusions.\nIf the diff is truncated where the capability is added, or the project''s plist is unreadable, report a collection gap and record no observation.\n\n## Judge\nEnumerate the added capabilities first, then assess the standard.\n- MET: every added permission-requiring capability has a truthful usage key when required (in the change or checkout), and authorization is requested at the point of use. Quote the required key and request, or name the platform exemption.\n- NOT_MET: the key is present but the description is a placeholder, or the request runs before the feature that needs it is reached. Quote the description or the request site.\n- NOT_MET: an added capability requires a usage key but has none anywhere in the change or the checkout. Quote the capability line and say where you looked.\n- UNDETERMINED: the usage keys live in a build setting or generated file the checkout does not carry; name it.\nOne observation per review, on the single most consequential capability when there are several.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: a placeholder description, or a request made one screen early. MAJOR: a capability whose required usage key is missing everywhere, so its access cannot be authorized, or a request made at launch for a feature the user has not reached. Identical evidence yields identical severity.\n\n## Grounding\nQuote the `[L<n>]` capability or request line and the plist/project key as written. Never claim a key is missing without stating the files scanned; never claim a request site is launch without the call chain that reaches it.\n\n## Defer\nOver-broad permissions and insecure defaults belong to `avoids-insecure-defaults-and-over-broad-permissions`. Here only: is the permission declared truthfully and asked for at the point of use?","precomputeScript":"// Precompute HINTS for declares-permissions-truthfully-at-point-of-use: the permission-related references\n// and authorization requests ADDED in Swift files, and the usage-description keys located in the change\n// or in the first plist/project files of the checkout, each with its path. A reference names a type or\n// call to inspect; it does not show that the change requests restricted access. A key located in some file\n// does not show that the target in question declares it, nor does a key not located show that it does\n// not; the review reads the target, the actual API and the description.\nimport { readFile } from \"node:fs/promises\";\nimport path from \"node:path\";\n\nimport { globFilesSync } from \"../lib/files.ts\";\nimport { countLabel, sampleNote, scanAddedLines, type SourcePattern } from \"../lib/source-scan.ts\";\nimport type { DiffFile, Hint, PullRequestMetadata } from \"../lib/types.ts\";\n\n// reference kind -> [a permission-related type or call to inspect, usage keys that may declare its access].\n// A match is a place to look, not access: a type named in a signature or conformance requests nothing,\n// the system photo picker needs no library permission, and an image picker reaches the camera only when\n// the camera is its source.\nconst PERMISSION_REFERENCES: readonly [string, RegExp, string[]][] = [\n\t[\n\t\t\"Location\",\n\t\t/\\bCLLocationManager\\b/u,\n\t\t[\"NSLocationWhenInUseUsageDescription\", \"NSLocationAlwaysAndWhenInUseUsageDescription\"],\n\t],\n\t[\n\t\t\"Camera\",\n\t\t/\\bAVCaptureDevice\\b|\\bAVCaptureSession\\b|\\bsourceType\\s*[:=]\\s*\\.camera\\b|\\.isSourceTypeAvailable\\s*\\(\\s*\\.camera\\s*\\)/u,\n\t\t[\"NSCameraUsageDescription\"],\n\t],\n\t[\n\t\t\"Microphone\",\n\t\t/\\bAVAudioRecorder\\b|\\bAVAudioSession\\b.*record|\\.record\\(/u,\n\t\t[\"NSMicrophoneUsageDescription\"],\n\t],\n\t[\n\t\t\"PhotoLibrary\",\n\t\t/\\bPHPhotoLibrary\\b|\\bPHAsset\\b/u,\n\t\t[\"NSPhotoLibraryUsageDescription\", \"NSPhotoLibraryAddUsageDescription\"],\n\t],\n\t[\"Notifications\", /\\bUNUserNotificationCenter\\b/u, []],\n\t[\n\t\t\"Calendar\",\n\t\t/\\bEKEventStore\\b/u,\n\t\t[\n\t\t\t\"NSCalendarsUsageDescription\",\n\t\t\t\"NSCalendarsFullAccessUsageDescription\",\n\t\t\t\"NSCalendarsWriteOnlyAccessUsageDescription\",\n\t\t],\n\t],\n\t[\"Contacts\", /\\bCNContactStore\\b/u, [\"NSContactsUsageDescription\"]],\n\t[\n\t\t\"HealthKit\",\n\t\t/\\bHKHealthStore\\b/u,\n\t\t[\"NSHealthShareUsageDescription\", \"NSHealthUpdateUsageDescription\"],\n\t],\n\t[\"Tracking\", /\\bATTrackingManager\\b/u, [\"NSUserTrackingUsageDescription\"]],\n\t[\n\t\t\"Bluetooth\",\n\t\t/\\bCBCentralManager\\b|\\bCBPeripheralManager\\b/u,\n\t\t[\"NSBluetoothAlwaysUsageDescription\"],\n\t],\n\t[\"Motion\", /\\bCMMotionActivityManager\\b|\\bCMPedometer\\b/u, [\"NSMotionUsageDescription\"]],\n\t[\"Speech\", /\\bSFSpeechRecognizer\\b/u, [\"NSSpeechRecognitionUsageDescription\"]],\n\t[\"LocalNetwork\", /\\bNWBrowser\\b|\\bNetService\\b/u, [\"NSLocalNetworkUsageDescription\"]],\n];\n\nconst REQUEST: readonly SourcePattern[] = [\n\t[\n\t\t\"authorization request\",\n\t\t/\\brequest(?:WhenInUse|Always)?Authorization\\b|\\brequestAccess\\b|\\brequestTrackingAuthorization\\b|\\bPHPhotoLibrary\\.requestAuthorization\\b/u,\n\t],\n\t...PERMISSION_REFERENCES.map(([kind, re]): SourcePattern => [\n\t\t`permission-related reference ${kind}`,\n\t\tre,\n\t]),\n];\n\nconst USAGE_KEY = /\\b(?<key>NS\\w+UsageDescription)\\b/gu;\n\n/** How many plist/project files of the checkout are read for keys. */\nconst PROJECT_FILES_READ = 20;\n\ninterface CheckoutKeys {\n\tkeys: Map<string, string[]>;\n\tfilesFound: number;\n\tfilesRead: number;\n\tunreadable: number;\n}\n\nasync function usageKeysInCheckout(repoPath: string): Promise<CheckoutKeys> {\n\tconst keys = new Map<string, string[]>();\n\tlet files: string[] = [];\n\ttry {\n\t\tfiles = [\n\t\t\t...globFilesSync(\"**/Info.plist\", repoPath),\n\t\t\t...globFilesSync(\"**/project.yml\", repoPath),\n\t\t\t...globFilesSync(\"**/project.yaml\", repoPath),\n\t\t\t...globFilesSync(\"**/*.xcodeproj/project.pbxproj\", repoPath),\n\t\t].filter((f) => !/(?:^|\\/)(?:Pods|\\.build|DerivedData|Carthage)\\//u.test(f));\n\t} catch {\n\t\t// no readable checkout: no file read, so no key located\n\t}\n\tlet unreadable = 0;\n\tconst read = files.slice(0, PROJECT_FILES_READ);\n\tfor (const file of read) {\n\t\tlet text: string;\n\t\ttry {\n\t\t\ttext = await readFile(path.join(repoPath, file), \"utf8\");\n\t\t} catch {\n\t\t\tunreadable += 1;\n\t\t\tcontinue;\n\t\t}\n\t\tfor (const match of text.matchAll(USAGE_KEY)) {\n\t\t\tconst key = match.groups?.key ?? \"\";\n\t\t\tkeys.set(key, [...new Set([...(keys.get(key) ?? []), file])]);\n\t\t}\n\t}\n\treturn { keys, filesFound: files.length, filesRead: read.length - unreadable, unreadable };\n}\n\nexport default async function declaresPermissionsTruthfullyAtPointOfUse(\n\trepoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n) {\n\tconst scan = await scanAddedLines(repoPath, diffFiles, {\n\t\tlanguages: [\"swift\"],\n\t\tpatterns: REQUEST,\n\t});\n\tconst hints: Hint[] = [...scan.hints];\n\t// Usage keys the change itself adds, in any file.\n\tconst keysInChange = new Map<string, string>();\n\tfor (const [file, df] of diffFiles) {\n\t\tif (!/Info\\.plist$|project\\.ya?ml$|project\\.pbxproj$/u.test(file)) {\n\t\t\tcontinue;\n\t\t}\n\t\tfor (const [line, content] of df.addedLines) {\n\t\t\tfor (const match of content.matchAll(USAGE_KEY)) {\n\t\t\t\tconst key = match.groups?.key ?? \"\";\n\t\t\t\tkeysInChange.set(key, file);\n\t\t\t\thints.push({\n\t\t\t\t\tfile,\n\t\t\t\t\tline,\n\t\t\t\t\tpattern: \"usage key added\",\n\t\t\t\t\tcontext: content.trim().slice(0, 160),\n\t\t\t\t\tinDiff: true,\n\t\t\t\t\tflags: { key },\n\t\t\t\t});\n\t\t\t}\n\t\t}\n\t}\n\tconst checkout = await usageKeysInCheckout(repoPath);\n\tconst references = PERMISSION_REFERENCES.filter(([kind]) =>\n\t\tscan.counts.has(`permission-related reference ${kind}`),\n\t);\n\tconst located = (keys: string[]) =>\n\t\tkeys.flatMap((key) => {\n\t\t\tconst inChange = keysInChange.get(key);\n\t\t\tconst where = [\n\t\t\t\t...new Set([\n\t\t\t\t\t...(inChange === undefined ? [] : [inChange]),\n\t\t\t\t\t...(checkout.keys.get(key) ?? []),\n\t\t\t\t]),\n\t\t\t];\n\t\t\treturn where.length === 0 ? [] : [`${key} (${where.join(\", \")})`];\n\t\t});\n\tconst directions: string[] = [...sampleNote(scan)];\n\tif (references.length > 0) {\n\t\tconst read = `${String(checkout.filesRead)} of ${String(checkout.filesFound)} plist/project file(s) read${checkout.unreadable > 0 ? `, ${String(checkout.unreadable)} unreadable` : \"\"}`;\n\t\tdirections.push(\n\t\t\t`Permission-related references to inspect: ${references\n\t\t\t\t.map(([kind, , keys]) => {\n\t\t\t\t\tif (keys.length === 0) {\n\t\t\t\t\t\treturn `${kind} (no usage key applies)`;\n\t\t\t\t\t}\n\t\t\t\t\tconst found = located(keys);\n\t\t\t\t\treturn `${kind} — keys located: ${found.length > 0 ? found.join(\"; \") : \"none\"}`;\n\t\t\t\t})\n\t\t\t\t.join(\n\t\t\t\t\t\". \",\n\t\t\t\t)}. Searched the change and ${read}. A key located in a file does not show the target declares it, and a key not located does not show it is missing: read the target''s own Info.plist or build settings, and the key the actual API and deployment target require.`,\n\t\t);\n\t}\n\tconst requests = countLabel(scan, \"authorization request\");\n\tif (requests > 0) {\n\t\tdirections.push(\n\t\t\t`${requests} authorization requests were added. For each request, read the enclosing flag and the call chain. Decide whether it runs when the feature is reached or earlier. A root view can be the feature that needs authorization.`,\n\t\t);\n\t}\n\treturn {\n\t\thints: hints.slice(0, 40),\n\t\tmetrics: {\n\t\t\tpermissionReferenceKinds: references.length,\n\t\t\tauthorizationRequests: requests,\n\t\t\tusageKeysAdded: keysInChange.size,\n\t\t\tusageKeysLocatedInCheckout: checkout.keys.size,\n\t\t\tprojectFilesRead: checkout.filesRead,\n\t\t\tfilesScanned: scan.filesScanned,\n\t\t\tlinesAdded: scan.linesAdded,\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"Access that requires a usage description cannot be authorized without one. A specific explanation and a request made when the feature needs access help users make an informed choice. The declaration and the request are part of the feature.","whatGoodLooksLike":"When a change adds a capability that needs the user''s permission, the `Info.plist` usage description arrives in the same change, says truthfully what the app does with the access, and the permission is requested where the feature needs it, not at launch.","groupSlug":"ios-app-craft","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 180\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Asked at launch</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"94.5\" height=\"118.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <rect class=\"pv-fill-muted\" x=\"32\" y=\"48\" width=\"32\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"70\" width=\"64\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"82\" width=\"48\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"16\" y=\"94\" width=\"56\" height=\"6\" rx=\"3\"/>\n  <path class=\"pv-stroke-muted\" d=\"M104 92h16\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M128 92l-8-5v10z\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"136.75\" y=\"32.75\" width=\"166.5\" height=\"118.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"152\" y=\"61\" font-size=\"15\">Camera</text>\n  <text class=\"pv-fill-muted\" x=\"152\" y=\"89\" font-size=\"15\">Access needed</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"152.75\" y=\"112.75\" width=\"70.5\" height=\"22.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"188\" y=\"129\" font-size=\"15\" text-anchor=\"middle\">Allow</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"176\" font-size=\"15\">User guesses why</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Asked when needed</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"94.5\" height=\"118.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <rect class=\"pv-fill-muted\" x=\"368\" y=\"48\" width=\"32\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"70\" width=\"64\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-muted\" x=\"352\" y=\"82\" width=\"48\" height=\"6\" rx=\"3\"/>\n  <rect class=\"pv-fill-surface pv-stroke-ink\" x=\"352.75\" y=\"112.75\" width=\"62.5\" height=\"22.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"384\" y=\"129\" font-size=\"15\" text-anchor=\"middle\">Scan</text>\n  <path class=\"pv-stroke-muted\" d=\"M440 124h16\" fill=\"none\" stroke-width=\"2\"/>\n  <path class=\"pv-fill-muted\" d=\"M464 124l-8-5v10z\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"472.75\" y=\"32.75\" width=\"166.5\" height=\"118.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"488\" y=\"61\" font-size=\"15\">Camera</text>\n  <text class=\"pv-fill-accent\" x=\"488\" y=\"89\" font-size=\"15\">To scan receipts</text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"488.75\" y=\"112.75\" width=\"70.5\" height=\"22.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"524\" y=\"129\" font-size=\"15\" text-anchor=\"middle\">Allow</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"176\" font-size=\"15\">User sees why</text>\n</svg>\n","alt":"Asked at launch, a camera prompt that says only “Access needed” leaves the user guessing why. Asked when needed, after the user taps Scan, a camera prompt that says “To scan receipts” lets the user see why."},"guide":{"markdown":"## How to do it\n\n- For each access that your change adds, add any missing usage key. The authorization API and the iOS version decide which key.\n- Put the key where the project keeps them: in `Info.plist`, in `project.yml`, or in the target’s build settings.\n- Write a plain usage description that says what the app does with the access. Instead of “Camera access is needed”, write “Scan receipts to add expenses.”\n- Ask for access from the feature that needs it, not at launch.\n- Before you add a key, check that the system needs one. Notifications need no usage description.\n\n## When it does not apply\n\n- Your change adds no access that needs the user’s permission. It adds no use of location, the photo library, camera or microphone capture, notifications, calendars, contacts, health data or tracking. It adds no authorization request.\n- Your change only adds the system photo picker, such as `PhotosPicker` or `PHPickerViewController`. It needs no access to the whole library.\n- Your change only imports a framework. An import alone asks for no access.\n\nIt still applies when the first screen is the feature that needs the permission.\n\n## Common mistakes\n\n- Adding one fixed key for each framework that you import. Instead, read which authorization call the code makes and which iOS version the app targets.\n- Asking for every permission when the app starts. The user has not reached the feature, so they cannot see why you ask. Instead, move each request to its feature.\n- Moving a request away from a first screen that needs the access. If the app opens on a map, asking for location when the map appears is the point of use. Instead, keep the request there.\n- Writing a placeholder such as “Needed for the app”, or leaving the text empty. Instead, name the task that the access makes possible, in words the user knows.\n\n## Sources\n\n- [Privacy](https://developer.apple.com/design/human-interface-guidelines/privacy), Apple Human Interface Guidelines. Ask for access when people use the feature that needs it. Avoid a launch request unless the app needs the access to function.\n- [Requesting access to protected resources](https://developer.apple.com/documentation/uikit/requesting-access-to-protected-resources), Apple Developer Documentation. The system asks once, and a missing purpose string can crash the app or lead to App Review rejection.\n- [App Review Guidelines](https://developer.apple.com/app-store/review/guidelines/), Apple, section 5.1.1 (ii). Purpose strings must clearly and completely describe how the app uses the data.\n- [Explanation beats context: the effect of timing and rationales on users’ runtime permission decisions](https://group.cispa.io/bugiel/publication/elbitar-usenix-21/elbitar-usenix-21.pdf), Elbitar and others, 2021. In a study with Android mockup apps, requests in context and requests with a reason were each granted more often.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Permissions say truthfully why and are asked for in use"'::jsonb),'v5:6d4b3b45f9a3371a6e003bde2ee6e4f4d6bc52870bf8b87a3435d51b15fcf8bd','practice:v3:fb5a15c9874c5728c220489fe90c093664078e54b957f65e8361b0157cd05012');
INSERT INTO _cutover_bundle VALUES('PRACTICE','uses-adaptive-colors-for-every-appearance','scm.pull_request','{"name":"Use adaptive colors so every appearance works","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":{"skipReason":"the change touches no Swift source file","anyOf":[{"changedPathMatches":["**/*.swift"]}]},"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the added interface takes its colors from colors that resolve per appearance — standard and dynamic system colors, semantic styles, materials, the accent color or asset colors with both appearances — not from literals that hold one value.\n\n## The standard\nJudge each color the change adds to SwiftUI views by what it resolves to, never by its spelling. A literal holds one value in every appearance: a color built from fixed components (`Color(red:green:blue:)`, `Color(white:)`, `Color(hex:)` or another hex-parsing initializer, `UIColor(red:green:blue:alpha:)`), white or black (`Color.white`, `.black`), a fixed UIKit constant such as `UIColor.green` or `UIColor.gray`, or a color converted from one of these (`Color(uiColor: .green)`), with or without opacity. An adaptive color resolves per appearance: SwiftUI''s standard colors, which Apple documents as context-dependent (such as `Color.green` or `.gray` where a `Color` is expected); UIKit''s dynamic colors (such as `UIColor.systemGreen`, `UIColor.label`, `UIColor.link`, or one built with `UIColor(dynamicProvider:)`); semantic styles (`.primary`, `.secondary`); materials (`.regularMaterial`); the accent (`.accentColor`, `.tint`); and an asset color whose colorset carries a dark appearance. These are examples of each kind, not complete lists. One spelling can name different types: `.green` passed to `foregroundStyle` is SwiftUI''s standard color, while `Color(.green)` converts UIKit''s fixed `UIColor.green` unless the app defines an asset of that name. A name the app defines — a `Color` or `UIColor` extension, an asset, a property named like a system color — is whatever its definition says. Read the expression''s type and, for the app''s own names, the definition or colorset; when neither the diff nor the checkout settles it, the color is unclassified. A literal is not a lapse where the color is the content: text or a symbol over a fill or image the same view sets, a brand color deliberately constant, a shadow or a translucent scrim over an image. Judge the added lines only.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the change sets no color in a SwiftUI view: no added `.foregroundStyle`, `.foregroundColor`, `.background`, `.fill`, `.tint`, `.shadow(color:` or `Color`/`UIColor` expression inside a view type. Added color lines are the occasion, whether or not they carry a lapse.\n\n## Sources\n1. The diff (`work/change/diff.patch`) with `[L<n>]` markers: each added color expression and the modifier chain it sits in — what it colors (text, background, fill) and what fill the same view sets around it. It establishes the literal and its role. It never establishes an unchanged view''s colors.\n2. The checkout (`<repositoryRoot>`): the asset catalog (`*.xcassets/<name>.colorset/Contents.json`) for a named color''s appearances, and a color extension (`Color+App.swift`) a name may resolve to. Read it to classify a name; a `Color(\"x\")` whose colorset has only one appearance is a literal in disguise.\n3. The precomputed leads below these criteria: the added color lines it found, each under the first shape its text shows, and, for each named asset color, whether its colorset has a dark appearance. A shape is spelling, not a type: leads, never conclusions, and a line holding several colors is listed once.\nIf the diff is truncated where a view body is edited, report a collection gap and record no observation.\n\n## Judge\nEnumerate the added color expressions first, then assess the standard.\n- MET: every added color is adaptive, or a literal only where the color is the content. Quote a representative adaptive color or a permitted literal and its content role.\n- NOT_MET: an added literal colors text on a system background, a screen or card background, or a fill the rest of the interface adapts around — one appearance baked in. Quote the line and name what it colors.\n- UNDETERMINED: a color the outcome turns on stays unclassified — an asset whose colorset the checkout does not carry, or an app-defined name whose definition it does not show; name it.\nOne observation per review, on the single most consequential literal when there are several; count the rest in the summary.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: one literal text or fill color on a secondary element. MAJOR: a screen or card background, or the primary text of a screen, hard-coded to one appearance. Identical evidence yields identical severity.\n\n## Grounding\nQuote the `[L<n>]` color line and, when the role matters, the fill or background line of the same view; for an asset color, the colorset''s appearances. Never call a color a literal without its line, nor classify one from its spelling alone; never call an asset or app-defined color adaptive without its colorset or its definition.\n\n## Defer\nLabels, fonts and colour-only state belong to `makes-ui-accessible-by-default`. Whether a text color reads well against the fill behind it is a contrast question, not this one: an adaptive color adapts even where a pairing reads poorly. Here only: does the color hold in both appearances?","precomputeScript":"// Precompute HINTS for uses-adaptive-colors-for-every-appearance: the color expressions ADDED inside\n// SwiftUI view types, each under the first shape its text shows, and for each named asset color whether\n// its colorset carries a dark appearance. A shape is spelling, not a type: `.green` given to\n// `foregroundStyle` is SwiftUI''s context-dependent standard color, `Color(.green)` converts UIKit''s fixed\n// `UIColor.green`, and a name the app defines is whatever its definition says. Only the shapes whose\n// spelling fixes the kind — components, white or black, semantic styles, materials, the accent — are\n// counted as literal or adaptive; the rest are left to the review to classify. The role a color plays —\n// content over a fill, or a background that bakes in one appearance — is the review''s to read from the\n// modifier chain.\nimport { readFile } from \"node:fs/promises\";\nimport path from \"node:path\";\n\nimport { globFilesSync } from \"../lib/files.ts\";\nimport { isJsonObject } from \"../lib/practice-contract.ts\";\nimport { countLabel, sampleNote, scanAddedLines, type SourcePattern } from \"../lib/source-scan.ts\";\nimport type { DiffFile, Hint, PullRequestMetadata } from \"../lib/types.ts\";\n\nconst SWIFTUI_VIEW = /\\b(?:View|App|Scene)\\b/u;\n\n// First match wins on a line, so the order runs from the shapes whose spelling fixes the kind to those it\n// does not.\nconst COLORS: readonly SourcePattern[] = [\n\t[\n\t\t\"fixed components\",\n\t\t/\\bColor\\s*\\(\\s*(?:red|hue|white|\\.sRGB|\\.displayP3|hex)\\s*:|\\bColor\\s*\\(\\s*\"#|\\bUIColor\\s*\\(\\s*(?:red|white|hue|displayP3Red)\\s*:/u,\n\t],\n\t[\"literal white/black\", /\\b(?:UI)?Color\\.(?:white|black)\\b|[:(,]\\s*\\.(?:white|black)\\b/u],\n\t[\"UIKit color\", /\\bUIColor\\s*\\.\\s*[a-z]\\w*|\\bColor\\s*\\(\\s*uiColor:\\s*\\.[a-z]\\w*/u],\n\t// `Color(_:bundle:)`: the bundle is optional, and without one the app''s main bundle is searched.\n\t[\"named asset\", /\\bColor\\s*\\(\\s*\"[^\"]+\"\\s*(?:\\)|,\\s*bundle\\s*:)/u],\n\t[\"Color from a value\", /\\bColor\\s*\\(\\s*\\.[a-z]\\w*/u],\n\t[\"semantic\", /\\.(?:primary|secondary|tertiary|quaternary)\\b/u],\n\t[\"material\", /\\.(?:ultraThin|thin|regular|thick|ultraThick|bar)Material\\b/u],\n\t[\"accent\", /\\.accentColor\\b|[:(,]\\s*\\.tint\\b(?!\\s*\\()/u],\n\t[\"SwiftUI Color member\", /\\bColor\\s*\\.\\s*[a-z]\\w*/u],\n\t[\n\t\t\"member given to a color modifier\",\n\t\t/\\.(?:foregroundStyle|foregroundColor|background|fill|tint|stroke|strokeBorder|border)\\s*\\(\\s*\\.[a-z]\\w*/u,\n\t],\n];\n\n/** The shapes whose spelling leaves the kind open: a type or a definition decides it. */\nconst TO_CLASSIFY = [\n\t\"UIKit color\",\n\t\"Color from a value\",\n\t\"SwiftUI Color member\",\n\t\"member given to a color modifier\",\n] as const;\n\n/** Whether a colorset carries a dark appearance; \"unknown\" when it cannot be read as one. */\ntype DarkAppearance = boolean | \"unknown\";\n\nfunction darkAppearanceOf(source: string): DarkAppearance {\n\tlet parsed: unknown;\n\ttry {\n\t\tparsed = JSON.parse(source);\n\t} catch {\n\t\treturn \"unknown\";\n\t}\n\tif (!isJsonObject(parsed) || !Array.isArray(parsed.colors) || parsed.colors.length === 0) {\n\t\treturn \"unknown\";\n\t}\n\t// Every entry is read before a missing dark appearance is a fact: one entry of another shape could\n\t// be the dark one.\n\tlet dark = false;\n\tfor (const entry of parsed.colors) {\n\t\tif (!isJsonObject(entry)) {\n\t\t\treturn \"unknown\";\n\t\t}\n\t\tif (entry.appearances === undefined) {\n\t\t\tcontinue;\n\t\t}\n\t\tif (\n\t\t\t!Array.isArray(entry.appearances) ||\n\t\t\t!entry.appearances.every(\n\t\t\t\t(appearance) =>\n\t\t\t\t\tisJsonObject(appearance) &&\n\t\t\t\t\ttypeof appearance.appearance === \"string\" &&\n\t\t\t\t\ttypeof appearance.value === \"string\",\n\t\t\t)\n\t\t) {\n\t\t\treturn \"unknown\";\n\t\t}\n\t\tdark ||= entry.appearances.some(\n\t\t\t(appearance) =>\n\t\t\t\tisJsonObject(appearance) &&\n\t\t\t\tappearance.appearance === \"luminosity\" &&\n\t\t\t\tappearance.value === \"dark\",\n\t\t);\n\t}\n\treturn dark;\n}\n\n/** The bundle a `Color(\"name\", bundle:)` names, or null for the main bundle it searches without one. */\nfunction bundleOf(context: string): string | null {\n\tconst bundle = /Color\\s*\\(\\s*\"[^\"]+\"\\s*,\\s*bundle\\s*:\\s*(?<bundle>[^,)]+(?:\\([^)]*\\))?)/u.exec(\n\t\tcontext,\n\t)?.groups?.bundle;\n\treturn bundle === undefined || /^(?:\\.main|Bundle\\.main|nil)\\s*$/u.test(bundle)\n\t\t? null\n\t\t: bundle.trim();\n}\n\n/** How many colorsets of the checkout are read; a name beyond them is unknown. */\nconst COLORSETS_READ = 200;\n\ninterface AssetColors {\n\t/** Every colorset path of the checkout by color name, read or not. */\n\tpaths: Map<string, string[]>;\n\t/** The appearances of the colorsets read, by path. */\n\tread: Map<string, DarkAppearance>;\n}\n\nfunction colorNameOf(file: string): string {\n\treturn (\n\t\tfile\n\t\t\t.split(\"/\")\n\t\t\t.at(-2)\n\t\t\t?.replace(/\\.colorset$/u, \"\") ?? \"\"\n\t);\n}\n\n/**\n * The appearance of a named color, from its one colorset: the only one of exactly that name, else the\n * only one whose name differs in case alone. Two candidates anywhere in the checkout, or one not read,\n * leave it unknown, since nothing here says which target''s catalog the view uses.\n */\nfunction appearanceOf({ paths, read }: AssetColors, name: string): DarkAppearance {\n\tconst exact = paths.get(name);\n\tconst candidates =\n\t\texact ??\n\t\t[...paths.entries()]\n\t\t\t.filter(([n]) => n.toLowerCase() === name.toLowerCase())\n\t\t\t.flatMap(([, files]) => files);\n\tconst [only] = candidates;\n\treturn candidates.length === 1 && only !== undefined ? (read.get(only) ?? \"unknown\") : \"unknown\";\n}\n\nasync function assetColors(repoPath: string): Promise<AssetColors> {\n\tlet all: string[] = [];\n\ttry {\n\t\tall = globFilesSync(\"**/*.xcassets/**/*.colorset/Contents.json\", repoPath);\n\t} catch {\n\t\t// no readable checkout: no colorset read\n\t}\n\tconst paths = new Map<string, string[]>();\n\tfor (const file of all) {\n\t\tconst name = colorNameOf(file);\n\t\tpaths.set(name, [...(paths.get(name) ?? []), file]);\n\t}\n\tconst read = new Map<string, DarkAppearance>();\n\tfor (const file of all.slice(0, COLORSETS_READ)) {\n\t\tlet dark: DarkAppearance = \"unknown\";\n\t\ttry {\n\t\t\tdark = darkAppearanceOf(await readFile(path.join(repoPath, file), \"utf8\"));\n\t\t} catch {\n\t\t\t// an unreadable colorset is not a fact about its appearances\n\t\t}\n\t\tread.set(file, dark);\n\t}\n\treturn { paths, read };\n}\n\nexport default async function usesAdaptiveColorsForEveryAppearance(\n\trepoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n) {\n\tconst scan = await scanAddedLines(repoPath, diffFiles, {\n\t\tlanguages: [\"swift\"],\n\t\tpatterns: COLORS,\n\t\tscope: SWIFTUI_VIEW,\n\t\tonlyInScope: true,\n\t});\n\tconst assets = await assetColors(repoPath);\n\tconst colorsetsFound = [...assets.paths.values()].reduce((sum, files) => sum + files.length, 0);\n\tconst hints: Hint[] = scan.hints.map((h) => {\n\t\tif (h.pattern !== \"named asset\" && h.pattern !== \"Color from a value\") {\n\t\t\treturn h;\n\t\t}\n\t\tconst name =\n\t\t\t/Color\\s*\\(\\s*\"(?<name>[^\"]+)\"/u.exec(h.context)?.groups?.name ??\n\t\t\t/Color\\s*\\(\\s*\\.(?<name>\\w+)/u.exec(h.context)?.groups?.name ??\n\t\t\t\"\";\n\t\t// Which catalog another bundle, such as a package''s `.module`, holds is not read here.\n\t\tconst bundle = h.pattern === \"named asset\" ? bundleOf(h.context) : null;\n\t\treturn {\n\t\t\t...h,\n\t\t\tflags: {\n\t\t\t\t...h.flags,\n\t\t\t\tasset: name,\n\t\t\t\t...(bundle === null ? {} : { bundle }),\n\t\t\t\thasDarkAppearance: bundle === null ? appearanceOf(assets, name) : \"unknown\",\n\t\t\t},\n\t\t};\n\t});\n\tconst inOtherBundles = hints.filter((h) => h.flags.bundle !== undefined).length;\n\tconst literals = countLabel(scan, \"fixed components\") + countLabel(scan, \"literal white/black\");\n\tconst toClassify = TO_CLASSIFY.reduce((sum, label) => sum + countLabel(scan, label), 0);\n\tconst systemAdaptive =\n\t\tcountLabel(scan, \"semantic\") + countLabel(scan, \"material\") + countLabel(scan, \"accent\");\n\tconst namedAssets = countLabel(scan, \"named asset\");\n\tconst assetsWithoutDarkAppearance = hints.filter(\n\t\t(h) => h.flags.hasDarkAppearance === false,\n\t).length;\n\tconst directions: string[] = [...sampleNote(scan)];\n\tif (literals > 0) {\n\t\tdirections.push(\n\t\t\t`Found ${literals} literal colors, ${systemAdaptive} system-adaptive colors and ${namedAssets} named asset colors added in view types. For each literal, read the modifier chain. Text over a fill the same view sets is content. A literal background or text on a system background can fix one appearance. A translucent scrim over an image is content, not an adaptive screen background.`,\n\t\t);\n\t}\n\tif (toClassify > 0) {\n\t\tdirections.push(\n\t\t\t`${toClassify} added line(s) name a color whose spelling does not settle its kind — a UIKit color, \\`Color(.name)\\`, a \\`Color\\` member or a member given to a color modifier. Read the type it resolves to and, for a name the app defines, its definition: SwiftUI''s standard colors and UIKit''s dynamic colors change with the appearance, UIKit''s fixed constants do not.`,\n\t\t);\n\t}\n\tif (scan.hints.length > 0) {\n\t\tdirections.push(\n\t\t\t\"Each line is listed once, under the first shape its text shows: enumerate every color a listed line holds.\",\n\t\t);\n\t}\n\tif (assetsWithoutDarkAppearance > 0) {\n\t\tdirections.push(\n\t\t\t`${assetsWithoutDarkAppearance} listed named asset color(s) whose colorset has no dark luminosity entry — read its color values and how it is used before judging whether it adapts.`,\n\t\t);\n\t}\n\tif (inOtherBundles > 0) {\n\t\tdirections.push(\n\t\t\t`${String(inOtherBundles)} listed named asset color(s) are looked up in a bundle other than the main one: which asset catalog that bundle holds was not resolved, so their dark appearance is unknown until the catalog is located.`,\n\t\t);\n\t}\n\tif (namedAssets > 0 && colorsetsFound > COLORSETS_READ) {\n\t\tdirections.push(\n\t\t\t`The checkout holds ${String(colorsetsFound)} colorsets and the first ${String(COLORSETS_READ)} were read: a named color whose colorset was not read is unknown, not missing.`,\n\t\t);\n\t}\n\treturn {\n\t\thints,\n\t\tmetrics: {\n\t\t\tliteralColors: literals,\n\t\t\tsystemAdaptiveColors: systemAdaptive,\n\t\t\tnamedAssetColors: namedAssets,\n\t\t\tcolorsToClassify: toClassify,\n\t\t\tassetsWithoutDarkAppearance,\n\t\t\tassetColorsInCheckout: colorsetsFound,\n\t\t\tfilesWithoutCheckout: scan.filesWithoutCheckout,\n\t\t\tfilesScanned: scan.filesScanned,\n\t\t\tlinesAdded: scan.linesAdded,\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A screen built from literal colors is right in one appearance and wrong in the other: white text vanishes on a light background, a hard-coded card stays white in Dark Mode, and every screen has to be revisited when the palette changes. Semantic and asset colors adapt on their own, and the whole app follows one palette.","whatGoodLooksLike":"Text, backgrounds and fills use colors that adapt — SwiftUI''s standard colors such as `.green`, UIKit''s dynamic colors such as `UIColor.systemTeal` — semantic colors (`.primary`, `.secondary`, `Color(.systemBackground)`), materials, the accent color or named asset colors with light and dark variants; a literal is used only where the color is part of the content, such as text over a fill the same view sets.","groupSlug":"ios-app-craft","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 140\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Text in <tspan class=\"pv-mono\">.black</tspan></text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"134.5\" height=\"78.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"16\" y=\"77\" font-size=\"15\">Coffee €3</text>\n  <rect class=\"pv-fill-ink pv-stroke-ink\" x=\"168.75\" y=\"32.75\" width=\"134.5\" height=\"78.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"136\" font-size=\"15\">Vanishes in one appearance</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Text in <tspan class=\"pv-fill-accent pv-mono\">.primary</tspan></text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"134.5\" height=\"78.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"352\" y=\"77\" font-size=\"15\">Coffee €3</text>\n  <rect class=\"pv-fill-ink pv-stroke-ink\" x=\"504.75\" y=\"32.75\" width=\"134.5\" height=\"78.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-surface\" x=\"520\" y=\"77\" font-size=\"15\">Coffee €3</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"136\" font-size=\"15\">Shows in both appearances</text>\n</svg>\n","alt":"With text in .black, Coffee €3 shows in light appearance and vanishes in dark. With text in .primary, Coffee €3 shows in both light and dark."},"guide":{"markdown":"## How to do it\n\n- Color text with a semantic style such as `.primary` or `.secondary`. For example, instead of `.foregroundStyle(.black)`, write `.foregroundStyle(.primary)`.\n- Give a screen or a card a system background such as `Color(.systemBackground)`, or a material such as `.regularMaterial`.\n- For a highlight, use the accent color with `.tint`, or a standard SwiftUI color such as `.green`. SwiftUI picks its value for the current appearance.\n- Use a named asset color whose color set defines both light and dark values.\n- Keep a fixed color only where the color is part of the content. One example is text on a fill that the same view sets. A brand color that you keep the same on purpose is another. So is a shadow or a see-through layer over an image.\n\n## When it does not apply\n\n- Your change sets no color in a SwiftUI view. It adds no `.foregroundStyle`, `.foregroundColor`, `.background`, `.fill`, `.tint` or `.shadow(color:)`, and no `Color` or `UIColor` inside a view.\n\nIt still applies when every color you add already adapts.\n\n## Common mistakes\n\n- Judging a color by its name. `.green` passed to `foregroundStyle` is SwiftUI’s standard green, and it adapts. `Color(.green)` converts UIKit’s fixed `UIColor.green`, and it does not. Instead, check the type and, for a name that your app defines, its definition or color set. `UIColor.systemGreen` is the adaptive UIKit green.\n- Using a color set with only one appearance for an interface color that must adapt. `Color(\"brand\")` then shows the same value in light and dark. Instead, add a dark value to the color set.\n- Building an interface color from fixed parts, such as `Color(red:green:blue:)` or a hex value, in a shared extension. Every screen that uses it gets one value. Instead, point the extension at an asset color or a system color.\n- Adding opacity to fixed white or black, such as `Color.black.opacity(0.7)`, for text on a system background. It still holds one value. Instead, use a semantic style or an adaptive system color.\n\n## Sources\n\n- [Dark Mode](https://developer.apple.com/design/human-interface-guidelines/dark-mode), Apple Human Interface Guidelines. Apple recommends system colors that adapt and custom color assets with values for both appearances.\n- [Supporting Dark Mode in your interface](https://developer.apple.com/documentation/uikit/supporting-dark-mode-in-your-interface), Apple Developer Documentation. Semantic colors and asset variants adapt to appearance changes, while colors built from fixed components do not.\n- [Color](https://developer.apple.com/documentation/swiftui/color), Apple Developer Documentation for SwiftUI. SwiftUI resolves system and asset colors when it draws, so their values can depend on the appearance.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Use adaptive colors so every appearance works","signals":["scm.pull_request.opened","scm.pull_request.ready","scm.pull_request.synchronized"],"evidenceRequirements":[{"sourceKind":"scm.pull-request.diff","stance":"EXHAUSTIVE"},{"sourceKind":"scm.repository.tree","stance":"CONTEXTUAL"}],"reviewWhen":{"draftStatus":["NOT_DRAFT"]},"subject":"AUTHOR","precondition":{"skipReason":"the change touches no Swift source file","anyOf":[{"changedPathMatches":["**/*.swift"]}]},"criteria":"Review this practice against the captured change: the added and removed lines and the surrounding code the practice names. Precompute hints are leads to inspect, never conclusions. Cite the old or new line coordinates of the diff; do not claim to have compiled or executed the change.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: the added interface takes its colors from colors that resolve per appearance — standard and dynamic system colors, semantic styles, materials, the accent color or asset colors with both appearances — not from literals that hold one value.\n\n## The standard\nJudge each color the change adds to SwiftUI views by what it resolves to, never by its spelling. A literal holds one value in every appearance: a color built from fixed components (`Color(red:green:blue:)`, `Color(white:)`, `Color(hex:)` or another hex-parsing initializer, `UIColor(red:green:blue:alpha:)`), white or black (`Color.white`, `.black`), a fixed UIKit constant such as `UIColor.green` or `UIColor.gray`, or a color converted from one of these (`Color(uiColor: .green)`), with or without opacity. An adaptive color resolves per appearance: SwiftUI''s standard colors, which Apple documents as context-dependent (such as `Color.green` or `.gray` where a `Color` is expected); UIKit''s dynamic colors (such as `UIColor.systemGreen`, `UIColor.label`, `UIColor.link`, or one built with `UIColor(dynamicProvider:)`); semantic styles (`.primary`, `.secondary`); materials (`.regularMaterial`); the accent (`.accentColor`, `.tint`); and an asset color whose colorset carries a dark appearance. These are examples of each kind, not complete lists. One spelling can name different types: `.green` passed to `foregroundStyle` is SwiftUI''s standard color, while `Color(.green)` converts UIKit''s fixed `UIColor.green` unless the app defines an asset of that name. A name the app defines — a `Color` or `UIColor` extension, an asset, a property named like a system color — is whatever its definition says. Read the expression''s type and, for the app''s own names, the definition or colorset; when neither the diff nor the checkout settles it, the color is unclassified. A literal is not a lapse where the color is the content: text or a symbol over a fill or image the same view sets, a brand color deliberately constant, a shadow or a translucent scrim over an image. Judge the added lines only.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the change sets no color in a SwiftUI view: no added `.foregroundStyle`, `.foregroundColor`, `.background`, `.fill`, `.tint`, `.shadow(color:` or `Color`/`UIColor` expression inside a view type. Added color lines are the occasion, whether or not they carry a lapse.\n\n## Sources\n1. The diff (`work/change/diff.patch`) with `[L<n>]` markers: each added color expression and the modifier chain it sits in — what it colors (text, background, fill) and what fill the same view sets around it. It establishes the literal and its role. It never establishes an unchanged view''s colors.\n2. The checkout (`<repositoryRoot>`): the asset catalog (`*.xcassets/<name>.colorset/Contents.json`) for a named color''s appearances, and a color extension (`Color+App.swift`) a name may resolve to. Read it to classify a name; a `Color(\"x\")` whose colorset has only one appearance is a literal in disguise.\n3. The precomputed leads below these criteria: the added color lines it found, each under the first shape its text shows, and, for each named asset color, whether its colorset has a dark appearance. A shape is spelling, not a type: leads, never conclusions, and a line holding several colors is listed once.\nIf the diff is truncated where a view body is edited, report a collection gap and record no observation.\n\n## Judge\nEnumerate the added color expressions first, then assess the standard.\n- MET: every added color is adaptive, or a literal only where the color is the content. Quote a representative adaptive color or a permitted literal and its content role.\n- NOT_MET: an added literal colors text on a system background, a screen or card background, or a fill the rest of the interface adapts around — one appearance baked in. Quote the line and name what it colors.\n- UNDETERMINED: a color the outcome turns on stays unclassified — an asset whose colorset the checkout does not carry, or an app-defined name whose definition it does not show; name it.\nOne observation per review, on the single most consequential literal when there are several; count the rest in the summary.\n\n## Severity\nNOT_MET only; never above MAJOR on this alone — non-blocking. MINOR, the usual band: one literal text or fill color on a secondary element. MAJOR: a screen or card background, or the primary text of a screen, hard-coded to one appearance. Identical evidence yields identical severity.\n\n## Grounding\nQuote the `[L<n>]` color line and, when the role matters, the fill or background line of the same view; for an asset color, the colorset''s appearances. Never call a color a literal without its line, nor classify one from its spelling alone; never call an asset or app-defined color adaptive without its colorset or its definition.\n\n## Defer\nLabels, fonts and colour-only state belong to `makes-ui-accessible-by-default`. Whether a text color reads well against the fill behind it is a contrast question, not this one: an adaptive color adapts even where a pairing reads poorly. Here only: does the color hold in both appearances?","precomputeScript":"// Precompute HINTS for uses-adaptive-colors-for-every-appearance: the color expressions ADDED inside\n// SwiftUI view types, each under the first shape its text shows, and for each named asset color whether\n// its colorset carries a dark appearance. A shape is spelling, not a type: `.green` given to\n// `foregroundStyle` is SwiftUI''s context-dependent standard color, `Color(.green)` converts UIKit''s fixed\n// `UIColor.green`, and a name the app defines is whatever its definition says. Only the shapes whose\n// spelling fixes the kind — components, white or black, semantic styles, materials, the accent — are\n// counted as literal or adaptive; the rest are left to the review to classify. The role a color plays —\n// content over a fill, or a background that bakes in one appearance — is the review''s to read from the\n// modifier chain.\nimport { readFile } from \"node:fs/promises\";\nimport path from \"node:path\";\n\nimport { globFilesSync } from \"../lib/files.ts\";\nimport { isJsonObject } from \"../lib/practice-contract.ts\";\nimport { countLabel, sampleNote, scanAddedLines, type SourcePattern } from \"../lib/source-scan.ts\";\nimport type { DiffFile, Hint, PullRequestMetadata } from \"../lib/types.ts\";\n\nconst SWIFTUI_VIEW = /\\b(?:View|App|Scene)\\b/u;\n\n// First match wins on a line, so the order runs from the shapes whose spelling fixes the kind to those it\n// does not.\nconst COLORS: readonly SourcePattern[] = [\n\t[\n\t\t\"fixed components\",\n\t\t/\\bColor\\s*\\(\\s*(?:red|hue|white|\\.sRGB|\\.displayP3|hex)\\s*:|\\bColor\\s*\\(\\s*\"#|\\bUIColor\\s*\\(\\s*(?:red|white|hue|displayP3Red)\\s*:/u,\n\t],\n\t[\"literal white/black\", /\\b(?:UI)?Color\\.(?:white|black)\\b|[:(,]\\s*\\.(?:white|black)\\b/u],\n\t[\"UIKit color\", /\\bUIColor\\s*\\.\\s*[a-z]\\w*|\\bColor\\s*\\(\\s*uiColor:\\s*\\.[a-z]\\w*/u],\n\t// `Color(_:bundle:)`: the bundle is optional, and without one the app''s main bundle is searched.\n\t[\"named asset\", /\\bColor\\s*\\(\\s*\"[^\"]+\"\\s*(?:\\)|,\\s*bundle\\s*:)/u],\n\t[\"Color from a value\", /\\bColor\\s*\\(\\s*\\.[a-z]\\w*/u],\n\t[\"semantic\", /\\.(?:primary|secondary|tertiary|quaternary)\\b/u],\n\t[\"material\", /\\.(?:ultraThin|thin|regular|thick|ultraThick|bar)Material\\b/u],\n\t[\"accent\", /\\.accentColor\\b|[:(,]\\s*\\.tint\\b(?!\\s*\\()/u],\n\t[\"SwiftUI Color member\", /\\bColor\\s*\\.\\s*[a-z]\\w*/u],\n\t[\n\t\t\"member given to a color modifier\",\n\t\t/\\.(?:foregroundStyle|foregroundColor|background|fill|tint|stroke|strokeBorder|border)\\s*\\(\\s*\\.[a-z]\\w*/u,\n\t],\n];\n\n/** The shapes whose spelling leaves the kind open: a type or a definition decides it. */\nconst TO_CLASSIFY = [\n\t\"UIKit color\",\n\t\"Color from a value\",\n\t\"SwiftUI Color member\",\n\t\"member given to a color modifier\",\n] as const;\n\n/** Whether a colorset carries a dark appearance; \"unknown\" when it cannot be read as one. */\ntype DarkAppearance = boolean | \"unknown\";\n\nfunction darkAppearanceOf(source: string): DarkAppearance {\n\tlet parsed: unknown;\n\ttry {\n\t\tparsed = JSON.parse(source);\n\t} catch {\n\t\treturn \"unknown\";\n\t}\n\tif (!isJsonObject(parsed) || !Array.isArray(parsed.colors) || parsed.colors.length === 0) {\n\t\treturn \"unknown\";\n\t}\n\t// Every entry is read before a missing dark appearance is a fact: one entry of another shape could\n\t// be the dark one.\n\tlet dark = false;\n\tfor (const entry of parsed.colors) {\n\t\tif (!isJsonObject(entry)) {\n\t\t\treturn \"unknown\";\n\t\t}\n\t\tif (entry.appearances === undefined) {\n\t\t\tcontinue;\n\t\t}\n\t\tif (\n\t\t\t!Array.isArray(entry.appearances) ||\n\t\t\t!entry.appearances.every(\n\t\t\t\t(appearance) =>\n\t\t\t\t\tisJsonObject(appearance) &&\n\t\t\t\t\ttypeof appearance.appearance === \"string\" &&\n\t\t\t\t\ttypeof appearance.value === \"string\",\n\t\t\t)\n\t\t) {\n\t\t\treturn \"unknown\";\n\t\t}\n\t\tdark ||= entry.appearances.some(\n\t\t\t(appearance) =>\n\t\t\t\tisJsonObject(appearance) &&\n\t\t\t\tappearance.appearance === \"luminosity\" &&\n\t\t\t\tappearance.value === \"dark\",\n\t\t);\n\t}\n\treturn dark;\n}\n\n/** The bundle a `Color(\"name\", bundle:)` names, or null for the main bundle it searches without one. */\nfunction bundleOf(context: string): string | null {\n\tconst bundle = /Color\\s*\\(\\s*\"[^\"]+\"\\s*,\\s*bundle\\s*:\\s*(?<bundle>[^,)]+(?:\\([^)]*\\))?)/u.exec(\n\t\tcontext,\n\t)?.groups?.bundle;\n\treturn bundle === undefined || /^(?:\\.main|Bundle\\.main|nil)\\s*$/u.test(bundle)\n\t\t? null\n\t\t: bundle.trim();\n}\n\n/** How many colorsets of the checkout are read; a name beyond them is unknown. */\nconst COLORSETS_READ = 200;\n\ninterface AssetColors {\n\t/** Every colorset path of the checkout by color name, read or not. */\n\tpaths: Map<string, string[]>;\n\t/** The appearances of the colorsets read, by path. */\n\tread: Map<string, DarkAppearance>;\n}\n\nfunction colorNameOf(file: string): string {\n\treturn (\n\t\tfile\n\t\t\t.split(\"/\")\n\t\t\t.at(-2)\n\t\t\t?.replace(/\\.colorset$/u, \"\") ?? \"\"\n\t);\n}\n\n/**\n * The appearance of a named color, from its one colorset: the only one of exactly that name, else the\n * only one whose name differs in case alone. Two candidates anywhere in the checkout, or one not read,\n * leave it unknown, since nothing here says which target''s catalog the view uses.\n */\nfunction appearanceOf({ paths, read }: AssetColors, name: string): DarkAppearance {\n\tconst exact = paths.get(name);\n\tconst candidates =\n\t\texact ??\n\t\t[...paths.entries()]\n\t\t\t.filter(([n]) => n.toLowerCase() === name.toLowerCase())\n\t\t\t.flatMap(([, files]) => files);\n\tconst [only] = candidates;\n\treturn candidates.length === 1 && only !== undefined ? (read.get(only) ?? \"unknown\") : \"unknown\";\n}\n\nasync function assetColors(repoPath: string): Promise<AssetColors> {\n\tlet all: string[] = [];\n\ttry {\n\t\tall = globFilesSync(\"**/*.xcassets/**/*.colorset/Contents.json\", repoPath);\n\t} catch {\n\t\t// no readable checkout: no colorset read\n\t}\n\tconst paths = new Map<string, string[]>();\n\tfor (const file of all) {\n\t\tconst name = colorNameOf(file);\n\t\tpaths.set(name, [...(paths.get(name) ?? []), file]);\n\t}\n\tconst read = new Map<string, DarkAppearance>();\n\tfor (const file of all.slice(0, COLORSETS_READ)) {\n\t\tlet dark: DarkAppearance = \"unknown\";\n\t\ttry {\n\t\t\tdark = darkAppearanceOf(await readFile(path.join(repoPath, file), \"utf8\"));\n\t\t} catch {\n\t\t\t// an unreadable colorset is not a fact about its appearances\n\t\t}\n\t\tread.set(file, dark);\n\t}\n\treturn { paths, read };\n}\n\nexport default async function usesAdaptiveColorsForEveryAppearance(\n\trepoPath: string,\n\tdiffFiles: Map<string, DiffFile>,\n\t_metadata: PullRequestMetadata,\n) {\n\tconst scan = await scanAddedLines(repoPath, diffFiles, {\n\t\tlanguages: [\"swift\"],\n\t\tpatterns: COLORS,\n\t\tscope: SWIFTUI_VIEW,\n\t\tonlyInScope: true,\n\t});\n\tconst assets = await assetColors(repoPath);\n\tconst colorsetsFound = [...assets.paths.values()].reduce((sum, files) => sum + files.length, 0);\n\tconst hints: Hint[] = scan.hints.map((h) => {\n\t\tif (h.pattern !== \"named asset\" && h.pattern !== \"Color from a value\") {\n\t\t\treturn h;\n\t\t}\n\t\tconst name =\n\t\t\t/Color\\s*\\(\\s*\"(?<name>[^\"]+)\"/u.exec(h.context)?.groups?.name ??\n\t\t\t/Color\\s*\\(\\s*\\.(?<name>\\w+)/u.exec(h.context)?.groups?.name ??\n\t\t\t\"\";\n\t\t// Which catalog another bundle, such as a package''s `.module`, holds is not read here.\n\t\tconst bundle = h.pattern === \"named asset\" ? bundleOf(h.context) : null;\n\t\treturn {\n\t\t\t...h,\n\t\t\tflags: {\n\t\t\t\t...h.flags,\n\t\t\t\tasset: name,\n\t\t\t\t...(bundle === null ? {} : { bundle }),\n\t\t\t\thasDarkAppearance: bundle === null ? appearanceOf(assets, name) : \"unknown\",\n\t\t\t},\n\t\t};\n\t});\n\tconst inOtherBundles = hints.filter((h) => h.flags.bundle !== undefined).length;\n\tconst literals = countLabel(scan, \"fixed components\") + countLabel(scan, \"literal white/black\");\n\tconst toClassify = TO_CLASSIFY.reduce((sum, label) => sum + countLabel(scan, label), 0);\n\tconst systemAdaptive =\n\t\tcountLabel(scan, \"semantic\") + countLabel(scan, \"material\") + countLabel(scan, \"accent\");\n\tconst namedAssets = countLabel(scan, \"named asset\");\n\tconst assetsWithoutDarkAppearance = hints.filter(\n\t\t(h) => h.flags.hasDarkAppearance === false,\n\t).length;\n\tconst directions: string[] = [...sampleNote(scan)];\n\tif (literals > 0) {\n\t\tdirections.push(\n\t\t\t`Found ${literals} literal colors, ${systemAdaptive} system-adaptive colors and ${namedAssets} named asset colors added in view types. For each literal, read the modifier chain. Text over a fill the same view sets is content. A literal background or text on a system background can fix one appearance. A translucent scrim over an image is content, not an adaptive screen background.`,\n\t\t);\n\t}\n\tif (toClassify > 0) {\n\t\tdirections.push(\n\t\t\t`${toClassify} added line(s) name a color whose spelling does not settle its kind — a UIKit color, \\`Color(.name)\\`, a \\`Color\\` member or a member given to a color modifier. Read the type it resolves to and, for a name the app defines, its definition: SwiftUI''s standard colors and UIKit''s dynamic colors change with the appearance, UIKit''s fixed constants do not.`,\n\t\t);\n\t}\n\tif (scan.hints.length > 0) {\n\t\tdirections.push(\n\t\t\t\"Each line is listed once, under the first shape its text shows: enumerate every color a listed line holds.\",\n\t\t);\n\t}\n\tif (assetsWithoutDarkAppearance > 0) {\n\t\tdirections.push(\n\t\t\t`${assetsWithoutDarkAppearance} listed named asset color(s) whose colorset has no dark luminosity entry — read its color values and how it is used before judging whether it adapts.`,\n\t\t);\n\t}\n\tif (inOtherBundles > 0) {\n\t\tdirections.push(\n\t\t\t`${String(inOtherBundles)} listed named asset color(s) are looked up in a bundle other than the main one: which asset catalog that bundle holds was not resolved, so their dark appearance is unknown until the catalog is located.`,\n\t\t);\n\t}\n\tif (namedAssets > 0 && colorsetsFound > COLORSETS_READ) {\n\t\tdirections.push(\n\t\t\t`The checkout holds ${String(colorsetsFound)} colorsets and the first ${String(COLORSETS_READ)} were read: a named color whose colorset was not read is unknown, not missing.`,\n\t\t);\n\t}\n\treturn {\n\t\thints,\n\t\tmetrics: {\n\t\t\tliteralColors: literals,\n\t\t\tsystemAdaptiveColors: systemAdaptive,\n\t\t\tnamedAssetColors: namedAssets,\n\t\t\tcolorsToClassify: toClassify,\n\t\t\tassetsWithoutDarkAppearance,\n\t\t\tassetColorsInCheckout: colorsetsFound,\n\t\t\tfilesWithoutCheckout: scan.filesWithoutCheckout,\n\t\t\tfilesScanned: scan.filesScanned,\n\t\t\tlinesAdded: scan.linesAdded,\n\t\t},\n\t\tdirections,\n\t};\n}\n","automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"RUNTIME_BEHAVIOR_NOT_OBSERVED","description":"Repository evidence does not establish behavior in a deployed runtime."}],"insufficiencyReason":null},"whyItMatters":"A screen built from literal colors is right in one appearance and wrong in the other: white text vanishes on a light background, a hard-coded card stays white in Dark Mode, and every screen has to be revisited when the palette changes. Semantic and asset colors adapt on their own, and the whole app follows one palette.","whatGoodLooksLike":"Text, backgrounds and fills use colors that adapt — SwiftUI''s standard colors such as `.green`, UIKit''s dynamic colors such as `UIColor.systemTeal` — semantic colors (`.primary`, `.secondary`, `Color(.systemBackground)`), materials, the accent color or named asset colors with light and dark variants; a literal is used only where the color is part of the content, such as text over a fill the same view sets.","groupSlug":"ios-app-craft","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 140\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Text in <tspan class=\"pv-mono\">.black</tspan></text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"0.75\" y=\"32.75\" width=\"134.5\" height=\"78.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"16\" y=\"77\" font-size=\"15\">Coffee €3</text>\n  <rect class=\"pv-fill-ink pv-stroke-ink\" x=\"168.75\" y=\"32.75\" width=\"134.5\" height=\"78.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"136\" font-size=\"15\">Vanishes in one appearance</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Text in <tspan class=\"pv-fill-accent pv-mono\">.primary</tspan></text>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"336.75\" y=\"32.75\" width=\"134.5\" height=\"78.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-ink\" x=\"352\" y=\"77\" font-size=\"15\">Coffee €3</text>\n  <rect class=\"pv-fill-ink pv-stroke-ink\" x=\"504.75\" y=\"32.75\" width=\"134.5\" height=\"78.5\" rx=\"12\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-surface\" x=\"520\" y=\"77\" font-size=\"15\">Coffee €3</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"136\" font-size=\"15\">Shows in both appearances</text>\n</svg>\n","alt":"With text in .black, Coffee €3 shows in light appearance and vanishes in dark. With text in .primary, Coffee €3 shows in both light and dark."},"guide":{"markdown":"## How to do it\n\n- Color text with a semantic style such as `.primary` or `.secondary`. For example, instead of `.foregroundStyle(.black)`, write `.foregroundStyle(.primary)`.\n- Give a screen or a card a system background such as `Color(.systemBackground)`, or a material such as `.regularMaterial`.\n- For a highlight, use the accent color with `.tint`, or a standard SwiftUI color such as `.green`. SwiftUI picks its value for the current appearance.\n- Use a named asset color whose color set defines both light and dark values.\n- Keep a fixed color only where the color is part of the content. One example is text on a fill that the same view sets. A brand color that you keep the same on purpose is another. So is a shadow or a see-through layer over an image.\n\n## When it does not apply\n\n- Your change sets no color in a SwiftUI view. It adds no `.foregroundStyle`, `.foregroundColor`, `.background`, `.fill`, `.tint` or `.shadow(color:)`, and no `Color` or `UIColor` inside a view.\n\nIt still applies when every color you add already adapts.\n\n## Common mistakes\n\n- Judging a color by its name. `.green` passed to `foregroundStyle` is SwiftUI’s standard green, and it adapts. `Color(.green)` converts UIKit’s fixed `UIColor.green`, and it does not. Instead, check the type and, for a name that your app defines, its definition or color set. `UIColor.systemGreen` is the adaptive UIKit green.\n- Using a color set with only one appearance for an interface color that must adapt. `Color(\"brand\")` then shows the same value in light and dark. Instead, add a dark value to the color set.\n- Building an interface color from fixed parts, such as `Color(red:green:blue:)` or a hex value, in a shared extension. Every screen that uses it gets one value. Instead, point the extension at an asset color or a system color.\n- Adding opacity to fixed white or black, such as `Color.black.opacity(0.7)`, for text on a system background. It still holds one value. Instead, use a semantic style or an adaptive system color.\n\n## Sources\n\n- [Dark Mode](https://developer.apple.com/design/human-interface-guidelines/dark-mode), Apple Human Interface Guidelines. Apple recommends system colors that adapt and custom color assets with values for both appearances.\n- [Supporting Dark Mode in your interface](https://developer.apple.com/documentation/uikit/supporting-dark-mode-in-your-interface), Apple Developer Documentation. Semantic colors and asset variants adapt to appearance changes, while colors built from fixed components do not.\n- [Color](https://developer.apple.com/documentation/swiftui/color), Apple Developer Documentation for SwiftUI. SwiftUI resolves system and asset colors when it draws, so their values can depend on the appearance.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Colors adapt to light and dark appearance alike"'::jsonb),'v5:2a3a9921024fd5caef483ee6e8ba9acbbe23df75d399e3f015ce67b19dee164a','practice:v3:925bc50fec110bafecd5edbcfac34de4670004a0c49d189d8b07e2f029b9eb90');
INSERT INTO _cutover_bundle VALUES('GROUP','communication',NULL,'{"name":"Communicating in the open","description":"How you talk to teammates in shared channels: ask questions someone can actually answer, give answers people can act on, and keep others informed about where the work stands and what is blocking it. This is about the clarity of the exchange, not the correctness of the code being discussed.","icon":"MessageCircle","color":"violet"}'::jsonb,'{"name":"Communicating in the open","description":"How you talk to teammates in shared channels: ask questions someone can actually answer, give answers people can act on, and keep others informed about where the work stands and what is blocking it. This is about the clarity of the exchange, not the correctness of the code being discussed.","icon":"MessageCircle","color":"violet"}'::jsonb,'b7460bd63ee667f3f95e6af11b5f9ddb479b6d49b558d3da040e1574c27fe3b1','group:v1:b7460bd63ee667f3f95e6af11b5f9ddb479b6d49b558d3da040e1574c27fe3b1');
INSERT INTO _cutover_bundle VALUES('PRACTICE','asks-answerable-questions','chat.conversation_thread','{"name":"Ask questions a teammate can answer","signals":["chat.conversation_thread.settled"],"evidenceRequirements":[{"sourceKind":"slack.conversation.thread","stance":"EXHAUSTIVE"}],"reviewWhen":{},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured conversation: the turns the practice names, read in their surrounding context. Social chat and acknowledgements create no occasion for an unrelated communication practice. Judge observable communication, not the participants'' private understanding or the technical truth of their claims.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: a question posed in the captured exchange carries enough context — the goal, what was tried, what happened — for a teammate to answer it in one reply.\n\n## The standard\nJudge whether a question raised in this conversation gives a teammate enough to answer it in a single reply, rather than forcing a round of clarifying questions first. A well-formed ask names the concrete goal, what was already tried, and what actually happened or is blocking. A bare \"it doesn''t work\" or \"how do I do this?\" with no context makes the responder guess. Judge only the observable way the question is posed; never whether the underlying problem is real, hard or worth solving. Use judgment about how much context the question genuinely needs: a quick clarification among people who plainly share the context is not a defect. The review is about one participant. Judge only the turns that `context/conversation_thread.json` marks `\"underReview\": true`. The other turns are context.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the turn is not actually a question (a statement, an acknowledgement, social chat), or when there is no settled conversation to read. A real question whose needed context is supplied by the surrounding turns is not NOT_APPLICABLE; it is MET.\n\n## Sources\n1. The turn that poses the question (`context/conversation_thread.json`): its stated objective, what was tried, the exact behaviour seen or the specific point of confusion. It establishes how the question is posed. It never establishes whether the problem is real or worth solving.\n2. The surrounding turns of the same thread (`context/conversation_thread.json`): earlier turns may supply the context the question leans on; a later reply that has to ask what was meant shows what the responder had to extract first. They establish what context was shared inside the captured thread and nothing outside it.\nAn image or attachment in a turn: read its caption and the sentence around it. An external link: nothing. When the thread begins mid-conversation, so you cannot tell whether what the question leans on was supplied in a turn you never saw, report a collection gap and record no observation; that is neither absent nor UNDETERMINED.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: a knowledgeable teammate could answer the question from the message alone, or from the message plus the surrounding turns, because it states the objective and the specific point of confusion or the exact behaviour seen. A quick clarification between people who share obvious context belongs here.\n- NOT_MET: the question is so thin on context that answering it requires asking the author what they mean, what they tried, or what they expected — and no surrounding turn supplies it. Name the missing element.\n- UNDETERMINED only when every declared turn was captured and the meaning still genuinely admits incompatible readings; quote the ambiguity and say what would settle it. Having read the whole thread and found the context missing is NOT_MET, not UNDETERMINED. A thread that begins mid-conversation is a collection gap, not an observation.\nOne observation per review, on the question turn you assessed.\n\n## Severity\nNOT_MET only. Scale to how much a responder must extract before they can help. MINOR, the usual band: a little more detail would sharpen the ask. MAJOR: the question as written cannot be answered without a full exchange of clarifications first. Never above MAJOR on question phrasing alone; this is a formative practice, never a gate.\n\n## Grounding\nQuote the exact turn you assessed. For MET where the surrounding turns supply the context, quote those turns too. For NOT_MET, the citations show the question and the boundary you searched: the whole captured thread, with no turn supplying the goal, the attempt or the observed behaviour. Describe the observable gap — \"the question names no goal and no attempt\" — never laziness or intent. Never invent missing context, grade an exchange you cannot quote, or claim the problem is or is not real.\n\n## Defer\nWhether the reply moves the asker forward belongs to `gives-actionable-answers`. Here only: does the question, as posed, let a teammate answer it in one reply?","precomputeScript":null,"automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"PRIVATE_CONTEXT_NOT_OBSERVED","description":"The captured thread does not include decisions or context shared outside the conversation."}],"insufficiencyReason":null},"whyItMatters":"A vague question forces the person helping you to stop and ask what you actually mean before they can even start, turning a one-message answer into a slow exchange. A question that carries its own context gets answered on the first reply.","whatGoodLooksLike":"A question that says what you are trying to do, what you already tried, and exactly where it broke, so a teammate can answer it in a single reply without asking you anything first.","groupSlug":"communication","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 180\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Vague question</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M36.75 32.75H291.25A12 12 0 0 1 303.25 44.75V83.25A12 12 0 0 1 291.25 95.25H24.75V44.75A12 12 0 0 1 36.75 32.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"41\" y=\"60\" font-size=\"15\">Why does it fail?</text>\n  <path class=\"pv-fill-surface pv-stroke-muted\" d=\"M60.75 104.75H291.25A12 12 0 0 1 303.25 116.75V139.25A12 12 0 0 1 291.25 151.25H48.75V116.75A12 12 0 0 1 60.75 104.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"65\" y=\"132\" font-size=\"15\">What failed?</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"176\" font-size=\"15\">Slow exchange</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Answerable question</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M372.75 32.75H627.25A12 12 0 0 1 639.25 44.75V83.25A12 12 0 0 1 627.25 95.25H360.75V44.75A12 12 0 0 1 372.75 32.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"377\" y=\"60\" font-size=\"15\">Deploy retry times out.</text>\n  <text class=\"pv-fill-accent\" x=\"377\" y=\"78\" font-size=\"15\">Which setting?</text>\n  <path class=\"pv-fill-surface pv-stroke-muted\" d=\"M396.75 104.75H627.25A12 12 0 0 1 639.25 116.75V139.25A12 12 0 0 1 627.25 151.25H384.75V116.75A12 12 0 0 1 396.75 104.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"401\" y=\"132\" font-size=\"15\">Set timeout in <tspan class=\"pv-mono\">deploy.yml</tspan></text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"176\" font-size=\"15\">One reply</text>\n</svg>\n","alt":"A vague question says only “Why does it fail?”, and the reply asks “What failed?”, a slow exchange. An answerable question says “Deploy retry times out. Which setting?”, so one reply, “Set timeout in deploy.yml”, answers it."},"guide":{"markdown":"## How to do it\n\n- Start with your goal. Say what you are trying to do.\n- Say what you already tried and what happened after each try.\n- Say exactly what happened, and what you expected. For example, instead of “Why does the build fail?”, write “I’m trying to run the tests on my laptop. After a clean install, `npm test` stops with ‘Cannot find module config’. Reinstalling did not help.”\n- Before you send, read your question as a teammate who does not know your work.\n- Add what they would have to ask first, unless earlier messages already give it.\n\n## When it does not apply\n\n- Your message is not a question. For example, it is a statement, a thank-you or social chat.\n- The conversation has not settled yet, so there is no finished thread to read.\n\nIt still applies when your question leans on earlier messages in the same thread. Those messages count, so you do not need to repeat them.\n\n## Common mistakes\n\n- Thinking that every question needs a long background. When you and your teammate clearly share the context, a quick question is fine. Add only what your teammate would otherwise have to ask for.\n- Writing only “Help, it’s broken”. Your teammate can only guess what you did. Instead, say what you ran, what you saw and what you expected.\n- Sharing an error with no explanation. An error alone does not say what you ran or what you expected. Instead, describe what you ran, what happened and what you expected.\n- Pasting your whole program or the whole log. Instead, share just enough code and output for a teammate to see the problem.\n\n## Sources\n\n- [How do I ask a good question?](https://stackoverflow.com/help/how-to-ask), Stack Overflow Help Center. Explain the problem, copy errors as text, and check that someone without your context can understand the question.\n- [How to report bugs effectively](https://www.chiark.greenend.org.uk/~sgtatham/bugs.html), Simon Tatham, 1999. Report what you did, what you saw and what you expected to see, so the programmer can help.\n- [An empirical study of question discussions on Stack Overflow](https://doi.org/10.1007/s10664-022-10180-z), Zhu, Zhang, Hassan and Godfrey, 2022. Questions with more comments were answered more slowly, but the study shows a link, not a cause.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Ask questions a teammate can answer","signals":["chat.conversation_thread.settled"],"evidenceRequirements":[{"sourceKind":"slack.conversation.thread","stance":"EXHAUSTIVE"}],"reviewWhen":{},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured conversation: the turns the practice names, read in their surrounding context. Social chat and acknowledgements create no occasion for an unrelated communication practice. Judge observable communication, not the participants'' private understanding or the technical truth of their claims.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: a question posed in the captured exchange carries enough context — the goal, what was tried, what happened — for a teammate to answer it in one reply.\n\n## The standard\nJudge whether a question raised in this conversation gives a teammate enough to answer it in a single reply, rather than forcing a round of clarifying questions first. A well-formed ask names the concrete goal, what was already tried, and what actually happened or is blocking. A bare \"it doesn''t work\" or \"how do I do this?\" with no context makes the responder guess. Judge only the observable way the question is posed; never whether the underlying problem is real, hard or worth solving. Use judgment about how much context the question genuinely needs: a quick clarification among people who plainly share the context is not a defect. The review is about one participant. Judge only the turns that `context/conversation_thread.json` marks `\"underReview\": true`. The other turns are context.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the turn is not actually a question (a statement, an acknowledgement, social chat), or when there is no settled conversation to read. A real question whose needed context is supplied by the surrounding turns is not NOT_APPLICABLE; it is MET.\n\n## Sources\n1. The turn that poses the question (`context/conversation_thread.json`): its stated objective, what was tried, the exact behaviour seen or the specific point of confusion. It establishes how the question is posed. It never establishes whether the problem is real or worth solving.\n2. The surrounding turns of the same thread (`context/conversation_thread.json`): earlier turns may supply the context the question leans on; a later reply that has to ask what was meant shows what the responder had to extract first. They establish what context was shared inside the captured thread and nothing outside it.\nAn image or attachment in a turn: read its caption and the sentence around it. An external link: nothing. When the thread begins mid-conversation, so you cannot tell whether what the question leans on was supplied in a turn you never saw, report a collection gap and record no observation; that is neither absent nor UNDETERMINED.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: a knowledgeable teammate could answer the question from the message alone, or from the message plus the surrounding turns, because it states the objective and the specific point of confusion or the exact behaviour seen. A quick clarification between people who share obvious context belongs here.\n- NOT_MET: the question is so thin on context that answering it requires asking the author what they mean, what they tried, or what they expected — and no surrounding turn supplies it. Name the missing element.\n- UNDETERMINED only when every declared turn was captured and the meaning still genuinely admits incompatible readings; quote the ambiguity and say what would settle it. Having read the whole thread and found the context missing is NOT_MET, not UNDETERMINED. A thread that begins mid-conversation is a collection gap, not an observation.\nOne observation per review, on the question turn you assessed.\n\n## Severity\nNOT_MET only. Scale to how much a responder must extract before they can help. MINOR, the usual band: a little more detail would sharpen the ask. MAJOR: the question as written cannot be answered without a full exchange of clarifications first. Never above MAJOR on question phrasing alone; this is a formative practice, never a gate.\n\n## Grounding\nQuote the exact turn you assessed. For MET where the surrounding turns supply the context, quote those turns too. For NOT_MET, the citations show the question and the boundary you searched: the whole captured thread, with no turn supplying the goal, the attempt or the observed behaviour. Describe the observable gap — \"the question names no goal and no attempt\" — never laziness or intent. Never invent missing context, grade an exchange you cannot quote, or claim the problem is or is not real.\n\n## Defer\nWhether the reply moves the asker forward belongs to `gives-actionable-answers`. Here only: does the question, as posed, let a teammate answer it in one reply?","precomputeScript":null,"automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"PRIVATE_CONTEXT_NOT_OBSERVED","description":"The captured thread does not include decisions or context shared outside the conversation."}],"insufficiencyReason":null},"whyItMatters":"A vague question forces the person helping you to stop and ask what you actually mean before they can even start, turning a one-message answer into a slow exchange. A question that carries its own context gets answered on the first reply.","whatGoodLooksLike":"A question that says what you are trying to do, what you already tried, and exactly where it broke, so a teammate can answer it in a single reply without asking you anything first.","groupSlug":"communication","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 180\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Vague question</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M36.75 32.75H291.25A12 12 0 0 1 303.25 44.75V83.25A12 12 0 0 1 291.25 95.25H24.75V44.75A12 12 0 0 1 36.75 32.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"41\" y=\"60\" font-size=\"15\">Why does it fail?</text>\n  <path class=\"pv-fill-surface pv-stroke-muted\" d=\"M60.75 104.75H291.25A12 12 0 0 1 303.25 116.75V139.25A12 12 0 0 1 291.25 151.25H48.75V116.75A12 12 0 0 1 60.75 104.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"65\" y=\"132\" font-size=\"15\">What failed?</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"176\" font-size=\"15\">Slow exchange</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Answerable question</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M372.75 32.75H627.25A12 12 0 0 1 639.25 44.75V83.25A12 12 0 0 1 627.25 95.25H360.75V44.75A12 12 0 0 1 372.75 32.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"377\" y=\"60\" font-size=\"15\">Deploy retry times out.</text>\n  <text class=\"pv-fill-accent\" x=\"377\" y=\"78\" font-size=\"15\">Which setting?</text>\n  <path class=\"pv-fill-surface pv-stroke-muted\" d=\"M396.75 104.75H627.25A12 12 0 0 1 639.25 116.75V139.25A12 12 0 0 1 627.25 151.25H384.75V116.75A12 12 0 0 1 396.75 104.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"401\" y=\"132\" font-size=\"15\">Set timeout in <tspan class=\"pv-mono\">deploy.yml</tspan></text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"176\" font-size=\"15\">One reply</text>\n</svg>\n","alt":"A vague question says only “Why does it fail?”, and the reply asks “What failed?”, a slow exchange. An answerable question says “Deploy retry times out. Which setting?”, so one reply, “Set timeout in deploy.yml”, answers it."},"guide":{"markdown":"## How to do it\n\n- Start with your goal. Say what you are trying to do.\n- Say what you already tried and what happened after each try.\n- Say exactly what happened, and what you expected. For example, instead of “Why does the build fail?”, write “I’m trying to run the tests on my laptop. After a clean install, `npm test` stops with ‘Cannot find module config’. Reinstalling did not help.”\n- Before you send, read your question as a teammate who does not know your work.\n- Add what they would have to ask first, unless earlier messages already give it.\n\n## When it does not apply\n\n- Your message is not a question. For example, it is a statement, a thank-you or social chat.\n- The conversation has not settled yet, so there is no finished thread to read.\n\nIt still applies when your question leans on earlier messages in the same thread. Those messages count, so you do not need to repeat them.\n\n## Common mistakes\n\n- Thinking that every question needs a long background. When you and your teammate clearly share the context, a quick question is fine. Add only what your teammate would otherwise have to ask for.\n- Writing only “Help, it’s broken”. Your teammate can only guess what you did. Instead, say what you ran, what you saw and what you expected.\n- Sharing an error with no explanation. An error alone does not say what you ran or what you expected. Instead, describe what you ran, what happened and what you expected.\n- Pasting your whole program or the whole log. Instead, share just enough code and output for a teammate to see the problem.\n\n## Sources\n\n- [How do I ask a good question?](https://stackoverflow.com/help/how-to-ask), Stack Overflow Help Center. Explain the problem, copy errors as text, and check that someone without your context can understand the question.\n- [How to report bugs effectively](https://www.chiark.greenend.org.uk/~sgtatham/bugs.html), Simon Tatham, 1999. Report what you did, what you saw and what you expected to see, so the programmer can help.\n- [An empirical study of question discussions on Stack Overflow](https://doi.org/10.1007/s10664-022-10180-z), Zhu, Zhang, Hassan and Godfrey, 2022. Questions with more comments were answered more slowly, but the study shows a link, not a cause.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Questions carry the goal, the attempt and the error"'::jsonb),'v5:7edfe772ca69c2ce99660050e27f5e2064babdd06724adb3f00d87518c2e909e','practice:v3:c2c745384b168aed4117636df98b5de65cad7a7b2e021c5c30009f46f41d516a');
INSERT INTO _cutover_bundle VALUES('PRACTICE','gives-actionable-answers','chat.conversation_thread','{"name":"Give answers people can act on","signals":["chat.conversation_thread.settled"],"evidenceRequirements":[{"sourceKind":"slack.conversation.thread","stance":"EXHAUSTIVE"}],"reviewWhen":{},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured conversation: the turns the practice names, read in their surrounding context. Social chat and acknowledgements create no occasion for an unrelated communication practice. Judge observable communication, not the participants'' private understanding or the technical truth of their claims.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: a reply to a question in the captured exchange gives the asker something to act on now — the answer, the exact place to look, or the next step.\n\n## The standard\nJudge whether a reply to someone''s question actually moves them forward, rather than leaving them where they started. A useful answer either resolves the question directly or names a concrete next step the asker can take. A reply that only restates the problem, points vaguely at \"the docs\", or answers a different question does not. A short answer can be fully actionable; length is not the signal. Judge only the observable helpfulness of the reply as written, never whether its technical content is ultimately correct. Use judgment about what the asker needed. The review is about one participant. Judge only the turns that `context/conversation_thread.json` marks `\"underReview\": true`. The other turns are context.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the turn is not answering a question; when no question was actually asked; when the reply is a reasonable partial step in an ongoing exchange; or when there is no settled conversation to read.\n\n## Sources\n1. The question turn (`context/conversation_thread.json`): what was asked and what the asker needed. It establishes the question the reply is measured against. It never establishes whether the problem is real or hard.\n2. The reply turn (`context/conversation_thread.json`): the answer given, the place named, the step proposed. It establishes what the asker can do next. It never establishes that the answer is technically right.\n3. The surrounding turns (`context/conversation_thread.json`): whether the exchange is still in progress, and whether the answer had already been given elsewhere in the thread. They establish the state of the exchange inside the captured thread and nothing outside it.\nAn image or attachment in a turn: read its caption and the sentence around it. An external link: nothing; judge the reply by its own words. When a real question and its reply are both in front of you but the thread begins mid-conversation, so you cannot tell whether the answer had already been given elsewhere in it, report a collection gap and record no observation; that is neither absent nor UNDETERMINED.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: the asker could act on the reply immediately because it gives the answer, the specific place to look, or the exact next step.\n- NOT_MET: a genuine question was met with a reply that leaves the asker still stuck — too vague to act on, or it sidesteps what was asked. Name what the asker still lacks.\n- UNDETERMINED only when every declared turn was captured and the meaning still genuinely admits incompatible readings; quote the ambiguity and say what would settle it. Having read the reply and the surrounding turns and found no actionable content is NOT_MET, not UNDETERMINED. A thread that begins mid-conversation is a collection gap, not an observation.\nOne observation per review, on the question-and-reply pair you assessed.\n\n## Severity\nNOT_MET only. Scale to how stuck the asker remains after the reply. MINOR, the usual band: the answer is nearly there and one pointer would land it. MAJOR: a real question is met with a reply that cannot be acted on at all. Never above MAJOR on reply clarity alone; this is a formative practice, never a gate.\n\n## Grounding\nQuote the question and the reply you assessed. For NOT_MET, the citations show the question, the reply, and the boundary you searched: the surrounding captured turns, with no other turn supplying the answer. Describe the observable gap — \"the reply names no place to look and no step\" — never dismissiveness. Never fabricate an answer the reply did not give, and never claim the reply''s content is correct or incorrect.\n\n## Defer\nWhether the question itself carried enough context to be answerable belongs to `asks-answerable-questions`. Here only: does the reply, as written, let the asker move forward?","precomputeScript":null,"automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"PRIVATE_CONTEXT_NOT_OBSERVED","description":"The captured thread does not include decisions or context shared outside the conversation."}],"insufficiencyReason":null},"whyItMatters":"When someone asks for help, a reply that only gestures at the problem leaves them exactly as stuck as before and burns another round of messages. An answer with a concrete next step lets them get moving right away.","whatGoodLooksLike":"A reply that either solves the question outright or points to the exact next step or place to look, so the person who asked can act on it immediately instead of asking again.","groupSlug":"communication","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 180\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Vague reply</text>\n  <path class=\"pv-fill-surface pv-stroke-muted\" d=\"M36.75 32.75H267.25A12 12 0 0 1 279.25 44.75V67.25A12 12 0 0 1 267.25 79.25H24.75V44.75A12 12 0 0 1 36.75 32.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"41\" y=\"60\" font-size=\"15\">Deploy times out. Why?</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M60.75 88.75H291.25A12 12 0 0 1 303.25 100.75V139.25A12 12 0 0 1 291.25 151.25H48.75V100.75A12 12 0 0 1 60.75 88.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"65\" y=\"116\" font-size=\"15\">See the docs</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"176\" font-size=\"15\">Still stuck</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Concrete reply</text>\n  <path class=\"pv-fill-surface pv-stroke-muted\" d=\"M372.75 32.75H603.25A12 12 0 0 1 615.25 44.75V67.25A12 12 0 0 1 603.25 79.25H360.75V44.75A12 12 0 0 1 372.75 32.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"377\" y=\"60\" font-size=\"15\">Deploy times out. Why?</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M396.75 88.75H627.25A12 12 0 0 1 639.25 100.75V139.25A12 12 0 0 1 627.25 151.25H384.75V100.75A12 12 0 0 1 396.75 88.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"401\" y=\"116\" font-size=\"15\">Raise timeout in</text>\n  <text class=\"pv-fill-accent pv-mono\" x=\"401\" y=\"134\" font-size=\"15\">deploy.yml</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"176\" font-size=\"15\">Can act now</text>\n</svg>\n","alt":"A vague reply to “Deploy times out. Why?” says only “See the docs”, so the person is still stuck. A concrete reply says “Raise timeout in deploy.yml”, so they can act now."},"guide":{"markdown":"## How to do it\n\n- Read the question again before you reply.\n- Answer what the person asked, not a nearby question that is easier.\n- When you know the answer, give it in the reply. A short answer is enough if the person can act on it.\n- When the answer is in a document, name the exact page or section and the part that answers the question. Instead of “See the docs”, write “Set `retries` in the deploy config. The Retries section of the deploy guide has an example.”\n- When you do not know the answer, name the next step. Say who to ask, or where they can look next.\n\n## When it does not apply\n\n- Your message does not answer a question.\n- No one asked a question.\n- Your reply is a reasonable partial step in a conversation that is still going on.\n- The conversation has not settled yet, so there is no finished exchange to read.\n\n## Common mistakes\n\n- Writing a long reply so that it looks helpful. Length is not what helps. A short reply that gives the answer or the exact step is enough.\n- Pointing at “the docs” or a whole wiki. Instead, name the exact section and the part that answers the question.\n- Saying the problem back to the person. “That build fails a lot” tells them nothing new. Instead, add one thing they can do about it now.\n- Answering a different question from the one they asked. Instead, answer their question first. Then add the other point if it still helps.\n\n## Sources\n\n- [How do I write a good answer?](https://stackoverflow.com/help/how-to-answer), Stack Overflow Help Center. It asks for an answer to the question asked, a thing to try instead, and context around each link.\n- [Why and how are some answers deleted?](https://stackoverflow.com/help/deleted-answers), Stack Overflow Help Center. It lists replies that do not answer the question, such as a different question or barely more than a link.\n- [GitLab Handbook usage](https://handbook.gitlab.com/handbook/about/handbook-usage/), GitLab. It asks team members to link to the relevant handbook information when they answer questions.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Give answers people can act on","signals":["chat.conversation_thread.settled"],"evidenceRequirements":[{"sourceKind":"slack.conversation.thread","stance":"EXHAUSTIVE"}],"reviewWhen":{},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured conversation: the turns the practice names, read in their surrounding context. Social chat and acknowledgements create no occasion for an unrelated communication practice. Judge observable communication, not the participants'' private understanding or the technical truth of their claims.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: a reply to a question in the captured exchange gives the asker something to act on now — the answer, the exact place to look, or the next step.\n\n## The standard\nJudge whether a reply to someone''s question actually moves them forward, rather than leaving them where they started. A useful answer either resolves the question directly or names a concrete next step the asker can take. A reply that only restates the problem, points vaguely at \"the docs\", or answers a different question does not. A short answer can be fully actionable; length is not the signal. Judge only the observable helpfulness of the reply as written, never whether its technical content is ultimately correct. Use judgment about what the asker needed. The review is about one participant. Judge only the turns that `context/conversation_thread.json` marks `\"underReview\": true`. The other turns are context.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the turn is not answering a question; when no question was actually asked; when the reply is a reasonable partial step in an ongoing exchange; or when there is no settled conversation to read.\n\n## Sources\n1. The question turn (`context/conversation_thread.json`): what was asked and what the asker needed. It establishes the question the reply is measured against. It never establishes whether the problem is real or hard.\n2. The reply turn (`context/conversation_thread.json`): the answer given, the place named, the step proposed. It establishes what the asker can do next. It never establishes that the answer is technically right.\n3. The surrounding turns (`context/conversation_thread.json`): whether the exchange is still in progress, and whether the answer had already been given elsewhere in the thread. They establish the state of the exchange inside the captured thread and nothing outside it.\nAn image or attachment in a turn: read its caption and the sentence around it. An external link: nothing; judge the reply by its own words. When a real question and its reply are both in front of you but the thread begins mid-conversation, so you cannot tell whether the answer had already been given elsewhere in it, report a collection gap and record no observation; that is neither absent nor UNDETERMINED.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: the asker could act on the reply immediately because it gives the answer, the specific place to look, or the exact next step.\n- NOT_MET: a genuine question was met with a reply that leaves the asker still stuck — too vague to act on, or it sidesteps what was asked. Name what the asker still lacks.\n- UNDETERMINED only when every declared turn was captured and the meaning still genuinely admits incompatible readings; quote the ambiguity and say what would settle it. Having read the reply and the surrounding turns and found no actionable content is NOT_MET, not UNDETERMINED. A thread that begins mid-conversation is a collection gap, not an observation.\nOne observation per review, on the question-and-reply pair you assessed.\n\n## Severity\nNOT_MET only. Scale to how stuck the asker remains after the reply. MINOR, the usual band: the answer is nearly there and one pointer would land it. MAJOR: a real question is met with a reply that cannot be acted on at all. Never above MAJOR on reply clarity alone; this is a formative practice, never a gate.\n\n## Grounding\nQuote the question and the reply you assessed. For NOT_MET, the citations show the question, the reply, and the boundary you searched: the surrounding captured turns, with no other turn supplying the answer. Describe the observable gap — \"the reply names no place to look and no step\" — never dismissiveness. Never fabricate an answer the reply did not give, and never claim the reply''s content is correct or incorrect.\n\n## Defer\nWhether the question itself carried enough context to be answerable belongs to `asks-answerable-questions`. Here only: does the reply, as written, let the asker move forward?","precomputeScript":null,"automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"PRIVATE_CONTEXT_NOT_OBSERVED","description":"The captured thread does not include decisions or context shared outside the conversation."}],"insufficiencyReason":null},"whyItMatters":"When someone asks for help, a reply that only gestures at the problem leaves them exactly as stuck as before and burns another round of messages. An answer with a concrete next step lets them get moving right away.","whatGoodLooksLike":"A reply that either solves the question outright or points to the exact next step or place to look, so the person who asked can act on it immediately instead of asking again.","groupSlug":"communication","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 180\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Vague reply</text>\n  <path class=\"pv-fill-surface pv-stroke-muted\" d=\"M36.75 32.75H267.25A12 12 0 0 1 279.25 44.75V67.25A12 12 0 0 1 267.25 79.25H24.75V44.75A12 12 0 0 1 36.75 32.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"41\" y=\"60\" font-size=\"15\">Deploy times out. Why?</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M60.75 88.75H291.25A12 12 0 0 1 303.25 100.75V139.25A12 12 0 0 1 291.25 151.25H48.75V100.75A12 12 0 0 1 60.75 88.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"65\" y=\"116\" font-size=\"15\">See the docs</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"176\" font-size=\"15\">Still stuck</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Concrete reply</text>\n  <path class=\"pv-fill-surface pv-stroke-muted\" d=\"M372.75 32.75H603.25A12 12 0 0 1 615.25 44.75V67.25A12 12 0 0 1 603.25 79.25H360.75V44.75A12 12 0 0 1 372.75 32.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"377\" y=\"60\" font-size=\"15\">Deploy times out. Why?</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M396.75 88.75H627.25A12 12 0 0 1 639.25 100.75V139.25A12 12 0 0 1 627.25 151.25H384.75V100.75A12 12 0 0 1 396.75 88.75Z\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-accent\" x=\"401\" y=\"116\" font-size=\"15\">Raise timeout in</text>\n  <text class=\"pv-fill-accent pv-mono\" x=\"401\" y=\"134\" font-size=\"15\">deploy.yml</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"176\" font-size=\"15\">Can act now</text>\n</svg>\n","alt":"A vague reply to “Deploy times out. Why?” says only “See the docs”, so the person is still stuck. A concrete reply says “Raise timeout in deploy.yml”, so they can act now."},"guide":{"markdown":"## How to do it\n\n- Read the question again before you reply.\n- Answer what the person asked, not a nearby question that is easier.\n- When you know the answer, give it in the reply. A short answer is enough if the person can act on it.\n- When the answer is in a document, name the exact page or section and the part that answers the question. Instead of “See the docs”, write “Set `retries` in the deploy config. The Retries section of the deploy guide has an example.”\n- When you do not know the answer, name the next step. Say who to ask, or where they can look next.\n\n## When it does not apply\n\n- Your message does not answer a question.\n- No one asked a question.\n- Your reply is a reasonable partial step in a conversation that is still going on.\n- The conversation has not settled yet, so there is no finished exchange to read.\n\n## Common mistakes\n\n- Writing a long reply so that it looks helpful. Length is not what helps. A short reply that gives the answer or the exact step is enough.\n- Pointing at “the docs” or a whole wiki. Instead, name the exact section and the part that answers the question.\n- Saying the problem back to the person. “That build fails a lot” tells them nothing new. Instead, add one thing they can do about it now.\n- Answering a different question from the one they asked. Instead, answer their question first. Then add the other point if it still helps.\n\n## Sources\n\n- [How do I write a good answer?](https://stackoverflow.com/help/how-to-answer), Stack Overflow Help Center. It asks for an answer to the question asked, a thing to try instead, and context around each link.\n- [Why and how are some answers deleted?](https://stackoverflow.com/help/deleted-answers), Stack Overflow Help Center. It lists replies that do not answer the question, such as a different question or barely more than a link.\n- [GitLab Handbook usage](https://handbook.gitlab.com/handbook/about/handbook-usage/), GitLab. It asks team members to link to the relevant handbook information when they answer questions.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Answers give the next step, not another question"'::jsonb),'v5:cb9b1de9e9f1f07fee04882a9d7d72279fe4bd7a4a4b0f0d886e7d524edae40d','practice:v3:cff2de84c4168b2c7c04d06533786e4a182e909346a619329425cab3612088fe');
INSERT INTO _cutover_bundle VALUES('PRACTICE','posts-clear-status-and-blocker-updates','chat.conversation_thread','{"name":"Post clear status and blocker updates","signals":["chat.conversation_thread.settled"],"evidenceRequirements":[{"sourceKind":"slack.conversation.thread","stance":"EXHAUSTIVE"}],"reviewWhen":{},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured conversation: the turns the practice names, read in their surrounding context. Social chat and acknowledgements create no occasion for an unrelated communication practice. Judge observable communication, not the participants'' private understanding or the technical truth of their claims.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: an update about ongoing work says where things stand and, when stuck, names the blocker and what would clear it.\n\n## The standard\nJudge whether an update about ongoing work tells the team where things stand and, when the author is stuck, names the blocker plainly along with what is needed to clear it. A clear update lets teammates plan around the work or step in to unblock it; an update so vague no one can tell whether help is needed leaves the team guessing. Judge only the observable clarity of the update, never whether the work itself is on track. Use judgment about how much an update needs to say: a brief \"still on it, no blockers\" among teammates already in sync is fine, and a real update made clear by its surrounding context is a good update, not a missing one. The review is about one participant. Judge only the turns that `context/conversation_thread.json` marks `\"underReview\": true`. The other turns are context.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the turn is not a status update, when there is no in-flight work or blocker to report, or when there is no settled conversation to read. A real update whose standing or blocker is established by the surrounding turns is not NOT_APPLICABLE; it is MET.\n\n## Sources\n1. The update turn (`context/conversation_thread.json`): what it says about the current standing, whether it reports being blocked, what it names as the blocker and what it asks for. It establishes the clarity of the update as posted. It never establishes whether the work is actually on track or whether the blocker is real.\n2. The surrounding turns of the same thread (`context/conversation_thread.json`): earlier turns may already establish the standing an update omits, or show that the teammates are in sync; a later turn that has to ask what is needed shows what the update left unsaid. They establish what was shared inside the captured thread and nothing outside it.\nAn image or attachment in a turn: read its caption and the sentence around it. An external link: nothing. When an update IS posted but the thread begins mid-conversation, so you cannot tell whether the standing it omits was already established, report a collection gap and record no observation; that is neither absent nor UNDETERMINED.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: the update states the current standing and, if blocked, says what is blocking and what would unblock it — from the turn alone or from the turn plus the surrounding thread.\n- NOT_MET: an update on stalled or in-flight work that hides a blocker behind a vague line, or reports being stuck without naming what is actually needed, so no one can plan or help. Quote the vague line and name what the team cannot tell from it.\n- UNDETERMINED only when every declared turn was captured and the update''s meaning still genuinely admits incompatible readings; quote the ambiguity and say what would settle it. A thread that begins mid-conversation is a collection gap, not UNDETERMINED.\nOne observation per review, on the update turn you assessed.\n\n## Severity\nNOT_MET only; never above MAJOR on update clarity alone — a formative practice, never a gate. Scale to how much the update leaves the team unable to plan or help. MINOR, the usual band: the standing is clear but the ask is fuzzy. MAJOR: a real blocker is present yet the update gives the team nothing to act on.\n\n## Grounding\nQuote the update you assessed. For MET where the surrounding turns supply the standing or the ask, quote those turns too. For NOT_MET, quote the vague line and the turns you read around it. Describe the observable gap — \"the update says it is blocked and names no blocker\" — never avoidance or intent. Never invent a blocker the author did not mention, and never claim the work is or is not on track.\n\n## Defer\nWhether a question posed in the thread carries enough context to answer belongs to `asks-answerable-questions`; whether a reply moves the asker forward belongs to `gives-actionable-answers`. Here only: does the update tell the team where things stand and what would unblock them?","precomputeScript":null,"automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"PRIVATE_CONTEXT_NOT_OBSERVED","description":"The captured thread does not include decisions or context shared outside the conversation."}],"insufficiencyReason":null},"whyItMatters":"When work stalls quietly, the people depending on it keep waiting without knowing anything is wrong, and a blocker someone else could have cleared in minutes sits for days. A plain update on where things stand and what you need keeps the team moving.","whatGoodLooksLike":"An update that says where the work stands and, when you are stuck, names the blocker and what would unblock it, so teammates can plan around it or step in to help.","groupSlug":"communication","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 140\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Vague update</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M36.75 32.75H291.25A12 12 0 0 1 303.25 44.75V99.25A12 12 0 0 1 291.25 111.25H24.75V44.75A12 12 0 0 1 36.75 32.75Z\" stroke-width=\"1.5\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"40.75\" y=\"48.75\" width=\"78.5\" height=\"22.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"52\" y=\"65\" font-size=\"15\">Blocked</text>\n  <text class=\"pv-fill-muted\" x=\"41\" y=\"94\" font-size=\"15\">Still stuck on this</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"136\" font-size=\"15\">Team keeps waiting</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Clear update</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M372.75 32.75H627.25A12 12 0 0 1 639.25 44.75V99.25A12 12 0 0 1 627.25 111.25H360.75V44.75A12 12 0 0 1 372.75 32.75Z\" stroke-width=\"1.5\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"376.75\" y=\"48.75\" width=\"78.5\" height=\"22.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"388\" y=\"65\" font-size=\"15\">Blocked</text>\n  <text class=\"pv-fill-accent\" x=\"377\" y=\"94\" font-size=\"15\">Need the API key from Maya</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"136\" font-size=\"15\">Team can help</text>\n</svg>\n","alt":"A vague update is marked Blocked and says only “Still stuck on this”, so the team keeps waiting. A clear update says “Need the API key from Maya”, so the team can help."},"guide":{"markdown":"## How to do it\n\n- Start with where the work stands, such as done, in progress or blocked.\n- If you are stuck, name the blocker plainly. For example, instead of “Still stuck”, write “Blocked: the test server fails because its access key is missing”.\n- Say what would clear the blocker, such as access, a decision or a review. Naming someone who can help can make the request clearer.\n- If teammates need to plan around your work, say what comes next. Do not list everything you did since the last update.\n- If teammates might wonder whether you need help, say whether anything blocks you. A short “No blockers” answers that.\n\n## When it does not apply\n\n- Your message is not a status update.\n- You have no work in progress and no blocker to report.\n- The conversation has not settled yet.\n\nIt still applies when earlier messages in the thread already say where the work stands or what blocks it. Then a short update that relies on them is a clear update.\n\n## Common mistakes\n\n- Hiding a blocker because it sounds like bad news. The practice looks at how clear your update is, not at whether the work is on track. Say plainly that you’re blocked.\n- Padding a short update. Among teammates who already know the work, “Still on it, no blockers” is enough. Add detail when the team needs it to plan or to help.\n- Saying you’re stuck with no ask, such as “Kind of stuck on this”. Then a teammate has to reply and ask what you need. Instead, say what you need in the same update.\n- Listing everything you did since the last update. That rarely starts a discussion that solves a problem. Instead, name what comes next and what is in the way.\n\n## Sources\n\n- [The Scrum Guide](https://scrumguides.org/scrum-guide.html#daily-scrum), Schwaber and Sutherland, 2020. The Daily Scrum checks progress toward the goal and helps the team find what blocks its work.\n- [Daily stand-up meetings: start breaking the rules](https://doi.org/10.1109/MS.2018.2875988), Stray, Moe and Sjøberg, 2020. In 102 observed stand-ups, a next task or an obstacle usually led to talk about solutions. Past work rarely did.\n- [Engineering communication](https://handbook.gitlab.com/handbook/engineering/workflow/engineering-comms/#sending-status-updates-to-engineering-fyi), GitLab Handbook. GitLab asks for updates on what was completed and what is blocked or at risk. It also asks you to tag relevant people as needed.\n","figures":{}}}'::jsonb,jsonb_set(pg_temp.cutover_normalize(pg_temp.cutover_definition('{"name":"Post clear status and blocker updates","signals":["chat.conversation_thread.settled"],"evidenceRequirements":[{"sourceKind":"slack.conversation.thread","stance":"EXHAUSTIVE"}],"reviewWhen":{},"subject":"AUTHOR","precondition":null,"criteria":"Review this practice against the captured conversation: the turns the practice names, read in their surrounding context. Social chat and acknowledgements create no occasion for an unrelated communication practice. Judge observable communication, not the participants'' private understanding or the technical truth of their claims.\n\n---\n\nAssess the complete practice standard within the captured evidence boundary.\n\nREVIEW FOCUS: an update about ongoing work says where things stand and, when stuck, names the blocker and what would clear it.\n\n## The standard\nJudge whether an update about ongoing work tells the team where things stand and, when the author is stuck, names the blocker plainly along with what is needed to clear it. A clear update lets teammates plan around the work or step in to unblock it; an update so vague no one can tell whether help is needed leaves the team guessing. Judge only the observable clarity of the update, never whether the work itself is on track. Use judgment about how much an update needs to say: a brief \"still on it, no blockers\" among teammates already in sync is fine, and a real update made clear by its surrounding context is a good update, not a missing one. The review is about one participant. Judge only the turns that `context/conversation_thread.json` marks `\"underReview\": true`. The other turns are context.\n\n## Occasion\nThis is a gate. Record NOT_APPLICABLE, name the fact, and stop when the turn is not a status update, when there is no in-flight work or blocker to report, or when there is no settled conversation to read. A real update whose standing or blocker is established by the surrounding turns is not NOT_APPLICABLE; it is MET.\n\n## Sources\n1. The update turn (`context/conversation_thread.json`): what it says about the current standing, whether it reports being blocked, what it names as the blocker and what it asks for. It establishes the clarity of the update as posted. It never establishes whether the work is actually on track or whether the blocker is real.\n2. The surrounding turns of the same thread (`context/conversation_thread.json`): earlier turns may already establish the standing an update omits, or show that the teammates are in sync; a later turn that has to ask what is needed shows what the update left unsaid. They establish what was shared inside the captured thread and nothing outside it.\nAn image or attachment in a turn: read its caption and the sentence around it. An external link: nothing. When an update IS posted but the thread begins mid-conversation, so you cannot tell whether the standing it omits was already established, report a collection gap and record no observation; that is neither absent nor UNDETERMINED.\n\n## Judge\nAssess conformance to the standard in this context.\n- MET: the update states the current standing and, if blocked, says what is blocking and what would unblock it — from the turn alone or from the turn plus the surrounding thread.\n- NOT_MET: an update on stalled or in-flight work that hides a blocker behind a vague line, or reports being stuck without naming what is actually needed, so no one can plan or help. Quote the vague line and name what the team cannot tell from it.\n- UNDETERMINED only when every declared turn was captured and the update''s meaning still genuinely admits incompatible readings; quote the ambiguity and say what would settle it. A thread that begins mid-conversation is a collection gap, not UNDETERMINED.\nOne observation per review, on the update turn you assessed.\n\n## Severity\nNOT_MET only; never above MAJOR on update clarity alone — a formative practice, never a gate. Scale to how much the update leaves the team unable to plan or help. MINOR, the usual band: the standing is clear but the ask is fuzzy. MAJOR: a real blocker is present yet the update gives the team nothing to act on.\n\n## Grounding\nQuote the update you assessed. For MET where the surrounding turns supply the standing or the ask, quote those turns too. For NOT_MET, quote the vague line and the turns you read around it. Describe the observable gap — \"the update says it is blocked and names no blocker\" — never avoidance or intent. Never invent a blocker the author did not mention, and never claim the work is or is not on track.\n\n## Defer\nWhether a question posed in the thread carries enough context to answer belongs to `asks-answerable-questions`; whether a reply moves the asker forward belongs to `gives-actionable-answers`. Here only: does the update tell the team where things stand and what would unblock them?","precomputeScript":null,"automatedReviewPolicy":{"sourceContractVersion":"1.3.0","automatedReview":{"mode":"LANGUAGE_MODEL","evidenceSufficiency":"SUFFICIENT_WHEN_REQUIREMENTS_MET"},"whenEvidenceIsInsufficient":"SKIP_AUTOMATED_REVIEW","knownLimitations":[{"code":"PRIVATE_CONTEXT_NOT_OBSERVED","description":"The captured thread does not include decisions or context shared outside the conversation."}],"insufficiencyReason":null},"whyItMatters":"When work stalls quietly, the people depending on it keep waiting without knowing anything is wrong, and a blocker someone else could have cleared in minutes sits for days. A plain update on where things stand and what you need keeps the team moving.","whatGoodLooksLike":"An update that says where the work stands and, when you are stuck, names the blocker and what would unblock it, so teammates can plan around it or step in to help.","groupSlug":"communication","deliveryBehavior":{"summaryOnly":false,"overlapGroup":null,"redundantToSlug":null},"visual":{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 140\">\n  <text class=\"pv-fill-ink\" x=\"0\" y=\"16\" font-size=\"16\" font-weight=\"600\">Vague update</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M36.75 32.75H291.25A12 12 0 0 1 303.25 44.75V99.25A12 12 0 0 1 291.25 111.25H24.75V44.75A12 12 0 0 1 36.75 32.75Z\" stroke-width=\"1.5\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"40.75\" y=\"48.75\" width=\"78.5\" height=\"22.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"52\" y=\"65\" font-size=\"15\">Blocked</text>\n  <text class=\"pv-fill-muted\" x=\"41\" y=\"94\" font-size=\"15\">Still stuck on this</text>\n  <text class=\"pv-fill-muted\" x=\"0\" y=\"136\" font-size=\"15\">Team keeps waiting</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"16\" font-size=\"16\" font-weight=\"600\">Clear update</text>\n  <path class=\"pv-fill-surface pv-stroke-ink\" d=\"M372.75 32.75H627.25A12 12 0 0 1 639.25 44.75V99.25A12 12 0 0 1 627.25 111.25H360.75V44.75A12 12 0 0 1 372.75 32.75Z\" stroke-width=\"1.5\"/>\n  <rect class=\"pv-fill-surface pv-stroke-muted\" x=\"376.75\" y=\"48.75\" width=\"78.5\" height=\"22.5\" rx=\"8\" stroke-width=\"1.5\"/>\n  <text class=\"pv-fill-muted\" x=\"388\" y=\"65\" font-size=\"15\">Blocked</text>\n  <text class=\"pv-fill-accent\" x=\"377\" y=\"94\" font-size=\"15\">Need the API key from Maya</text>\n  <text class=\"pv-fill-ink\" x=\"336\" y=\"136\" font-size=\"15\">Team can help</text>\n</svg>\n","alt":"A vague update is marked Blocked and says only “Still stuck on this”, so the team keeps waiting. A clear update says “Need the API key from Maya”, so the team can help."},"guide":{"markdown":"## How to do it\n\n- Start with where the work stands, such as done, in progress or blocked.\n- If you are stuck, name the blocker plainly. For example, instead of “Still stuck”, write “Blocked: the test server fails because its access key is missing”.\n- Say what would clear the blocker, such as access, a decision or a review. Naming someone who can help can make the request clearer.\n- If teammates need to plan around your work, say what comes next. Do not list everything you did since the last update.\n- If teammates might wonder whether you need help, say whether anything blocks you. A short “No blockers” answers that.\n\n## When it does not apply\n\n- Your message is not a status update.\n- You have no work in progress and no blocker to report.\n- The conversation has not settled yet.\n\nIt still applies when earlier messages in the thread already say where the work stands or what blocks it. Then a short update that relies on them is a clear update.\n\n## Common mistakes\n\n- Hiding a blocker because it sounds like bad news. The practice looks at how clear your update is, not at whether the work is on track. Say plainly that you’re blocked.\n- Padding a short update. Among teammates who already know the work, “Still on it, no blockers” is enough. Add detail when the team needs it to plan or to help.\n- Saying you’re stuck with no ask, such as “Kind of stuck on this”. Then a teammate has to reply and ask what you need. Instead, say what you need in the same update.\n- Listing everything you did since the last update. That rarely starts a discussion that solves a problem. Instead, name what comes next and what is in the way.\n\n## Sources\n\n- [The Scrum Guide](https://scrumguides.org/scrum-guide.html#daily-scrum), Schwaber and Sutherland, 2020. The Daily Scrum checks progress toward the goal and helps the team find what blocks its work.\n- [Daily stand-up meetings: start breaking the rules](https://doi.org/10.1109/MS.2018.2875988), Stray, Moe and Sjøberg, 2020. In 102 observed stand-ups, a next task or an obstacle usually led to talk about solutions. Past work rarely did.\n- [Engineering communication](https://handbook.gitlab.com/handbook/engineering/workflow/engineering-comms/#sending-status-updates-to-engineering-fyi), GitLab Handbook. GitLab asks for updates on what was completed and what is blocked or at risk. It also asks you to tag relevant people as needed.\n","figures":{}}}'::jsonb)),'{guidance,goingWell}','"Updates say where the work stands and what blocks it"'::jsonb),'v5:f47fe7ff6eb8c562ccf0c9cf0e2d47896ab4d99d25d5da5f02366fcf978ffa7f','practice:v3:838ec270f5cbd9ac442b8988891afe9b09f0d22d65a983b736b7d222cd3d3aed');

CREATE FUNCTION pg_temp.cutover_authored_kind(k text,events jsonb,role_name text,bundled text) RETURNS text LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE inferred text; n bigint; resolved text;
BEGIN
 IF events IS NOT NULL AND events<>'null'::jsonb THEN
  SELECT count(DISTINCT split_part(value,'.',1)||'.'||split_part(value,'.',2)),min(split_part(value,'.',1)||'.'||split_part(value,'.',2)) INTO n,inferred FROM jsonb_array_elements_text(events);
  IF n>1 THEN RAISE EXCEPTION 'authored events have conflicting item kinds'; END IF;
 END IF;
 IF k IS NOT NULL AND inferred IS NOT NULL AND pg_temp.cutover_kind(k)<>pg_temp.cutover_kind(inferred) THEN RAISE EXCEPTION 'authored kind conflicts with its events'; END IF;
 resolved:=pg_temp.cutover_kind(COALESCE(k,inferred,bundled));
 IF role_name='REVIEWER' THEN
  IF resolved<>'scm.pull_request' THEN RAISE EXCEPTION 'reviewer definition does not name a pull request'; END IF;
  RETURN 'scm.pull_request_review';
 END IF;
 IF resolved IS NULL THEN RAISE EXCEPTION 'local authored kind cannot be resolved from released facts'; END IF;
 RETURN resolved;
END $$;

CREATE FUNCTION pg_temp.cutover_catalog(d jsonb,k text,g text) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
 SELECT jsonb_build_object('kind',CASE WHEN d->>'subject'='REVIEWER' THEN 'scm.pull_request_review' ELSE CASE k WHEN 'chat.conversation_thread' THEN 'chat.thread' ELSE k END END,
  'groupSlug',g,'definition',pg_temp.cutover_normalize(pg_temp.cutover_definition(d)) - CASE WHEN d->'subject' IS NULL OR d->'subject'='null'::jsonb THEN 'about' ELSE '_unknown' END)
$$;
INSERT INTO practice_group(id,workspace_id,slug,name,description,icon,color,position,shown_to_developers,feedback_mode,catalog_slug,catalog_base,created_at,updated_at)
SELECT g.id,g.workspace_id,g.slug,g.name,g.description,g.icon,g.color,g.display_order,g.visible_in_practice_dashboards,
 CASE g.autonomy WHEN 'HUMAN_APPROVAL' THEN 'APPROVE_FIRST' ELSE g.autonomy END,g.source_curated_slug,
 CASE WHEN g.source_curated_slug IS NOT NULL THEN COALESCE(b.definition,jsonb_build_object('name',g.name,'description',g.description,'icon',g.icon,'color',g.color)) END,g.created_at,g.updated_at
FROM _cutover_old_practice_group g LEFT JOIN _cutover_bundle b ON b.entry_type='GROUP' AND b.slug=g.source_curated_slug AND b.old_review_fingerprint=g.source_curated_fingerprint;
UPDATE _cutover_sequence SET last_value=GREATEST(last_value,COALESCE((SELECT max(id) FROM _cutover_old_practice_revision),last_value)),is_called=is_called OR EXISTS(SELECT 1 FROM _cutover_old_practice_revision) WHERE table_name='practice_revision';
SELECT pg_temp.cutover_align_sequence('practice_version','practice_revision');
CREATE TEMP TABLE _cutover_initial_version ON COMMIT DROP AS SELECT id AS practice_id,
 COALESCE(current_revision_id,nextval(pg_get_serial_sequence('practice_version','id'))) AS id,
 current_revision_id IS NULL AS unbound FROM _cutover_old_practice;
ALTER TABLE _cutover_initial_version ADD PRIMARY KEY(practice_id);
INSERT INTO practice(id,workspace_id,slug,kind,group_id,position,current_version_id,feedback_mode,catalog_slug,catalog_base,created_at,updated_at)
SELECT p.id,p.workspace_id,p.slug,
 CASE p.subject WHEN 'REVIEWER' THEN 'scm.pull_request_review' ELSE pg_temp.cutover_kind(p.applies_to) END,
 p.practice_group_id,p.display_order,initial_version.id,
 CASE p.autonomy WHEN 'HUMAN_APPROVAL' THEN 'APPROVE_FIRST' ELSE p.autonomy END,p.source_curated_slug,
 CASE WHEN p.source_curated_slug IS NOT NULL THEN COALESCE(
  CASE WHEN p.declined_offered_digest=b.old_catalog_digest THEN jsonb_build_object('kind',CASE WHEN b.old_definition->>'subject'='REVIEWER' THEN 'scm.pull_request_review' ELSE pg_temp.cutover_kind(b.kind) END,'groupSlug',b.old_definition->'groupSlug','definition',b.definition) END,
  CASE WHEN p.adopted_base IS NOT NULL THEN pg_temp.cutover_catalog(p.adopted_base,p.applies_to,p.adopted_base->>'groupSlug') END,
  CASE WHEN b.old_review_fingerprint=p.source_curated_fingerprint THEN jsonb_build_object('kind',CASE WHEN b.old_definition->>'subject'='REVIEWER' THEN 'scm.pull_request_review' ELSE pg_temp.cutover_kind(b.kind) END,'groupSlug',b.old_definition->'groupSlug','definition',b.definition) END,
  (SELECT jsonb_build_object('kind',CASE v.subject WHEN 'REVIEWER' THEN 'scm.pull_request_review' ELSE pg_temp.cutover_kind(v.applies_to) END,'groupSlug',v.group_slug,'definition',pg_temp.cutover_columns(to_jsonb(v)))
   FROM _cutover_old_practice_revision v WHERE v.practice_id=p.id AND v.review_rule_fingerprint=p.source_curated_fingerprint AND v.name IS NOT NULL AND v.subject IS NOT NULL AND v.automated_review_policy IS NOT NULL AND v.signals IS NOT NULL AND v.review_when IS NOT NULL AND v.evidence_requirements IS NOT NULL ORDER BY v.revision_number,v.id LIMIT 1),
  jsonb_build_object('kind',CASE p.subject WHEN 'REVIEWER' THEN 'scm.pull_request_review' ELSE pg_temp.cutover_kind(p.applies_to) END,'groupSlug',g.slug,'definition',pg_temp.cutover_columns(to_jsonb(p)))) END,
 p.created_at,p.updated_at
FROM _cutover_old_practice p JOIN _cutover_initial_version initial_version ON initial_version.practice_id=p.id
LEFT JOIN _cutover_old_practice_group g ON g.id=p.practice_group_id
LEFT JOIN _cutover_bundle b ON b.entry_type='PRACTICE' AND b.slug=p.source_curated_slug;
INSERT INTO practice_version(id,workspace_id,practice_id,number,definition,created_at)
SELECT v.id,p.workspace_id,v.practice_id,v.revision_number,pg_temp.cutover_columns(to_jsonb(v)),v.created_at
FROM _cutover_old_practice_revision v JOIN _cutover_old_practice p ON p.id=v.practice_id;
INSERT INTO practice_version(id,workspace_id,practice_id,number,definition,created_at)
 SELECT i.id,p.workspace_id,p.id,COALESCE((SELECT max(v.revision_number)+1 FROM _cutover_old_practice_revision v WHERE v.practice_id=p.id),1),
 jsonb_set(pg_temp.cutover_columns(to_jsonb(p)),'{reads,contract}','"2.0.0"'::jsonb),c.at
 FROM _cutover_old_practice p JOIN _cutover_initial_version i ON i.practice_id=p.id AND i.unbound CROSS JOIN _cutover_clock c;
INSERT INTO catalog_entry(entry_type,slug,kind,definition,base,position,excluded_at,created_at,updated_at,version)
SELECT 'PRACTICE',o.slug,CASE WHEN o.name IS NOT NULL THEN pg_temp.cutover_authored_kind(o.applies_to,o.signals,o.subject,b.kind) END,
 CASE WHEN o.name IS NOT NULL THEN pg_temp.cutover_columns(to_jsonb(o)) END,
 CASE WHEN o.name IS NOT NULL THEN COALESCE(CASE WHEN o.based_on_digest=b.old_catalog_digest THEN jsonb_build_object('kind',CASE WHEN b.old_definition->>'subject'='REVIEWER' THEN 'scm.pull_request_review' ELSE pg_temp.cutover_kind(b.kind) END,'groupSlug',b.old_definition->'groupSlug','definition',b.definition) END,
 CASE WHEN o.adopted_base IS NOT NULL THEN pg_temp.cutover_catalog(o.adopted_base,COALESCE(o.applies_to,b.kind),o.adopted_base->>'groupSlug') END,
 jsonb_build_object('kind',pg_temp.cutover_authored_kind(o.applies_to,o.signals,o.subject,b.kind),'groupSlug',o.group_slug,'definition',pg_temp.cutover_columns(to_jsonb(o)))) END,
 o.position,o.retired_at,o.created_at,o.updated_at,o.version
FROM _cutover_old_curated_practice_override o LEFT JOIN _cutover_bundle b ON b.entry_type='PRACTICE' AND b.slug=o.slug;
INSERT INTO catalog_entry(entry_type,slug,definition,base,position,excluded_at,created_at,updated_at,version)
SELECT 'GROUP',o.slug,CASE WHEN o.name IS NOT NULL THEN jsonb_build_object('name',o.name,'description',o.description,'icon',o.icon,'color',o.color) END,
 CASE WHEN o.name IS NOT NULL THEN COALESCE(CASE WHEN o.based_on_digest=b.old_catalog_digest THEN b.definition END,jsonb_build_object('name',o.name,'description',o.description,'icon',o.icon,'color',o.color)) END,
 o.position,o.retired_at,o.created_at,o.updated_at,o.version FROM _cutover_old_curated_group_override o LEFT JOIN _cutover_bundle b ON b.entry_type='GROUP' AND b.slug=o.slug;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM catalog_entry WHERE entry_type='PRACTICE' AND definition IS NOT NULL AND kind IS NULL) THEN RAISE EXCEPTION 'local catalog kind cannot be resolved'; END IF;
END $$;

CREATE TEMP TABLE _cutover_offer ON COMMIT DROP AS
 SELECT b.entry_type,b.slug,COALESCE(e.kind,CASE WHEN b.old_definition->>'subject'='REVIEWER' THEN 'scm.pull_request_review' ELSE pg_temp.cutover_kind(b.kind) END) AS kind,
 COALESCE(e.base->>'groupSlug',b.old_definition->>'groupSlug') AS group_slug,COALESCE(e.definition,b.definition) AS definition
 FROM _cutover_bundle b LEFT JOIN catalog_entry e ON e.entry_type=b.entry_type AND e.slug=b.slug WHERE e.excluded_at IS NULL
 UNION ALL SELECT e.entry_type,e.slug,e.kind,e.base->>'groupSlug',e.definition FROM catalog_entry e WHERE e.definition IS NOT NULL AND e.excluded_at IS NULL AND NOT EXISTS(SELECT 1 FROM _cutover_bundle b WHERE b.entry_type=e.entry_type AND b.slug=e.slug);
UPDATE practice p SET catalog_slug=o.slug,catalog_base=jsonb_build_object('kind',o.kind,'groupSlug',o.group_slug,'definition',o.definition)
 FROM _cutover_old_practice source JOIN _cutover_old_practice_catalog_installation i ON i.workspace_id=source.workspace_id AND i.provenance_linked_at IS NULL
 LEFT JOIN _cutover_old_practice_group g ON g.id=source.practice_group_id JOIN _cutover_offer o ON o.entry_type='PRACTICE' AND o.slug=source.slug AND g.slug IS NOT DISTINCT FROM o.group_slug
 WHERE p.id=source.id AND source.source_curated_slug IS NULL AND p.kind=o.kind
 AND pg_temp.cutover_columns(to_jsonb(source))=jsonb_set(o.definition,'{guidance,goingWell}','null'::jsonb);
UPDATE practice_group g SET catalog_slug=o.slug,catalog_base=o.definition
 FROM _cutover_old_practice_group source JOIN _cutover_old_practice_catalog_installation i ON i.workspace_id=source.workspace_id AND i.provenance_linked_at IS NULL
 JOIN _cutover_offer o ON o.entry_type='GROUP' AND o.slug=source.slug
 WHERE g.id=source.id AND source.source_curated_slug IS NULL AND o.definition=jsonb_build_object('name',source.name,'description',source.description,'icon',source.icon,'color',source.color);

CREATE TEMP TABLE _job_key_candidates(job_id uuid,workspace_id bigint,kind varchar(64),source_id bigint) ON COMMIT DROP;
INSERT INTO _job_key_candidates
 SELECT id,workspace_id,
 CASE WHEN metadata->>'subject_role'='REVIEWER' THEN 'scm.pull_request_review'
      ELSE COALESCE(artifact_kind,CASE job_type WHEN 'PULL_REQUEST_REVIEW' THEN 'scm.pull_request'
        WHEN 'ISSUE_REVIEW' THEN 'scm.issue' WHEN 'CONVERSATION_REVIEW' THEN 'chat.thread'
        WHEN 'DOCUMENT_REVIEW' THEN 'docs.document' END) END,
 CASE WHEN metadata->>'subject_role'='REVIEWER' THEN NULLIF(metadata->>'review_id','')::bigint
      ELSE COALESCE(NULLIF(metadata->>'pull_request_id','')::bigint,NULLIF(metadata->>'issue_id','')::bigint,
        NULLIF(metadata->>'slack_thread_id','')::bigint,NULLIF(metadata->>'docs_document_id','')::bigint) END
 FROM _cutover_old_agent_job;
INSERT INTO _job_key_candidates
 SELECT o.agent_job_id,o.workspace_id,
        CASE WHEN j.metadata->>'subject_role'='REVIEWER' THEN 'scm.pull_request_review' ELSE o.artifact_kind END,
        CASE WHEN j.metadata->>'subject_role'='REVIEWER' THEN NULLIF(j.metadata->>'review_id','')::bigint ELSE o.artifact_id END
 FROM _cutover_old_observation o JOIN _cutover_old_agent_job j ON j.id=o.agent_job_id;
INSERT INTO _job_key_candidates
 SELECT s.job_id,s.workspace_id,
        CASE WHEN s.signal_name='scm.pull_request.reviewed' THEN 'scm.pull_request_review' ELSE s.artifact_kind END,
        CASE WHEN s.signal_name='scm.pull_request.reviewed' THEN substring(s.revision FROM 7)::bigint ELSE s.artifact_id END
 FROM _cutover_old_artifact_signal s WHERE s.job_id IS NOT NULL;
INSERT INTO _job_key_candidates
 SELECT f.agent_job_id,f.workspace_id,
        CASE WHEN j.metadata->>'subject_role'='REVIEWER' THEN 'scm.pull_request_review' ELSE f.artifact_kind END,
        CASE WHEN j.metadata->>'subject_role'='REVIEWER' THEN NULLIF(j.metadata->>'review_id','')::bigint ELSE f.artifact_id END
 FROM _cutover_old_feedback f JOIN _cutover_old_agent_job j ON j.id=f.agent_job_id WHERE f.artifact_id IS NOT NULL;

UPDATE _job_key_candidates SET kind=pg_temp.cutover_kind(kind);
-- An exact reviewer event restores reviewer identity when the subject flag was stripped.
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _job_key_candidates c JOIN _job_key_candidates v ON v.job_id=c.job_id
           AND v.kind='scm.pull_request_review' AND v.source_id IS NOT NULL
           WHERE c.kind='scm.pull_request' AND c.source_id IS NOT NULL
           AND NOT EXISTS(SELECT 1 FROM pull_request_review p WHERE p.id=v.source_id AND p.pull_request_id=c.source_id)
           AND NOT EXISTS(SELECT 1 FROM _cutover_old_artifact_signal e WHERE e.job_id=c.job_id
             AND e.signal_name='scm.pull_request.reviewed' AND e.artifact_id=c.source_id
             AND e.revision='event~'||v.source_id::text)) THEN
   RAISE EXCEPTION 'reviewer parent differs from routed pull request'; END IF;
END $$;
UPDATE _job_key_candidates c SET kind='scm.pull_request_review',source_id=v.source_id
 FROM (SELECT job_id,min(source_id) AS source_id FROM _job_key_candidates
       WHERE kind='scm.pull_request_review' AND source_id IS NOT NULL GROUP BY job_id
       HAVING count(DISTINCT source_id)=1) v
 WHERE c.job_id=v.job_id AND c.kind='scm.pull_request';
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _job_key_candidates WHERE source_id IS NOT NULL GROUP BY job_id
           HAVING count(DISTINCT (workspace_id,kind,source_id))>1) THEN
   RAISE EXCEPTION 'job item keys disagree'; END IF;
 IF EXISTS(SELECT 1 FROM _job_key_candidates WHERE source_id<=0 OR (source_id IS NOT NULL AND kind IS NULL)) THEN
   RAISE EXCEPTION 'job has invalid routed item'; END IF;
END $$;
CREATE TEMP TABLE _job_work ON COMMIT DROP AS
 SELECT DISTINCT job_id,workspace_id,kind,source_id FROM _job_key_candidates WHERE source_id IS NOT NULL;
CREATE UNIQUE INDEX ON _job_work(job_id);
CREATE TEMP TABLE _discarded_job_ids ON COMMIT DROP AS
 SELECT j.id FROM _cutover_old_agent_job j WHERE NOT EXISTS(SELECT 1 FROM _job_work w WHERE w.job_id=j.id);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _discarded_job_ids d JOIN _cutover_old_agent_job j ON j.id=d.id
  WHERE (j.metadata IS NOT NULL AND j.metadata<>'{}'::jsonb)
   OR EXISTS(SELECT 1 FROM _cutover_old_observation o WHERE o.agent_job_id=d.id)
   OR EXISTS(SELECT 1 FROM _cutover_old_feedback f WHERE f.agent_job_id=d.id)
   OR EXISTS(SELECT 1 FROM _cutover_old_feedback_dispatch f WHERE f.agent_job_id=d.id)
   OR EXISTS(SELECT 1 FROM _cutover_old_public_review_completion p WHERE p.job_id=d.id)
   OR EXISTS(SELECT 1 FROM _cutover_old_review_composition_basis b WHERE b.job_id=d.id)) THEN
  RAISE EXCEPTION 'unresolved job has product facts or unredacted metadata'; END IF;
END $$;

CREATE TEMP TABLE _work_ref(workspace_id bigint,kind varchar(64),source_id bigint,
 PRIMARY KEY(workspace_id,kind,source_id)) ON COMMIT DROP;
INSERT INTO _work_ref
 SELECT workspace_id,kind,source_id FROM _job_work
 UNION SELECT workspace_id,pg_temp.cutover_kind(artifact_kind),artifact_id FROM _cutover_old_observation
 UNION SELECT workspace_id,pg_temp.cutover_kind(artifact_kind),artifact_id FROM _cutover_old_feedback WHERE artifact_id IS NOT NULL
 UNION SELECT workspace_id,pg_temp.cutover_kind(artifact_kind),artifact_id FROM _cutover_old_artifact_signal
 UNION SELECT workspace_id,pg_temp.cutover_kind(artifact_kind),cursor_artifact_id FROM _cutover_old_review_backfill_run WHERE cursor_artifact_id IS NOT NULL;
INSERT INTO _work_ref
 SELECT workspace_id,'scm.pull_request_review',substring(revision FROM 7)::bigint
 FROM _cutover_old_artifact_signal WHERE signal_name='scm.pull_request.reviewed'
 ON CONFLICT DO NOTHING;
-- Recover immutable ancestry from exact released references even when a provider mirror was removed.
CREATE TEMP TABLE _cutover_review_parent_candidate(workspace_id bigint,review_source_id bigint,parent_source_id bigint) ON COMMIT DROP;
INSERT INTO _cutover_review_parent_candidate
 SELECT x.workspace_id,x.source_id,p.pull_request_id FROM _work_ref x
 JOIN pull_request_review p ON x.kind='scm.pull_request_review' AND p.id=x.source_id
 WHERE p.pull_request_id IS NOT NULL
 UNION ALL SELECT s.workspace_id,substring(s.revision FROM 7)::bigint,s.artifact_id
 FROM _cutover_old_artifact_signal s WHERE s.signal_name='scm.pull_request.reviewed' AND s.artifact_kind='scm.pull_request'
 UNION ALL SELECT w.workspace_id,w.source_id,NULLIF(j.metadata->>'pull_request_id','')::bigint
 FROM _job_work w JOIN _cutover_old_agent_job j ON j.id=w.job_id
 WHERE w.kind='scm.pull_request_review' AND NULLIF(j.metadata->>'pull_request_id','') IS NOT NULL
 UNION ALL SELECT w.workspace_id,w.source_id,o.artifact_id
 FROM _job_work w JOIN _cutover_old_observation o ON o.agent_job_id=w.job_id AND o.workspace_id=w.workspace_id
 WHERE w.kind='scm.pull_request_review' AND o.artifact_kind='scm.pull_request'
 UNION ALL SELECT w.workspace_id,w.source_id,f.artifact_id
 FROM _job_work w JOIN _cutover_old_feedback f ON f.agent_job_id=w.job_id AND f.workspace_id=w.workspace_id
 WHERE w.kind='scm.pull_request_review' AND f.artifact_kind='scm.pull_request' AND f.artifact_id IS NOT NULL;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_review_parent_candidate GROUP BY workspace_id,review_source_id
           HAVING count(DISTINCT parent_source_id)>1)
 OR EXISTS(SELECT 1 FROM _cutover_review_parent_candidate WHERE parent_source_id<=0 OR review_source_id<=0) THEN
   RAISE EXCEPTION 'exact reviewer ancestry disagrees'; END IF;
END $$;
CREATE TEMP TABLE _cutover_review_parent ON COMMIT DROP AS
 SELECT DISTINCT workspace_id,review_source_id,parent_source_id FROM _cutover_review_parent_candidate;
CREATE UNIQUE INDEX ON _cutover_review_parent(workspace_id,review_source_id);
INSERT INTO _work_ref
 SELECT workspace_id,'scm.pull_request',parent_source_id FROM _cutover_review_parent ON CONFLICT DO NOTHING;
-- Parent repositories for all PR/issue items, including shared provider rows.
INSERT INTO _work_ref
 SELECT x.workspace_id,'scm.repository',i.repository_id FROM _work_ref x JOIN issue i ON i.id=x.source_id
 WHERE x.kind IN ('scm.pull_request','scm.issue') AND i.repository_id IS NOT NULL ON CONFLICT DO NOTHING;
-- Adapter-owned workspace tables already have exact tenancy.
INSERT INTO _work_ref SELECT workspace_id,'chat.thread',id FROM slack_thread ON CONFLICT DO NOTHING;
INSERT INTO _work_ref SELECT workspace_id,'docs.document',id FROM outline_document ON CONFLICT DO NOTHING;

CREATE TEMP TABLE _cutover_monitor ON COMMIT DROP AS
 SELECT DISTINCT m.workspace_id,m.id AS monitor_id,r.id AS repository_id FROM repository_to_monitor m
 JOIN workspace w ON w.id=m.workspace_id LEFT JOIN organization o ON o.id=w.organization_id
 JOIN identity_provider p ON p.id=o.provider_id OR (o.id IS NULL AND EXISTS(
  SELECT 1 FROM connection c WHERE c.workspace_id=w.id AND c.kind IN ('GITHUB','GITLAB') AND c.kind=p.type
   AND rtrim(COALESCE(c.config->>'serverUrl',CASE c.kind WHEN 'GITHUB' THEN 'https://github.com' ELSE 'https://gitlab.com' END),'/')=rtrim(p.server_url,'/')))
 JOIN repository r ON r.provider_id=p.id AND ((m.native_id IS NOT NULL AND r.native_id=m.native_id) OR (m.native_id IS NULL AND r.name_with_owner=m.name_with_owner));
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_monitor GROUP BY monitor_id HAVING count(*)>1) THEN RAISE EXCEPTION 'monitor provider/source is ambiguous'; END IF;
 IF EXISTS(SELECT 1 FROM _work_ref WHERE kind NOT IN ('scm.repository','scm.pull_request','scm.issue','scm.pull_request_review','chat.thread','docs.document')) THEN RAISE EXCEPTION 'unknown released item kind'; END IF;
 IF EXISTS(SELECT 1 FROM _work_ref x JOIN issue i ON i.id=x.source_id WHERE (x.kind='scm.pull_request' AND i.issue_type<>'PULL_REQUEST') OR (x.kind='scm.issue' AND i.issue_type<>'ISSUE')) THEN RAISE EXCEPTION 'item kind disagrees with provider mirror'; END IF;
 IF EXISTS(SELECT 1 FROM _work_ref x JOIN slack_thread t ON x.kind='chat.thread' AND t.id=x.source_id WHERE x.workspace_id<>t.workspace_id) OR EXISTS(SELECT 1 FROM _work_ref x JOIN outline_document d ON x.kind='docs.document' AND d.id=x.source_id WHERE x.workspace_id<>d.workspace_id) THEN RAISE EXCEPTION 'source crosses workspace'; END IF;
END $$;
INSERT INTO _work_ref SELECT workspace_id,'scm.repository',repository_id FROM _cutover_monitor ON CONFLICT DO NOTHING;
INSERT INTO item(workspace_id,kind,source_id,created_at,removed_at)
 SELECT x.workspace_id,x.kind,x.source_id,COALESCE(r.created_at,c.at),
        CASE WHEN r.id IS NULL THEN c.at END
 FROM _work_ref x LEFT JOIN repository r ON r.id=x.source_id
 CROSS JOIN _cutover_clock c WHERE x.kind='scm.repository';
INSERT INTO item(workspace_id,kind,source_id,parent_id,created_at,removed_at)
 SELECT x.workspace_id,x.kind,x.source_id,p.id,COALESCE(i.created_at,c.at),
        COALESCE(i.deleted_at,CASE WHEN i.id IS NULL THEN c.at END)
 FROM _work_ref x LEFT JOIN issue i ON i.id=x.source_id
 LEFT JOIN item p ON p.workspace_id=x.workspace_id AND p.kind='scm.repository' AND p.source_id=i.repository_id
 CROSS JOIN _cutover_clock c WHERE x.kind IN ('scm.pull_request','scm.issue');
INSERT INTO item(workspace_id,kind,source_id,parent_id,created_at,removed_at)
 SELECT x.workspace_id,x.kind,x.source_id,p.id,COALESCE(r.submitted_at,c.at),CASE WHEN r.id IS NULL THEN c.at END
 FROM _work_ref x LEFT JOIN pull_request_review r ON r.id=x.source_id
 LEFT JOIN _cutover_review_parent ancestry ON ancestry.workspace_id=x.workspace_id AND ancestry.review_source_id=x.source_id
 LEFT JOIN item p ON p.workspace_id=x.workspace_id AND p.kind='scm.pull_request' AND p.source_id=ancestry.parent_source_id
 CROSS JOIN _cutover_clock c WHERE x.kind='scm.pull_request_review';
INSERT INTO item(workspace_id,kind,source_id,created_at,removed_at)
 SELECT x.workspace_id,x.kind,x.source_id,COALESCE(t.created_at,c.at),CASE WHEN t.id IS NULL THEN c.at END
 FROM _work_ref x LEFT JOIN slack_thread t ON t.id=x.source_id CROSS JOIN _cutover_clock c WHERE x.kind='chat.thread';
INSERT INTO item(workspace_id,kind,source_id,created_at,removed_at)
 SELECT x.workspace_id,x.kind,x.source_id,COALESCE(d.created_at,c.at),
        COALESCE(d.deleted_at,CASE WHEN d.id IS NULL THEN c.at END)
 FROM _work_ref x LEFT JOIN outline_document d ON d.id=x.source_id CROSS JOIN _cutover_clock c WHERE x.kind='docs.document';
CREATE TEMP TABLE _item_map ON COMMIT DROP AS SELECT workspace_id,kind,source_id,id AS item_id FROM item
 UNION ALL SELECT workspace_id,'chat.conversation_thread',source_id,id FROM item WHERE kind='chat.thread';
CREATE UNIQUE INDEX ON _item_map(workspace_id,kind,source_id);
CREATE TEMP TABLE _cutover_person ON COMMIT DROP AS SELECT user_id,account_id FROM _person_map;
ALTER TABLE _cutover_person ADD PRIMARY KEY(user_id);
CREATE TEMP TABLE _cutover_item ON COMMIT DROP AS
 SELECT workspace_id,kind AS old_kind,source_id AS old_source_id,item_id FROM _item_map;
ALTER TABLE _cutover_item ADD PRIMARY KEY(workspace_id,old_kind,old_source_id);

INSERT INTO review_scope_repository(workspace_id,repository_monitor_id,base_branches)
 SELECT workspace_id,repository_monitor_id,base_branches FROM _cutover_old_practice_review_repository_target;
INSERT INTO review_schedule(id,version,workspace_id,kind,cadence,lookback_days,enabled,next_run_at,last_run_at,created_by_account_id,created_at,updated_at)
 SELECT id,version,workspace_id,pg_temp.cutover_kind(artifact_kind),cadence,lookback_days,enabled,next_run_at,last_run_at,created_by_account_id,created_at,updated_at FROM _cutover_old_review_sweep_schedule;
INSERT INTO review_batch(id,version,workspace_id,kind,origin,schedule_id,from_at,to_at,status,pause_reason,estimated_items,estimated_cost_usd,cursor_item_id,submitted_count,skipped_count,failed_count,requested_by_account_id,confirmed_by_account_id,created_at,started_at,finished_at,updated_at)
 SELECT b.id,b.version,b.workspace_id,pg_temp.cutover_kind(b.artifact_kind),CASE b.discovered_via WHEN 'SWEEP' THEN 'SCHEDULE' ELSE 'BACKFILL' END,b.sweep_schedule_id,b.from_at,b.to_at,b.status,b.pause_reason,b.estimated_artifacts,b.estimated_cost_usd,i.item_id,b.submitted_count,b.passed_count,b.failed_count,b.requested_by_account_id,b.confirmed_by_account_id,b.created_at,b.started_at,b.finished_at,b.updated_at
 FROM _cutover_old_review_backfill_run b LEFT JOIN _cutover_item i ON (i.workspace_id,i.old_kind,i.old_source_id)=(b.workspace_id,b.artifact_kind,b.cursor_artifact_id);

INSERT INTO item_event(id,workspace_id,item_id,name,item_version,occurred_at,found_by,
 actor_user_id,requested_by_id,state,reason,decided_at,last_attempted_at,retry_at)
SELECT s.id,s.workspace_id,m.item_id,
 CASE WHEN s.signal_name='scm.pull_request.reviewed' THEN 'scm.pull_request_review.submitted'
 ELSE regexp_replace(s.signal_name,'^chat\.conversation_thread\.','chat.thread.') END,
 s.revision,s.occurred_at,
 CASE s.discovered_via WHEN 'EVENT' THEN 'WEBHOOK' WHEN 'SYNC' THEN 'SYNC'
      WHEN 'MANUAL' THEN 'REQUEST' WHEN 'BACKFILL' THEN 'BACKFILL' WHEN 'SWEEP' THEN 'SCHEDULE' END,
 s.actor_user_id,p.account_id,
 CASE s.state WHEN 'RECORDED' THEN 'RECORDED' WHEN 'DEFERRED' THEN 'WAITING'
      WHEN 'TRIGGERED' THEN 'STARTED' WHEN 'SUPPRESSED' THEN 'WITHHELD'
      WHEN 'PENDING' THEN 'BLOCKED' WHEN 'LAPSED' THEN 'EXPIRED' END,
 CASE s.state_reason WHEN 'GATE_SKIPPED' THEN 'GATE_WITHHELD' WHEN 'PRACTICE_AUTONOMY_OFF' THEN 'FEEDBACK_MODE_OFF'
      WHEN 'ARTIFACT_NOT_VISIBLE' THEN 'ITEM_NOT_VISIBLE' WHEN 'ARTIFACT_GONE' THEN 'ITEM_GONE' ELSE s.state_reason END,
 s.state_changed_at,s.last_attempted_at,
 CASE WHEN s.state IN ('RECORDED','DEFERRED','PENDING') THEN c.at END
FROM _cutover_old_artifact_signal s
JOIN _item_map m ON m.workspace_id=s.workspace_id
 AND m.kind=CASE WHEN s.signal_name='scm.pull_request.reviewed' THEN 'scm.pull_request_review' ELSE s.artifact_kind END
 AND m.source_id=CASE WHEN s.signal_name='scm.pull_request.reviewed' THEN substring(s.revision FROM 7)::bigint ELSE s.artifact_id END
LEFT JOIN _person_map p ON p.user_id=s.requested_by_user_id CROSS JOIN _cutover_clock c;

CREATE TEMP TABLE _job_transition ON COMMIT DROP AS
WITH origins AS (
 SELECT j.id,CASE
   WHEN EXISTS(SELECT 1 FROM _cutover_old_observation o WHERE o.agent_job_id=j.id AND o.origin='BACKFILL')
     OR j.metadata->>'observation_origin'='BACKFILL'
     THEN CASE WHEN EXISTS(SELECT 1 FROM _cutover_old_artifact_signal s WHERE s.job_id=j.id AND s.discovered_via='SWEEP')
               THEN 'SCHEDULE' ELSE 'BACKFILL' END
   WHEN EXISTS(SELECT 1 FROM _cutover_old_observation o WHERE o.agent_job_id=j.id AND o.origin='MANUAL')
     OR j.metadata->>'observation_origin'='MANUAL' THEN 'REQUEST'
   WHEN EXISTS(SELECT 1 FROM _cutover_old_observation o WHERE o.agent_job_id=j.id AND o.origin='LIVE') THEN 'EVENT'
   WHEN EXISTS(SELECT 1 FROM _cutover_old_artifact_signal s WHERE s.job_id=j.id AND s.discovered_via='SWEEP') THEN 'SCHEDULE'
   WHEN EXISTS(SELECT 1 FROM _cutover_old_artifact_signal s WHERE s.job_id=j.id AND s.discovered_via='BACKFILL') THEN 'BACKFILL'
   WHEN EXISTS(SELECT 1 FROM _cutover_old_artifact_signal s WHERE s.job_id=j.id AND s.discovered_via='MANUAL')
     OR j.practice_trigger_mode='MANUAL' THEN 'REQUEST' ELSE 'EVENT' END AS origin
 FROM _cutover_old_agent_job j
), admission AS (
 SELECT agent_job_id,min(observed_at) AS admitted_at FROM _cutover_old_observation GROUP BY agent_job_id
)
SELECT j.id,j.workspace_id,m.item_id,w.kind AS item_kind,o.origin,
 a.admitted_at,
 CASE WHEN o.origin<>'BACKFILL' AND o.origin<>'SCHEDULE'
  AND j.job_type='PULL_REQUEST_REVIEW'
  AND (j.metadata->'subject_role' IS NULL OR j.metadata->>'subject_role'='AUTHOR')
  AND jsonb_typeof(j.metadata->'current_work_at_admission')='boolean'
  AND j.metadata->>'current_work_at_admission'='true'
  AND (j.metadata->>'signal' IN ('scm.pull_request.opened','scm.pull_request.ready',
       'scm.pull_request.synchronized','scm.pull_request.edited','scm.pull_request.manual_review')
       OR (j.metadata->'signal' IS NULL AND j.metadata->>'observation_origin'='MANUAL'))
  AND j.evidence_snapshot->'reviewedWork'->>'retainedBasis'='ADMISSION'
  THEN j.created_at ELSE COALESCE(a.admitted_at,j.completed_at,j.created_at) END AS ordered_at,
 CASE WHEN w.kind='scm.pull_request_review' THEN
      COALESCE(NULLIF(j.evidence_snapshot->'reviewedWork'->>'head',''),NULLIF(j.metadata->>'commit_sha',''),pr.commit_id)
      ELSE COALESCE(NULLIF(j.evidence_snapshot->'reviewedWork'->>'head',''),NULLIF(j.metadata->>'commit_sha',''),
        NULLIF(j.evidence_snapshot->'reviewedWork'->>'titleAndDescriptionRevision',''),
        NULLIF(j.metadata->>'review_snapshot_id',''),NULLIF(j.metadata->>'slack_last_ts','')) END AS captured_head,
 NULLIF(j.metadata->>'base_ref_oid','') AS base_version,
 (SELECT e.id FROM _cutover_old_artifact_signal s JOIN item_event e ON e.id=s.id
  WHERE s.job_id=j.id AND s.workspace_id=j.workspace_id
  ORDER BY CASE WHEN s.signal_name=j.metadata->>'signal' AND s.revision=j.metadata->>'signal_revision'
                THEN 0 ELSE 1 END,s.state_changed_at DESC,s.id LIMIT 1) AS event_candidate,
 (SELECT p.account_id FROM _cutover_old_artifact_signal s JOIN _person_map p ON p.user_id=s.requested_by_user_id
  WHERE s.job_id=j.id AND s.workspace_id=j.workspace_id ORDER BY s.state_changed_at DESC,s.id LIMIT 1) AS requested_by_id
FROM _cutover_old_agent_job j JOIN _job_work w ON w.job_id=j.id
JOIN _item_map m ON (m.workspace_id,m.kind,m.source_id)=(w.workspace_id,w.kind,w.source_id)
JOIN origins o ON o.id=j.id LEFT JOIN admission a ON a.agent_job_id=j.id
LEFT JOIN pull_request_review pr ON w.kind='scm.pull_request_review' AND pr.id=w.source_id;
CREATE UNIQUE INDEX ON _job_transition(id);

INSERT INTO review(id,workspace_id,item_id,kind,item_version,base_version,origin,event_id,batch_id,
 requested_by_id,status,stop_reason,budget_usd,rollout_revision,ordered_at,created_at,admitted_at,completed_at,public_review_at)
SELECT j.id,j.workspace_id,t.item_id,'ITEM',
 CASE WHEN t.item_kind='scm.pull_request' AND t.base_version IS NOT NULL AND t.captured_head IS NOT NULL
      THEN 'base~'||t.base_version||'~head~'||t.captured_head ELSE t.captured_head END,
 t.base_version,t.origin,CASE WHEN t.origin='EVENT' THEN t.event_candidate END,NULL,
 CASE WHEN t.origin='REQUEST' THEN t.requested_by_id END,
 CASE WHEN j.status IN ('QUEUED','RUNNING') THEN CASE WHEN t.admitted_at IS NOT NULL THEN 'PARTIAL' ELSE 'CANCELLED' END WHEN j.status='COMPLETED' AND j.delivery_status='FAILED' THEN 'FAILED'
      WHEN j.status='COMPLETED' THEN 'COMPLETE' WHEN j.status='CANCELLED' THEN 'CANCELLED'
      WHEN j.status IN ('FAILED','TIMED_OUT') THEN 'FAILED' ELSE j.status END,
 CASE WHEN j.status IN ('QUEUED','RUNNING') THEN 'CONTRACT_CHANGED' WHEN j.status='TIMED_OUT' THEN 'TIMED_OUT'
      WHEN j.status='FAILED' THEN 'EXECUTION_FAILED'
      WHEN j.status='COMPLETED' AND j.delivery_status='FAILED' THEN 'PROCESSING_FAILED'
      WHEN j.status='CANCELLED' THEN CASE j.cancellation_reason
        WHEN 'PERSON_DATA_ERASED' THEN 'PERSON_DATA_ERASED'
        WHEN 'STALE_ROLLOUT_REVISION' THEN 'STALE_ROLLOUT_REVISION'
        WHEN 'REPLACED' THEN 'REPLACED' ELSE 'LEGACY_FAILURE' END END,
 NULL,j.practice_rollout_revision,t.ordered_at,j.created_at,t.admitted_at,CASE WHEN j.status IN ('QUEUED','RUNNING') THEN c.at ELSE j.completed_at END,p.accepted_at
FROM _cutover_old_agent_job j JOIN _job_transition t ON t.id=j.id
LEFT JOIN _cutover_old_public_review_completion p ON p.job_id=j.id AND p.workspace_id=j.workspace_id CROSS JOIN _cutover_clock c;

INSERT INTO review_job(id,review_id,workspace_id,status,attempt,processing_status,available_at,hold_reason,worker_id,
 idempotency_key,trace_id,job_token_hash,input,config_snapshot,capture,output,exit_code,error_message,cancellation_reason,
 delivery_attempts,conversation_prepared_at,practice_page_prepared_at,public_review_digest,admission_attempt,admission_digest,
 llm_calls,llm_input_tokens,llm_output_tokens,llm_reasoning_tokens,llm_cache_read_tokens,llm_cache_write_tokens,
 started_at,execution_started_at,completed_at)
SELECT j.id,j.id,j.workspace_id,CASE WHEN j.status IN ('QUEUED','RUNNING') THEN 'CANCELLED' ELSE j.status END,j.retry_count,
 CASE WHEN j.status IN ('QUEUED','RUNNING') THEN 'DONE' ELSE CASE j.delivery_status WHEN 'PENDING' THEN 'FAILED' WHEN 'DELIVERED' THEN 'DONE' WHEN 'FAILED' THEN 'FAILED' ELSE 'NONE' END END,
 j.available_at,j.hold_reason,CASE WHEN j.status IN ('QUEUED','RUNNING') THEN NULL ELSE j.worker_id END,j.idempotency_key,j.trace_id,CASE WHEN j.status IN ('QUEUED','RUNNING') THEN NULL ELSE j.job_token_hash END,jsonb_build_object('reviewId',j.id,'itemId',r.item_id::text),j.config_snapshot,
 j.evidence_snapshot-'reviewedWork'-'practices'-'answeredPractices',j.output,j.exit_code,j.error_message,CASE WHEN j.status IN ('QUEUED','RUNNING') THEN 'CONTRACT_CHANGED' ELSE CASE WHEN j.cancellation_reason IN('DRAIN_GRACEFUL','DRAIN_IMMEDIATE','BUDGET_EXHAUSTED','MODEL_UNAVAILABLE','MEMBER_AI_DECLINED','PERSON_DATA_ERASED','CANCELLED_BY_ADMIN','CANCELLED_BY_REQUESTER','CONTRACT_CHANGED') THEN j.cancellation_reason END END,
 j.delivery_attempts,j.in_chat_prepared_at,j.in_app_prepared_at,p.review_digest,
 COALESCE(p.admission_attempt,NULLIF(j.metadata->>'observation_admission_attempt','')::integer),
 COALESCE(p.admission_digest,NULLIF(j.metadata->>'observation_admission_digest','')),
 COALESCE(j.llm_total_calls,0),COALESCE(j.llm_total_input_tokens,0),COALESCE(j.llm_total_output_tokens,0),
 COALESCE(j.llm_total_reasoning_tokens,0),COALESCE(j.llm_cache_read_tokens,0),COALESCE(j.llm_cache_write_tokens,0),
 j.started_at,j.execution_started_at,CASE WHEN j.status IN ('QUEUED','RUNNING') THEN c.at ELSE j.completed_at END
FROM _cutover_old_agent_job j JOIN review r ON r.id=j.id
LEFT JOIN _cutover_old_public_review_completion p ON p.job_id=j.id AND p.workspace_id=j.workspace_id CROSS JOIN _cutover_clock c;


UPDATE review r SET checks=jsonb_build_object('MIGRATION',jsonb_build_object(
 'jobStatus',j.status,'processingStatus',j.delivery_status,'triggerMode',j.practice_trigger_mode,
 'cancellationReason',j.cancellation_reason)) FROM _cutover_old_agent_job j WHERE j.id=r.id;
INSERT INTO review_composition_basis(job_id,workspace_id,admission_attempt,admission_digest,basis_digest,basis_version,copy_id,expires_at,payload)
SELECT job_id,workspace_id,admission_attempt,admission_digest,basis_digest,basis_version,copy_id,expires_at,payload FROM _cutover_old_review_composition_basis;
ALTER TABLE llm_usage_event ADD COLUMN review_id uuid,ADD COLUMN search_units bigint NOT NULL DEFAULT 0,ADD COLUMN unreported_calls integer NOT NULL DEFAULT 0;
ALTER TABLE llm_usage_event DROP CONSTRAINT ck_llm_usage_event_source_type;
ALTER TABLE llm_usage_event ALTER COLUMN source_type TYPE varchar(32);
UPDATE llm_usage_event e SET review_id=j.review_id FROM review_job j WHERE e.source_type='AGENT_JOB' AND e.source_id=j.id AND e.workspace_id=j.workspace_id;
UPDATE llm_usage_event SET source_type='REVIEW_JOB' WHERE source_type='AGENT_JOB';
ALTER TABLE llm_usage_event ADD CONSTRAINT ck_llm_usage_event_source_type CHECK(source_type IN ('REVIEW_JOB','MENTOR_TURN','PRACTICE_SCRIPT_DECISION','PRACTICE_SCRIPT_EMBEDDING','PRACTICE_SCRIPT_RERANKING'));
ALTER TABLE llm_usage_event ADD CONSTRAINT uk_llm_usage_event_workspace UNIQUE(id,workspace_id);
ALTER TABLE llm_usage_event ADD CONSTRAINT sfk_llm_usage_event_review FOREIGN KEY(review_id,workspace_id) REFERENCES review(id,workspace_id) ON DELETE SET NULL(review_id);
ALTER TABLE llm_usage_event ADD CONSTRAINT ck_llm_usage_event_counts CHECK(search_units>=0 AND unreported_calls>=0);
ALTER TABLE person_evidence_copy ADD COLUMN created_at timestamptz;
UPDATE person_evidence_copy e SET created_at=COALESCE(j.created_at,c.at) FROM _cutover_clock c LEFT JOIN _cutover_old_agent_job j ON true WHERE e.job_id=j.id;
UPDATE person_evidence_copy SET created_at=(SELECT at FROM _cutover_clock) WHERE created_at IS NULL;
ALTER TABLE person_evidence_copy ALTER COLUMN created_at SET NOT NULL,ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE person_evidence_copy ADD CONSTRAINT uk_person_evidence_copy_workspace UNIQUE(id,workspace_id);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_old_observation GROUP BY agent_job_id,practice_id HAVING count(DISTINCT practice_revision_id)>1 OR (count(practice_revision_id)>0 AND count(practice_revision_id)<count(*))) THEN RAISE EXCEPTION 'result/capture version is ambiguous'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_agent_job j CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(j.evidence_snapshot->'practices')='array' THEN j.evidence_snapshot->'practices' ELSE '[]'::jsonb END) e WHERE NOT EXISTS(SELECT 1 FROM practice p WHERE p.workspace_id=j.workspace_id AND p.slug=e->>'slug')) THEN RAISE EXCEPTION 'captured practice does not exist in workspace'; END IF;
END $$;
INSERT INTO review_practice(review_id,practice_id,workspace_id,practice_version_id,status,items_listed,listing_complete)
 SELECT o.agent_job_id,o.practice_id,o.workspace_id,min(o.practice_revision_id),'DONE',1,true
 FROM _cutover_old_observation o GROUP BY o.agent_job_id,o.practice_id,o.workspace_id;

CREATE TEMP TABLE _captured_practice ON COMMIT DROP AS
 SELECT j.id AS review_id,j.workspace_id,p.id AS practice_id,
        NULLIF(e.value->>'revisionId','')::bigint AS version_id
 FROM _cutover_old_agent_job j CROSS JOIN LATERAL jsonb_array_elements(
   CASE WHEN jsonb_typeof(j.evidence_snapshot->'practices')='array'
        THEN j.evidence_snapshot->'practices' ELSE '[]'::jsonb END) e(value)
 JOIN practice p ON p.workspace_id=j.workspace_id AND p.slug=e.value->>'slug';
CREATE TEMP TABLE _capture_decision ON COMMIT DROP AS
 SELECT j.id AS review_id,j.workspace_id,p.id AS practice_id,d.value AS decision
 FROM _cutover_old_agent_job j CROSS JOIN LATERAL jsonb_array_elements(
   CASE WHEN jsonb_typeof(j.review_readiness->'decisions')='array'
        THEN j.review_readiness->'decisions' ELSE '[]'::jsonb END) d(value)
 JOIN practice p ON p.workspace_id=j.workspace_id AND p.slug=d.value->>'practiceSlug';

INSERT INTO review_practice(review_id,practice_id,workspace_id,practice_version_id,status,reason,
 items_listed,listing_complete,capture_decision)
 SELECT k.review_id,k.practice_id,k.workspace_id,c.version_id,
 CASE WHEN d.decision->>'ready'='false' THEN 'WITHHELD'
      WHEN j.status IN ('FAILED','TIMED_OUT','CANCELLED') THEN 'FAILED' ELSE 'WITHHELD' END,
 CASE WHEN d.decision->>'ready'='false' THEN 'READINESS_REFUSED'
      WHEN j.status IN ('FAILED','TIMED_OUT','CANCELLED') THEN 'EXECUTION_FAILED' ELSE 'NO_RECORDED_RESULT' END,
 1,CASE WHEN j.evidence_snapshot->'manifest' IS NOT NULL THEN true ELSE NULL END,d.decision
 FROM (SELECT review_id,workspace_id,practice_id FROM _captured_practice
       UNION SELECT review_id,workspace_id,practice_id FROM _capture_decision) k
 JOIN _cutover_old_agent_job j ON j.id=k.review_id JOIN review r ON r.id=k.review_id
 LEFT JOIN _captured_practice c ON (c.review_id,c.workspace_id,c.practice_id)=(k.review_id,k.workspace_id,k.practice_id)
 LEFT JOIN _capture_decision d ON (d.review_id,d.workspace_id,d.practice_id)=(k.review_id,k.workspace_id,k.practice_id)
 ON CONFLICT(review_id,practice_id) DO UPDATE SET capture_decision=EXCLUDED.capture_decision;
INSERT INTO result(id,workspace_id,review_id,practice_id,practice_version_id,item_id,item_version,developer_id,
 outcome,severity,summary,explanation,evidence,evidence_version,recorded_at,ended_at,end_reason)
SELECT o.id,o.workspace_id,o.agent_job_id,o.practice_id,o.practice_revision_id,
 CASE WHEN t.item_kind='scm.pull_request_review' THEN t.item_id ELSE m.item_id END,
 r.item_version,p.account_id,
 CASE o.outcome WHEN 'NOT_APPLICABLE' THEN 'DOES_NOT_APPLY' WHEN 'UNDETERMINED' THEN 'COULD_NOT_DETERMINE' ELSE o.outcome END,
 CASE o.severity WHEN 'INFO' THEN 'TRIVIAL' ELSE o.severity END,
 o.summary,o.evidence_rationale,
 CASE WHEN jsonb_typeof(o.evidence->'undecidability')='object' THEN
      (o.evidence-'undecidability')||jsonb_build_object('openQuestions',jsonb_build_array(o.evidence->'undecidability'))
      WHEN jsonb_typeof(o.evidence->'undecidability')='array' THEN
      (o.evidence-'undecidability')||jsonb_build_object('openQuestions',o.evidence->'undecidability')
      ELSE CASE WHEN jsonb_exists(o.evidence, 'undecidability') THEN (o.evidence-'undecidability')||jsonb_build_object('openQuestions',o.evidence->'undecidability') ELSE o.evidence END END,
 0,o.observed_at,
 CASE WHEN o.superseded_at IS NOT NULL THEN greatest(o.superseded_at,o.observed_at) END,
 CASE WHEN o.superseded_at IS NOT NULL THEN 'WORK_CHANGED' END
FROM _cutover_old_observation o JOIN review r ON r.id=o.agent_job_id
JOIN _job_transition t ON t.id=o.agent_job_id
JOIN _item_map m ON (m.workspace_id,m.kind,m.source_id)=(o.workspace_id,o.artifact_kind,o.artifact_id)
JOIN _person_map p ON p.user_id=o.about_user_id;

INSERT INTO problem(id,workspace_id,result_id,position,key,severity,summary,explanation,citations,basis)
SELECT gen_random_uuid(),o.workspace_id,o.id,0,NULL,
 CASE o.severity WHEN 'INFO' THEN 'TRIVIAL' ELSE o.severity END,
 o.summary,COALESCE(o.evidence_rationale,o.summary),
 CASE WHEN jsonb_typeof(o.evidence->'citations')='array' THEN o.evidence->'citations' ELSE '[]'::jsonb END,NULL
FROM _cutover_old_observation o WHERE o.outcome='NOT_MET';

INSERT INTO result_mark(id,workspace_id,result_id,kind,reason,created_by_id,created_at,removed_by_id,removed_at,removal_reason)
SELECT id,workspace_id,observation_id,'INCORRECT',reason,invalidated_by_account_id,invalidated_at,
 restored_by_account_id,restored_at,restoration_reason FROM _cutover_old_observation_invalidation;

INSERT INTO review_item(workspace_id,review_id,practice_id,item_id,item_version,state,result_id,job_id,attempted_at)
 SELECT workspace_id,review_id,practice_id,item_id,item_version,'JUDGED',id,review_id,recorded_at FROM result;
INSERT INTO review_item(workspace_id,review_id,practice_id,item_id,item_version,state,job_id,attempted_at,reason,detail)
 SELECT p.workspace_id,p.review_id,p.practice_id,r.item_id,r.item_version,'WITHHELD',j.id,j.started_at,
        COALESCE(p.reason,'NO_RECORDED_RESULT'),CASE WHEN octet_length(p.capture_decision::text)<=8192 THEN p.capture_decision END
 FROM review_practice p JOIN review r ON r.id=p.review_id JOIN review_job j ON j.review_id=r.id
 WHERE NOT EXISTS(SELECT 1 FROM review_item a WHERE a.review_id=p.review_id AND a.practice_id=p.practice_id);

CREATE FUNCTION pg_temp.cutover_citations(v jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE out_value jsonb; k text; child jsonb; proof jsonb;
BEGIN
 IF v IS NULL THEN RETURN NULL; END IF;
 IF jsonb_typeof(v)='array' THEN
  SELECT COALESCE(jsonb_agg(pg_temp.cutover_citations(e.value) ORDER BY e.ordinal),'[]'::jsonb)
   INTO out_value FROM jsonb_array_elements(v) WITH ORDINALITY e(value,ordinal);
  RETURN out_value;
 END IF;
 IF jsonb_typeof(v)<>'object' THEN RETURN v; END IF;
 out_value := '{}'::jsonb;
 FOR k,child IN SELECT key,value FROM jsonb_each(v) LOOP
  out_value := out_value || jsonb_build_object(k,pg_temp.cutover_citations(child));
 END LOOP;
 IF out_value ? 'sourceKind' AND out_value ? 'artifactPath' THEN
  IF out_value ? 'sourcePath' AND out_value->'sourcePath' IS DISTINCT FROM out_value->'artifactPath' THEN
   RAISE EXCEPTION 'legacy citation paths conflict'; END IF;
  out_value := (out_value-'artifactPath')||jsonb_build_object('sourcePath',out_value->'artifactPath');
  IF jsonb_typeof(out_value->'verification')='object' THEN
   proof := out_value->'verification';
   proof := proof-'jobId'-'attempt'-'scope'-'citationSha256';
   out_value := jsonb_set(out_value,'{verification}',proof);
  END IF;
 END IF;
 RETURN out_value;
END $$;
UPDATE result SET evidence=pg_temp.cutover_citations(evidence),example=pg_temp.cutover_citations(example);
UPDATE problem SET citations=pg_temp.cutover_citations(citations);
UPDATE result SET evidence=jsonb_set(evidence,'{inapplicability}',
 ((evidence->'inapplicability')-'subject')||jsonb_build_object('prerequisite',evidence->'inapplicability'->'subject'))
 WHERE jsonb_typeof(evidence->'inapplicability')='object' AND jsonb_exists(evidence->'inapplicability', 'subject');

UPDATE review r SET status='PARTIAL',stop_reason=CASE
 WHEN EXISTS(SELECT 1 FROM review_item a WHERE a.review_id=r.id AND a.state='WITHHELD')
 THEN 'RESULT_WITHHELD' ELSE 'LEGACY_SCOPE_UNKNOWN' END
 WHERE r.status='COMPLETE' AND (
  EXISTS(SELECT 1 FROM review_item a WHERE a.review_id=r.id AND a.state IN ('LISTED','WITHHELD'))
  OR NOT EXISTS(SELECT 1 FROM review_item a WHERE a.review_id=r.id));

CREATE TEMP TABLE _cutover_result ON COMMIT DROP AS SELECT r.id AS observation_id,r.id AS result_id,p.id AS problem_id,r.workspace_id,r.developer_id FROM result r LEFT JOIN problem p ON p.result_id=r.id;
ALTER TABLE _cutover_result ADD PRIMARY KEY(observation_id);
CREATE TEMP TABLE _cutover_review ON COMMIT DROP AS
SELECT r.id AS job_id,r.id AS review_id,r.workspace_id,r.item_id,
 COALESCE((SELECT m.account_id FROM _cutover_person m JOIN _cutover_old_agent_job j ON j.id=r.id WHERE j.metadata->>'about_user_id'=m.user_id::text),
 (SELECT min(x.developer_id) FROM result x WHERE x.review_id=r.id HAVING count(DISTINCT x.developer_id)=1)) AS developer_id FROM review r;
ALTER TABLE _cutover_review ADD PRIMARY KEY(job_id);
UPDATE result SET evidence=evidence-'citations' WHERE outcome='NOT_MET';
CREATE TEMP TABLE _claim_rank ON COMMIT DROP AS
SELECT r.id,r.practice_id,r.item_id,r.developer_id,r.recorded_at,v.origin,v.ordered_at,v.id AS review_id,
 row_number() OVER(PARTITION BY r.practice_id,r.item_id,r.developer_id ORDER BY CASE WHEN v.origin IN ('EVENT','REQUEST') THEN 0 ELSE 1 END,v.ordered_at DESC,r.recorded_at DESC,v.id::text DESC,r.id::text DESC) AS rn
FROM result r JOIN review v ON v.id=r.review_id WHERE r.ended_at IS NULL;
UPDATE result loser SET ended_at=greatest(loser.recorded_at,winner.recorded_at),
 end_reason=CASE WHEN l.origin IN ('BACKFILL','SCHEDULE') AND w.origin IN ('EVENT','REQUEST') OR l.ordered_at>w.ordered_at THEN 'OUTRANKED' ELSE 'REPLACED' END
FROM _claim_rank l JOIN _claim_rank w ON w.practice_id=l.practice_id AND w.item_id=l.item_id AND w.developer_id IS NOT DISTINCT FROM l.developer_id AND w.rn=1
JOIN result winner ON winner.id=w.id WHERE loser.id=l.id AND l.rn>1;



CREATE TEMP TABLE _cutover_answered ON COMMIT DROP AS
 SELECT j.id AS review_id,j.workspace_id,p.id AS practice_id,(e->>'revisionId')::bigint AS version_id,
 (SELECT r.id FROM result r JOIN review current_review ON current_review.id=j.id
 JOIN _cutover_review owner ON owner.review_id=j.id
 WHERE r.review_id=(NULLIF(e->>'reviewId',''))::uuid AND r.practice_id=p.id AND r.practice_version_id=(e->>'revisionId')::bigint
 AND r.workspace_id=j.workspace_id AND r.item_id=current_review.item_id AND r.item_version IS NOT DISTINCT FROM current_review.item_version
 AND r.developer_id IS NOT DISTINCT FROM owner.developer_id) AS result_id
 FROM _cutover_old_agent_job j CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(j.evidence_snapshot->'answeredPractices')='array' THEN j.evidence_snapshot->'answeredPractices' ELSE '[]'::jsonb END) e
 JOIN practice p ON p.workspace_id=j.workspace_id AND p.slug=e->>'practiceSlug';
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_old_agent_job j CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(j.evidence_snapshot->'answeredPractices')='array' THEN j.evidence_snapshot->'answeredPractices' ELSE '[]'::jsonb END) e WHERE NOT EXISTS(SELECT 1 FROM practice p WHERE p.workspace_id=j.workspace_id AND p.slug=e->>'practiceSlug')) THEN RAISE EXCEPTION 'answered practice is not in workspace'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_answered GROUP BY review_id,practice_id HAVING count(*)>1) THEN RAISE EXCEPTION 'answered practice is ambiguous'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_answered a JOIN review_practice p ON p.review_id=a.review_id AND p.practice_id=a.practice_id WHERE a.version_id IS DISTINCT FROM p.practice_version_id AND EXISTS(SELECT 1 FROM result r WHERE r.review_id=a.review_id AND r.practice_id=a.practice_id)) THEN RAISE EXCEPTION 'answered version conflicts with admission'; END IF;
END $$;
INSERT INTO review_practice(review_id,practice_id,workspace_id,practice_version_id,status,reason,items_listed,listing_complete)
 SELECT review_id,practice_id,workspace_id,version_id,CASE WHEN result_id IS NULL THEN 'WITHHELD' ELSE 'DONE' END,CASE WHEN result_id IS NULL THEN 'LEGACY_REUSE_UNBOUND' END,1,true FROM _cutover_answered
 ON CONFLICT(review_id,practice_id) DO UPDATE SET practice_version_id=EXCLUDED.practice_version_id,status=EXCLUDED.status,reason=EXCLUDED.reason,items_listed=1,listing_complete=true
 WHERE NOT EXISTS(SELECT 1 FROM result r WHERE r.review_id=EXCLUDED.review_id AND r.practice_id=EXCLUDED.practice_id);
INSERT INTO review_item(workspace_id,review_id,practice_id,item_id,item_version,state,result_id,job_id,reason)
 SELECT a.workspace_id,a.review_id,a.practice_id,r.item_id,r.item_version,CASE WHEN a.result_id IS NULL THEN 'WITHHELD' ELSE 'REUSED' END,a.result_id,a.review_id,CASE WHEN a.result_id IS NULL THEN 'LEGACY_REUSE_UNBOUND' END
 FROM _cutover_answered a JOIN review r ON r.id=a.review_id WHERE NOT EXISTS(SELECT 1 FROM result produced WHERE produced.review_id=a.review_id AND produced.practice_id=a.practice_id)
 ON CONFLICT(review_id,practice_id,item_id) DO UPDATE SET state=EXCLUDED.state,result_id=EXCLUDED.result_id,reason=EXCLUDED.reason;


UPDATE review_job j SET input=jsonb_build_object('itemId',r.item_id,'assignments',COALESCE(
 (SELECT jsonb_agg(jsonb_build_object('reviewId',a.review_id,'practiceId',a.practice_id,'itemId',a.item_id) ORDER BY a.practice_id,a.item_id)
  FROM review_item a WHERE a.review_id=j.review_id AND a.workspace_id=j.workspace_id),'[]'::jsonb))
 FROM review r WHERE r.id=j.review_id AND r.workspace_id=j.workspace_id;

CREATE FUNCTION pg_temp.cutover_stop(v text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE v
 WHEN 'COMPOSER_DEDUPED' THEN 'NOTHING_NEW' WHEN 'REACTED_DISPUTED' THEN 'REACTED_DISAGREE'
 WHEN 'ARTIFACT_GONE' THEN 'ITEM_GONE' WHEN 'ARTIFACT_CLOSED' THEN 'ITEM_CLOSED' WHEN 'ARTIFACT_MERGED' THEN 'ITEM_MERGED'
 WHEN 'ARTIFACT_DRAFT' THEN 'ITEM_STATE_INELIGIBLE' WHEN 'RECIPIENT_OPTED_OUT' THEN 'RECIPIENT_UNAVAILABLE'
 WHEN 'OUTSIDE_CURRENT_COVERAGE' THEN 'OUTSIDE_CURRENT_SCOPE' WHEN 'OBSERVATION_INVALIDATED' THEN 'RESULT_MARKED_INCORRECT'
 WHEN 'REVIEWED_REVISION_CHANGED' THEN 'REVIEWED_VERSION_CHANGED' ELSE v END $$;
CREATE TEMP TABLE _cutover_send_parent(dispatch_id uuid PRIMARY KEY,feedback_id uuid NOT NULL,workspace_id bigint NOT NULL,review_id uuid NOT NULL,developer_id bigint NOT NULL) ON COMMIT DROP;
INSERT INTO _cutover_send_parent
 SELECT d.id,coalesce(d.feedback_id,f.id,d.id),d.workspace_id,r.review_id,coalesce(p.account_id,r.developer_id)
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_review r ON r.job_id=d.agent_job_id AND r.workspace_id=d.workspace_id
 LEFT JOIN LATERAL(SELECT x.id,x.recipient_user_id FROM _cutover_old_feedback x WHERE x.agent_job_id=d.agent_job_id AND x.workspace_id=d.workspace_id AND x.channel='IN_CONTEXT' AND x.position IN(0,5000) ORDER BY (x.position=0) DESC,x.created_at,x.id LIMIT 1) f ON d.feedback_id IS NULL
 LEFT JOIN _cutover_old_feedback approved ON approved.id=d.feedback_id
 LEFT JOIN _cutover_person p ON p.user_id=coalesce(approved.recipient_user_id,f.recipient_user_id);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_send_parent GROUP BY feedback_id HAVING count(*)>1) THEN RAISE EXCEPTION 'multiple physical sends resolve to one feedback'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_feedback f LEFT JOIN _cutover_person p ON p.user_id=f.recipient_user_id LEFT JOIN _cutover_person subject ON subject.user_id=f.about_user_id WHERE p.account_id IS NULL OR p.account_id IS DISTINCT FROM subject.account_id) THEN RAISE EXCEPTION 'feedback person is ambiguous'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_feedback_dispatch d WHERE NOT EXISTS(SELECT 1 FROM _cutover_send_parent p WHERE p.dispatch_id=d.id)) THEN RAISE EXCEPTION 'send cannot resolve its review/person'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_feedback_dispatch d JOIN _cutover_old_feedback f ON f.id=d.feedback_id WHERE d.body IS DISTINCT FROM coalesce(f.body,'')) THEN RAISE EXCEPTION 'approved summary text differs from its released proposal'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_feedback_dispatch d WHERE d.package_content->>'inlineMarker' IS NOT NULL AND d.package_content->>'inlineMarker' IS DISTINCT FROM CASE WHEN d.feedback_id IS NOT NULL THEN '<!-- hephaestus-approved-package:'||d.feedback_id||' -->' ELSE '<!-- hephaestus-review-package:'||d.agent_job_id||' -->' END) THEN RAISE EXCEPTION 'sealed marker differs from its released package'; END IF;
END $$;
INSERT INTO feedback(id,workspace_id,review_id,item_id,developer_id,destination,state,stop_reason,body,checks,replaces_id,created_at,delivered_at)
 SELECT f.id,f.workspace_id,f.agent_job_id,CASE WHEN f.channel='IN_CONTEXT' THEN r.item_id ELSE i.item_id END,p.account_id,
 CASE f.channel WHEN 'IN_CONTEXT' THEN 'ON_WORK' WHEN 'IN_APP' THEN 'PRACTICE_PAGE' WHEN 'IN_CHAT' THEN 'CONVERSATION' END,
 CASE f.delivery_state WHEN 'PREPARED' THEN 'READY' WHEN 'PARTIALLY_DELIVERED' THEN 'DELIVERED' WHEN 'PARTIALLY_FAILED' THEN 'DELIVERED' WHEN 'SUPPRESSED' THEN 'WITHHELD' WHEN 'DISCARDED' THEN 'REJECTED' WHEN 'SUPERSEDED' THEN 'REPLACED' ELSE f.delivery_state END,
 CASE WHEN f.delivery_state='UNCONFIRMED' THEN 'DELIVERY_UNCONFIRMED' ELSE pg_temp.cutover_stop(f.suppression_reason) END,
 f.body,jsonb_build_object('MIGRATION',jsonb_build_object('deliveryState',f.delivery_state,'stopReason',f.suppression_reason,'reviewedVersion',f.reviewed_revision)),f.replaces_id,f.created_at,
 COALESCE(f.delivered_at,(SELECT min(c.created_at) FROM _cutover_old_feedback_placement c WHERE c.feedback_id=f.id AND (c.posted_comment_ref IS NOT NULL OR c.chat_message_id IS NOT NULL) AND f.delivery_state<>'UNCONFIRMED'),
 (SELECT min(d.updated_at) FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id WHERE sp.feedback_id=f.id AND d.delivered_external_ref IS NOT NULL))
 FROM _cutover_old_feedback f JOIN _cutover_person p ON p.user_id=f.recipient_user_id JOIN review r ON r.id=f.agent_job_id AND r.workspace_id=f.workspace_id
 LEFT JOIN _cutover_item i ON(i.workspace_id,i.old_kind,i.old_source_id)=(f.workspace_id,f.artifact_kind,f.artifact_id);
INSERT INTO feedback(id,workspace_id,review_id,item_id,developer_id,destination,state,stop_reason,body,checks,created_at,delivered_at)
 SELECT sp.feedback_id,d.workspace_id,sp.review_id,r.item_id,sp.developer_id,'ON_WORK',
 CASE WHEN d.delivered_external_ref IS NOT NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(pg_temp.cutover_array(d.delivered_placements)) e WHERE nullif(e->>'externalRef','') IS NOT NULL AND e->>'disposition' IN('POSTED','FELL_BACK','PRESERVED_EXISTING')) THEN 'DELIVERED'
 WHEN d.state='SUPPRESSED' THEN 'WITHHELD' WHEN d.state='FAILED' THEN 'FAILED' WHEN d.state='SENT' THEN 'WITHHELD'
 WHEN d.write_started OR d.inline_write_started IS DISTINCT FROM false THEN 'UNCONFIRMED' ELSE 'READY' END,
 CASE WHEN d.state='SENT' AND d.delivered_external_ref IS NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(pg_temp.cutover_array(d.delivered_placements)) e WHERE nullif(e->>'externalRef','') IS NOT NULL) THEN 'NOTHING_NEW' ELSE pg_temp.cutover_stop(d.suppression_reason) END,
 d.body,jsonb_build_object('MIGRATION',jsonb_build_object('dispatchId',d.id,'state',d.state,'stopReason',d.suppression_reason,'renderedTextKnown',(d.feedback_id IS NOT NULL OR d.package_content->>'inlineMarker' IS NOT NULL))),d.created_at,
 CASE WHEN d.delivered_external_ref IS NOT NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(pg_temp.cutover_array(d.delivered_placements)) e WHERE nullif(e->>'externalRef','') IS NOT NULL AND e->>'disposition' IN('POSTED','FELL_BACK','PRESERVED_EXISTING')) THEN d.updated_at END
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id JOIN review r ON r.id=sp.review_id
 WHERE NOT EXISTS(SELECT 1 FROM feedback f WHERE f.id=sp.feedback_id);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_old_feedback_observation b JOIN feedback f ON f.id=b.feedback_id LEFT JOIN _cutover_result r ON r.observation_id=b.observation_id AND r.workspace_id=f.workspace_id AND r.developer_id=f.developer_id WHERE r.result_id IS NULL) THEN RAISE EXCEPTION 'basis cannot resolve to the same workspace/developer'; END IF;
END $$;
INSERT INTO feedback_basis(id,workspace_id,feedback_id,result_id,problem_id,developer_id,ordinal)
 SELECT gen_random_uuid(),f.workspace_id,b.feedback_id,r.result_id,r.problem_id,f.developer_id,min(b.ordinal)
 FROM _cutover_old_feedback_observation b JOIN feedback f ON f.id=b.feedback_id JOIN _cutover_result r ON r.observation_id=b.observation_id AND r.workspace_id=f.workspace_id AND r.developer_id=f.developer_id
 GROUP BY f.workspace_id,b.feedback_id,r.result_id,r.problem_id,f.developer_id;
CREATE TEMP TABLE _cutover_contributors ON COMMIT DROP AS
 SELECT sp.feedback_id,sp.review_id,sp.workspace_id,sp.developer_id,e.value AS occurrence_key,e.ordinal
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id
 CROSS JOIN LATERAL jsonb_array_elements_text(pg_temp.cutover_array(d.package_content->'summaryContributors')) WITH ORDINALITY e(value,ordinal)
 UNION ALL SELECT sp.feedback_id,sp.review_id,sp.workspace_id,sp.developer_id,e.value,n.ordinal
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id
 CROSS JOIN LATERAL jsonb_array_elements(pg_temp.cutover_array(d.package_content->'diffNotes')) WITH ORDINALITY n(value,ordinal)
 CROSS JOIN LATERAL jsonb_array_elements_text(pg_temp.cutover_array(n.value->'contributors')) e(value);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_contributors c WHERE (SELECT count(*) FROM _cutover_old_observation o JOIN _cutover_result r ON r.observation_id=o.id WHERE(o.occurrence_key=c.occurrence_key OR o.id::text=c.occurrence_key) AND o.agent_job_id=c.review_id AND r.workspace_id=c.workspace_id AND r.developer_id=c.developer_id)<>1) THEN RAISE EXCEPTION 'sealed contributor cannot resolve exactly'; END IF;
END $$;
INSERT INTO feedback_basis(id,workspace_id,feedback_id,result_id,problem_id,developer_id,ordinal)
 SELECT gen_random_uuid(),c.workspace_id,c.feedback_id,r.result_id,r.problem_id,c.developer_id,min(c.ordinal)::integer
 FROM _cutover_contributors c JOIN _cutover_old_observation o ON(o.occurrence_key=c.occurrence_key OR o.id::text=c.occurrence_key) AND o.agent_job_id=c.review_id
 JOIN _cutover_result r ON r.observation_id=o.id AND r.workspace_id=c.workspace_id AND r.developer_id=c.developer_id
 WHERE NOT EXISTS(SELECT 1 FROM feedback_basis b WHERE b.feedback_id=c.feedback_id AND b.result_id=r.result_id AND b.problem_id IS NOT DISTINCT FROM r.problem_id)
 GROUP BY c.workspace_id,c.feedback_id,r.result_id,r.problem_id,c.developer_id;



CREATE TEMP TABLE _cutover_completion_parent ON COMMIT DROP AS
 SELECT c.job_id,gen_random_uuid() AS feedback_id,c.workspace_id,r.developer_id,c.review,c.accepted_at,c.review_digest
 FROM _cutover_old_public_review_completion c JOIN _cutover_review r ON r.job_id=c.job_id AND r.workspace_id=c.workspace_id
 WHERE c.review IS NOT NULL AND c.review<>'null'::jsonb
 AND NOT EXISTS(SELECT 1 FROM _cutover_send_parent sp WHERE sp.review_id=r.review_id)
 AND NOT EXISTS(SELECT 1 FROM _cutover_old_feedback f WHERE f.agent_job_id=c.job_id AND f.channel='IN_CONTEXT' AND f.position IN(0,5000));
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_completion_parent WHERE developer_id IS NULL) THEN RAISE EXCEPTION 'accepted composition has no exact developer'; END IF;
END $$;
INSERT INTO feedback(id,workspace_id,review_id,item_id,developer_id,destination,state,stop_reason,body,checks,created_at)
 SELECT c.feedback_id,c.workspace_id,c.job_id,r.item_id,c.developer_id,'ON_WORK','WITHHELD',CASE WHEN r.stop_reason='CONTRACT_CHANGED' THEN 'REVIEW_CANCELLED' ELSE 'APPROVAL_NO_LONGER_ELIGIBLE' END,c.review->'summary'->>'body',
 jsonb_build_object('MIGRATION',jsonb_build_object('acceptedReviewDigest',c.review_digest,'writeVisibility','UNKNOWN')),c.accepted_at
 FROM _cutover_completion_parent c JOIN review r ON r.id=c.job_id;
CREATE TEMP TABLE _cutover_completion_basis ON COMMIT DROP AS
 SELECT c.feedback_id,c.job_id,c.workspace_id,c.developer_id,x.value AS old_key
 FROM _cutover_completion_parent c CROSS JOIN LATERAL jsonb_array_elements_text(pg_temp.cutover_array(c.review->'summary'->'basedOn')) x
 UNION ALL SELECT c.feedback_id,c.job_id,c.workspace_id,c.developer_id,x.value
 FROM _cutover_completion_parent c CROSS JOIN LATERAL jsonb_array_elements(pg_temp.cutover_array(c.review->'inline')||pg_temp.cutover_array(c.review->'withheld')) note
 CROSS JOIN LATERAL jsonb_array_elements_text(pg_temp.cutover_array(note->'basedOn')) x;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_completion_basis c WHERE (SELECT count(*) FROM _cutover_old_observation o JOIN _cutover_result r ON r.observation_id=o.id AND r.workspace_id=c.workspace_id AND r.developer_id=c.developer_id WHERE o.agent_job_id=c.job_id AND(o.occurrence_key=c.old_key OR o.id::text=c.old_key))<>1) THEN RAISE EXCEPTION 'accepted contributor has no exact result'; END IF;
END $$;
INSERT INTO feedback_basis(id,workspace_id,feedback_id,result_id,problem_id,developer_id,ordinal)
 SELECT gen_random_uuid(),c.workspace_id,c.feedback_id,r.result_id,r.problem_id,c.developer_id,0
 FROM _cutover_completion_basis c JOIN _cutover_old_observation o ON o.agent_job_id=c.job_id AND(o.occurrence_key=c.old_key OR o.id::text=c.old_key)
 JOIN _cutover_result r ON r.observation_id=o.id AND r.workspace_id=c.workspace_id AND r.developer_id=c.developer_id
 GROUP BY c.workspace_id,c.feedback_id,r.result_id,r.problem_id,c.developer_id;

CREATE TEMP TABLE _cutover_copy_candidate(
 candidate_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,old_copy_id uuid,feedback_id uuid NOT NULL,source varchar(16) NOT NULL,source_order bigint NOT NULL,
 kind varchar(16) NOT NULL,body text,path text,start_line integer,end_line integer,side varchar(3),write_key text,write_marker text,state varchar(16) NOT NULL,
 write_started_at timestamptz,external_ref text,external_url text,chat_message_id uuid,created_at timestamptz NOT NULL,posted_at timestamptz,stop_reason varchar(48),last_error varchar(512)) ON COMMIT DROP;
INSERT INTO _cutover_copy_candidate(old_copy_id,feedback_id,source,source_order,kind,body,path,start_line,end_line,side,state,external_ref,external_url,chat_message_id,created_at,posted_at)
 SELECT p.id,p.feedback_id,'PLACEMENT',row_number() OVER(PARTITION BY p.feedback_id ORDER BY p.created_at,p.id::text),
 CASE p.placement_type WHEN 'SUMMARY' THEN 'SUMMARY' WHEN 'INLINE' THEN 'LINE_NOTE' WHEN 'LOCATION_COMMENT' THEN 'FILE_NOTE' WHEN 'CONVERSATION_TURN' THEN 'CHAT_TURN' END,
 CASE WHEN p.placement_type='CONVERSATION_TURN' THEN
 (SELECT CASE WHEN count(*)=1 THEN min(part->'data'->>'text') END
  FROM chat_message cm CROSS JOIN LATERAL jsonb_array_elements(cm.parts) WITH ORDINALITY x(part,n)
  WHERE cm.id=p.chat_message_id AND cm.workspace_id=f.workspace_id AND part->>'type'='data-observation'
   AND nullif(btrim(part->'data'->>'text'),'') IS NOT NULL
   AND EXISTS(SELECT 1 FROM _cutover_old_feedback_observation b
     WHERE b.feedback_id=f.id AND b.observation_id::text=part->'data'->>'observationId')) END,
 p.anchor_path,p.anchor_start_line,coalesce(p.anchor_end_line,p.anchor_start_line),p.anchor_side,
 CASE WHEN f.delivery_state='UNCONFIRMED' THEN 'WITHHELD' ELSE 'POSTED' END,p.posted_comment_ref,p.posted_comment_url,p.chat_message_id,p.created_at,
 CASE WHEN f.delivery_state<>'UNCONFIRMED' THEN p.created_at END
 FROM _cutover_old_feedback_placement p JOIN _cutover_old_feedback f ON f.id=p.feedback_id;
INSERT INTO _cutover_copy_candidate(feedback_id,source,source_order,kind,body,path,start_line,end_line,write_key,state,created_at)
 SELECT f.id,'PROPOSED',n,CASE p->>'type' WHEN 'SUMMARY' THEN 'SUMMARY' WHEN 'INLINE' THEN 'LINE_NOTE' WHEN 'LOCATION_COMMENT' THEN 'FILE_NOTE' WHEN 'CONVERSATION_TURN' THEN 'CHAT_TURN' END,
 CASE WHEN p->>'type'<>'SUMMARY' THEN p->>'body' END,p->>'path',(p->>'startLine')::integer,coalesce((p->>'endLine')::integer,(p->>'startLine')::integer),coalesce(p->>'deliveryKey',p->>'recurrenceKey'),'PLANNED',f.created_at
 FROM _cutover_old_feedback f CROSS JOIN LATERAL jsonb_array_elements(pg_temp.cutover_array(f.proposed_placements)) WITH ORDINALITY x(p,n);
INSERT INTO _cutover_copy_candidate(feedback_id,source,source_order,kind,body,path,start_line,end_line,write_key,write_marker,state,created_at)
 SELECT sp.feedback_id,'PACKAGE',n,'LINE_NOTE',note->>'body',note->>'filePath',(note->>'startLine')::integer,coalesce((note->>'endLine')::integer,(note->>'startLine')::integer),
 CASE WHEN d.feedback_id IS NOT NULL THEN 'approved:'||d.feedback_id||':'||(n-1)::text ELSE note->>'deliveryKey' END,
 COALESCE(d.package_content->>'inlineMarker',CASE WHEN d.feedback_id IS NOT NULL THEN '<!-- hephaestus-approved-package:'||d.feedback_id||' -->' ELSE '<!-- hephaestus-diff-note -->' END),'PLANNED',d.created_at
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id
 CROSS JOIN LATERAL jsonb_array_elements(pg_temp.cutover_array(d.package_content->'diffNotes')) WITH ORDINALITY x(note,n);
INSERT INTO _cutover_copy_candidate(feedback_id,source,source_order,kind,write_key,write_marker,state,write_started_at,external_ref,external_url,created_at,posted_at)
 SELECT sp.feedback_id,'SUMMARY',0,'SUMMARY',CASE WHEN d.feedback_id IS NOT NULL THEN d.feedback_id::text ELSE d.agent_job_id::text END,
 CASE WHEN d.feedback_id IS NOT NULL THEN '<!-- hephaestus:approved-feedback:'||d.feedback_id||' -->' ELSE '<!-- hephaestus:practice-review:'||d.agent_job_id||' -->' END,
 CASE WHEN d.delivered_external_ref IS NOT NULL THEN 'POSTED' WHEN d.write_started THEN 'WRITE_STARTED' ELSE 'PLANNED' END,
 CASE WHEN d.write_started THEN coalesce(d.write_started_at,d.created_at) END,d.delivered_external_ref,d.delivered_external_url,d.created_at,CASE WHEN d.delivered_external_ref IS NOT NULL THEN d.updated_at END
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id
 WHERE nullif(btrim(d.package_content->>'mrNote'),'') IS NOT NULL OR d.delivered_external_ref IS NOT NULL OR d.write_started;
CREATE TEMP TABLE _cutover_copy_receipt ON COMMIT DROP AS
 SELECT sp.feedback_id,d.id AS dispatch_id,n AS receipt_order,coalesce(receipt->>'deliveryKey',receipt->>'recurrenceKey') AS write_key,
 receipt->>'path' AS path,(receipt->>'startLine')::integer AS start_line,coalesce((receipt->>'endLine')::integer,(receipt->>'startLine')::integer) AS end_line,
 receipt->>'disposition' AS disposition,nullif(receipt->>'externalRef','') AS external_ref,receipt->>'externalUrl' AS external_url,
 receipt->'writeMayHaveStarted' AS write_may_have_started,receipt->>'placement' AS actual_placement,d.write_started_at,d.created_at,d.updated_at
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id
 CROSS JOIN LATERAL jsonb_array_elements(pg_temp.cutover_array(d.delivered_placements)) WITH ORDINALITY x(receipt,n);
INSERT INTO _cutover_copy_candidate(feedback_id,source,source_order,kind,path,start_line,end_line,write_key,state,write_started_at,external_ref,external_url,created_at,posted_at)
 SELECT feedback_id,'RECEIPT',receipt_order,CASE actual_placement WHEN 'LOCATION_COMMENT' THEN 'FILE_NOTE' ELSE 'LINE_NOTE' END,path,start_line,end_line,write_key,
 CASE WHEN external_ref IS NOT NULL AND disposition IN('POSTED','FELL_BACK','PRESERVED_EXISTING') THEN 'POSTED' WHEN write_may_have_started IS DISTINCT FROM 'false'::jsonb THEN 'WRITE_STARTED' ELSE 'FAILED' END,
 CASE WHEN write_may_have_started IS DISTINCT FROM 'false'::jsonb THEN coalesce(write_started_at,created_at) END,external_ref,external_url,created_at,
 CASE WHEN external_ref IS NOT NULL AND disposition IN('POSTED','FELL_BACK','PRESERVED_EXISTING') THEN updated_at END FROM _cutover_copy_receipt;

INSERT INTO _cutover_copy_candidate(feedback_id,source,source_order,kind,state,created_at,stop_reason)
 SELECT feedback_id,'COMPLETION',0,'SUMMARY','WITHHELD',accepted_at,'APPROVAL_NO_LONGER_ELIGIBLE' FROM _cutover_completion_parent WHERE nullif(btrim(review->'summary'->>'body'),'') IS NOT NULL;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_completion_parent c CROSS JOIN LATERAL jsonb_array_elements(pg_temp.cutover_array(c.review->'inline')) note
 LEFT JOIN _cutover_old_observation o ON o.agent_job_id=c.job_id AND(o.occurrence_key=note->'anchor'->>'observationId' OR o.id::text=note->'anchor'->>'observationId')
 WHERE o.id IS NULL OR o.workspace_id<>c.workspace_id OR (note->'anchor'->>'citationIndex')::integer<0 OR (note->'anchor'->>'citationIndex')::integer>=jsonb_array_length(o.evidence->'citations')) THEN RAISE EXCEPTION 'accepted inline anchor cannot resolve exactly'; END IF;
END $$;
INSERT INTO _cutover_copy_candidate(feedback_id,source,source_order,kind,body,path,start_line,end_line,side,state,created_at,stop_reason)
 SELECT c.feedback_id,'COMPLETION',n,'LINE_NOTE',note->>'body',citation->>'path',(citation->>'startLine')::integer,COALESCE((citation->>'endLine')::integer,(citation->>'startLine')::integer),citation->>'side','WITHHELD',c.accepted_at,'APPROVAL_NO_LONGER_ELIGIBLE'
 FROM _cutover_completion_parent c CROSS JOIN LATERAL jsonb_array_elements(pg_temp.cutover_array(c.review->'inline')) WITH ORDINALITY x(note,n)
 JOIN _cutover_old_observation o ON o.agent_job_id=c.job_id AND(o.occurrence_key=note->'anchor'->>'observationId' OR o.id::text=note->'anchor'->>'observationId')
 CROSS JOIN LATERAL(SELECT o.evidence->'citations'->((note->'anchor'->>'citationIndex')::integer) AS citation) a;

CREATE TEMP TABLE _cutover_physical_copy(LIKE feedback_copy INCLUDING DEFAULTS) ON COMMIT DROP;
ALTER TABLE _cutover_physical_copy ADD COLUMN plan_order bigint;
DO $$ DECLARE r record; existing _cutover_physical_copy%ROWTYPE; n bigint; chosen uuid; BEGIN
 FOR r IN SELECT * FROM _cutover_copy_candidate ORDER BY CASE source WHEN 'PLACEMENT' THEN 0 WHEN 'SUMMARY' THEN 1 WHEN 'PACKAGE' THEN 2 WHEN 'PROPOSED' THEN 3 ELSE 4 END,source_order,candidate_id LOOP
  SELECT count(*),(array_agg(c.id ORDER BY c.id::text))[1] INTO n,chosen FROM _cutover_physical_copy c WHERE c.feedback_id=r.feedback_id AND
   ((r.external_ref IS NOT NULL AND c.external_ref=r.external_ref) OR (r.write_key IS NOT NULL AND c.write_key=r.write_key) OR
    (r.kind='SUMMARY' AND c.kind='SUMMARY') OR (r.kind='CHAT_TURN' AND c.kind='CHAT_TURN' AND c.chat_message_id=r.chat_message_id) OR
    (r.kind IN('LINE_NOTE','FILE_NOTE') AND c.kind IN('LINE_NOTE','FILE_NOTE') AND c.path=r.path AND c.start_line IS NOT DISTINCT FROM r.start_line AND c.end_line IS NOT DISTINCT FROM r.end_line));
  IF n>1 THEN RAISE EXCEPTION 'ambiguous physical copy reconciliation for %',r.feedback_id; END IF;
  IF n=0 THEN
   INSERT INTO _cutover_physical_copy(id,workspace_id,feedback_id,kind,position,body,path,start_line,end_line,side,state,write_started_at,write_key,write_marker,external_ref,external_url,chat_message_id,created_at,posted_at,plan_order,stop_reason,last_error)
    SELECT coalesce(r.old_copy_id,gen_random_uuid()),f.workspace_id,r.feedback_id,r.kind,0,r.body,r.path,r.start_line,r.end_line,r.side,r.state,r.write_started_at,r.write_key,r.write_marker,r.external_ref,r.external_url,r.chat_message_id,r.created_at,r.posted_at,r.source_order,r.stop_reason,r.last_error FROM feedback f WHERE f.id=r.feedback_id;
  ELSE
   SELECT * INTO existing FROM _cutover_physical_copy WHERE id=chosen;
   IF r.old_copy_id IS NOT NULL AND r.old_copy_id<>chosen THEN RAISE EXCEPTION 'two released copy ids describe one physical copy'; END IF;
   IF r.external_ref IS NOT NULL AND existing.external_ref IS NOT NULL AND r.external_ref<>existing.external_ref THEN RAISE EXCEPTION 'conflicting provider receipt'; END IF;
   IF r.body IS NOT NULL AND existing.body IS NOT NULL AND r.body<>existing.body THEN RAISE EXCEPTION 'approved/sealed copy text mismatch'; END IF;
   IF r.write_key IS NOT NULL AND existing.write_key IS NOT NULL AND r.write_key<>existing.write_key THEN RAISE EXCEPTION 'copy write identity mismatch'; END IF;
   UPDATE _cutover_physical_copy SET body=coalesce(existing.body,r.body),side=coalesce(existing.side,r.side),write_key=coalesce(existing.write_key,r.write_key),write_marker=coalesce(existing.write_marker,r.write_marker),
    state=CASE WHEN existing.state='POSTED' OR r.state='POSTED' THEN 'POSTED' WHEN existing.state='WRITE_STARTED' OR r.state='WRITE_STARTED' THEN 'WRITE_STARTED' WHEN existing.state='WITHHELD' THEN 'WITHHELD' WHEN r.state='FAILED' THEN 'FAILED' ELSE existing.state END,
    kind=CASE WHEN existing.kind='FILE_NOTE' OR r.kind='FILE_NOTE' THEN 'FILE_NOTE' ELSE existing.kind END,
    write_started_at=coalesce(existing.write_started_at,r.write_started_at),external_ref=coalesce(existing.external_ref,r.external_ref),external_url=coalesce(existing.external_url,r.external_url),posted_at=coalesce(existing.posted_at,r.posted_at),
    plan_order=CASE WHEN r.source IN('PACKAGE','PROPOSED') THEN r.source_order ELSE existing.plan_order END,stop_reason=coalesce(existing.stop_reason,r.stop_reason),last_error=coalesce(existing.last_error,r.last_error) WHERE id=chosen;
  END IF;
 END LOOP;
END $$;
-- A missing old inline flag retains a possible-write fence, even if a later policy withheld its parent.
UPDATE _cutover_physical_copy c SET state='WRITE_STARTED',write_started_at=coalesce(c.write_started_at,d.write_started_at,d.created_at)
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id WHERE c.feedback_id=sp.feedback_id AND c.kind IN('LINE_NOTE','FILE_NOTE') AND c.state NOT IN('POSTED','WRITE_STARTED') AND d.inline_write_started IS DISTINCT FROM false;
UPDATE _cutover_physical_copy c SET state='WITHHELD',stop_reason=f.stop_reason FROM feedback f WHERE f.id=c.feedback_id AND c.state='PLANNED' AND f.state IN('WITHHELD','REJECTED','REPLACED','UNCONFIRMED');
UPDATE _cutover_physical_copy c SET state='FAILED',last_error=d.last_error FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id WHERE c.feedback_id=sp.feedback_id AND c.state='PLANNED' AND d.state='FAILED';
WITH ranked AS(SELECT id,row_number() OVER(PARTITION BY feedback_id ORDER BY (kind='SUMMARY') DESC,plan_order,created_at,id::text)-1 AS n FROM _cutover_physical_copy)
UPDATE _cutover_physical_copy c SET position=r.n::integer FROM ranked r WHERE r.id=c.id;
INSERT INTO feedback_copy(id,workspace_id,feedback_id,kind,position,body,path,start_line,end_line,side,stop_reason,last_error,state,write_started_at,write_key,write_marker,external_ref,external_url,chat_message_id,created_at,posted_at)
 SELECT id,workspace_id,feedback_id,kind,position,body,path,start_line,end_line,side,stop_reason,last_error,state,write_started_at,write_key,write_marker,external_ref,external_url,chat_message_id,created_at,posted_at FROM _cutover_physical_copy;
UPDATE feedback f SET state='UNCONFIRMED',stop_reason='DELIVERY_UNCONFIRMED' WHERE EXISTS(SELECT 1 FROM feedback_copy c WHERE c.feedback_id=f.id AND c.state='WRITE_STARTED');
INSERT INTO feedback_send(feedback_id,workspace_id,action,state,attempts,next_attempt_at,last_error,created_at,updated_at)
 SELECT sp.feedback_id,d.workspace_id,'POST',CASE WHEN f.state='UNCONFIRMED' THEN CASE WHEN f.destination='ON_WORK' AND EXISTS(SELECT 1 FROM feedback_copy c WHERE c.feedback_id=f.id AND c.state='WRITE_STARTED') THEN 'UNCERTAIN' ELSE 'DONE' END
 WHEN d.state IN('SENT','SUPPRESSED','FAILED') OR f.state IN('DELIVERED','WITHHELD','REJECTED','REPLACED','FAILED') THEN 'DONE'
 WHEN d.state IN('CLAIMED','UNCERTAIN') THEN 'UNCERTAIN' ELSE 'PENDING' END,d.attempt_count,d.next_attempt_at,d.last_error,d.created_at,d.updated_at
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id JOIN feedback f ON f.id=sp.feedback_id;
UPDATE feedback f SET state='WITHHELD',stop_reason='APPROVAL_NO_LONGER_ELIGIBLE'
 WHERE f.state IN('READY','AWAITING_APPROVAL') AND NOT EXISTS(SELECT 1 FROM feedback_basis b WHERE b.feedback_id=f.id) AND NOT EXISTS(SELECT 1 FROM feedback_copy c WHERE c.feedback_id=f.id AND c.state IN('WRITE_STARTED','POSTED'));
UPDATE feedback_send s SET state='DONE' FROM feedback f WHERE f.id=s.feedback_id AND f.state='WITHHELD';



-- Correction custody moves with the existing copy. RETRACT never creates a provider comment.
UPDATE feedback_copy c SET state='RETRACTED',stop_reason='RESULT_MARKED_INCORRECT'
 FROM feedback_basis b JOIN _cutover_old_observation_invalidation m ON m.observation_id=b.result_id
 WHERE c.feedback_id=b.feedback_id AND c.kind='SUMMARY' AND c.state='POSTED' AND m.restored_at IS NULL AND m.provider_copy IN('UPDATED','INLINE_REMAINS');
CREATE TEMP TABLE _cutover_correction ON COMMIT DROP AS
 SELECT f.id AS feedback_id,f.workspace_id,min(m.provider_copy_retry_at) AS retry_at,bool_or(m.provider_copy='UNRESOLVED') AS uncertain
 FROM feedback f JOIN feedback_basis b ON b.feedback_id=f.id JOIN _cutover_old_observation_invalidation m ON m.observation_id=b.result_id
 WHERE f.destination='ON_WORK' AND(m.provider_copy IN('PENDING','UNRESOLVED') OR(m.restored_at IS NULL AND m.provider_copy='INLINE_REMAINS' AND EXISTS(SELECT 1 FROM feedback_copy c WHERE c.feedback_id=f.id AND c.kind IN('LINE_NOTE','FILE_NOTE') AND c.state='POSTED')))
 AND EXISTS(SELECT 1 FROM feedback_copy c WHERE c.feedback_id=f.id AND(c.external_ref IS NOT NULL OR c.state='WRITE_STARTED'))
 GROUP BY f.id,f.workspace_id;
INSERT INTO feedback_send(feedback_id,workspace_id,action,state,attempts,next_attempt_at)
 SELECT feedback_id,workspace_id,'RETRACT',CASE WHEN uncertain THEN 'UNCERTAIN' ELSE 'PENDING' END,0,retry_at FROM _cutover_correction
 ON CONFLICT(feedback_id) DO UPDATE SET action='RETRACT',state=EXCLUDED.state,lease_owner=NULL,lease_expires_at=NULL,next_attempt_at=EXCLUDED.next_attempt_at;
UPDATE feedback f SET state='WITHHELD',stop_reason='RESULT_MARKED_INCORRECT'
 WHERE f.state IN('READY','AWAITING_APPROVAL') AND EXISTS(SELECT 1 FROM feedback_basis b JOIN result_mark m ON m.result_id=b.result_id WHERE b.feedback_id=f.id AND m.kind='INCORRECT' AND m.removed_at IS NULL);
UPDATE feedback_send s SET state='DONE' FROM feedback f WHERE f.id=s.feedback_id AND f.state='WITHHELD' AND s.action='POST';
WITH marks AS(SELECT b.feedback_id,jsonb_agg(jsonb_build_object('markId',m.id,'providerCopy',m.provider_copy,'retryAt',m.provider_copy_retry_at) ORDER BY m.id::text) AS prior
 FROM feedback_basis b JOIN _cutover_old_observation_invalidation m ON m.observation_id=b.result_id GROUP BY b.feedback_id)
UPDATE feedback f SET checks=f.checks||jsonb_build_object('MIGRATION_CORRECTION',m.prior) FROM marks m WHERE m.feedback_id=f.id;

CREATE FUNCTION feedback_content_digest(p_id uuid) RETURNS varchar(64) LANGUAGE sql STABLE STRICT AS $$
 SELECT encode(sha256(convert_to(jsonb_build_object('workspaceId',f.workspace_id,'reviewId',f.review_id,'developerId',f.developer_id,'destination',f.destination,'itemId',f.item_id,'itemVersion',r.item_version,'body',f.body,
 'basis',COALESCE((SELECT jsonb_agg(jsonb_build_object('resultId',b.result_id,'problemId',b.problem_id) ORDER BY b.result_id::text,b.problem_id::text NULLS FIRST) FROM feedback_basis b WHERE b.feedback_id=f.id),'[]'::jsonb),
 'copies',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',v.id,'kind',CASE WHEN v.kind IN('LINE_NOTE','FILE_NOTE') THEN 'NOTE' ELSE v.kind END,'position',v.position,'body',CASE WHEN v.kind='CHAT_TURN' THEN NULL ELSE v.body END,'path',v.path,'startLine',v.start_line,'endLine',v.end_line,'side',v.side) ORDER BY v.position) FROM feedback_copy v WHERE v.feedback_id=f.id),'[]'::jsonb))::text,'UTF8')),'hex')::varchar(64)
 FROM feedback f JOIN review r ON r.id=f.review_id AND r.workspace_id=f.workspace_id WHERE f.id=p_id
$$;
CREATE FUNCTION feedback_package_digest(p_digests text[]) RETURNS varchar(64) LANGUAGE plpgsql IMMUTABLE STRICT AS $$
BEGIN
 IF array_ndims(p_digests)>1 OR EXISTS(SELECT 1 FROM unnest(p_digests) d WHERE d IS NULL OR d !~ '^[0-9a-f]{64}$') THEN
  RAISE EXCEPTION 'package pieces must be an ordered list of SHA-256 digests' USING ERRCODE='23514';
 END IF;
 RETURN encode(sha256(convert_to(to_jsonb(p_digests)::text,'UTF8')),'hex')::varchar(64);
END $$;
UPDATE feedback f SET checks=jsonb_set(f.checks,'{MIGRATION,approvalDigest}',to_jsonb(a.content_digest)) FROM _cutover_old_feedback_approval a WHERE a.feedback_id=f.id;
INSERT INTO feedback_decision(id,workspace_id,feedback_id,action,actor_account_id,reason,note,content_digest,decided_at)
 SELECT a.id,a.workspace_id,a.feedback_id,CASE a.decision WHEN 'APPROVED' THEN 'APPROVE' WHEN 'REJECTED' THEN 'REJECT' END,account.id,a.rejection_reason,a.rejection_note,feedback_content_digest(a.feedback_id),a.decided_at
 FROM _cutover_old_feedback_approval a LEFT JOIN account ON account.id=a.actor_account_id;
INSERT INTO feedback_decision(id,workspace_id,feedback_id,action,actor_account_id,note,decided_at)
 SELECT id,workspace_id,feedback_id,'WITHDRAW',withdrawn_by_account_id,reason,withdrawn_at FROM _cutover_old_feedback_withdrawal;
INSERT INTO feedback_decision(id,workspace_id,feedback_id,action,actor_account_id,note,decided_at)
 SELECT gen_random_uuid(),workspace_id,feedback_id,'RESTORE',restored_by_account_id,restoration_reason,restored_at FROM _cutover_old_feedback_withdrawal WHERE restored_at IS NOT NULL;
INSERT INTO feedback_response(id,workspace_id,feedback_id,resolution,usefulness,comment,created_at)
 SELECT r.id,f.workspace_id,r.feedback_id,CASE r.action WHEN 'DISPUTED' THEN 'DISAGREE' ELSE r.action END,r.usefulness,r.explanation,r.created_at FROM _cutover_old_reaction r JOIN feedback f ON f.id=r.feedback_id;
WITH evaluations AS(SELECT feedback_id,jsonb_agg(pg_temp.cutover_citations(to_jsonb(e)) ORDER BY e.evaluated_at,e.id::text) AS payload FROM _cutover_old_delivery_policy_evaluation e WHERE feedback_id IS NOT NULL GROUP BY feedback_id)
UPDATE feedback f SET checks=f.checks||jsonb_build_object('MIGRATION_POLICY',e.payload) FROM evaluations e WHERE e.feedback_id=f.id;
WITH evaluations AS(SELECT agent_job_id,jsonb_agg(pg_temp.cutover_citations(to_jsonb(e)) ORDER BY e.evaluated_at,e.id::text) AS payload FROM _cutover_old_delivery_policy_evaluation e WHERE feedback_id IS NULL GROUP BY agent_job_id)
UPDATE review r SET checks=r.checks||jsonb_build_object('MIGRATION_POLICY',e.payload) FROM evaluations e WHERE e.agent_job_id=r.id;
-- Released data-observation links named verdicts; their UUID remains the Result UUID.
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM chat_message cm CROSS JOIN LATERAL jsonb_array_elements(cm.parts) p
  WHERE p->>'type'='data-observation' AND (
   jsonb_typeof(p->'data') IS DISTINCT FROM 'object'
   OR NOT coalesce(p->'data'->>'observationId' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$',false)
   OR (p->'data' ? 'text' AND jsonb_typeof(p->'data'->'text') NOT IN ('string','null'))
   OR (p->'data' ? 'resultId' AND p->'data'->>'resultId' IS DISTINCT FROM p->'data'->>'observationId'))) THEN
  RAISE EXCEPTION 'stored conversation verdict link is unrepresentable'; END IF;
 IF EXISTS(SELECT 1 FROM chat_message cm CROSS JOIN LATERAL jsonb_array_elements(cm.parts) p
  JOIN _cutover_result r ON r.observation_id::text=p->'data'->>'observationId'
  WHERE p->>'type'='data-observation' AND r.workspace_id<>cm.workspace_id) THEN
  RAISE EXCEPTION 'stored conversation verdict link crosses workspace'; END IF;
END $$;
WITH messages AS(SELECT cm.id,cm.workspace_id,jsonb_agg(
 CASE WHEN p->>'type'='data-observation' THEN jsonb_set(jsonb_set(p,'{type}','"data-result"'::jsonb),'{data}',
  ((p->'data')-'observationId')||jsonb_build_object('resultId',p->'data'->'observationId',
   'text',CASE WHEN jsonb_typeof(p->'data'->'text')='string' THEN p->'data'->'text' ELSE '""'::jsonb END))
 ELSE p END ORDER BY n) AS parts
 FROM chat_message cm CROSS JOIN LATERAL jsonb_array_elements(cm.parts) WITH ORDINALITY x(p,n)
 WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(cm.parts) q WHERE q->>'type'='data-observation')
 GROUP BY cm.id,cm.workspace_id)
UPDATE chat_message cm SET parts=m.parts FROM messages m WHERE cm.id=m.id AND cm.workspace_id=m.workspace_id;

-- Historical audit is inert Review data. Feedback checks contain only final typed stages.
WITH audits AS(SELECT review_id,jsonb_object_agg(id::text,checks ORDER BY id::text) AS payload
 FROM feedback WHERE checks<>'{}'::jsonb GROUP BY review_id)
UPDATE review r SET checks=jsonb_set(r.checks,'{MIGRATION}',coalesce(r.checks->'MIGRATION','{}'::jsonb)||jsonb_build_object('feedback',a.payload))
 FROM audits a WHERE a.review_id=r.id;
UPDATE feedback SET checks='{}'::jsonb WHERE checks<>'{}'::jsonb;
UPDATE review r SET checks=jsonb_set(r.checks-'MIGRATION_POLICY','{MIGRATION}',
 coalesce(r.checks->'MIGRATION','{}'::jsonb)||jsonb_build_object('policy',r.checks->'MIGRATION_POLICY'))
 WHERE jsonb_exists(r.checks, 'MIGRATION_POLICY');
UPDATE review_composition_basis SET payload=pg_temp.cutover_citations(payload);
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT conname FROM pg_constraint WHERE conrelid='workspace'::regclass AND contype='c'
  AND pg_get_constraintdef(oid) ~ 'practice_default_autonomy|practice_repository_coverage_mode|practice_person_coverage_mode|practice_skip_drafts'
 LOOP EXECUTE format('ALTER TABLE workspace DROP CONSTRAINT %I',r.conname); END LOOP;
END $$;
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT c.conname FROM pg_constraint c WHERE c.conrelid='chat_thread'::regclass AND c.contype='f'
  AND EXISTS(SELECT FROM pg_attribute a WHERE a.attrelid=c.conrelid AND a.attnum=ANY(c.conkey) AND a.attname IN ('user_id'))
 LOOP EXECUTE format('ALTER TABLE chat_thread DROP CONSTRAINT %I',r.conname); END LOOP;
END $$;
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT c.conname FROM pg_constraint c WHERE c.conrelid='chat_message'::regclass AND c.contype='f'
  AND EXISTS(SELECT FROM pg_attribute a WHERE a.attrelid=c.conrelid AND a.attnum=ANY(c.conkey) AND a.attname IN ('thread_id','parent_message_id'))
 LOOP EXECUTE format('ALTER TABLE chat_message DROP CONSTRAINT %I',r.conname); END LOOP;
END $$;
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT c.conname FROM pg_constraint c WHERE c.conrelid='auth_event'::regclass AND c.contype='f'
  AND EXISTS(SELECT FROM pg_attribute a WHERE a.attrelid=c.conrelid AND a.attnum=ANY(c.conkey) AND a.attname IN ('identity_link_id'))
 LOOP EXECUTE format('ALTER TABLE auth_event DROP CONSTRAINT %I',r.conname); END LOOP;
END $$;

DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT c.conname FROM pg_constraint c WHERE c.conrelid='slack_message'::regclass AND c.contype='f'
  AND EXISTS(SELECT FROM pg_attribute a WHERE a.attrelid=c.conrelid AND a.attnum=ANY(c.conkey) AND a.attname IN ('author_member_id'))
 LOOP EXECUTE format('ALTER TABLE slack_message DROP CONSTRAINT %I',r.conname); END LOOP;
END $$;
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT c.conname FROM pg_constraint c WHERE c.conrelid='slack_channel_consent_event'::regclass AND c.contype='f'
  AND EXISTS(SELECT FROM pg_attribute a WHERE a.attrelid=c.conrelid AND a.attnum=ANY(c.conkey) AND a.attname IN ('actor_user_id'))
 LOOP EXECUTE format('ALTER TABLE slack_channel_consent_event DROP CONSTRAINT %I',r.conname); END LOOP;
END $$;


