UPDATE auth_event e SET viewed_account_id=m.account_id FROM _cutover_person m WHERE m.user_id=e.viewed_actor_id;
-- The partition template carries the same person keys as future parent partitions.
DO $$ DECLARE extension_schema text; template_name text; template_oid regclass; old_fk record;
BEGIN
 SELECT n.nspname INTO extension_schema FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='pg_partman';
 EXECUTE format('SELECT template_table FROM %I.part_config WHERE parent_table=$1',extension_schema) INTO template_name USING 'public.auth_event';
 template_oid:=to_regclass(template_name);
 IF template_oid IS NULL THEN RAISE EXCEPTION 'auth_event partition template is missing'; END IF;
 FOR old_fk IN SELECT conname FROM pg_constraint WHERE conrelid=template_oid AND confrelid='_released_identity_link'::regclass LOOP
  EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I',template_oid,old_fk.conname);
 END LOOP;
 IF EXISTS(SELECT FROM pg_attribute WHERE attrelid=template_oid AND attname='identity_link_id' AND NOT attisdropped) THEN
  EXECUTE format('ALTER TABLE %s RENAME COLUMN identity_link_id TO identity_id',template_oid);
 END IF;
 IF EXISTS(SELECT FROM pg_attribute WHERE attrelid=template_oid AND attname='viewed_user_id' AND NOT attisdropped) THEN
  EXECUTE format('ALTER TABLE %s RENAME COLUMN viewed_user_id TO viewed_actor_id',template_oid);
 ELSE
  EXECUTE format('ALTER TABLE %s ADD COLUMN viewed_actor_id bigint',template_oid);
 END IF;
 EXECUTE format('ALTER TABLE %s ADD COLUMN viewed_account_id bigint',template_oid);
END $$;





