DO $auth_function$ BEGIN
 IF to_regprocedure('auth_event_block_mutation()') IS NOT NULL THEN
  EXECUTE $auth_definition$CREATE OR REPLACE FUNCTION auth_event_block_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'auth_event is append-only'; END IF;
 IF (NEW.account_id IS NULL OR NEW.account_id IS NOT DISTINCT FROM OLD.account_id)
 AND (NEW.acting_account_id IS NULL OR NEW.acting_account_id IS NOT DISTINCT FROM OLD.acting_account_id)
 AND (NEW.viewed_account_id IS NULL OR NEW.viewed_account_id IS NOT DISTINCT FROM OLD.viewed_account_id)
 AND (NEW.viewed_actor_id IS NULL OR NEW.viewed_actor_id IS NOT DISTINCT FROM OLD.viewed_actor_id)
 AND (NEW.identity_id IS NULL OR NEW.identity_id IS NOT DISTINCT FROM OLD.identity_id)
 AND (NEW.provider_id IS NULL OR NEW.provider_id IS NOT DISTINCT FROM OLD.provider_id)
 AND (NEW.workspace_id IS NULL OR NEW.workspace_id IS NOT DISTINCT FROM OLD.workspace_id)
 AND (NEW.ip_inet IS NULL OR NEW.ip_inet IS NOT DISTINCT FROM OLD.ip_inet)
 AND (NEW.user_agent IS NULL OR NEW.user_agent IS NOT DISTINCT FROM OLD.user_agent)
 AND (NEW.details IS NULL OR NEW.details IS NOT DISTINCT FROM OLD.details)
 AND (to_jsonb(NEW)-'account_id'-'acting_account_id'-'viewed_account_id'-'viewed_actor_id'-'identity_id'-'provider_id'-'workspace_id'-'ip_inet'-'user_agent'-'details')
 IS NOT DISTINCT FROM (to_jsonb(OLD)-'account_id'-'acting_account_id'-'viewed_account_id'-'viewed_actor_id'-'identity_id'-'provider_id'-'workspace_id'-'ip_inet'-'user_agent'-'details') THEN
  RETURN NEW; END IF;
 RAISE EXCEPTION 'auth_event permits only nulling private attribution and content';
END $$;$auth_definition$;
 END IF;
END $auth_function$;
DO $$ DECLARE guard record; action text; BEGIN
 FOR guard IN SELECT * FROM _cutover_auth_guard_state LOOP
  action:=CASE guard.mode WHEN 'O' THEN 'ENABLE' WHEN 'R' THEN 'ENABLE REPLICA'
    WHEN 'A' THEN 'ENABLE ALWAYS' ELSE 'DISABLE' END;
  EXECUTE format('ALTER TABLE ONLY %s %s TRIGGER trg_auth_event_block_mutation',guard.relation_id::regclass,action);
 END LOOP;
END $$;

DROP TRIGGER IF EXISTS trg_consent_decision_append_only ON consent_decision;
ALTER TABLE consent_decision DROP COLUMN notice_sha256;
CREATE OR REPLACE FUNCTION enforce_consent_decision_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='DELETE' OR (to_jsonb(NEW)-'account_id') IS DISTINCT FROM (to_jsonb(OLD)-'account_id') OR (NEW.account_id IS NOT NULL AND NEW.account_id IS DISTINCT FROM OLD.account_id) THEN RAISE EXCEPTION 'consent history is append-only' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER trg_consent_decision_append_only BEFORE UPDATE OR DELETE ON consent_decision FOR EACH ROW EXECUTE FUNCTION enforce_consent_decision_append_only();

CREATE FUNCTION practice_definition_complete(d jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT AS $$
DECLARE
  e jsonb;
  k text;
  seen text[];
  clause_count integer;
  policy text;
BEGIN
  IF jsonb_typeof(d)<>'object' OR NOT d ?& ARRAY[
    'name','reviewOn','appliesWhen','about','reads','reviewedBy','criteria',
    'script','scan','lineNotes','guidance'] THEN RETURN false; END IF;
  IF d - ARRAY['name','reviewOn','appliesWhen','about','reads','reviewedBy','criteria',
    'script','scan','lineNotes','guidance'] <> '{}'::jsonb THEN RETURN false; END IF;
  IF jsonb_typeof(d->'name')<>'string' OR nullif(btrim(d->>'name'),'') IS NULL
    OR length(d->>'name')>128 OR jsonb_typeof(d->'criteria')<>'string'
    OR nullif(btrim(d->>'criteria'),'') IS NULL THEN RETURN false; END IF;
  IF d->'about'<>'null'::jsonb AND
    (jsonb_typeof(d->'about')<>'string' OR d->>'about' NOT IN ('AUTHOR','REVIEWER','ASSIGNEE','MERGER'))
    THEN RETURN false; END IF;
  IF jsonb_typeof(d->'reviewOn')<>'object'
    OR NOT (d->'reviewOn') ?& ARRAY['events','state']
    OR (d->'reviewOn')-ARRAY['events','state']<>'{}'::jsonb
    OR jsonb_typeof(d->'reviewOn'->'events')<>'array'
    OR jsonb_typeof(d->'reviewOn'->'state')<>'object' THEN RETURN false; END IF;
  FOR e IN SELECT value FROM jsonb_array_elements(d->'reviewOn'->'events') LOOP
    IF jsonb_typeof(e)<>'string' OR nullif(btrim(e#>>'{}'),'') IS NULL THEN RETURN false; END IF;
  END LOOP;
  FOR k,e IN SELECT key,value FROM jsonb_each(d->'reviewOn'->'state') LOOP
    IF nullif(btrim(k),'') IS NULL OR jsonb_typeof(e)<>'array' THEN RETURN false; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(e) x WHERE jsonb_typeof(x.value)<>'string')
      THEN RETURN false; END IF;
  END LOOP;
  IF d->'appliesWhen'<>'null'::jsonb THEN
    IF jsonb_typeof(d->'appliesWhen')<>'object'
      OR NOT (d->'appliesWhen') ?& ARRAY['anyOf','otherwise']
      OR (d->'appliesWhen')-ARRAY['anyOf','otherwise']<>'{}'::jsonb
      OR jsonb_typeof(d->'appliesWhen'->'anyOf')<>'array'
      OR jsonb_array_length(d->'appliesWhen'->'anyOf')=0
      OR jsonb_typeof(d->'appliesWhen'->'otherwise')<>'string' THEN RETURN false; END IF;
    FOR e IN SELECT value FROM jsonb_array_elements(d->'appliesWhen'->'anyOf') LOOP
      IF jsonb_typeof(e)<>'object' OR e-ARRAY['changedPath','diffContains','hasItems']<>'{}'::jsonb
        THEN RETURN false; END IF;
      SELECT count(*) INTO clause_count FROM jsonb_object_keys(e);
      IF clause_count<>1 THEN RETURN false; END IF;
      IF e ? 'hasItems' THEN
        IF jsonb_typeof(e->'hasItems')<>'string' THEN RETURN false; END IF;
      ELSE
        FOR k IN SELECT jsonb_object_keys(e) LOOP
          IF jsonb_typeof(e->k)<>'array' OR jsonb_array_length(e->k)=0
            OR EXISTS (SELECT 1 FROM jsonb_array_elements(e->k) x
              WHERE jsonb_typeof(x.value)<>'string' OR nullif(btrim(x.value#>>'{}'),'') IS NULL)
            THEN RETURN false; END IF;
        END LOOP;
      END IF;
    END LOOP;
  END IF;
  IF jsonb_typeof(d->'reads')<>'object' OR NOT (d->'reads') ?& ARRAY['contract','sources']
    OR (d->'reads')-ARRAY['contract','sources']<>'{}'::jsonb
    OR jsonb_typeof(d->'reads'->'contract')<>'string'
    OR jsonb_typeof(d->'reads'->'sources')<>'array' THEN RETURN false; END IF;
  seen:=ARRAY[]::text[];
  FOR e IN SELECT value FROM jsonb_array_elements(d->'reads'->'sources') LOOP
    IF jsonb_typeof(e)<>'object' OR NOT e ?& ARRAY['source','need']
      OR e-ARRAY['source','need']<>'{}'::jsonb OR jsonb_typeof(e->'source')<>'string'
      OR jsonb_typeof(e->'need')<>'string' OR e->>'need' NOT IN ('REQUIRED','COMPLETE','OPTIONAL')
      OR nullif(btrim(e->>'source'),'') IS NULL OR e->>'source'=ANY(seen)
      THEN RETURN false; END IF;
    seen:=array_append(seen,e->>'source');
  END LOOP;
  IF jsonb_typeof(d->'reviewedBy')<>'object'
    OR NOT (d->'reviewedBy') ?& ARRAY['by','humanReason','limits']
    OR (d->'reviewedBy')-ARRAY['by','humanReason','limits']<>'{}'::jsonb
    OR jsonb_typeof(d->'reviewedBy'->'by')<>'string'
    OR jsonb_typeof(d->'reviewedBy'->'limits')<>'array' THEN RETURN false; END IF;
  policy:=d->'reviewedBy'->>'by';
  IF policy NOT IN ('HEPHAESTUS','PEOPLE','NOBODY') THEN RETURN false; END IF;
  IF (policy='PEOPLE') <> (d->'reviewedBy'->'humanReason'<>'null'::jsonb) THEN RETURN false; END IF;
  seen:=ARRAY[]::text[];
  FOR e IN SELECT value FROM jsonb_array_elements(d->'reviewedBy'->'limits') LOOP
    IF jsonb_typeof(e)<>'object' OR NOT e ?& ARRAY['code','description']
      OR e-ARRAY['code','description']<>'{}'::jsonb
      OR jsonb_typeof(e->'code')<>'string' OR jsonb_typeof(e->'description')<>'string'
      OR nullif(btrim(e->>'code'),'') IS NULL OR e->>'code'=ANY(seen) THEN RETURN false; END IF;
    seen:=array_append(seen,e->>'code');
  END LOOP;
  IF policy='PEOPLE' THEN
    e:=d->'reviewedBy'->'humanReason';
    IF jsonb_typeof(e)<>'object' OR NOT e ?& ARRAY['code','description']
      OR e-ARRAY['code','description']<>'{}'::jsonb
      OR jsonb_typeof(e->'code')<>'string' OR jsonb_typeof(e->'description')<>'string' THEN RETURN false; END IF;
  END IF;
  IF policy='HEPHAESTUS' AND NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(d->'reads'->'sources') x
      WHERE x.value->>'need' IN ('REQUIRED','COMPLETE')) THEN RETURN false; END IF;
  IF d->'script'<>'null'::jsonb AND (jsonb_typeof(d->'script')<>'string'
    OR length(d->>'script')>100000 OR nullif(btrim(d->>'script'),'') IS NULL) THEN RETURN false; END IF;
  IF jsonb_typeof(d->'lineNotes')<>'boolean' THEN RETURN false; END IF;
  IF d->'scan'<>'null'::jsonb THEN
    IF policy<>'HEPHAESTUS' OR jsonb_typeof(d->'scan')<>'object'
      OR NOT (d->'scan') ?& ARRAY['itemKind','include','exclude','context']
      OR (d->'scan')-ARRAY['itemKind','include','exclude','context']<>'{}'::jsonb
      OR jsonb_typeof(d->'scan'->'itemKind')<>'string' OR d->'scan'->>'itemKind' !~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' THEN RETURN false; END IF;
    FOREACH k IN ARRAY ARRAY['include','exclude','context'] LOOP
      IF jsonb_typeof(d->'scan'->k)<>'array' OR jsonb_array_length(d->'scan'->k)>64
        THEN RETURN false; END IF;
      FOR e IN SELECT value FROM jsonb_array_elements(d->'scan'->k) LOOP
        IF jsonb_typeof(e)<>'string' OR nullif(btrim(e#>>'{}'),'') IS NULL
          OR length(e#>>'{}')>4096 THEN RETURN false; END IF;
      END LOOP;
    END LOOP;
    IF jsonb_array_length(d->'scan'->'include')=0 THEN RETURN false; END IF;
  END IF;
  IF jsonb_typeof(d->'guidance')<>'object'
    OR NOT (d->'guidance') ?& ARRAY['whyItMatters','whatGoodLooksLike','goingWell','visual','guide']
    OR (d->'guidance')-ARRAY['whyItMatters','whatGoodLooksLike','goingWell','visual','guide']<>'{}'::jsonb
    THEN RETURN false; END IF;
  FOREACH k IN ARRAY ARRAY['whyItMatters','whatGoodLooksLike','goingWell'] LOOP
    IF d->'guidance'->k<>'null'::jsonb AND jsonb_typeof(d->'guidance'->k)<>'string' THEN RETURN false; END IF;
  END LOOP;
  e:=d->'guidance'->'visual';
  IF e<>'null'::jsonb AND (jsonb_typeof(e)<>'object' OR NOT e ?& ARRAY['svg','alt']
    OR e-ARRAY['svg','alt']<>'{}'::jsonb OR jsonb_typeof(e->'svg')<>'string'
    OR jsonb_typeof(e->'alt')<>'string') THEN RETURN false; END IF;
  e:=d->'guidance'->'guide';
  IF e<>'null'::jsonb THEN
    IF jsonb_typeof(e)<>'object' OR NOT e ?& ARRAY['markdown','figures']
      OR e-ARRAY['markdown','figures']<>'{}'::jsonb OR jsonb_typeof(e->'markdown')<>'string'
      OR jsonb_typeof(e->'figures')<>'object' THEN RETURN false; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_each(e->'figures') x WHERE jsonb_typeof(x.value)<>'string')
      THEN RETURN false; END IF;
  END IF;
  RETURN true;
EXCEPTION WHEN invalid_parameter_value OR invalid_text_representation OR numeric_value_out_of_range
  THEN RETURN false;
END
$$;


-- Exact released program transformations. Historical definitions retain their original bytes.
CREATE TEMP TABLE _cutover_program(
 source_sha256 varchar(64) PRIMARY KEY,source text NOT NULL,target_sha256 varchar(64) NOT NULL,target text NOT NULL,
 CHECK(source_sha256=encode(sha256(convert_to(source,'UTF8')),'hex')),
 CHECK(target_sha256=encode(sha256(convert_to(target,'UTF8')),'hex'))) ON COMMIT DROP;
INSERT INTO _cutover_program VALUES('2903beda1da3ad7cf67e338c533cbc0acad1f32c87b59d0ffa6203d8bba24cf6','import {
	branchIssueReferences,
	closingReferences,
	issueNumberReferences,
	withoutHtmlComments,
} from "../lib/references.ts";
// Precompute FACTS for states-how-to-verify-the-change: what kind of change this is, and where
// guidance-shaped text sits. The occasion gate is where a small model slips most (a diagram or a
// self-introduction judged as lacking instructions), so the facts it needs for that gate
// are stated up front. Nothing here is a verdict — the model reads the sources and judges.
import { readLinkedWorkItemCapture } from "../lib/review.ts";
import type { DiffFile, PullRequestMetadata } from "../lib/types.ts";

const IMAGE = /\.(?:png|jpe?g|gif|svg|webp|pdf)$/iu;
const DIAGRAM_PATH = /(?:^|\/)(?:diagrams?|uml|models?|architecture)\//iu;
const DIAGRAM_JSON = /\.(?:json|drawio|puml|plantuml|mmd)$/iu;
const PROSE = /\.(?:md|markdown|txt|rst|adoc)$/iu;
const PROJECT_CONFIG =
	/(?:^|\/)(?:project\.yml|project\.yaml|package\.json|Package\.swift|Package\.resolved|Podfile|Cartfile|build\.gradle(?:\.kts)?|pom\.xml|pyproject\.toml|requirements\.txt|\.gitignore|\.editorconfig|\.swiftlint\.yml|Info\.plist)$/iu;
const TEST_PATH =
	/(?:^|\/)(?:tests?|specs?|__tests__)(?:\/)|[._-](?:test|tests|spec|specs)\.[a-z]+$|Tests?\.[a-z0-9]+$|Spec\.[a-z0-9]+$/iu;
const CODE = /\.(?:swift|ts|tsx|js|jsx|py|java|kt|go|rb|cs|cpp|cc|cxx|c|m|mm|h|hpp|vue|dart|rs)$/iu;
const PREVIEW = /^\+.*(?:#Preview\b|PreviewProvider\b|\.stories\.[jt]sx?|storiesOf\()/u;
// A CommonMark heading may be indented by up to three spaces.
const TESTING_HEADING =
	/^ {0,3}#+\s*(?:testing|test(?:ing)? instructions|how to test|verification|steps to (?:test|verify|reproduce))/iu;
const PLACEHOLDER_TESTING_TEXT = /^(?:n\/?a|none|not applicable|-|—)\.?$/iu;
const SCREENSHOT = /!\[[^\]]*\]\([^)]*\)/gu;
// Xcode''s library inserts these around a control''s defaults until the author replaces them.
const PLACEHOLDER_TOKEN = /\/\*@(?:START_MENU_TOKEN|PLACEHOLDER=)/u;
// A key or secret the code reads at runtime: a secret-shaped name beside a runtime lookup.
const SECRET_NAME =
	/api[_-]?key|apikey|client[_-]?secret|\bsecrets?\b|secret[A-Z_]|access[_-]?token/iu;
const RUNTIME_LOOKUP =
	/Bundle\.main|ProcessInfo|\benvironment\[|\.plist|xcconfig|Keychain|SecItem|UserDefaults|infoDictionary|process\.env|System\.getenv|os\.environ/u;

/** The section under a testing heading, stripped of template comments; empty when it holds nothing. */
function testingSection(body: string): { heading: string; content: string } | null {
	const lines = body.split(/\r?\n/u);
	for (let index = 0; index < lines.length; index += 1) {
		const line = lines[index] ?? "";
		if (!TESTING_HEADING.test(line)) {
			continue;
		}
		const level = (/#+/u.exec(line)?.[0] ?? "#").length;
		const content: string[] = [];
		for (let next = index + 1; next < lines.length; next += 1) {
			const candidate = lines[next] ?? "";
			const nextLevel = /^ {0,3}(?<hashes>#+)\s/u.exec(candidate)?.groups?.hashes?.length;
			if (nextLevel !== undefined && nextLevel <= level) {
				break;
			}
			content.push(candidate);
		}
		const text = withoutHtmlComments(content.join("\n")).trim();
		return { heading: line.trim(), content: text };
	}
	return null;
}

/** `path:line, line` for each file with a matching added line. */
function addedLinesMatching(
	diffFiles: Map<string, DiffFile>,
	matches: (path: string, line: string) => boolean,
): string[] {
	return [...diffFiles.values()].flatMap((file) => {
		const lines = [...file.addedLines]
			.filter(([, line]) => matches(file.path, line))
			.map(([number]) => String(number));
		return lines.length === 0 ? [] : [`${file.path}:${lines.join(", ")}`];
	});
}

export default async function statesHowToVerifyTheChange(
	_repoPath: string,
	diffFiles: Map<string, DiffFile>,
	metadata: PullRequestMetadata,
	contextDir?: string,
) {
	const paths = [...diffFiles.keys()];
	// A move, a rename or a binary file changes no line; an image among them is still content.
	const unchanged = [...diffFiles.values()]
		.filter(
			(file) => file.hunks.length === 0 && file.addedLines.size + file.removedLines.size === 0,
		)
		.map((file) => file.path)
		.filter((path) => !IMAGE.test(path));
	const content = paths.filter((path) => !unchanged.includes(path));
	const kinds = {
		images: content.filter((path) => IMAGE.test(path)).length,
		diagramFiles: content.filter(
			(path) =>
				DIAGRAM_PATH.test(path) ||
				(DIAGRAM_JSON.test(path) && /diagram|aom|uml|model/iu.test(path)),
		).length,
		prose: content.filter((path) => PROSE.test(path)).length,
		projectConfig: content.filter((path) => PROJECT_CONFIG.test(path)).length,
		tests: content.filter((path) => TEST_PATH.test(path)).length,
		code: content.filter((path) => CODE.test(path) && !TEST_PATH.test(path)).length,
	};
	const addedLines = [...diffFiles.values()].reduce((sum, file) => sum + file.addedLines.size, 0);
	const removedLines = [...diffFiles.values()].reduce(
		(sum, file) => sum + file.removedLines.size,
		0,
	);
	const previews = [...diffFiles.values()].filter((file) =>
		[...file.addedLines.values()].some((line) => PREVIEW.test(`+${line}`)),
	);
	const placeholders = addedLinesMatching(diffFiles, (_path, line) => PLACEHOLDER_TOKEN.test(line));
	const secretReads = addedLinesMatching(
		diffFiles,
		(path, line) =>
			!path.endsWith(".gitignore") && SECRET_NAME.test(line) && RUNTIME_LOOKUP.test(line),
	);
	const ignoredSecrets = [...diffFiles.values()]
		.filter((file) => file.path.endsWith(".gitignore"))
		.flatMap((file) => [...file.addedLines.values()])
		.map((line) => line.trim())
		.filter((line) => SECRET_NAME.test(line) || /\.xcconfig$|\.env\b/iu.test(line));

	const body = typeof metadata.body === "string" ? metadata.body : "";
	const testing = testingSection(body);
	const screenshots = body.match(SCREENSHOT)?.length ?? 0;
	// Only the author''s own words adopt an issue: a closing keyword in their prose, the title, the
	// branch, or the provider''s closing link. A template''s example in code or a comment names nothing.
	const capture = await readLinkedWorkItemCapture(contextDir);
	const captured = capture?.items.map((item) => item.number) ?? [];
	const named = new Map<number, string[]>();
	const name = (how: string, numbers: number[]) => {
		for (const n of numbers) {
			named.set(n, [...(named.get(n) ?? []), how]);
		}
	};
	name(
		"provider closing link",
		(capture?.items ?? [])
			.filter((item) => item.how === "closesOnMerge")
			.map((item) => item.number),
	);
	name("closing keyword in the description", closingReferences(body));
	name("title", issueNumberReferences(metadata.title ?? ""));
	name("branch", branchIssueReferences(metadata.source_branch));

	const directions: string[] = [];
	if (paths.length === 0 || addedLines + removedLines === 0) {
		directions.push(
			"The pinned range changes no lines: an empty diff is one of the kinds the criteria''s Occasion section names; cite it through metadata.json changed_files or work/change/files.json.",
		);
	} else if (kinds.code === 0 && kinds.tests === 0 && kinds.projectConfig === 0) {
		directions.push(
			`No code, test or project-configuration file has line changes; the change is ${kinds.images} image(s), ${kinds.diagramFiles} diagram file(s) and ${kinds.prose} prose file(s). Read the prose hunks: if they add setup or run instructions the change is material; if they add an introduction, a glossary, user stories or a diagram''s embedding, it is one of the kinds the criteria''s Occasion section names.`,
		);
	} else {
		directions.push(
			`Files with line changes: ${kinds.code} code, ${kinds.tests} test, ${kinds.projectConfig} project-configuration, ${kinds.prose} prose, ${kinds.images} image.`,
		);
	}
	if (unchanged.length > 0) {
		directions.push(
			`${unchanged.length} file(s) change no line — moves, renames or binary files: ${unchanged.slice(0, 5).join(", ")}${unchanged.length > 5 ? ", …" : ""}.`,
		);
	}
	// A bare testing section reads as "nothing anywhere" unless the direction says what it settles.
	const elsewhere =
		" That settles nothing either way: the entry, action and expected result can be in other sections, an adopted issue, a preview, the documented setup or the author''s discussion.";
	if (testing === null) {
		directions.push(`The description has no testing heading.${elsewhere}`);
	} else if (testing.content.length === 0) {
		directions.push(
			`The description''s testing heading ("${testing.heading}") has no content beneath it once template comments are removed.${elsewhere}`,
		);
	} else if (PLACEHOLDER_TESTING_TEXT.test(testing.content)) {
		directions.push(
			`The description''s testing section ("${testing.heading}") holds only "${testing.content}".${elsewhere}`,
		);
	} else {
		directions.push(
			`The description''s testing section ("${testing.heading}") holds ${testing.content.split(/\r?\n/u).filter((line) => line.trim()).length} line(s) of author text.`,
		);
	}
	if (named.size > 0) {
		directions.push(
			`Issue(s) the author names: ${[...named].map(([n, how]) => `#${n} (${how.join(", ")})`).join("; ")}.`,
		);
	}
	const unnamed = captured.filter((n) => !named.has(n));
	if (unnamed.length > 0) {
		directions.push(
			`Captured as linked_work_items/<n>.md but not named by a closing keyword, the title, the branch or a provider closing link: ${unnamed.map((n) => `#${n}`).join(", ")}.`,
		);
	}
	const uncaptured = [...named.keys()].filter((n) => !captured.includes(n));
	if (capture !== null && uncaptured.length > 0) {
		directions.push(
			`Named by the author but not captured: ${uncaptured.map((n) => `#${n}`).join(", ")}.`,
		);
	}
	if (previews.length > 0) {
		directions.push(
			`The patch adds an authored preview or story in: ${previews.map((file) => file.path).join(", ")}.`,
		);
	}
	if (placeholders.length > 0) {
		directions.push(`Added lines keep Xcode placeholder tokens: ${placeholders.join("; ")}.`);
	}
	if (secretReads.length > 0 || ignoredSecrets.length > 0) {
		directions.push(
			`Added lines read a key or secret at runtime: ${secretReads.join("; ") || "none"}.${ignoredSecrets.length > 0 ? ` The ignore file gains: ${ignoredSecrets.join(", ")}.` : ""}`,
		);
	}
	if (screenshots > 0) {
		directions.push(
			`The description embeds ${screenshots} image(s); read their captions and the sentences around them — the image bytes are not available to you.`,
		);
	}
	return {
		hints: [],
		metrics: {
			changedFiles: paths.length,
			filesWithoutLineChanges: unchanged.length,
			addedLines,
			removedLines,
			imageFiles: kinds.images,
			diagramFiles: kinds.diagramFiles,
			proseFiles: kinds.prose,
			projectConfigFiles: kinds.projectConfig,
			testFiles: kinds.tests,
			codeFiles: kinds.code,
			previewFiles: previews.length,
			screenshotsInDescription: screenshots,
			testingSectionLines: testing
				? testing.content.split(/\r?\n/u).filter((line) => line.trim()).length
				: 0,
			linkedIssues: captured.length,
			namedIssues: named.size,
			secretReadLines: secretReads.length,
		},
		directions,
	};
}
','72b81be50149275db559ef014021553b990f1c5002b289478bc2c1c795a89115','import { scm, expectKind, requireChange, type DiffFile } from "../kits/scm/index.ts";
import {
	branchIssueReferences,
	closingReferences,
	issueNumberReferences,
	withoutHtmlComments,
} from "../kits/scm/references.ts";
import { readLinkedWorkItemCapture } from "../kits/scm/review.ts";
// Tells what kind of change this is, where text that tells how to verify it can be, and which added
// lines keep an Xcode placeholder or read a secret. The criteria''s applicability gate needs these facts
// first: a small model often judges a diagram or an introduction as a change without instructions.
import { DIRECTION_CHARS, listWithin, oneLine } from "../lib/core/bounded-text.ts";
import { definePracticeScript, type ReviewLead } from "../lib/core/practice-script.ts";

export const LABELS = {
	"xcode-placeholder": "An added line that keeps an Xcode placeholder token.",
	"runtime-secret-read": "An added line that reads a key or secret at runtime.",
	"ignored-secret":
		"A line that the change adds to an ignore file and that names a secret or a configuration file.",
};

const IMAGE = /\.(?:png|jpe?g|gif|svg|webp|pdf)$/iu;
const DIAGRAM_PATH = /(?:^|\/)(?:diagrams?|uml|models?|architecture)\//iu;
const DIAGRAM_JSON = /\.(?:json|drawio|puml|plantuml|mmd)$/iu;
const PROSE = /\.(?:md|markdown|txt|rst|adoc)$/iu;
const PROJECT_CONFIG =
	/(?:^|\/)(?:project\.yml|project\.yaml|package\.json|Package\.swift|Package\.resolved|Podfile|Cartfile|build\.gradle(?:\.kts)?|pom\.xml|pyproject\.toml|requirements\.txt|\.gitignore|\.editorconfig|\.swiftlint\.yml|Info\.plist)$/iu;
const TEST_PATH =
	/(?:^|\/)(?:tests?|specs?|__tests__)(?:\/)|[._-](?:test|tests|spec|specs)\.[a-z]+$|Tests?\.[a-z0-9]+$|Spec\.[a-z0-9]+$/iu;
const CODE = /\.(?:swift|ts|tsx|js|jsx|py|java|kt|go|rb|cs|cpp|cc|cxx|c|m|mm|h|hpp|vue|dart|rs)$/iu;
const PREVIEW = /^\+.*(?:#Preview\b|PreviewProvider\b|\.stories\.[jt]sx?|storiesOf\()/u;
// A CommonMark heading may be indented by up to three spaces.
const TESTING_HEADING =
	/^ {0,3}#+\s*(?:testing|test(?:ing)? instructions|how to test|verification|steps to (?:test|verify|reproduce))/iu;
const PLACEHOLDER_TESTING_TEXT = /^(?:n\/?a|none|not applicable|-|—)\.?$/iu;
const SCREENSHOT = /!\[[^\]]*\]\([^)]*\)/gu;
// Xcode''s library inserts these around a control''s defaults until the author replaces them.
const PLACEHOLDER_TOKEN = /\/\*@(?:START_MENU_TOKEN|PLACEHOLDER=)/u;
// A key or secret the code reads at runtime: a secret-shaped name beside a runtime lookup.
const SECRET_NAME =
	/api[_-]?key|apikey|client[_-]?secret|\bsecrets?\b|secret[A-Z_]|access[_-]?token/iu;
const RUNTIME_LOOKUP =
	/Bundle\.main|ProcessInfo|\benvironment\[|\.plist|xcconfig|Keychain|SecItem|UserDefaults|infoDictionary|process\.env|System\.getenv|os\.environ/u;

/** The section under a testing heading, stripped of template comments; empty when it holds nothing. */
function testingSection(body: string): { heading: string; content: string } | null {
	const lines = body.split(/\r?\n/u);
	for (let index = 0; index < lines.length; index += 1) {
		const line = lines[index] ?? "";
		if (!TESTING_HEADING.test(line)) {
			continue;
		}
		const level = (/#+/u.exec(line)?.[0] ?? "#").length;
		const content: string[] = [];
		for (let next = index + 1; next < lines.length; next += 1) {
			const candidate = lines[next] ?? "";
			const nextLevel = /^ {0,3}(?<hashes>#+)\s/u.exec(candidate)?.groups?.hashes?.length;
			if (nextLevel !== undefined && nextLevel <= level) {
				break;
			}
			content.push(candidate);
		}
		const text = withoutHtmlComments(content.join("\n")).trim();
		return { heading: line.trim(), content: text };
	}
	return null;
}

/** The characters of an author''s testing heading that a direction quotes. */
const HEADING_CHARS = 100;

/** A lead for each added line that matches. */
function addedLinesMatching(
	change: ReadonlyMap<string, DiffFile>,
	kind: keyof typeof LABELS,
	matches: (path: string, line: string) => boolean,
): ReviewLead[] {
	return [...change.values()].flatMap((file) =>
		[...file.addedLines]
			.filter(([, line]) => matches(file.path, line))
			.map(([line]): ReviewLead => ({ at: { change: file.path, line }, label: LABELS[kind] })),
	);
}

/** `opening` and as many of the items as fit in one direction. */
function listed(opening: string, items: readonly string[], separator = ", "): string {
	return `${opening}${listWithin(items, DIRECTION_CHARS - opening.length - 1, separator)}.`;
}

export default definePracticeScript({
	meta: {},
	async run(ctx) {
		const domain = scm(ctx);
		expectKind(domain, "scm.pull_request");
		const { item: record } = domain;
		const change = requireChange(domain.files);
		const paths = [...change.keys()];
		// A move, a rename or a binary file changes no line; an image among them is still content.
		const unchanged = [...change.values()]
			.filter(
				(file) => file.hunks.length === 0 && file.addedLines.size + file.removedLines.size === 0,
			)
			.map((file) => file.path)
			.filter((path) => !IMAGE.test(path));
		const content = paths.filter((path) => !unchanged.includes(path));
		const kinds = {
			images: content.filter((path) => IMAGE.test(path)).length,
			diagramFiles: content.filter(
				(path) =>
					DIAGRAM_PATH.test(path) ||
					(DIAGRAM_JSON.test(path) && /diagram|aom|uml|model/iu.test(path)),
			).length,
			prose: content.filter((path) => PROSE.test(path)).length,
			projectConfig: content.filter((path) => PROJECT_CONFIG.test(path)).length,
			tests: content.filter((path) => TEST_PATH.test(path)).length,
			code: content.filter((path) => CODE.test(path) && !TEST_PATH.test(path)).length,
		};
		const addedLines = [...change.values()].reduce((sum, file) => sum + file.addedLines.size, 0);
		const removedLines = [...change.values()].reduce(
			(sum, file) => sum + file.removedLines.size,
			0,
		);
		const previews = [...change.values()].filter((file) =>
			[...file.addedLines.values()].some((line) => PREVIEW.test(`+${line}`)),
		);
		const placeholders = addedLinesMatching(change, "xcode-placeholder", (_path, line) =>
			PLACEHOLDER_TOKEN.test(line),
		);
		const secretReads = addedLinesMatching(
			change,
			"runtime-secret-read",
			(path, line) =>
				!path.endsWith(".gitignore") && SECRET_NAME.test(line) && RUNTIME_LOOKUP.test(line),
		);
		const ignoredSecrets = addedLinesMatching(
			change,
			"ignored-secret",
			(path, line) =>
				path.endsWith(".gitignore") &&
				(SECRET_NAME.test(line.trim()) || /\.xcconfig$|\.env\b/iu.test(line.trim())),
		);

		const body = record.body ?? "";
		const testing = testingSection(body);
		const screenshots = body.match(SCREENSHOT)?.length ?? 0;
		// Only the author''s own words adopt an issue: a closing keyword in their prose, the title, the
		// branch, or the provider''s closing link. A template''s example in code or a comment names nothing.
		const capture = await readLinkedWorkItemCapture(ctx.evidence);
		const captured = capture?.items.map((item) => item.number) ?? [];
		const named = new Map<number, string[]>();
		const name = (how: string, numbers: number[]) => {
			for (const n of numbers) {
				named.set(n, [...(named.get(n) ?? []), how]);
			}
		};
		name(
			"provider closing link",
			(capture?.items ?? [])
				.filter((item) => item.how === "closesOnMerge")
				.map((item) => item.number),
		);
		name("closing keyword in the description", closingReferences(body));
		name("title", issueNumberReferences(record.title ?? ""));
		name("branch", branchIssueReferences(record.source_branch));

		const directions: string[] = [];
		if (paths.length === 0 || addedLines + removedLines === 0) {
			directions.push(
				"The pinned range changes no lines: an empty diff is one of the kinds the criteria''s applicability section names; cite it through metadata.json changed_files or work/change/files.json.",
			);
		} else if (kinds.code === 0 && kinds.tests === 0 && kinds.projectConfig === 0) {
			directions.push(
				`No code, test or project-configuration file has line changes; the change is ${kinds.images} image(s), ${kinds.diagramFiles} diagram file(s) and ${kinds.prose} prose file(s).`,
				"Read the prose hunks: if they add setup or run instructions the change is material; if they add an introduction, a glossary, user stories or a diagram''s embedding, it is one of the kinds the criteria''s applicability section names.",
			);
		} else {
			directions.push(
				`Files with line changes: ${kinds.code} code, ${kinds.tests} test, ${kinds.projectConfig} project-configuration, ${kinds.prose} prose, ${kinds.images} image.`,
			);
		}
		if (unchanged.length > 0) {
			directions.push(
				listed(
					`${unchanged.length} file(s) change no line — moves, renames or binary files: `,
					unchanged,
				),
			);
		}
		// A bare testing section reads as "nothing anywhere" unless the direction says what it settles.
		const elsewhere =
			" That settles nothing either way: the entry, action and expected result can be in other sections, an adopted issue, a preview, the documented setup or the author''s discussion.";
		const heading = testing === null ? "" : oneLine(testing.heading, HEADING_CHARS);
		if (testing === null) {
			directions.push(`The description has no testing heading.${elsewhere}`);
