INSERT INTO _cutover_program VALUES('9cd7655703ab5ce8aaf3f6bcd8d2b1cc4352146810eb0c129f4a04ad83c8b2cf','// Precompute HINTS for uses-structured-concurrency-safely: every concurrency construct ADDED in Swift
// files, placed in its enclosing type, and the lines of the project files that mention a default actor
// isolation. Whether the work must outlive the view, and whether a mutation lands on the main actor, is
// the review''s to decide from the checkout.
import { readFile } from "node:fs/promises";
import path from "node:path";

import { globFilesSync } from "../lib/files.ts";
import { countLabel, sampleNote, scanAddedLines, type SourcePattern } from "../lib/source-scan.ts";
import type { DiffFile, PullRequestMetadata } from "../lib/types.ts";

const SWIFTUI_VIEW = /\b(?:View|App|Scene)\b/u;

const CONCURRENCY: readonly SourcePattern[] = [
	["Task.detached", /\bTask\.detached\b/u],
	["stored task handle", /(?:let|var)\s+\w+\s*(?::\s*Task<[^>]*>)?\s*=\s*Task\s*[{(]/u],
	["Task { }", /\bTask\s*(?:\(priority:[^)]*\))?\s*\{/u],
	[".task modifier", /\.task\s*(?:\(id:[^)]*\))?\s*\{/u],
	[".onAppear", /\.onAppear\s*\{/u],
	["DispatchQueue", /\bDispatchQueue\b/u],
	["@MainActor", /@MainActor\b/u],
	["MainActor.run", /\bMainActor\.run\b/u],
	["actor declaration", /^\s*(?:\w+\s+)*actor\s+\w+/u],
	["async function", /\bfunc\s+\w+[^{]*\basync\b/u],
	["await", /\bawait\b/u],
];

/** Text naming a default actor isolation: an Xcode build setting or a SwiftPM target setting. */
const DEFAULT_ISOLATION = /SWIFT_DEFAULT_ACTOR_ISOLATION\s*[:=]|defaultIsolation\s*\(/u;

/**
 * Lines of the first few project files that mention a default actor isolation, as `path:line text`. The
 * setting belongs to one target or SwiftPM module and build configuration, and a line may be commented
 * out, so a line found here is a place to read, not the isolation of any changed type.
 */
async function defaultIsolationLines(repoPath: string): Promise<string[]> {
	let files: string[];
	try {
		files = [
			...globFilesSync("**/project.yml", repoPath),
			...globFilesSync("**/project.yaml", repoPath),
			...globFilesSync("**/*.xcodeproj/project.pbxproj", repoPath),
			...globFilesSync("**/Package.swift", repoPath),
		].filter((f) => !/(?:^|\/)(?:Pods|\.build|DerivedData|Carthage)\//u.test(f));
	} catch {
		return [];
	}
	const found: string[] = [];
	for (const file of files.slice(0, 20)) {
		let text: string;
		try {
			text = await readFile(path.join(repoPath, file), "utf8");
		} catch {
			continue;
		}
		for (const [index, line] of text.split(/\r?\n/u).entries()) {
			if (DEFAULT_ISOLATION.test(line)) {
				found.push(`${file}:${String(index + 1)} ${line.trim().slice(0, 120)}`);
			}
		}
	}
	return found.slice(0, 10);
}

export default async function usesStructuredConcurrencySafely(
	repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_metadata: PullRequestMetadata,
) {
	const scan = await scanAddedLines(repoPath, diffFiles, {
		languages: ["swift"],
		patterns: CONCURRENCY,
		scope: SWIFTUI_VIEW,
		maxHints: 60,
	});
	const count = (label: string) => countLabel(scan, label);
	const unstructuredInViews = scan.hints.filter(
		(h) => h.pattern === "Task { }" && h.flags.inScope === true,
	).length;
	const metrics = {
		concurrencyLinesAdded: scan.matched,
		taskBlocks: count("Task { }"),
		taskBlocksInListedViewRows: unstructuredInViews,
		taskModifiers: count(".task modifier"),
		detachedTasks: count("Task.detached"),
		dispatchQueues: count("DispatchQueue"),
		mainActorMarks: count("@MainActor") + count("MainActor.run"),
		filesWithoutCheckout: scan.filesWithoutCheckout,
		filesScanned: scan.filesScanned,
		linesAdded: scan.linesAdded,
	};
	const directions: string[] = [...sampleNote(scan)];
	if (unstructuredInViews > 0) {
		directions.push(
			`${unstructuredInViews} Task { } block(s) added inside view types — read the lifetime each needs: work tied to the view belongs to a lifecycle that cancels it, while a Task started from a user action may legitimately finish after the view is gone.`,
		);
	}
	if (metrics.detachedTasks + metrics.dispatchQueues > 0) {
		directions.push(
			`${metrics.detachedTasks} detached task(s) and ${metrics.dispatchQueues} dispatch queue use(s) — read whether the code shows a need for independent execution or scheduling; no written reason is required when it does.`,
		);
	}
	if (scan.matched > 0) {
		const settings = await defaultIsolationLines(repoPath);
		directions.push(
			settings.length > 0
				? `Default actor isolation text in project files: ${settings.join("; ")}. Each applies only to its own target or SwiftPM module and build configuration, and a commented line sets nothing: read which target and configuration build the changed file before relying on any of them.`
				: "No default actor isolation text was found in the project files read, which leaves the module''s default unknown rather than nonisolated.",
			"A type''s isolation comes from its declaration, its module''s setting or what it inherits. A missing @MainActor on an added line does not by itself put a mutation off the main actor. Check the SDK before relying on inherited SwiftUI View isolation. Swallowed failures belong to handles-errors-instead-of-swallowing-them, not this practice.",
		);
	}
	return { hints: scan.hints, metrics, directions };
}
','ba05ae7f5f6fe0e5d98415d2005f1a48c9565b37d8d5c09137f861b248f36099','import { scm, type FileTree } from "../kits/scm/index.ts";
import {
	countLabel,
	sampleNote,
	scanOccurrences,
	type SourcePattern,
} from "../kits/scm/source-scan.ts";
// Finds each concurrency construct that the change adds to Swift files, with the type that encloses
// it, and the lines of the project files that name a default actor isolation. The review decides
// from the checkout whether the work must outlive the view and where each mutation runs.
import { factsOf, noMatchDirections } from "../lib/core/bounded-text.ts";
import { definePracticeScript, type ReviewLead } from "../lib/core/practice-script.ts";

const SWIFTUI_VIEW = /\b(?:View|App|Scene)\b/u;

// The first pattern that matches a line gives its kind.
const CONCURRENCY: readonly SourcePattern[] = [
	["detached-task", /\bTask\.detached\b/u],
	["stored-task-handle", /(?:let|var)\s+\w+\s*(?::\s*Task<[^>]*>)?\s*=\s*Task\s*[{(]/u],
	["task-block", /\bTask\s*(?:\(priority:[^)]*\))?\s*\{/u],
	["task-modifier", /\.task\s*(?:\(id:[^)]*\))?\s*\{/u],
	["on-appear", /\.onAppear\s*\{/u],
	["dispatch-queue", /\bDispatchQueue\b/u],
	["main-actor-mark", /@MainActor\b/u],
	["main-actor-run", /\bMainActor\.run\b/u],
	["actor-declaration", /^\s*(?:\w+\s+)*actor\s+\w+/mu],
	["async-function", /\bfunc\s+\w+[^{]*\basync\b/u],
	["await", /\bawait\b/u],
];

/** Text naming a default actor isolation: an Xcode build setting or a SwiftPM target setting. */
const DEFAULT_ISOLATION = /SWIFT_DEFAULT_ACTOR_ISOLATION\s*[:=]|defaultIsolation\s*\(/u;

const PROJECT_FILES = [
	"**/project.yml",
	"**/project.yaml",
	"**/*.xcodeproj/project.pbxproj",
	"**/Package.swift",
];

/**
 * The lines of the first few project files that name a default actor isolation. The setting belongs
 * to one target or SwiftPM module and build configuration, and a line can be commented out. Thus, a
 * line found here is a place to read, not the isolation of a changed type.
 */
async function defaultIsolationLines(
	tree: FileTree | null,
): Promise<{ file: string; line: number }[]> {
	if (tree === null) {
		return [];
	}
	const files: string[] = [];
	try {
		for (const glob of PROJECT_FILES) {
			const { paths } = await tree.list(glob);
			files.push(...paths);
		}
	} catch {
		return [];
	}
	const found: { file: string; line: number }[] = [];
	const projectFiles = files.filter(
		(f) => !/(?:^|\/)(?:Pods|\.build|DerivedData|Carthage)\//u.test(f),
	);
	for (const file of projectFiles.slice(0, 20)) {
		const source = await tree.read(file).catch(() => null);
		if (source?.status !== "FOUND") {
			continue;
		}
		for (const [index, line] of source.text.split(/\r?\n/u).entries()) {
			if (DEFAULT_ISOLATION.test(line)) {
				found.push({ file, line: index + 1 });
			}
		}
	}
	return found.slice(0, 10);
}

export const LABELS = {
	"detached-task": "A selected Task.detached call.",
	"stored-task-handle": "A selected property that stores a Task.",
	"task-block": "A selected unstructured Task { } block.",
	"task-modifier": "A selected .task view modifier.",
	"on-appear": "A selected .onAppear block.",
	"dispatch-queue": "A selected line that uses DispatchQueue.",
	"main-actor-mark": "A selected @MainActor attribute.",
	"main-actor-run": "A selected MainActor.run call.",
	"actor-declaration": "A selected actor declaration.",
	"async-function": "A selected async function declaration.",
	await: "A selected await expression.",
	"default-isolation-setting":
		"A line of a project file that names a default actor isolation for one target or module.",
};
const LABEL_OF = new Map<string, string>(Object.entries(LABELS));

export default definePracticeScript({
	meta: {},
	async run(ctx) {
		const domain = scm(ctx);
		if (domain.kind !== "scm.pull_request" && domain.kind !== "scm.file") {
			throw new Error("this practice requires SCM source files");
		}
		const scan = await scanOccurrences(ctx, domain.files, {
			languages: ["swift"],
			patterns: CONCURRENCY,
			scope: SWIFTUI_VIEW,
			maxHints: 60,
		});
		const leads: ReviewLead[] = scan.hints.flatMap((hint) => {
			const label = LABEL_OF.get(hint.pattern);
			return label === undefined
				? []
				: [
						{
							at: { file: hint.file, line: hint.line, endLine: hint.endLine },
							label,
							facts: factsOf(hint.flags),
						},
					];
		});
		const count = (label: string) => countLabel(scan, label);
		const unstructuredInViews = scan.hints.filter(
			(hint) => hint.pattern === "task-block" && hint.flags.inScope === true,
		).length;
		const facts = {
			concurrencyLinesSelected: scan.matched,
			taskBlocks: count("task-block"),
			taskBlocksInListedViewRows: unstructuredInViews,
			taskModifiers: count("task-modifier"),
			detachedTasks: count("detached-task"),
			dispatchQueues: count("dispatch-queue"),
			mainActorMarks: count("main-actor-mark") + count("main-actor-run"),
			filesWithUnknownLocation: scan.filesWithUnknownLocation,
			filesScanned: scan.filesScanned,
			linesSelected: scan.linesSelected,
		};
		const directions: string[] = [...sampleNote(scan)];
		if (leads.length === 0) {
			directions.push(...noMatchDirections(scan.linesSelected, scan.filesScanned));
		}
		if (unstructuredInViews > 0) {
			directions.push(
				`${unstructuredInViews} Task { } block(s) selected inside view types — read the lifetime each needs: work tied to the view belongs to a lifecycle that cancels it, while a Task started from a user action may legitimately finish after the view is gone.`,
			);
		}
		if (facts.detachedTasks + facts.dispatchQueues > 0) {
			directions.push(
				`${facts.detachedTasks} detached task(s) and ${facts.dispatchQueues} dispatch queue use(s) — read whether the code shows a need for independent execution or scheduling; no written reason is required when it does.`,
			);
		}
		if (scan.matched > 0) {
			const settings = await defaultIsolationLines(domain.files?.head ?? null);
			leads.push(
				...settings.map((at): ReviewLead => ({ at, label: LABELS["default-isolation-setting"] })),
			);
			directions.push(
				settings.length > 0
					? "Each default-isolation-setting lead applies only to its own target or SwiftPM module and build configuration, and a commented line sets nothing: read which target and configuration build the changed file before relying on any of them."
					: "No default actor isolation text was found in the project files read, which leaves the module''s default unknown rather than nonisolated.",
				"A type''s isolation comes from its declaration, its module''s setting or what it inherits. A missing @MainActor on a selected line does not by itself put a mutation off the main actor.",
				"Check the SDK before relying on inherited SwiftUI View isolation. Swallowed failures belong to handles-errors-instead-of-swallowing-them, not this practice.",
			);
		}
		return ctx.review({ leads, facts, directions });
	},
});
');
INSERT INTO _cutover_program VALUES('6d29d3ed21f6cf9ec7d718ac3ae74d7ec8a6abfb5a0860726fb9d5cc8894e25e','// Precompute HINTS for ships-a-preview-with-each-new-view: the view types this change declares and the
// previews it adds, per file. The pairing is a fact the review checks; whether a preview''s data is
// representative is the review''s to read.
import { isCommentLine } from "../lib/declarations.ts";
import { isTestPath, languageOf } from "../lib/languages.ts";
import type { DiffFile, Hint, PullRequestMetadata } from "../lib/types.ts";

const VIEW_DECLARATION =
	/^\s*(?:@\w+\s+)*(?:(?:public|private|fileprivate|internal)\s+)?struct\s+(?<name>[A-Za-z_]\w*)\s*(?:<[^>]*>)?\s*:\s*[^{]*\bView\b/u;
const PREVIEW = /^\s*#Preview\b|:\s*PreviewProvider\b/u;

export default function shipsAPreviewWithEachNewView(
	_repoPath: string,
	diffFiles: Map<string, DiffFile>,
	_metadata: PullRequestMetadata,
) {
	const hints: Hint[] = [];
	let newViews = 0;
	let previewsAdded = 0;
	let filesWithNewViewAndNoPreview = 0;
	for (const [path, df] of diffFiles) {
		if (languageOf(path) !== "swift" || isTestPath(path)) {
			continue;
		}
		let views = 0;
		let previews = 0;
		for (const [line, content] of df.addedLines) {
			if (isCommentLine(content, "swift")) {
				continue;
			}
			const view = VIEW_DECLARATION.exec(content);
			if (view) {
				views += 1;
				hints.push({
					file: path,
					line,
					pattern: "new view type",
					context: content.trim().slice(0, 160),
					inDiff: true,
					flags: { name: view.groups?.name ?? "" },
				});
			} else if (PREVIEW.test(content)) {
				previews += 1;
				hints.push({
					file: path,
					line,
					pattern: "preview",
					context: content.trim().slice(0, 160),
					inDiff: true,
					flags: {},
				});
			}
		}
		newViews += views;
		previewsAdded += previews;
		if (views > 0 && previews === 0) {
			filesWithNewViewAndNoPreview += 1;
		}
	}
	const directions: string[] = [];
	if (newViews > 0) {
		directions.push(
			`${newViews} new view type(s) declared and ${previewsAdded} preview(s) added; ${filesWithNewViewAndNoPreview} file(s) declare a view and add no preview — a preview may live in another file of the change, so scan the whole diff before deciding. These counts pair no preview with a view. Read the previews and view bodies to trace the presentation coverage described in the criteria, including nested views and content delegated by an effect-only owner.`,
		);
	}
	return {
		hints: hints.slice(0, 40),
		metrics: { newViews, previewsAdded, filesWithNewViewAndNoPreview },
		directions,
	};
}
','9674a2373c182717d034f86127cf212d5f273b4e7ce9b999625e7839a6445557','import { isCommentLine } from "../kits/scm/declarations.ts";
import { scm, expectKind, requireChange } from "../kits/scm/index.ts";
import { isTestPath, languageOf } from "../kits/scm/languages.ts";
// Finds the view types that the change declares and the previews that it adds, in each Swift file.
// The review pairs them, and reads if the data of each preview is representative.
import { factsOf } from "../lib/core/bounded-text.ts";
import { definePracticeScript, type ReviewLead } from "../lib/core/practice-script.ts";

const VIEW_DECLARATION =
	/^\s*(?:@\w+\s+)*(?:(?:public|private|fileprivate|internal)\s+)?struct\s+(?<name>[A-Za-z_]\w*)\s*(?:<[^>]*>)?\s*:\s*[^{]*\bView\b/u;
const PREVIEW = /^\s*#Preview\b|:\s*PreviewProvider\b/u;

export const LABELS = {
	"new-view-type": "An added struct that conforms to View, with its name.",
	preview: "An added #Preview or PreviewProvider.",
};

export default definePracticeScript({
	meta: {},
	async run(ctx) {
		const domain = scm(ctx);
		expectKind(domain, "scm.pull_request");
		const leads: ReviewLead[] = [];
		let newViews = 0;
		let previewsAdded = 0;
		let filesWithNewViewAndNoPreview = 0;
		for (const [path, df] of requireChange(domain.files)) {
			if (languageOf(path) !== "swift" || isTestPath(path)) {
				continue;
			}
			let views = 0;
			let previews = 0;
			for (const [line, content] of df.addedLines) {
				if (isCommentLine(content, "swift")) {
					continue;
				}
				const view = VIEW_DECLARATION.exec(content);
				if (view) {
					views += 1;
					leads.push({
						at: { change: path, line },
						label: LABELS["new-view-type"],
						facts: factsOf({ name: view.groups?.name ?? "" }),
					});
				} else if (PREVIEW.test(content)) {
					previews += 1;
					leads.push({ at: { change: path, line }, label: LABELS.preview });
				}
			}
			newViews += views;
			previewsAdded += previews;
			if (views > 0 && previews === 0) {
				filesWithNewViewAndNoPreview += 1;
			}
		}
		const directions: string[] = [];
		if (newViews > 0) {
			directions.push(
				`${newViews} new view type(s) declared and ${previewsAdded} preview(s) added; ${filesWithNewViewAndNoPreview} file(s) declare a view and add no preview — a preview may live in another file of the change, so scan the whole diff before deciding.`,
				"These counts pair no preview with a view. Read the previews and view bodies to trace the presentation coverage described in the criteria, including nested views and content delegated by an effect-only owner.",
			);
		}
		return ctx.review({
			leads: leads.slice(0, 40),
			facts: { newViews, previewsAdded, filesWithNewViewAndNoPreview },
			directions,
		});
	},
});
